C******************************************************************************
C
C  PDBHTML.F    -  Program to convert data output by PDBSPLIT.F into a
C                  WWW "home page" for the PDB file in question
C
C----------------------------------------------------------------------+---
C
C
C The files used by this program are:
C
C  1 <filename>     -  Input PDB file
C  1  secsurf.out   -  Input file generated by secsurf.f giving the
C                      information about the PDB file's contents
C  1  chains.dat    -  Input file giving which chains are unique and
C                      which afre duplicates
C  2  rfactors      -  File generated by IDITIS of all R-factors, used when
C                      R-factor in PDB file not found
C  2  unpubrefs.list - List of PDB entries in Stuart Moodie's Unpublished
C                      references list
C  2  <various>.html - Files opened to check they exist and are not empty,
C                      to determine whether links to them should be included
C  2  sp_list       -  List of links to Swiss Prot entries for each PDB
C                      file
C  2  mcsg.lst      -  List of MCSG structures deposited in the PDB
C  3  pdb_EC        -  File containing the PDB entries that have E.C.
C                      numbers, generated by Alex Michie's program
C  3  pdb_NDB       -  File containing the DNA entries that have entries
C                      in NDB (list obtained by query to NDB database)
C  3  3dp.tof.list  -  Database of true/false status of all the PROSITE
C                      pattern matches in 3dp.matches.list
C  3  template_head.html - Template for PDBsum page header details
C  4  cath.numbers  -  CATH-numbers file, generated by Alex Michie's
C                      programs
C  4  cath.domains  -  CATH-domains file, generated by Alex Michie's
C                      programs
C  4  cath.titles   -  CATH-titles file, generated by Alex Michie's
C                      programs (now by Andrew Martin's new versions)
C  4  3dp.matches.list -  Database of PROSITE pattern matches for all entries
C                      in the PDB
C  4  PRINTSvsPDB   -  PRINTS codes file, generated by Alex Michie's
C                      programs
C  4  ligplot.res   -  File containing list of residues in a given LIGPLOT
C  7  main_old.html -  Old output home page for the given PDB file in html
C                      format.
C  8  trace.html    -  Chain-trace descriptions and colours (NOT USED)
C 10 <various>.html -  Generated html files
C 11  chainNN.seq   -  Chain sequence, plus attached het groups, where
C                      relevant
C 12  enzyme.out    -  Output file giving all the mismatches between the
C                      E.C. codes in the PDB and those obtained from
C                      SWISS-PROT.
C 13 <various>.gif  -  Test for existence of .gif files
C 14 sites.html     -  HTML file holding details of active sites in the
C                      PDB entry
C 15 supersede.add  -  File containing all the SPRSDE records from the
C                      PDB file
C 15 supersede.dat  -  File containing the SPRSDE records from all PDB
C                      files
C 15 species.dat    -  File containing the list of available species
C                      GIF files for inclusion
C 16 supersede.new  -  File containing any existing PDBsum entries
C                      superseded by the current one
C 17 inph.html      -  Cut-down version of main.html for Inpharmatica (no
C                      longer used)
C 18 het_dictionary.txt - Het Group Dictionary
C 19 main.html      -  New version of main.html
C 20 bindsite.html  -  Binding site analysis page (currently only for
C                      MCSG structures)
C 21 database.dat   -  Database file containing all the data items written
C                      to the main.html file for use in generating new-
C                      format PDBsum pages on the fly
C
C----------------------------------------------------------------------+---
C
C Compiling under gfortran:-
C
C gfortran -fbounds-check -c pdbhtml.f
C gfortran -fbounds-check -c fcommon.f
C gfortran -o pdbhtml pdbhtml.o fcommon.o
C
C Subroutine calling tree
C -----------------------
C
C   MAIN  --> GETPTH  --> GETPAR (in fcommon.f)
C         --> LOWCAS (in fcommon.f)
C         --> UPPCAS (in fcommon.f)
C         --> GETMCS
C         --> OPNHET
C         --> SECDAT
C         --> CHUNIQ
C         --> GETOBS
C         --> GETSPE
C         --> PDBHED  --> STRPLN
C                     --> STOSWS
C         --> PROCMP
C         --> PROSRC
C         --> GETRVL
C         --> CHKLCHK
C         --> CHKLNK
C         --> ADDLNK
C         --> UPPCAS (in fcommon.f)
C         --> INITS
C         --> OPENTR
C         --> GETEC   --> UPPCAS (in fcommon.f)
C                     --> GETNUM
C                     --> ECCONV
C         --> OPENDB
C         --> GETNDB  --> LOWCAS (in fcommon.f)
C         --> OPNNEW
C         --> REANEW
C         --> OPNCAT }
C         --> REACAT } No longer used as for old-format
C         --> OPNDOM } CATH data files
C         --> READOM }
C         --> OPNTIT
C         --> REATIT
C         --> OPNPRN
C         --> REAPRN  --> LOWCAS (in fcommon.f)
C         --> SWISS   --> UPPCAS (in fcommon.f)
C                     --> STOSWS
C         --> CHKVEW
C         --> CHKVIE
C         --> TYPSET  --> UPSET
C         --> NEWHED  --> SWOFF   --> GETSTA
C                     --> DBINFO  --> SUBSCR
C                     --> GETSTA
C                     --> WRIRES
C                     --> SPLICE  --> WRIRES
C                                 --> WRIAUT
C                                 --> WRISWS
C                                 --> WRIECN  --> GETDIR
C                                             --> COMPRS
C                                             --> ECCONV
C                                 --> WRIPRN
C         --> WRITIT
C         --> WRIGIF  --> CHKLNK
C         --> WRIOBS  --> LOWCAS (in fcommon.f)
C                     --> FRMFNM (in fcommon.f)
C                     --> CHKLNK
C         --> WRIVIE  --> CHKLNK
C         --> WRIPRO
C         --> WRITAB
C         --> WRIECN  --> GETDIR
C                     --> COMPRS
C                     --> ECCONV
C         --> WRISWS
C         --> WRIPRN
C         --> GETLNK
C         --> WRIREL  --> TYPSET  --> UPSET
C                     --> ADDLNK
C         --> WRISUP  --> LOWCAS (in fcommon.f)
C                     --> CHKLNK
C                     --> SUPNEW
C         --> WRIHED
C         --> WRIBIN  --> CHKLNK
C         --> WRIFUN  --> CHKLNK
C         --> WRIFIG  --> CHKLNK
C         --> WRICHN  --> DOMCOL
C                     --> GETCAT  --> COMCAT
C                     --> GETDOM  --> COMCAT
C                     --> GETPAT  --> CHKPAT
C                                 --> LOWCAS (in fcommon.f)
C                     --> GETSWS
C                     --> OBJCOL
C                     --> WRNONS  --> RESDES
C                                 --> HETDES
C                     --> CHKFIL
C                     --> PROMTF  --> CHKFIL
C                     --> SITES   --> CHKFIL
C                                 --> GETSIT
C                     --> INTRNS  --> CHKFIL
C                     --> GIFILE  --> CHKFIL
C                                 --> GETRNG
C                     --> BINLNK  --> CHKLNK
C                     --> COLSEQ
C         --> WRINUC  --> WRNONS  --> RESDES
C                                 --> HETDES
C         --> WRILIG  --> GIFILE  --> CHKFIL
C                                 --> GETRNG
C                     --> WRNONS  --> RESDES
C                                 --> HETDES
C                     --> CHKFIL
C         --> WRIMET  --> ATMCOL
C         --> WRIEXT
C         --> WRIWAT
C         --> WRIEND
C         --> GETDAT
C
C----------------------------------------------------------------------+---

CVAX      IMPLICIT NONE

      PROGRAM PDBHTM

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   YESNO
      CHARACTER*4   FAKE, PDBCOD
      CHARACTER*12  ECCODE(MXENTR)
      CHARACTER*(FNAMLN) HGDFIL, SUMDAT, Z
      CHARACTER*(FNAMLN) PDB_TEMPLATE(NPDB_DIR)
      CHARACTER*(FNAMLN) PDBSUM_TEMPLATE(NPDBSUM_DIR)

      INTEGER       ALEN, BFILE, HLEN, IAPPEN, ICOL, IEC, IENTRY,
     -              IEXTRA, IFILE, ILINE, IMETAL, ISPECI, ISWISS, ITEM,
     -              LENSTR, LINE, NLEN(MXENTR), NLIG, SLEN
      LOGICAL       ALPHAF, BINPAG, HAVBIN, NOREAD

C---- JavaScript flag
      ALPHAF = .FALSE.
      FAKE = ' '
      JAVASC = .TRUE.

C---- Initialise variables
      BRCODE = '????'
      DATE = ' '
      RLDATE = ' '

C---- Get the PDB directory templates
      CALL GETPDR(PDB_TEMPLATE)

C---- Get the PDBsum directory templates
      CALL GETPSM(PDBSUM_TEMPLATE)

C---- Get the paths to the files, directories and URLs from the CATHPARAM
C     file
      CALL GETPTH(SUMDAT,FAKE,HGDFIL,NMRDIR,FILEN)

C---- Initialise paths and file names
      DOHEAD = ' '
      DOINTR = ' '
      DOMOLS = ' '
      DOSAS = ' '
      DOLRES = ' '
      DOPROS = ' '
      DONUCP = ' '
      ECNUMB = ' '
      ECEXPT = .FALSE.
      EMEXPT = .FALSE.
      ENSLNK = .FALSE.
      EXPENZ = ' '
      HAVBIN = .FALSE.
      HAVCHK = .FALSE.
      HAVLIG = .FALSE.
      HAVPRO = .FALSE.
      HAVRSC = .FALSE.
      HAVUNP = .FALSE.
      HAVWRL = .FALSE.
      HEADER = ' '
      IFAIL = .FALSE.
      ILINE = 0
      IMBJEN = ' '
      INCSAS = .TRUE.
      ITEM = 0
      KYOENZ = ' '
      LAYER1 = .FALSE.
      LINE = 0
      NALINE = 0
      NATOMS = 0
      NCHAIN = 0
      NCLINE = 0
      NCODES = 0
      NDBREF = ' '
      NELINE = 0
      NEXTRA = 0
      NHYDRO = 0
      NLIGAN = 0
      NMETAL = 0
      NMODEL = 0
      NMR = .FALSE.
      NMRLNK = .FALSE.
      NNUCL = 0
      NOLINK = .FALSE.
      NPCODE = 0
      NRLINE = 0
      NSLINE = 0
      NSPECI = 0
      NSUPER = 0
      NSWISS = 0
      NTLINE = 0
      NWATER = 0
      NXLINE = 0
      NXTCOL = 0
      OBSOL = .FALSE.
      PDBLNK = ' '
      PDBSM1 = .FALSE.
      PDB3DB = ' '
      PDBNDB = SUMDAT(1:LENSTR(SUMDAT)) // '/pdb_NDB'
      RELINK = .FALSE.
      RESOL = 0.0
      RFACT = 0.0
      RFREE = 0.0
      RUNLIG = ' '
      RUNWIR = ' '
      SFOPEN = .FALSE.
      SPEFIL = 'species.dat'
      SWADDR = ' '
      TMODEL = .FALSE.
      UNPUBL = ' '
      WITENZ = ' '
      WWWCAT = ' '
      WWWCDM = ' '
      WWWDHS = ' '
      WWWENZ = ' '
      WWWFSP = ' '
      WWWGET = ' '
      WWWHET = ' '
      WWWMAC = ' '
      WWWMMD = ' '
      WWWPFA = ' '
      WWWPRN = ' '
      WWWPRO = ' '
      WWWNDB = ' '
      WWWPDB = ' '
      WWWSPE = ' '
      WWWREP = ' '
      WWWRSC = ' '
      WWWDOM = ' '
      WWWSCP = ' '
      WWWTOP = ' '
      WWWYEA = ' '
      XRAY = .FALSE.
      YEAST = .FALSE.
      HLEN = INDEX(WWWHET,' ') - 1
      DO 10, ISWISS = 1, MXSWIS
          NSWCHN(ISWISS) = 0
          SWNAME(ISWISS) = ' '
          DO 5, ICOL = 1, MXSWCH
              SWICHN(ICOL,ISWISS) = ' '
 5        CONTINUE
 10   CONTINUE
      DO 20, IMETAL = 1, MXMETP
          METYPE(IMETAL) = ' '
          NMETYP(IMETAL) = 0
          METCOL(IMETAL) = 0
 20   CONTINUE
      DO 40, IEXTRA = 1, MXEXTR
          EXTRA(IEXTRA) = ' '
          NUMEXT(IEXTRA) = 0
 40   CONTINUE
      DO 60, ILINE = 1, MXITEM
          AUTHOR(ILINE) = ' '
          COMPND(ILINE) = ' '
          EXPDTA(ILINE) = ' '
          RELATE(ILINE) = ' '
          REM5(ILINE) = ' '
          SOURCE(ILINE) = ' '
          SPRSDE(ILINE) = ' '
          TITLE(ILINE) = ' '
          DO 50, IENTRY = 1, MXNONS
              DO 45, IAPPEN = 1, NAPPEN
                  DO 42, ITEM = 1, 3
                      ACOUNT(IENTRY,ILINE,IAPPEN,ITEM) = 0
                      ATTNAM(IENTRY,ILINE,IAPPEN,ITEM) = ' '
 42               CONTINUE
 45           CONTINUE
 50       CONTINUE
 60   CONTINUE
      DO 80, IENTRY = 1, MXNTRY
          CALPHA(IENTRY) = ' '
          CHAIN(IENTRY,CHN) = ' '
          CHAIN(IENTRY,LIG) = ' '
          CHAIN(IENTRY,NUC) = ' '
          CHNCOL(IENTRY) = ' '
          NBONDS(IENTRY) = 0
          NHELIX(IENTRY) = 0
          NUCCOL(IENTRY) = ' '
          NRESID(IENTRY,CHN) = 0
          NTIMES(IENTRY,CHN) = 0
          NRESID(IENTRY,LIG) = 0
          NTIMES(IENTRY,LIG) = 0
          NRESID(IENTRY,NUC) = 0
          NSTRND(IENTRY) = 0
          NTIMES(IENTRY,NUC) = 0
          DO 70, ILINE = 1, MXLINE 
              SEQUEN(ILINE,IENTRY,CHN) = ' '
              SEQUEN(ILINE,IENTRY,LIG) = ' '
              SEQUEN(ILINE,IENTRY,NUC) = ' '
 70       CONTINUE
 80   CONTINUE
      DO 85, ISPECI = 1, MXSPEC
          SPEGIF(ISPECI) = ' '
 85   CONTINUE

C---- Accept PDB code
      PRINT*, 'Enter 4-character PDB code'
      READ(*,90) BRCODE
 90   FORMAT(A)
      PRINT*, 'BRCODE =', BRCODE

C---- Check whether this is an uploaded entry or the fake PDB entry
      PRINT*, 'Enter whether Uploaded file, MCSG, PDBsum1, or blank'
      READ(*,90) YESNO
      UPLOAD = .FALSE.
      MCSG = .FALSE.
      IF (YESNO.EQ.'A') ALPHAF = .TRUE.
      IF (YESNO.EQ.'U') UPLOAD = .TRUE.
      IF (YESNO.EQ.'M') MCSG = .TRUE.
      IF (YESNO.EQ.'1') PDBSM1 = .TRUE.

C---- Convert the PDB number to lower-case if not an Alpha Fold struc
      IF (.NOT.ALPHAF) THEN
         CALL LOWCAS(4,BRCODE)
      ENDIF
      PDBCOD = BRCODE

C---- Find the file name of the corresponding PDB file
      CALL PDBNAM(PDBCOD,PDB_TEMPLATE,PDBFIL,MCSG,UPLOAD)

C---- Ditto for PDBsum directory
      CALL SUMNAM(PDBCOD,PDBSUM_TEMPLATE,PDBSUM,MCSG,UPLOAD)

C---- Convert the PDB number into upper-case
      CALL UPPCAS(4,PDBCOD)

C---- Form all filenames within the PDBsum directory structure
      CATFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // 'cath.numbers'
      DOMFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // 'cath.domains'
      LNKFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // 'nmr_links.data'
      MCSLST = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // 'mcsg.lst'
      OBSFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // 'supersede.dat'
      PATFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // '3dp.matches.list'
      PDBENT = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // 'pdb_EC'
      PRNFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // 'PRINTSvsPDB'
      RVLFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // 'rfactors.data'
      SWIFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // 'pdbtosp.txt'
      TITFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // 'cath.titles'
      TITFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP //
     -     'cath-b-newest-names'
      CATFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP //
     -     'cath-b-newest-latest-release'
      TOFFIL = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // '3dp.tof.list'
      UNPLST = SUMDAT(1:LENSTR(SUMDAT)) // DIRSEP // 'unpubrefs.list'

C---- Open the Het Group Dictionary file
      CALL OPNHET(HGDFIL,IFAIL)

C---- Read in the data items from the secsurf.out file
      CALL SECDAT

C---- Read in the unique chains from the chains.dat file
      CALL CHUNIQ

C---- If not PDBsum1, check various PDBsum data files
      IF (.NOT.PDBSM1) THEN

C----     Check whether this is an obsolete entry
         CALL GETOBS(PDBCOD)

C----     Check whether we have species GIF files to display
         CALL GETSPE(BRCODE)
      ENDIF

C---- Read in the header data from the PDB file
      CALL PDBHED
      IF (IFAIL) GO TO 999

C---- Process the COMPND entries to extract the molecule and E.C. number
C     information
      CALL PROCMP

C---- Process the SOURCE entries to splice out any unwanted keywords
      CALL PROSRC

C---- If R-factor not found then see if it is in the IDITIS-generated
C     file
      IF (RFACT.LE.0.0 .AND. .NOT.PDBSM1) THEN
          CALL GETRVL
      ENDIF

C---- Check whether have PROCHECK information on this file
      HAVCHK = .FALSE.
      NOREAD = .FALSE.
      IF (NCHAIN.GT.0) THEN
         IF (PDBSM1) THEN
             CALL CHKCHK(HAVCHK)
         ELSE
            CALL CHKLNK(PDBSUM,'procheck.html',HAVCHK,NOREAD)
         ENDIF
      ENDIF

C---- Check whether have PROMOTIF information on this file
      CALL CHKLNK(PDBSUM,'promotif.html',HAVPRO,NOREAD)
      IF (.NOT.HAVPRO) THEN
         CALL CHKLNK(PDBSUM,'../promotif/promotif.html',HAVPRO,NOREAD)
      ENDIF
      
C---- Count toal number of ligands
      NLIG = 0
      DO 100, IENTRY = 1, NLIGAN
          NLIG = NLIG + NTIMES(IENTRY,LIG)
 100  CONTINUE
      IF (NLIG.GT.0) HAVLIG = .TRUE.

C---- Check whether this PDB code has entires in Stuart Moodie's Unpublished
C     references database
      IF (.NOT.PDBSM1) THEN
         CALL CHKUNP(PDBCOD)
      ENDIF

C---- P R O C E S S   T H E    D A T A    R E A D    I N

C---- Initialise variables
      CALL INITS(ECTMPL,NUMLEN,CLENTH)

C---- Get the E.C. number(s) from the pdb_EC file
      IF (.NOT.PDBSM1) THEN
         CALL OPENTR(PDBENT,IFAIL)
         IF (.NOT.IFAIL) THEN
            CALL GETEC(BRCODE,ECCODE,EENTRY,NAMLEN,NLEN,MXENTR,NEC,
     -           ECTMPL,NUMLEN,IFAIL) 
            IF (NEC.GT.1) THEN
               WRITE(12,120) BRCODE, (EENTRY(IEC), IEC = 1, NEC)
 120           FORMAT(A4,' xxx E.C. numbers: ',10A12)
            ENDIF
         ENDIF

C----    Get the NDB number (where relevant) from the pdb_NDB file
         CALL OPENDB(PDBNDB,IFAIL)
         IF (.NOT.IFAIL) THEN
            CALL GETNDB(PDBCOD,NDBREF,IFAIL)
         ENDIF

C----    Open the new-format CATH numbers file and read numbers in
         CALL OPNNEW(CATFIL,CATPDB,CATNUM,DOMPDB,DOMNUM,MXCATH,NUMLEV,
     -        IFAIL)
         IF (.NOT.IFAIL) THEN
            CALL REANEW(CATPDB,CATNUM,NCATH,DOMPDB,DOMNUM,NDOMS,MXCATH,
     -           NUMLEV,IFAIL)
         ENDIF
         IFAIL = .FALSE.


C---- Open the CATH numbers file and read numbers in
C      CALL OPNCAT(CATFIL,CATPDB,CATNUM,MXCATH,NUMLEV,IFAIL)
C      IF (.NOT.IFAIL) THEN
C          CALL REACAT(CATPDB,CATNUM,NCATH,MXCATH,NUMLEV,IFAIL)
C      ENDIF
C      IFAIL = .FALSE.

C---- Open the CATH domains file and read in number of domains
C     for each PDB chain
C      CALL OPNDOM(DOMFIL,DOMPDB,DOMNUM,MXCATH,IFAIL)
C      IF (.NOT.IFAIL) THEN
C          CALL READOM(DOMPDB,DOMNUM,NDOMS,MXCATH,IFAIL)
C      ENDIF
C      IFAIL = .FALSE.

C----    Open the CATH titles file and read names in
         CALL OPNTIT(TITFIL,CATLEV,CATDSC,MXTITL,NUMLEV,IFAIL)
         IF (.NOT.IFAIL) THEN
            CALL REATIT(CATLEV,CATDSC,NTITLE,MXTITL,NUMLEV,IFAIL)
         ENDIF
         IFAIL = .FALSE.

C----    Get links to any SWISS-PROT entries for this PDB code
         SLEN = INDEX(SWIFIL,' ') - 1
         ALEN = INDEX(SWADDR,' ') - 1
COUT      IF (NSWISS.EQ.0) THEN
COUT          CALL SWISS
COUT      ENDIF

C----    Open the PRINTS data file and read codes in
         CALL OPNPRN(PRNFIL,IFAIL)
         IF (.NOT.IFAIL) THEN
            CALL REAPRN(BRCODE,PRCODE,PRNPDB,PRNUM,MXPCOD,MXPRIN,NPCODE,
     -           NPRLNK,IFAIL)
         ENDIF
         IFAIL = .FALSE.

C----    Check if there might be a link to a related entry (eg linked
C        entries containing NRM ensemble and ave. en. minimized structure)
         CALL GETLNK
      ENDIF

C---- Check whether have side-views
      CALL CHKVEW
 
C---- Check which RasMol and VRML viewers can be called
      CALL CHKVIE

C---- Interpret type-setting characters in title
      CALL TYPSET(PDILEN,NTLINE,TITLE,.FALSE.)

C---- Interpret type-setting characters in compound
      CALL TYPSET(PDILEN,NCLINE,COMPND,.FALSE.)

C---- Interpret type-setting characters in source
      CALL TYPSET(PDILEN,NSLINE,SOURCE,.FALSE.)

C---- Convert header
      IF (HEADER(1:3).NE.'APC') THEN
          CALL TYPSET(PDILEN,1,HEADER,.FALSE.)

      ENDIF

C---- Convert date
      CALL TYPSET(11,1,DATE,.TRUE.)

C---- Convert release date
      CALL TYPSET(11,1,RLDATE,.TRUE.)

C---- Convert author list
      CALL TYPSET(PDILEN,NALINE,AUTHOR,.TRUE.)

C---- Convert REMARK 5 records
      CALL TYPSET(PDILEN,NRLINE,REM5,.FALSE.)

C---- O U T P U T    T H E    D A T A    T O    H T M L    F I L E

C---- Open ouput files
C      OPEN(UNIT=7,FILE='main_old.html',STATUS='UNKNOWN',
CCVAX     -    CARRIAGECONTROL='LIST',RECL=RECLEN,
C     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=900)
COUT      OPEN(UNIT=17,FILE='inph.html',STATUS='UNKNOWN',
COUTCVAX     -    CARRIAGECONTROL='LIST',RECL=RECLEN,
COUT     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=902)
      OPEN(UNIT=19,FILE='main.html',STATUS='UNKNOWN',
CVAX     -    CARRIAGECONTROL='LIST',RECL=RECLEN,
     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=904)
      OPEN(UNIT=DBASE,FILE='database.dat',STATUS='UNKNOWN',
CVAX     -    CARRIAGECONTROL='LIST',RECL=RECLEN,
     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=908)

C---- Write out the stored information in html format
 510  FORMAT(10A)
 520  FORMAT(A)
      BFILE = 20

C---- Loop over the two HTML files to be written out (main.html and inph.html)
COUT
C      DO 5000, IFILE = 7, 19, 12
      IFILE = 19
COUT

C----     New-format header from the template
          IF (IFILE.EQ.19) THEN
              CALL NEWHED(IFILE,SUMDAT)

C----     Old-style header details
          ELSE

C----         Title
              CALL WRITIT(IFILE,BRCODE)
          
C----         Small GIF images of the protein
              CALL WRIGIF(IFILE,PDBSUM,BRCODE)
              PLAIN = .FALSE.
                       
C----         Check whether this is an obsolete entry
              IF (OBSOL) THEN

C----             Add link to obsolete entry's successor(s)
                  CALL WRIOBS(IFILE,PDBSUM_TEMPLATE(PDB_CURRENT),
     -                WWWPDB,NSUPER,SPRSDE,MXITEM,DBASE)
              ENDIF
         
C----         For main.html only, write out the various viewers
C              CALL WRIVIE(IFILE,BRCODE,PRODIR,WWWRSC,NATOMS,MXSCRP)
          
C----         Write out the protein header details
C              CALL WRIPRO(IFILE,HEADER,LAYER1,TITLE,NTLINE,COMPND,
C     -            NCLINE,SOURCE,NSLINE,AUTHOR,NALINE,NMR,NMODEL,RESOL,
C     -            RFACT,RFREE,DATE)
         
C----         Write out the table of links to other Web sites
C              CALL WRITAB(IFILE,DOHEAD,BRCODE,PDBCOD,HAVUNP,UNPUBL,
C     -            PDB3DB,IMBJEN,WWWCAT,WWWFSP,WWWMAC,WWWMMD,WWWNDB,
C     -            WWWREP,WWWSCP,WWWYEA,NCHAIN,NNUCL,NDBREF,YEAST,
C     -            HAVCHK,HAVPRO)
          
C----         Write out the E.C. number, if there is one
              IF (NEC.GT.0 .OR. ECNUMB.NE.' ') THEN
                  CALL WRIECN(IFILE,BRCODE,ECNUMB,NEC,EENTRY,MXENTR,
     -                WWWENZ,ENZPTH,NAMLEN,EXPENZ,KYOENZ,WITENZ,NUMLEN,
     -                ECTMPL,DBASE)
   
              ENDIF

C----         Write out any SWISS-PROT links
              IF (NSWISS.GT.0) THEN
C                  CALL WRISWS(IFILE)
              ENDIF

C----         Write out links to PRINTS entries
C              CALL WRIPRN(IFILE,WWWPRN,BRCODE,PRCODE,PRNPDB,PRNUM,
C     -            MXPCOD,MXPRIN,NPCODE)

C----         If have links to related entries, write out flag to
C             database.dat file
              IF (NELINE.GT.0 .OR. NMRLNK .OR. (NSUPER.GT.0 .AND.
     -             .NOT.OBSOL)) THEN
                  WRITE(DBASE,510) 'RELATED_ENTRIES TRUE'
              ENDIF
        
C----         Write out links to related entries
C              CALL WRIREL(IFILE,RELATE,NELINE,ENSLNK,NMRLNK,RELINK,
C     -            LNKCOD,NLINKS,PDBDIR,PDBPRE,PDBSUF,WWWPDB,DIRSEP)
         
C----         Entries superseded by this one
              IF (NSUPER.GT.0 .AND. .NOT.OBSOL) THEN
                  CALL WRISUP(IFILE,SPRSDE,NSUPER,
     -                PDBSUM_TEMPLATE(PDB_CURRENT),WWWPDB,SFOPEN)
              ENDIF

C----         Heading for molecules in the PDB file
              CALL WRIHED(IFILE,BRCODE)
        
          ENDIF

C----     List of PDB components

C----     Second time around, write out the binding-site analysis page
C         and link to auto-generated figures (currently for MCSG
C         structures only)
          IF (IFILE.EQ.19) THEN

C----         Binding-site analysis
              CALL WRIBIN(IFILE,BFILE,HAVBIN,BINPAG)
          
C----         Write link to functional analysis report
              CALL WRIFUN(IFILE)
          
C----         Auto-generated figures
              CALL WRIFIG(IFILE)
           
          ENDIF

C----     If have PROCHECK analysis, write out flag to database.dat file
          IF (HAVCHK) THEN
              WRITE(DBASE,510) 'PROCHECK TRUE'
          ENDIF

C----     If have entry in unpublished references list, write out
          IF (HAVUNP) THEN
              WRITE(DBASE,510) 'UNPUB_REFS TRUE'
          ENDIF

C----     Process all the chains
          CALL WRICHN(IFILE,BFILE,HAVBIN,BINPAG)
           
C----     Process all the nucleic acid chains
          CALL WRINUC(IFILE)
   
C----     Write link to NUCPLOT, if present
          CALL NUCPLT(IFILE)
          
C----     Process all the ligands
          CALL WRILIG(IFILE)
         
C----     Process any metals
          CALL WRIMET(IFILE,DBASE,WWWHET,METYPE,NMETYP,NMETAL)
           
C----     Process any extra, unidentified entries
          CALL WRIEXT(IFILE,EXTRA,NUMEXT,NEXTRA)
         
C----     Show the numbers of waters
          CALL WRIWAT(IFILE,DBASE,NWATER)
       
C----     Close off the HTML page
          CALL WRIEND(IFILE,WWWPDB)
     
C----     If have a binding-sites page, close it off
          IF (HAVBIN .AND. BINPAG) CALL WRIBND(BFILE)

COUT  5000 CONTINUE

C---- If there is an existing database.dat file in the PDBsum directory
C     copy across any info added to it by external programs (eg such as
C     catres for the CSA catalytic residue info)
      CALL GETDAT(PDBSUM,DBASE)

      GO TO 999

C---- File-read errors
 900  CONTINUE
      PRINT*, '*** ERROR - Unable to open output file: main.html'
      GO TO 999

 902  CONTINUE
      PRINT*, '*** ERROR - Unable to open output file: inph.html'
      GO TO 999

 904  CONTINUE
      PRINT*, '*** ERROR - Unable to open output file: main_new.html'
      GO TO 999

 906  CONTINUE
      PRINT*, '*** ERROR - Unable to open output file: trace.html'
      GO TO 999

 908  CONTINUE
      PRINT*, '*** ERROR - Unable to open output file: database.dat'
      GO TO 999

 999  CONTINUE
      END

        
C----------------------------------------------------------------------+---
C**************************************************************************
C
C  SUBROUTINE GETPTH  -  Get the paths to the files that may be required
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETPTH(SUMDAT,FAKE,HGDFIL,NMRDIR,FILEN)

      CHARACTER*4   FAKE
      CHARACTER*(*) HGDFIL, NMRDIR, SUMDAT
      INTEGER       FILEN

C---- Locate PDBSUM_REAL_DATA_DIR parameter
      CALL GETPAR('PDBSUM_REAL_DATA_DIR',SUMDAT,FILEN)

C---- Locate FAKE_PDB_ENTRY parameter
      CALL GETPAR('FAKE_PDB_ENTRY',FAKE,4)

C---- Locate HETGROUP_DICTIONARY parameter
      CALL GETPAR('HETGROUP_DICTIONARY',HGDFIL,FILEN)

C---- Locate NMRMIR_DIR parameter
      CALL GETPAR('NMRMIR_DIR',NMRDIR,FILEN)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETMCS  -  Determine whether this is an MCSG file
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETMCS(BRCODE,FILNAM,MCSG)

      CHARACTER*1   CH
      CHARACTER*4   BRCODE
      CHARACTER*(*) FILNAM
      CHARACTER*120 INREC
      INTEGER       LINE
      LOGICAL       MCSG

C---- Initialise flag
      MCSG = .FALSE.

C---- Check whether this is an MCSG structure that hasn't yet been
C     submitted to the PDB (ie first character of code is non-numeric)
      CH = BRCODE(1:1)
      IF ((LLT(CH,'0') .OR. LGT(CH,'9'))) MCSG = .TRUE.

C---- If this an MCSG structure, then return
      IF (MCSG) RETURN

C---- Open input file, mcsg.dat
      OPEN(UNIT=2,FILE=FILNAM,STATUS='OLD',
CVAX     -    CARRIAGECONTROL='LIST',READONLY,
     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=900)

C---- Loop while reading through input file to find if given PDB code
C     corresponds to an MCSG structure
100   CONTINUE

C----     Read in the next record from the input file(s)
          READ(2,110,ERR=904,END=500) INREC
110       FORMAT(A)
          LINE = LINE + 1

C----     If this is our PDB code, then have an MCSG structure
          IF (INREC(1:4).EQ.BRCODE) THEN

C----         Set flag
              MCSG = .TRUE.
          ENDIF

C---- Loop back for next record
      IF (.NOT.MCSG) GO TO 100

C---- End of file reached
500   CONTINUE

C---- Close the file
      CLOSE(2)

      GO TO 999

C---- File-read errors
900   CONTINUE
      PRINT*, '*** ERROR - Unable to open MCSG list file, mcsg.dat'
      GO TO 999

904   CONTINUE
      PRINT*, '*** Read error on input file at line ', LINE + 1
      PRINT 110, INREC
      GO TO 999

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE OPNHET  -  Open the Het Group Dictionary file
C
C----------------------------------------------------------------------+---

      SUBROUTINE OPNHET(HGDFIL,IFAIL)

      CHARACTER*120 HGDFIL
      INTEGER       LENSTR
      LOGICAL       IFAIL

C---- Open the file
      OPEN(UNIT=18, FILE=HGDFIL, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

      GO TO 999

C---- Fatal errors
900   CONTINUE
      PRINT*, '*** ERROR. Unable to open Het Group Dictionary'
      PRINT*, '***        ', HGDFIL(1:LENSTR(HGDFIL))
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE SECDAT  -  Read in the data from the secsurf.out file
C
C----------------------------------------------------------------------+---

      SUBROUTINE SECDAT

      INCLUDE 'pdbhtml.inc'

      CHARACTER*120 FULNAM
      CHARACTER*(RECLEN) INREC
      INTEGER       IENTRY, ILINE, ITEM, LENSTR, LINE, N, NATT, NHET,
     -              NONS
      LOGICAL       CHNFST, LIGFST, NUCFST
      LOGICAL       FOUND

C---- Initialise variables
      CHNFST = .TRUE.
      LIGFST = .TRUE.
      NUCFST = .TRUE.

C---- Open input file, secsurf.out
      IF (PDBSM1) THEN
         FULNAM = PDBSUM(1:LENSTR(PDBSUM)) // '/newsec/secsurf.out'
      ELSE
         FULNAM = PDBSUM(1:LENSTR(PDBSUM)) // '/secsurf.out'
      ENDIF
CDEBUG
C      INQUIRE(FILE=FULNAM,EXIST=FOUND)
C      PRINT*, 'PDBsum dir: [', PDBSUM(1:LENSTR(PDBSUM)), ']'
C      PRINT*, 'File: [', FULNAM(1:LENSTR(FULNAM)), '] FOUND=', FOUND
CDEBUG
      OPEN(UNIT=1,FILE=FULNAM,STATUS='OLD',
CVAX     -    CARRIAGECONTROL='LIST',READONLY,
     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=900)

C---- Loop while reading through input file, storing any information
C     encountered
100   CONTINUE

C----     Read in the next record from the input file(s)
          READ(1,110,ERR=904,END=500) INREC
110       FORMAT(A)
          LINE = LINE + 1

C----     Process according to key-word encountered in this line
C----     PDB code
          IF (INREC(1:8).EQ.'PDB code') THEN
CXXX              BRCODE = INREC(11:14)

C----     Resolution
          ELSE IF (INREC(1:10).EQ.'Resolution') THEN
              READ(INREC,220,ERR=904) RESOL
 220          FORMAT(11X,F9.0)

C----     R-factor
          ELSE IF (INREC(1:8).EQ.'R-factor') THEN
              READ(INREC,220,ERR=904) RFACT

C----     R-free
          ELSE IF (INREC(1:6).EQ.'R-free') THEN
              READ(INREC,220,ERR=904) RFREE

C----     NMR structure
          ELSE IF (INREC(1:13).EQ.'NMR structure') THEN
              READ(INREC,240,ERR=904) NMODEL
 240          FORMAT(15X,I6)
              NMR = .TRUE.

C----     Ensemble of crystal structures
          ELSE IF (INREC(1:11).EQ.'Ensemble of') THEN
              READ(INREC,250,ERR=904) NMODEL
 250          FORMAT(12X,I6)
              NMR = .FALSE.

C----     Chain information
          ELSE IF (INREC(1:5).EQ.'CHAIN') THEN

C----         Get the chain number
              IF (INREC(9:9).EQ.' ') THEN
                  READ(INREC,260,IOSTAT=RERROR) IENTRY
 260              FORMAT(5X,I3)
              ELSE IF (INREC(10:10).EQ.' ') THEN
                  READ(INREC,270,IOSTAT=RERROR) IENTRY
 270              FORMAT(5X,I4)
              ELSE
                  READ(INREC,275,IOSTAT=RERROR) IENTRY
 275              FORMAT(5X,I5)
              ENDIF
              IF (RERROR.EQ.0 .AND. IENTRY.LE.MXNTRY) THEN
                  READ(INREC,280,IOSTAT=RERROR) CHAIN(IENTRY,CHN),
     -                NRESID(IENTRY,CHN), CALPHA(IENTRY),
     -                CHNCOL(IENTRY), NHELIX(IENTRY), NSTRND(IENTRY)
 280              FORMAT(10X,A1,10X,I8,3X,A2,6X,A10,9X,I4,10X,I4)
                  IF (RERROR.NE.0) THEN
                      PRINT*, '* WARNING. Data error at line ', LINE
                      PRINT*, INREC
                  ENDIF
                  ILINE = 0
                  ITEM = CHN
                  NCHAIN = IENTRY
              ELSE IF (CHNFST) THEN
                  PRINT*, '*** Warning. Maximum number of entries,',
     -                ' MXNTRY exceeded for chains', MXNTRY
                  PRINT*, INREC
                  CHNFST = .FALSE.
              ENDIF
              NATT = 0
              NHET = 0
              NONS = 0

C----     Nucleic acid chains
          ELSE IF (INREC(1:5).EQ.'NUCLE') THEN

C----         Get the chain number
              IF (INREC(9:9).EQ.' ') THEN
                  READ(INREC,260,IOSTAT=RERROR) IENTRY
              ELSE IF (INREC(10:10).EQ.' ') THEN
                  READ(INREC,270,IOSTAT=RERROR) IENTRY
              ELSE
                  READ(INREC,275,IOSTAT=RERROR) IENTRY
              ENDIF
              IF (RERROR.EQ.0 .AND. IENTRY.LE.MXNTRY) THEN
                  READ(INREC,320,IOSTAT=RERROR) CHAIN(IENTRY,NUC),
     -                NRESID(IENTRY,NUC), NUCCOL(IENTRY)
 320              FORMAT(10X,A1,10X,I8,11X,A10)
                  IF (RERROR.NE.0) THEN
                      PRINT*, '* WARNING. Data error at line ', LINE
                      PRINT*, INREC
                  ENDIF
                  ILINE = 0
                  ITEM = NUC
                  NNUCL = IENTRY
              ELSE
                  PRINT*, '*** Warning. Maximum number of entries,',
     -                ' MXNTRY exceeded for DNA/RNA chains', MXNTRY
                  PRINT*, INREC
              ENDIF
              NATT = 0
              NHET = 0
              NONS = 0

C----     Ligand information
          ELSE IF (INREC(1:5).EQ.'LIGAN') THEN

C----         Get the ligand number
              IF (INREC(9:9).EQ.' ') THEN
                  READ(INREC,260,IOSTAT=RERROR) IENTRY
              ELSE IF (INREC(10:10).EQ.' ') THEN
                  READ(INREC,270,IOSTAT=RERROR) IENTRY
              ELSE
                  READ(INREC,275,IOSTAT=RERROR) IENTRY
              ENDIF
              IF (RERROR.EQ.0 .AND. IENTRY.LE.MXNTRY) THEN
                  READ(INREC,340,IOSTAT=RERROR) CHAIN(IENTRY,LIG),
     -                NRESID(IENTRY,LIG), NTIMES(IENTRY,LIG),
     -                NBONDS(IENTRY)
 340              FORMAT(10X,A1,10X,I8,10X,I4,9X,I4)
                  IF (RERROR.NE.0) THEN
                      PRINT*, '* WARNING. Data error at line ', LINE
                      PRINT*, INREC
                  ENDIF
                  ILINE = 0
                  ITEM = LIG
                  NLIGAN = IENTRY
              ELSE IF (LIGFST) THEN
                  PRINT*, '*** Warning. Maximum number of entries,',
     -                ' MXNTRY exceeded on ligands', MXNTRY
                  PRINT*, INREC
                  LIGFST = .FALSE.
              ENDIF
              NATT = 0
              NHET = 0
              NONS = 0

C----     If this is a sequence, stored for the appropriate chain or
C         ligand
          ELSE IF (INREC(1:1).EQ.'*' .AND. ITEM.NE.0 .AND.
     -        IENTRY.GT.0 .AND. IENTRY.LE.MXNTRY) THEN

C----         Increment line-count
              ILINE = ILINE + 1
              IF (ILINE.GT.MXLINE) THEN
                  PRINT*, '* WARNING. Maximum number of sequence lines',
     -                ', MXLINE, exceeded', MXLINE
                  PRINT*, INREC
              ELSE
                  SEQUEN(ILINE,IENTRY,ITEM) = INREC(2:)
              ENDIF

C----     If this is information on non-standard amino acids, then store
          ELSE IF (INREC(1:20).EQ.'Non-standard residue') THEN

C----         Increment count of these
              NONS = NONS + 1
              IF (NONS.GT.MXNONS) THEN
                  PRINT*, '* WARNING. Maximum number of non-standard',
     -                'residues, MXNONS, exceeded', MXNONS
                  PRINT*, INREC
              ELSE
                  READ(INREC,350,IOSTAT=RERROR)
     -                ATTNAM(NONS,IENTRY,1,ITEM),
     -                ACOUNT(NONS,IENTRY,1,ITEM)
                  IF (RERROR.NE.0) THEN
                      PRINT*, '* WARNING. Data error at line ', LINE
                      PRINT*, INREC
                  ENDIF
              ENDIF

C----     If this is information on HETATMs then store
          ELSE IF (INREC(1:9).EQ.'HET group') THEN

C----         Increment count of these
              NHET = NHET + 1
              IF (NHET.GT.MXNONS) THEN
                  PRINT*, '* WARNING. Maximum number of HETATM gps',
     -                ', MXNONS, exceeded', MXNONS
                  PRINT*, INREC
              ELSE IF (IENTRY.LE.MXNTRY) THEN
                  READ(INREC,350,IOSTAT=RERROR)
     -                ATTNAM(NHET,IENTRY,2,ITEM),
     -                ACOUNT(NHET,IENTRY,2,ITEM)
                  IF (RERROR.NE.0) THEN
                      PRINT*, '* WARNING. Data error at line ', LINE
                      PRINT*, INREC
                  ENDIF
              ENDIF

C----     If this is information on attached groups, then store
          ELSE IF (INREC(1:12).EQ.'Attached HET') THEN

C----         Increment count of these
              NATT = NATT + 1
              IF (NATT.GT.MXNONS) THEN
                  PRINT*, '* WARNING. Maximum number of attached gps',
     -                ', MXNONS, exceeded', MXNONS
                  PRINT*, INREC
              ELSE IF (IENTRY.LE.MXNTRY) THEN
                  READ(INREC,350,IOSTAT=RERROR)
     -                ATTNAM(NATT,IENTRY,3,ITEM),
     -                ACOUNT(NATT,IENTRY,3,ITEM)
 350              FORMAT(23X,A3,I6)
                  IF (RERROR.NE.0) THEN
                      PRINT*, '* WARNING. Data error at line ', LINE
                      PRINT*, INREC
                  ENDIF
              ENDIF

C----     Metal information
          ELSE IF (INREC(1:5).EQ.'METAL') THEN
              NMETAL = NMETAL + 1
              IF (NMETAL.LE.MXMETP) THEN
                  METYPE(NMETAL) = INREC(7:10)
                  READ(INREC,360,IOSTAT=RERROR) NMETYP(NMETAL)
 360              FORMAT(10X,I6)
                  IF (RERROR.NE.0) THEN
                      PRINT*, '* WARNING. Data error at line ', LINE
                      PRINT*, INREC
                  ENDIF
              ELSE
                  PRINT*, '*** ERROR. Maximum number of metal types,',
     -                ' MXMETP, exceeded', MXMETP
                  PRINT*, INREC
              ENDIF

C----     Extra (unidentified) one-atom residues
          ELSE IF (INREC(1:5).EQ.'EXTRA') THEN
              NEXTRA = NEXTRA + 1
              IF (NEXTRA.LE.MXEXTR) THEN
                  EXTRA(NEXTRA) = INREC(7:10)
                  READ(INREC,360,IOSTAT=RERROR) NUMEXT(NEXTRA)
                  IF (RERROR.NE.0) THEN
                      PRINT*, '* WARNING. Data error at line ', LINE
                      PRINT*, INREC
                  ENDIF
              ELSE
                  PRINT*, '*** ERROR. Maximum number of extras,',
     -                ' MXEXTR, exceeded', MXEXTR
                  PRINT*, INREC
              ENDIF

C----     Number of chains
CXXX          ELSE IF (INREC(1:16).EQ.'Number of chains') THEN
CXXX              READ(INREC,380,ERR=904) NCHAIN
 380          FORMAT(30X,I8)

CXXX          ELSE IF (INREC(1:16).EQ.'Number of nucleo') THEN
CXXX              READ(INREC,380,ERR=904) NNUCL

C----     Number of water molecules
          ELSE IF (INREC(1:16).EQ.'Number of waters') THEN
              READ(INREC,380,ERR=904) NWATER

C----     Number of ATOM records
          ELSE IF (INREC(1:22).EQ.'Number of ATOM records') THEN
              READ(INREC,380,ERR=904) N
              NATOMS = NATOMS + N

C----     Number of HETATM records
          ELSE IF (INREC(1:24).EQ.'Number of HETATM records') THEN
              READ(INREC,380,ERR=904) N
              NATOMS = NATOMS + N

C----     Number of ligands
CXXX          ELSE IF (INREC(1:17).EQ.'Number of ligands') THEN
CXXX              READ(INREC,380,ERR=904) NLIGAN

C----     Number of hydrogens
          ELSE IF (INREC(1:20).EQ.'Number of hydrogens') THEN
              READ(INREC,380,ERR=904) NHYDRO

          ENDIF

      GO TO 100

C---- End of file reached
500   CONTINUE

C---- IF this is an NMR structure, then adjust total number of atoms
      IF (NMODEL.GT.0) THEN
          NATOMS = NATOMS / NMODEL
      ENDIF

C---- Close the file
      CLOSE(1)

      GO TO 999

C---- File-read errors
900   CONTINUE
      PRINT*, '*** ERROR - Unable to open secsurf.out file'
      PRINT*, '***         ', FULNAM(1:LENSTR(FULNAM))
      GO TO 999

904   CONTINUE
      PRINT*, '*** Read error on input file at line ', LINE + 1
      PRINT 110, INREC
      GO TO 999

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE CHUNIQ  -  Read in the unique chains from the chains.dat
C                        file
C
C                        All unique stored as:      A  B  C  D  E  F
C                                      DUPLIC:      1  2  3  4  5  6
C                                      NXTCHN:      0  0  0  0  0  0
C                                             
C                        A-D and B-C-E-F as:        A  B  C  D  E  F
C                                      DUPLIC:      1  2  0  0  0  0
C                                      NXTCHN:      4  3  5  0  6  0
C
C----------------------------------------------------------------------+---

      SUBROUTINE CHUNIQ

      INCLUDE 'pdbhtml.inc'

      CHARACTER     INCHN, COPYOF
      CHARACTER*120 FULNAM
      CHARACTER*(RECLEN) INREC
      INTEGER       CCHAIN, ICHAIN, IENTRY, LEN, LENSTR, LINE, LSTCHN,
     -              NXTLNK, OCHAIN
      LOGICAL       FOUND


C---- Initialise assignment, taking each chain to be unique
      DO 50, ICHAIN = 1, NCHAIN
          DUPLIC(ICHAIN) = ICHAIN
          NXTCHN(ICHAIN) = 0
 50   CONTINUE
      NUNIQ = NCHAIN

C---- If have more than one protein chain, get which ones are unique
      IF (NCHAIN.GT.1) THEN

C----     Initialise line-count
          LINE = 0

C----     Open input file, chains.dat
          IF (PDBSM1) THEN
             FULNAM = PDBSUM(1:LENSTR(PDBSUM)) // '/newsec/chains.dat'
          ELSE
             FULNAM = PDBSUM(1:LENSTR(PDBSUM)) // '/chains.dat'
          ENDIF
          OPEN(UNIT=1,FILE=FULNAM,STATUS='OLD',
CVAX         -    CARRIAGECONTROL='LIST',READONLY,
     -        ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=900)

C----     Re-initialise count of unique chains
          NUNIQ = 0

C----     Loop while reading through input file, storing any information
C         encountered
 100      CONTINUE

C----         Read in the next record from the input file(s)
              READ(1,110,ERR=904,END=500) INREC
 110          FORMAT(A)
              LINE = LINE + 1

C----         Get the legnth of this line
              LEN = LENSTR(INREC)

C----         If line-length is zero, then have chain blank
              IF (LEN.EQ.0) LEN = 1

C----         Get the chain */
              INCHN = INREC(1:1)

C----         Determine which chain this is
              CCHAIN = 0
              DO 200, ICHAIN = 1, NCHAIN
                  IF (INCHN.EQ.CHAIN(ICHAIN,CHN)) CCHAIN = ICHAIN
 200          CONTINUE

C----         If this is a copy of another chain, store that
              IF (CCHAIN.GT.0 .AND. LEN.GT.2) THEN
                  COPYOF = INREC(3:3)

C----             Determine which chain this is
                  OCHAIN = 0
                  DO 300, ICHAIN = 1, NCHAIN
                      IF (COPYOF.EQ.CHAIN(ICHAIN,CHN)) THEN
                          OCHAIN = ICHAIN
                      ENDIF
 300              CONTINUE

C----             Mark current chain as a copy
                  DUPLIC(CCHAIN) = 0

C----             Get first link, if any, from the original chain
                  NXTLNK = NXTCHN(OCHAIN)
                  LSTCHN = OCHAIN

C----             Chase down any previous duplicates of the current
C                 chain to get the last one to point here
 400              CONTINUE

C----                 If the next link is not zero, then get the
C                     next link and loop back
                      IF (NXTLNK.NE.0) THEN

C----                     Get the next link and store current chain
C                         position
                          LSTCHN = NXTLNK
                          NXTLNK = NXTCHN(NXTLNK)

C----                     Loop back
                          GO TO 400
                      ENDIF

C----             Have the last member of the chain list, so get it
C                 to point to our newly found copy
                  NXTCHN(LSTCHN) = CCHAIN

C----         Otherwise, this is a unique chain
              ELSE IF (CCHAIN.GT.0) THEN

C----             Store as a unique chain
                  DUPLIC(CCHAIN) = CCHAIN

C----             Increment chain count */
                  NUNIQ = NUNIQ + 1
              ENDIF

          GO TO 100

C----     End of file reached
 500      CONTINUE

C----     Close the file
          CLOSE(1)
      ENDIF

      GO TO 999

C---- File-read errors
900   CONTINUE
      PRINT*, '*** ERROR - Unable to open chains.dat file'
      GO TO 999

904   CONTINUE
      PRINT*, '*** Read error on chains.dat file at line ', LINE + 1
      PRINT 110, INREC
      GO TO 999

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETOBS  -  Check the list of superseded entries to check if
C                        this one is obsolete
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETOBS(PDBCOD)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*4   CODE, PDBCOD
      CHARACTER*120 IREC
      INTEGER       IENTRY, IPOS, LINE

C---- Open the data file holding the list of superseded entries
      OPEN(UNIT=15, FILE=OBSFIL, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

C---- Initialise variables
      PRINT*
      PRINT*, 'Checking if entry is obsolete ...'
      LINE = 0
      NSUPER = 0

C---- Read through the links file
 100  CONTINUE

C----     Read in a record from the file
          READ(15,120,END=500,ERR=902) IREC
 120      FORMAT(A)
          LINE = LINE + 1
          IPOS = 38

C----     Loop through the list of obsolete codes to see if this is one
C         of them
          DO 300, IENTRY = 1, 8

C----         Get the code at this position
              CODE = IREC(IPOS:IPOS+3)

C----         If this is the current code, then have an obsolete entry
              IF (CODE.EQ.PDBCOD) THEN

C----             Set flag to signify entry is obsolete
                  OBSOL = .TRUE.

C----             Get the superseding code
                  CODE = IREC(1:4)

C----             Store this code, if have room
                  IF (NSUPER.LT.MXITEM) THEN

C----                 Increment count of links and store
                      NSUPER = NSUPER + 1
                      SPRSDE(NSUPER) = CODE

C----             Otherwise, display warning message
                  ELSE
                      PRINT*, '*** Warning. Max. number of superseding',
     -                    ' entries exceeded:', MXITEM
                      GO TO 500
                  ENDIF
              ENDIF

C----         Increment position along line
              IPOS = IPOS + 5
 300      CONTINUE

C---- Loop back for next record in file
      GO TO 100

C---- End of file reached
 500  CONTINUE

C---- Close the file
      CLOSE(15)

      GO TO 999

C---- Errors
 900  CONTINUE
      PRINT*, '*** Unable to open superseded entries file'
      GO TO 999

 902  CONTINUE
      PRINT*, '*** ERROR. File error in superseded entries file at lin',
     -    'e:', LINE + 1
      GO TO 999

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETSPE  -  Check the species.dat file to determine whether
C                        there are any species GIF files to be displayed
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETSPE(PDBCOD)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*4   PDBCOD
      CHARACTER*120 IREC
      INTEGER       LINE
      LOGICAL       READIN

C---- Open the data file holding the list of superseded entried
      OPEN(UNIT=15, FILE=SPEFIL, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

C---- Initialise variables
      PRINT*
      PRINT*, 'Checking for species GIF file(s) ...'
      LINE = 0
      NSPECI = 0
      READIN = .FALSE.

C---- Read through the links file
 100  CONTINUE

C----     Read in a record from the file
          READ(15,120,END=500,ERR=902) IREC
 120      FORMAT(A)
          LINE = LINE + 1

C----     Process if line not a comment or blank line
          IF (IREC(1:1).NE.'#' .AND. IREC(1:1).NE.' ') THEN

C----         Check whether this is our PDB code
              IF (IREC(1:4).EQ.PDBCOD) THEN

C----             Set flag to indicate we have one or more GIF files
C                 for our code
                  READIN = .TRUE.

C----             Store the name of the GIF file, if have room
                  IF (NSPECI.LT.MXSPEC) THEN

C----                 Increment count of links and store
                      NSPECI = NSPECI + 1
                      SPEGIF(NSPECI) = IREC(6:)

C----             Otherwise, display warning message
                  ELSE
                      PRINT*, '*** Warning. Max. number of species',
     -                    ' GIFs exceeded:', MXSPEC
                      GO TO 500
                  ENDIF

C----         Otherwise, if this is the PDB code after our one, then
C             can stop
              ELSE IF (READIN) THEN
                  GO TO 500
              ENDIF
          ENDIF

C---- Loop back for next record in file
      GO TO 100

C---- End of file reached
 500  CONTINUE

C---- Close the file
      CLOSE(15)

      GO TO 999

C---- Errors
 900  CONTINUE
      PRINT*, '*** Unable to open species.dat file'
      GO TO 999

 902  CONTINUE
      PRINT*, '*** ERROR. File error in species.dat file at line:',
     -    LINE + 1
      GO TO 999

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE PDBHED  -  Read in the data from the PDB header records
C
C----------------------------------------------------------------------+---

      SUBROUTINE PDBHED

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   INCHN
      CHARACTER*4   CODE
      CHARACTER*12  SWCODE
      CHARACTER*(RECLEN) INREC
      CHARACTER*70  TMPSTR
      CHARACTER*120 FULNAM
      INTEGER       ICODE, IPOS, JPOS, KPOS, LENSTR, LINE
      LOGICAL       ATEND, FOPEN, WANTED

C---- Initialise variables
      ATEND = .FALSE.
      FOPEN = .FALSE.

C---- Check if there's a "fixed" version of the PDB file in the "fixed"
C     files directory
      FULNAM = 'file.pdb'
      OPEN(UNIT=1,FILE=FULNAM,STATUS='OLD',
CVAX     -    CARRIAGECONTROL='LIST',READONLY,
     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',IOSTAT=RERROR)

C---- Check for MCSG file
C      IF (RERROR.NE.0) THEN
C          FULNAM = MCSGDR(1:LENSTR(MCSGDR)) // DIRSEP //
C     -        PDBPRE(1:LENSTR(PDBPRE)) // BRCODE // PDBSUF
C          OPEN(UNIT=1,FILE=FULNAM,STATUS='OLD',
CVAX     -        CARRIAGECONTROL='LIST',READONLY,
C     -        ACCESS='SEQUENTIAL',FORM='FORMATTED',IOSTAT=RERROR)
C      ENDIF

C---- Open input PDB file
C      IF (RERROR.NE.0) THEN
C          FULNAM = PDBDIR(1:LENSTR(PDBDIR)) // DIRSEP //
C     -        PDBPRE(1:LENSTR(PDBPRE)) // BRCODE // PDBSUF
C          OPEN(UNIT=1,FILE=FULNAM,STATUS='OLD',
CVAX     -        CARRIAGECONTROL='LIST',READONLY,
C     -        ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=900)
C      ENDIF

C---- For PDBsum1, open file for the header records
      IF (PDBSM1) THEN
         OPEN(UNIT=2,FILE='headers.txt',STATUS='UNKNOWN',
     -        ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=906)

c----     Write out the <PRE> line
          WRITE(2,110) '<PRE>'
      ENDIF

C---- Loop while reading through input file, storing any information
C     encountered
100   CONTINUE

C----     Read in the next record from the input file(s)
          READ(1,110,ERR=904,END=500) INREC
110       FORMAT(A)
          LINE = LINE + 1

C----     Check whether this is a "Layer 1" release
          IPOS = INDEX(INREC,"THIS IS LAYER 1 RELEASE")
          IF (IPOS.GT.0) LAYER1 = .TRUE.

C----     Process according to key-word encountered in this line

C----     Header
          IF (INREC(1:6).EQ.'HEADER') THEN
              HEADER = INREC(11:50)
              DATE = INREC(51:59)

C----     Obsolete entry
          ELSE IF (INREC(1:6).EQ.'OBSLTE') THEN
             OBSOL = .TRUE.

C----     Title
          ELSE IF (INREC(1:6).EQ.'TITLE ') THEN
              NTLINE = NTLINE + 1
              IF (NTLINE.LE.MXITEM) THEN
                  TITLE(NTLINE) = INREC(11:80)
              ELSE
                  PRINT*, '* WARNING. MXITEM exceeded for TITLE'
                  NTLINE = MXITEM
              ENDIF

C----     Compound
          ELSE IF (INREC(1:6).EQ.'COMPND') THEN
              NCLINE = NCLINE + 1
              IF (NCLINE.LE.MXITEM) THEN
                  COMPND(NCLINE) = INREC(11:80)
              ELSE
                  PRINT*, '* WARNING. MXITEM exceeded for COMPND'
                  NCLINE = MXITEM
              ENDIF

C----         If we have no header, and this is a molecule line,
C             use that
              IF (HEADER.EQ.' ' .AND. INREC(12:20).EQ.'MOLECULE:')
     -             THEN
                 HEADER = INREC(22:)
                 IPOS = LENSTR(HEADER)
                 IF (HEADER(IPOS:IPOS).EQ.';') THEN
                    HEADER(IPOS:IPOS) = ' '
                 ENDIF
              ENDIF

C----     Source
          ELSE IF (INREC(1:6).EQ.'SOURCE') THEN
              NSLINE = NSLINE + 1
              IF (NSLINE.LE.MXITEM) THEN
                  SOURCE(NSLINE) = INREC(11:79)
              ELSE
                  PRINT*, '* WARNING. MXITEM exceeded for SOURCE'
                  NSLINE = MXITEM
              ENDIF

C----         If this is a yeast structure, then set flag
              IPOS = INDEX(SOURCE(NSLINE),'YEAST')
              JPOS = INDEX(SOURCE(NSLINE),'SACCHAROMYCES CEREVISIAE')
              KPOS = INDEX(SOURCE(NSLINE),'S. CEREVISIAE')
              IF (IPOS.GT.0 .OR. JPOS.GT.0 .OR. KPOS.GT.0) THEN
                  YEAST = .TRUE.
              ENDIF

C----     Check for MCSG structure
C          ELSE IF (INREC(1:14).EQ.'REMARK    MCSG' .OR.
C     -        INREC(1:15).EQ.'REMARK     MCSG') THEN
C              NOLINK = .TRUE.
C              INCSAS = .FALSE.

C----     Experimental method
          ELSE IF (INREC(1:6).EQ.'EXPDTA') THEN
              NXLINE = NXLINE + 1
              IF (NXLINE.LE.MXITEM) THEN
                  EXPDTA(NXLINE) = INREC(11:79)
                  IF (EXPDTA(NXLINE).EQ.' ') NXLINE = NXLINE - 1
              ELSE
                  PRINT*, '* WARNING. MXITEM exceeded for EXPDTA'
                  NXLINE = MXITEM
              ENDIF

C----         Check whether this is an X-ray structure
              IPOS = INDEX(EXPDTA(NXLINE),'X-RAY DIFFRACTION')
              IF (IPOS.GT.0) THEN
                  XRAY = .TRUE.
              ENDIF

C----         Check for electron microscopy expt
              IPOS = INDEX(EXPDTA(NXLINE),'ELECTRON MICROSCOPY')
              IF (IPOS.GT.0) THEN
                  EMEXPT = .TRUE.
              ENDIF

C----         Check for electron crystallography expt
              IPOS = INDEX(EXPDTA(NXLINE),'ELECTRON CRYSTALLOGRAPHY')
              IF (IPOS.GT.0) THEN
                  ECEXPT = .TRUE.
              ENDIF

C----         Check whether structure solved by NMR
              IPOS = INDEX(EXPDTA(NXLINE),'NMR')
              IF (IPOS.GT.0 .AND. .NOT.NMR) THEN
                  NMR = .TRUE.
                  NMODEL = 1
              ENDIF

C----         Check whether this is a theoretical model
              IPOS = INDEX(EXPDTA(NXLINE),'THEORETICAL MODEL')
              IF (IPOS.GT.0 .AND. .NOT.TMODEL) THEN
                  TMODEL = .TRUE.
              ENDIF

C----     Remark 5
          ELSE IF (INREC(1:10).EQ.'REMARK   5') THEN
              NRLINE = NRLINE + 1
              IF (NRLINE.LE.MXITEM) THEN
                  REM5(NRLINE) = INREC(11:79)
                  IF (REM5(NRLINE).EQ.' ') NRLINE = NRLINE - 1
              ELSE
                  PRINT*, '* WARNING. MXITEM exceeded for REMARK 5'
                  NRLINE = MXITEM
              ENDIF

C----     Authors
          ELSE IF (INREC(1:6).EQ.'AUTHOR') THEN
              NALINE = NALINE + 1
              IF (NALINE.LE.MXITEM) THEN
                  AUTHOR(NALINE) = INREC(11:79)
                  IF (AUTHOR(NALINE).EQ.' ') NALINE = NALINE - 1
              ELSE
                  PRINT*, '* WARNING. MXITEM exceeded for AUTHOR'
                  NALINE = MXITEM
              ENDIF

C----     Release date
          ELSE IF (INREC(1:10).EQ.'REVDAT   1') THEN
              RLDATE = INREC(14:22)

C----     Check if this entry supersedes previous entries (and isn't
C         itself obsolete)
          ELSE IF (INREC(1:6).EQ.'SPRSDE' .AND. .NOT.OBSOL) THEN

C----         Loop through the possible list of superseded entries
              IPOS = 32
              DO 300, ICODE = 1, 9

C----             Get the code
                  CODE = INREC(IPOS:IPOS+3)

C----             If not blank, then store
                  IF (CODE.NE.' ') THEN

C----                 Check that maximum not exceeded
                      IF (NSUPER.LT.MXITEM) THEN
                          NSUPER = NSUPER + 1
                          SPRSDE(NSUPER) = CODE

C----                 Otherwise show warning message
                      ELSE
                          PRINT*, '*** Warning. Maximum number of supe',
     -                        'rsede entries exceeded', MXITEM
                      ENDIF
                  ENDIF

C----             Increment position along the line
                  IPOS = IPOS + 5
 300          CONTINUE

C----         If supersede.add file has not been opened, then do so now
              IF (.NOT.FOPEN) THEN

C----             Open the file
                  OPEN(UNIT=15, FILE='supersede.add', STATUS='UNKNOWN',
     -                FORM='FORMATTED', ACCESS='SEQUENTIAL',
CVAX     -                CARRIAGECONTROL='LIST',
     -                ERR=902)

C----             Open the file
                  FOPEN = .TRUE.
              ENDIF

C----         Write out the SPRSDE record to supersede.add file
              WRITE(15,110) BRCODE // ': ' // INREC(1:70)

C----     Related entries
          ELSE IF (INREC(1:11).EQ.'REMARK 900 ') THEN

C----         Check that this line has something of interest on it
              TMPSTR = INREC(12:70)
              WANTED = .TRUE.

C----         If blank, or just the RELATED ENTRIES line, then don't
C             want it
              IF (TMPSTR.EQ.' ') WANTED = .FALSE.
              IF (TMPSTR(1:15).EQ.'RELATED ENTRIES') THEN
                  TMPSTR = INREC(28:79)
                  IF (TMPSTR.EQ.' ') WANTED = .FALSE.
              ENDIF

C----         If entry is wanted, then store it
              IF (WANTED) THEN
                  NELINE = NELINE + 1
                  IF (NELINE.LE.MXITEM) THEN

C----                 Strip out any superflous text
                      CALL STRPLN(TMPSTR)

C----                 Store the related entry line
                      RELATE(NELINE) = TMPSTR
                      IF (RELATE(NELINE).EQ.' ') NELINE = NELINE - 1
                  ELSE
                      PRINT*, '*** Warning. MXITEM exceeded for RELATE',
     -                    'D ENTRIES'
                      NELINE = MXITEM
                  ENDIF

C----         Otherwise, check that last character of last entry was a 
C             full-stop
              ELSE IF (NELINE.GT.0) THEN

C----             Get position of last non-blank character
                  IPOS = LENSTR(RELATE(NELINE))

C----             If last character is not a full-stop, then add one
                  IF (IPOS.LT.PDILEN) THEN
                      IF (RELATE(NELINE)(IPOS:IPOS).NE.'.') THEN
                          RELATE(NELINE)(IPOS+1:) = '.'
                      ENDIF
                  ENDIF
              ENDIF

C----     Database references
          ELSE IF (INREC(1:6).EQ.'DBREF ') THEN

C----         Check if this line contains a link to a SWISS-PROT code
              IF (INREC(27:29).EQ.'SWS' .AND. INREC(43:43).NE.' ') THEN

C----             Get the chain-id and the code
                  INCHN = INREC(13:13)
                  SWCODE = INREC(43:)

C----             Store the code and chain-id
                  CALL STOSWS(SWCODE,INCHN)
              ENDIF

C----     NDB references for DNA entry
          ELSE IF (INREC(1:10).EQ.'REMARK 100') THEN
              IPOS = INDEX(INREC,'THE NDB ID CODE IS')
              IF (IPOS.GT.0) THEN
                  IPOS = IPOS + 19
                  NDBREF = INREC(IPOS:)

C----             Remove the full stop if there is one
                  IPOS = INDEX(NDBREF,'.')
                  IF (IPOS.GT.0) THEN
                      NDBREF(IPOS:) = ' '
                  ENDIF

C----             Convert into lower case
                  CALL LOWCAS(8,NDBREF)
              ENDIF

C----     If have reached the ATOM records, then can stop reading here
          ELSE IF (INREC(1:6).EQ.'ATOM  ') THEN
              ATEND = .TRUE.
          ENDIF

C----     For PDBsum1, write out to the headers.txt file
          IF (PDBSM1 .AND. .NOT.ATEND) THEN
             WRITE(2,110) INREC(1:LENSTR(INREC))
          ENDIF

C---- Loop back for next record if not at end yet
      IF (.NOT.ATEND) GO TO 100

C---- End of file reached
 500  CONTINUE

C---- Close the supersede.add file if it is open
      IF (FOPEN) CLOSE(15)

C---- For PDBsum1, close the headers.txt file
      IF (PDBSM1) THEN

c----     Write out the </PRE> line
          WRITE(2,110) '</PRE>'

c----     Close the file
          CLOSE(2)
      ENDIF

      GO TO 999

C---- File-read errors
 900  CONTINUE
      PRINT*, '*** ERROR - Unable to open PDB file'
      PRINT*, '*** [', FULNAM(1:LENSTR(FULNAM)), ']'
      GO TO 999

 902  CONTINUE
      PRINT*, '*** ERROR - Unable to open supersede.add file'
      GO TO 999

 904  CONTINUE
      PRINT*, '*** Read error on input file at line ', LINE + 1
      PRINT 110, INREC
      GO TO 999

 906  CONTINUE
      PRINT*, '*** ERROR - Unable to open output headers.txt file'
      GO TO 999

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE STRPLN  -  Strip out any superflous text from the related
C                        entries line
C
C----------------------------------------------------------------------+---

      SUBROUTINE STRPLN(STRING)

      INTEGER       NUNW
      PARAMETER    (NUNW = 2)

      CHARACTER*20  UNWANT(NUNW)
      CHARACTER*70  STRING, TMPSTR

      INTEGER       IFROM, IPOS, ITO, IUNW, LEN, LENSTR

      DATA UNWANT / 'RELATED ID: ', 'RELATED DB: PDB' /

C---- Loop through the unwanted text entries
      DO 400, IUNW = 1, NUNW

C----     Get length of search string
          LEN = LENSTR(UNWANT(IUNW))
          IF (IUNW.EQ.1) LEN = LEN + 1

C----     Check if the given text is in the string
          IPOS = INDEX(STRING,UNWANT(IUNW)(1:LEN))

C----     If present, then strip out
          IF (IPOS.GT.0) THEN

C----         Get start and end of unwanted text
              IFROM = IPOS - 1
              ITO = IPOS + LEN

C----         If text at beginning of line, just transfer the end part
C             of the line across
              IF (IFROM.EQ.0) THEN
                  TMPSTR = STRING(ITO:)

C----         Otherwise, splice out the offending text
              ELSE
                  TMPSTR = STRING(1:IFROM) // STRING(ITO:)
              ENDIF

C----         Transfer back
              STRING = TMPSTR
          ENDIF
 400  CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE STOSWS  -  Store the current SWISS-PROT code
C
C----------------------------------------------------------------------+---

      SUBROUTINE STOSWS(SWCODE,INCHN)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   INCHN
      CHARACTER*12  SWCODE
      INTEGER       ICOL, ISWISS
      LOGICAL       GOTIT

C---- Check whether already have this code
      GOTIT = .FALSE.
      DO 400, ISWISS = 1, NSWISS

C----     If have the code, store its location
          IF (SWCODE.EQ.SWNAME(ISWISS)) THEN

C----         Loop to see whether already have this chain
              GOTIT = .FALSE.
              DO 300, ICOL = 1, NSWCHN(ISWISS)

C----             If already have this chain, then don't need
C                 to do anything else
                  IF (INCHN.EQ.SWICHN(ICOL,ISWISS)) THEN
                      GOTIT = .TRUE.
                  ENDIF
 300          CONTINUE

C----         If don't have this chain, then add it to the
C             list
              IF (.NOT.GOTIT) THEN

C----             Check that maximum number of chains for
C                 this entry not exceeded
                  IF (NSWCHN(ISWISS).LT.MXSWCH) THEN

C----                 Increment count of chains for this entry
C                     and store chain
                      NSWCHN(ISWISS) = NSWCHN(ISWISS) + 1
                      ICOL = NSWCHN(ISWISS)
                      SWICHN(ICOL,ISWISS) = INCHN

C----             If maximum number of chains exceeded, show
C                 error message
                  ELSE
                      PRINT*, '*** Warning. Maximum number',
     -                    ' of chains per SWISS-PROT entry',
     -                    ', MXSWCH, exceeded ', MXSWCH
                  ENDIF
              ENDIF

C----         Mark that code found
              GOTIT = .TRUE.
          ENDIF
 400  CONTINUE

C---- If don't have this SWISS-PROT code, then store it
      IF (.NOT.GOTIT) THEN

C----     Check that maximum not exceeded
          IF (NSWISS.LT.MXSWIS) THEN

C----         Increment count and store the code
              NSWISS = NSWISS + 1
              SWNAME(NSWISS) = SWCODE
              SWICHN(1,NSWISS) = INCHN
              NSWCHN(ISWISS) = 1

C----     If maximum number of SWISS-PROT entries exceeded,
C         show error message
          ELSE
              PRINT*, '*** Warning. Maximum number of SWIS',
     -            'S-PROT entries, MXSWIS, exceeded ',
     -            MXSWIS
          ENDIF
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE PROCMP  -  Process the COMPND entries to extract the
C                        molecule and E.C. number information
C
C----------------------------------------------------------------------+---

      SUBROUTINE PROCMP

      INCLUDE 'pdbhtml.inc'

      INTEGER       NKEYS
      PARAMETER    (NKEYS = 2)

      CHARACTER*1   KEYEND(NKEYS)
      CHARACTER*20  KEYWRD(NKEYS)
      CHARACTER*(RECLEN) INREC
      INTEGER       ICHAR, IEND, IEXTRA, ICLINE, IKEY, IPOS, ISTART,
     -              KEYLEN, LENSTR, NFREE

      DATA KEYWRD / 'MOL_ID:',
     -              'MOLECULE:' /
      DATA KEYEND / ';',
     -              ' ' /

C---- Loop over all the COMPND entries to splice out any of the unwanted
C     keywords
      DO 200, ICLINE = 1, NCLINE

C----     Retrieve the line
          INREC = COMPND(ICLINE)

C----     Loop over all the unwanted keywords to be cut out
          DO 100, IKEY = 1, NKEYS

C----         Check whether the current keyword is in the line
              KEYLEN = LENSTR(KEYWRD(IKEY))
              ISTART = INDEX(INREC,KEYWRD(IKEY)(1:KEYLEN))
              IEND = 0

C----         If keyword is present, get the length to be spliced out
              IF (ISTART.GT.0) THEN
                  OUTREC = INREC(ISTART:)
                  IEND = INDEX(OUTREC,KEYEND(IKEY))

C----             Perform the splice 
                  IF (IEND.GT.1) THEN
                      IF (ISTART.EQ.1) THEN
                          OUTREC = INREC(ISTART + IEND:)
                      ELSE
                          OUTREC = INREC(1:ISTART - 1) //
     -                        INREC(ISTART + IEND:)
                      ENDIF
                      COMPND(ICLINE) = OUTREC
                  ENDIF
              ENDIF
 100      CONTINUE
 200  CONTINUE

C---- Loop over all the COMPND entries to check for E.C. number in line
      DO 600, ICLINE = 1, NCLINE

C----     Initialise variables
          ISTART = 0
          IEND = 0
          OUTREC = COMPND(ICLINE)
          INREC = OUTREC

C----     Old-style entry: (E.C.i.j.k.l)
          ISTART = INDEX(INREC,'(E.C.')
          IF (ISTART.GT.0) THEN
              IEXTRA = 5
              ECNUMB = INREC(ISTART + IEXTRA:)
              IEND = INDEX(ECNUMB,')')
              ECNUMB(IEND:) = ' '

C----         Check for there being at least one dot in the number
              IPOS = INDEX(ECNUMB,'.')
              IF (IPOS.EQ.0) ECNUMB = ' '

C----     Otherwise, check for new-style entry:  EC: i.j.k.l;
          ELSE
              ISTART = INDEX(INREC,'EC:')
              IF (ISTART.GT.0) THEN
                  IEXTRA = 4
                  ECNUMB = INREC(ISTART + IEXTRA:)
                  IEND = INDEX(ECNUMB,';')
              ENDIF
          ENDIF

C----     If have an E.C. number then transfer it to appropriate variable
          IF (ISTART.GT.1 .AND. IEND.GT.1) THEN
              OUTREC = ECNUMB
              ECNUMB = OUTREC(1:IEND - 1)

C----         Splice it out of the compound record
              OUTREC = INREC(1:ISTART - 1) //
     -            INREC(ISTART + IEND + IEXTRA + 1:)
              COMPND(ICLINE) = OUTREC
          ENDIF
 600  CONTINUE

C---- Initialise next free slot for compound entries
      NFREE = 0

C---- Loop over all the COMPND entries to replace semi-colons by full-stops
      DO 800, ICLINE = 1, NCLINE

C----     Initialise variables
          DO 700, ICHAR = 1, PDILEN
              IF (COMPND(ICLINE)(ICHAR:ICHAR).EQ.';') THEN
                  COMPND(ICLINE)(ICHAR:ICHAR) = '.'
              ENDIF
 700      CONTINUE

C----     Check that entry is not blank
          IF (LENSTR(COMPND(ICLINE)).GT.0) THEN
              NFREE = NFREE + 1
              COMPND(NFREE) = COMPND(ICLINE)
          ENDIF
 800  CONTINUE

C---- Save new number of COMPND entries
      NCLINE = NFREE


      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE PROSRC  -  Process the SOURCE entries to splice out the
C                        unwanted keywords
C
C----------------------------------------------------------------------+---

      SUBROUTINE PROSRC

      INCLUDE 'pdbhtml.inc'

      INTEGER       NKEYS
      PARAMETER    (NKEYS = 11)

      CHARACTER*2   KEYEND(NKEYS)
      CHARACTER*50  KEYWRD(NKEYS)
      CHARACTER*(RECLEN) INREC
      INTEGER       ICHAR, IEND, ISLINE, IKEY, ISTART, JSLINE, KEYLEN,
     -              KEYENL, LEN, LENSTR, NFREE
      LOGICAL       HAVEIT

      DATA KEYWRD / 'MOL_ID:',
     -              'ORGANISM_SCIENTIFIC:',
     -              'ORGANISM_COMMON:',
     -              'EXPRESSION_SYSTEM:',
     -              'EXPRESSION_SYSTEM_STRAIN:',
     -              'EXPRESSION_SYSTEM_VECTOR:',
     -              'EXPRESSION_SYSTEM_VECTOR_TYPE:',
     -              'EXPRESSION_SYSTEM_PLASMID:',
     -              'EXPRESSION_SYSTEM_COMMON:',
     -              'EXPRESSION_SYSTEM_CELLULAR_LOCATION:',
     -              'EXPRESSION_SYSTEM_GENE:' /
      DATA KEYEND / ';',
     -              ' ',
     -              ' ',
     -              ' ',
     -              ';',
     -              ';',
     -              ';',
     -              ';',
     -              ';',
     -              ';',
     -              ';' /

C---- Loop over all the SOURCE entries to splice out any of the unwanted
C     keywords
      DO 200, ISLINE = 1, NSLINE

C----     Retrieve the line
          INREC = SOURCE(ISLINE)

C----     Loop over all the unwanted keywords to be cut out
          DO 100, IKEY = 1, NKEYS

C----         Check whether the current keyword is in the line
              KEYLEN = LENSTR(KEYWRD(IKEY))
              ISTART = INDEX(INREC,KEYWRD(IKEY)(1:KEYLEN))
              IEND = 0

C----         If keyword is present, get the length to be spliced out
              IF (ISTART.GT.0) THEN
                  LEN = LENSTR(INREC)
                  OUTREC = INREC(ISTART:)
                  KEYENL = LENSTR(KEYEND(IKEY))
                  IF (KEYENL.LT.1) KEYENL = 1
                  IEND = INDEX(OUTREC,KEYEND(IKEY)(1:KEYENL))

C----             Perform the splice 
                  IF (IEND.GT.1) THEN

C----                 For expression system, replace text
                      IF (IKEY.EQ.4) THEN
                          OUTREC = INREC(1:ISTART - 1) //
     -                        ' Expressed in: ' // INREC(ISTART + IEND:)

C----                 Otherwise just splice out unwanted term
                      ELSE
                       IF (ISTART.EQ.1) THEN
                          OUTREC = INREC(ISTART + IEND:)
                       ELSE
                          OUTREC = INREC(1:ISTART - 1) //
     -                        INREC(ISTART + IEND:)
                       ENDIF
                      ENDIF
                      SOURCE(ISLINE) = OUTREC

C----             If no terminator found, but is a semi-colon, then
C                 want whole term out
                  ELSE IF (KEYEND(IKEY).EQ.';') THEN
                      SOURCE(ISLINE) = ' '
                  ENDIF
              ENDIF
 100      CONTINUE
 200  CONTINUE

C---- Loop over all the SOURCE entries to replace semi-colons by full-stops
      DO 400, ISLINE = 1, NSLINE

C----     Initialise variables
          DO 300, ICHAR = 1, PDILEN
              IF (SOURCE(ISLINE)(ICHAR:ICHAR).EQ.';') THEN
                  SOURCE(ISLINE)(ICHAR:ICHAR) = '.'
              ENDIF
 300      CONTINUE
 400  CONTINUE

C---- Initialise free position
      NFREE = 0

C---- Loop again to remove any duplicates
      DO 600, ISLINE = 1, NSLINE

C----     Initialise
          HAVEIT = .FALSE.

C----     Loop through all previous entries to see if we already have
C         this entry
          DO 500, JSLINE = 1, NFREE

C----         If have a match, then set flag and jump out
              IF (SOURCE(ISLINE).EQ.SOURCE(JSLINE)) THEN

C----             Set flag and exit
                  HAVEIT = .TRUE.
                  GO TO 510
              ENDIF
 500      CONTINUE

C----     If don't already have this source, then move it to the next
C         free slot
 510      CONTINUE
          IF (.NOT.HAVEIT .AND. LENSTR(SOURCE(ISLINE)).GT.0) THEN

C----         Increment count of free entries
              NFREE = NFREE + 1

C----         Transfer across
              SOURCE(NFREE) = SOURCE(ISLINE)
          ENDIF
 600  CONTINUE

C---- Save the new number of source entries
      NSLINE = NFREE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETRVL  -  Get the R-factor if it hasn't already been picked
C                        up
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETRVL

      INCLUDE 'pdbhtml.inc'

      CHARACTER*120 IREC
      INTEGER       LINE
      REAL          R

C---- Open the data file holding the R-factors of all PDB entries
C     (generated by IDITIS)
      OPEN(UNIT=2, FILE=RVLFIL, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

C---- Initialise variables
      PRINT*
      PRINT*, 'Reading in R-value ...'
      LINE = 0

C---- Read through the rfactors file
 100  CONTINUE

C----     Read in a record from the file
          READ(2,120,END=500,ERR=902) IREC
 120      FORMAT(A)
          LINE = LINE + 1

C----     Check if this is the correct PDB code
          IF (IREC(1:4).EQ.BRCODE) THEN

C----         Check whether the R-factor field contains a value
              IF (IREC(10:13).NE.'****') THEN

C----             Read the value
                  READ(IREC,160,ERR=904) R
 160              FORMAT(7X,F6.0)
                  RFACT = R
              ENDIF

C----         Jump out of the loop
              GO TO 500
          ENDIF

C---- Loop back for next record in file
      GO TO 100

C---- End of file reached
 500  CONTINUE

C---- Close the file
      CLOSE(2)

      GO TO 999

C---- Errors
900   CONTINUE
      PRINT*, '*** Unable to open rfactors file'
      GO TO 999

902   CONTINUE
      PRINT*, '*** ERROR. File error in rfactors at line:', LINE + 1
      GO TO 999

 904  CONTINUE
      PRINT*, '*** ERROR. Read error in rfactors at line:', LINE
      GO TO 999

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE CHKLNK  -  Check whether given file exists and is non-empty
C
C----------------------------------------------------------------------+---

      SUBROUTINE CHKLNK(PDBSUM,FNAME,HAVLNK,NOREAD)

      CHARACTER*(*) FNAME, PDBSUM
      CHARACTER*120 FULNAM, IREC
      INTEGER       LENSTR, LINE
      LOGICAL       HAVLNK, NOREAD


C---- Initialise variables
      FULNAM = PDBSUM(1:LENSTR(PDBSUM)) // '/' // FNAME
      HAVLNK = .FALSE.
      LINE = 0

C---- Open input file
      OPEN(UNIT=2,FILE=FULNAM,STATUS='OLD',
CVAX     -    CARRIAGECONTROL='LIST',READONLY,
     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=500)

C---- If don't need to read the file, then set flag that file is present
      IF (NOREAD) THEN
          HAVLNK = .TRUE.

C---- Otherwise, loop to read in a few records to ensure file is not empty
      ELSE

C----     Loop until required number of records have been read in
100       CONTINUE

C----         Read in the next record from the input file
              READ(2,110,ERR=500,END=500) IREC
110           FORMAT(A)
              IF (IREC.NE.' ') LINE = LINE + 1

C----     If haven't yet read in at least three non-blank records, then
C         read more
          IF (LINE.LT.3) GO TO 100

C----     If file contains at least two non-blank records, then mark as
C         existing
          IF (LINE.GT.1) HAVLNK = .TRUE.
      ENDIF

C---- End of file reached
500   CONTINUE

C---- Close the file
      CLOSE(2)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE CHKCHK  -  Check if have PROCHECK results
C
C----------------------------------------------------------------------+---

      SUBROUTINE CHKCHK(HAVCHK)

      CHARACTER*120 FULNAM, IREC
      INTEGER       LENSTR, LINE, NPLOTS
      LOGICAL       HAVCHK


C---- Initialise variables
      FULNAM = '../procheck/database.dat'
      HAVCHK = .FALSE.
      LINE = 0

C---- Open input file
      OPEN(UNIT=2,FILE=FULNAM,STATUS='OLD',
     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=500)

C---- Loop until reach the NPPLOT line
 100  CONTINUE

C----     Read in the next record from the input file
          READ(2,110,ERR=500,END=500) IREC
 110      FORMAT(A)

C----     If this is the NPPLOT line, get number of plots
          IF (IREC(1:7).EQ.'NPPLOT ') THEN

C----         Get the number of plots
              READ (IREC(8:),*,ERR=500) NPLOTS

C----         If have any plots, then set flag
              IF (NPLOTS.GT.0) HAVCHK = .TRUE.
          ENDIF

C----     Loop back
          GO TO 100
      
C---- End of file reached
500   CONTINUE

C---- Close the file
      CLOSE(2)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETLNK  -  Get the PDB code of any related NMR entry
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETLNK

      INCLUDE 'pdbhtml.inc'

      CHARACTER*4   CODE
      CHARACTER*120 IREC
      INTEGER       ELINE, FLINE, ILINE, IPOS, LINE

C---- Open the data file holding the NMR links file
      OPEN(UNIT=2, FILE=LNKFIL, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

C---- Initialise variables
      PRINT*
      PRINT*, 'Looking for related entries ...'
      LINE = 0
      NLINKS = 0

C---- Read through the links file
 100  CONTINUE

C----     Read in a record from the file
          READ(2,120,END=500,ERR=902) IREC
 120      FORMAT(A)
          LINE = LINE + 1

C----     Check if this is the correct PDB code
          IF (IREC(2:5).EQ.BRCODE .OR. IREC(10:13).EQ.BRCODE) THEN

C----         Get the other PDB code
              IF (IREC(2:5).EQ.BRCODE) THEN
                  CODE = IREC(10:13)
                  ENSLNK = .TRUE.
              ELSE
                  CODE = IREC(2:5)
              ENDIF

C----         Set flag to indicate that we have link
              NMRLNK = .TRUE.

C----         If first character is an asterisk, then this is a "related"
C             entry rather than links between NMR ensembles and minimized
C             structures
              IF (IREC(1:1).EQ.'*') THEN
                  RELINK = .TRUE.
                  ENSLNK = .FALSE.
              ENDIF

C----         Store this code, if have room
              IF (NLINKS.LT.MXLINK) THEN

C----             Increment count of links and store
                  NLINKS = NLINKS + 1
                  LNKCOD(NLINKS) = CODE

C----         Otherwise, display warning message
              ELSE
                  PRINT*, '*** Warning. Max. number of relating links ',
     -                'exceeded:', MXLINK
                  GO TO 500
              ENDIF
          ENDIF

C---- Loop back for next record in file
      GO TO 100

C---- End of file reached
 500  CONTINUE

C---- Close the file
      CLOSE(2)

C---- Check for any unwanted info in the related entries lines
      IF (NELINE.GT.0) THEN

C----     Initialise start and end lines for unwanted text
          FLINE = 0
          ELINE = 0

C----     Loop through the lines searching for unwanted text

          DO 800, ILINE = 1, NELINE

C----         If text is talking about exptal restraints then have first
C             unwanted line
              IPOS = INDEX(RELATE(ILINE),'RESTRAINTS')
              IF (IPOS.GT.0) THEN
                  FLINE = ILINE
              ENDIF

C----         If line might contain the name of a restraints file, then
C             could be the second of our unwanted lines
              IPOS = INDEX(RELATE(ILINE),'MR')
              IF (IPOS.GT.0 .AND. FLINE.EQ.ILINE - 1) THEN
                  ELINE = ILINE
              ENDIF
 800      CONTINUE

C----     If have two adjacent lines that seem to be unwanted, then can
C         get rid of them
          IF (FLINE.GT.0 .AND. ELINE.EQ.FLINE + 1) THEN

C----         Blank out the two lines
              RELATE(FLINE) = ' '
              RELATE(ELINE) = ' '

C----         If these are the only two lines there are, then nothing
C             to print
              IF (NELINE.EQ.2) NELINE = 0
          ENDIF
      ENDIF

C---- Convert related entries list
      CALL TYPSET(PDILEN,NELINE,RELATE,.FALSE.)

      GO TO 999

C---- Errors
 900  CONTINUE
      PRINT*, '*** Unable to open NMR links file'
      GO TO 999

 902  CONTINUE
      PRINT*, '*** ERROR. File error in NMR links  at line:', LINE + 1
      GO TO 999

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE CHKVEW  -  Check whether have side-views
C
C----------------------------------------------------------------------+---

      SUBROUTINE CHKVEW

      INCLUDE 'pdbhtml.inc'

      LOGICAL       HAVGF1, HAVGF2, HAVJP1, HAVJP2, HAVTR1, HAVTR2,
     -              NOREAD

C---- Initialise view flag
      HAVIEW = .FALSE.
      HAVJPG = .FALSE.

C---- Check whether there is a GIF image to be place to the right
      NOREAD = .FALSE.
      CALL CHKLNK(PDBSUM,'tracel_r.html',HAVTR1,NOREAD)
      NOREAD = .TRUE.
      CALL CHKLNK(PDBSUM,'traces_r.gif',HAVGF1,NOREAD)
      CALL CHKLNK(PDBSUM,'traces_r.jpg',HAVJP1,NOREAD)

C---- Check whether there is a GIF image to be place below first image
      NOREAD = .FALSE.
      CALL CHKLNK(PDBSUM,'tracel_b.html',HAVTR2,NOREAD)
      NOREAD = .TRUE.
      CALL CHKLNK(PDBSUM,'traces_b.gif',HAVGF2,NOREAD)
      CALL CHKLNK(PDBSUM,'traces_b.jpg',HAVJP2,NOREAD)

C---- If have all the relevant files, then set flag
      IF (HAVTR1 .AND. HAVGF1 .AND. HAVTR2 .AND. HAVGF2) THEN
          HAVIEW = .TRUE.
      ELSE IF (HAVJP1 .AND. HAVJP2) THEN
          HAVJPG = .TRUE.
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE CHKVIE  -  Determine which links to PDB viewers can be
C                        written out
C
C----------------------------------------------------------------------+---

      SUBROUTINE CHKVIE

      INCLUDE 'pdbhtml.inc'

      LOGICAL       NOREAD

C---- Check whether have a Rasmol script file for this protein
      NOREAD = .TRUE.
      CALL CHKLNK(PDBSUM,'rasmol.dfn',HAVRSC,NOREAD)

C---- Check whether structure is too large to add link to Rasmol script
      TOOBIG = .FALSE.
      IF (NATOMS.GT.MXSCRP) TOOBIG = .TRUE.
      IF (TOOBIG) PRINT*, '*** Very large structure:- ', NATOMS,
     -    ' atoms'

C---- Check whether have a VRML file for this protein
      NOREAD = .FALSE.
      CALL CHKLNK(PDBSUM,'secsurf.wrl',HAVWRL,NOREAD)

C---- If no secsurf.wrl file, check whether the gzipped version exists
      IF (.NOT.HAVWRL) THEN
          NOREAD = .TRUE.
          CALL CHKLNK(PDBSUM,'secsurf.wrl.gz',HAVWRL,NOREAD)
      ENDIF

C---- Check whether the surface file is present
      NOREAD = .TRUE.
      CALL CHKLNK(PDBSUM,'surf.gif',HAVSRF,NOREAD)
      IF (.NOT.HAVSRF) THEN
          CALL CHKLNK(PDBSUM,'surf.jpg',HAVSRF,NOREAD)
      ENDIF

C---- Check whether the clefts file is present
      NOREAD = .TRUE.
      IF (.NOT.PDBSM1) THEN
         CALL CHKLNK(PDBSUM,'clefts.gif',HAVCLF,NOREAD)
         IF (.NOT.HAVCLF) THEN
            CALL CHKLNK(PDBSUM,'clefts.jpg',HAVCLF,NOREAD)
         ENDIF
      ELSE
         CALL CHKLNK(PDBSUM,'clefts/speedfill.dbt',HAVCLF,NOREAD)
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE CHKUNP  -  Check whether this PDB code has entries in Stuart
C                        Moodie's Unpublished references database
C
C----------------------------------------------------------------------+---

      SUBROUTINE CHKUNP(PDBCOD)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*4   PDBCOD
      CHARACTER*120 IREC
      INTEGER       LINE
      LOGICAL       STARTD

C---- Initialise variables
      HAVUNP = .FALSE.
      STARTD = .FALSE.

C---- Open the data file holding the list of PDB codes with entries in
C     the Unpublished references database
      OPEN(UNIT=2, FILE=UNPLST, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

C---- Initialise variables
      PRINT*
      PRINT*, 'Reading Unpublished References list ...'
      LINE = 0

C---- Read through the file
 100  CONTINUE

C----     Read in a record from the file
          READ(2,120,END=500,ERR=902) IREC
 120      FORMAT(A)
          LINE = LINE + 1

C----     If haven't reached the list, yet, check for start
          IF (.NOT.STARTD) THEN

C----         Check for start of list
              IF (IREC(1:4).EQ.'SQL>') STARTD = .TRUE.

C----     Otherwise, check the PDB code just read in
          ELSE

C----         Check if this is the correct PDB code
              IF (IREC(1:4).EQ.PDBCOD) THEN

C----             Set flag to indicate that PDB code found
                  HAVUNP = .TRUE.
              ENDIF
          ENDIF

C---- Loop back for next record in file, unless have found a match
      IF (.NOT.HAVUNP) GO TO 100

C---- End of file reached
 500  CONTINUE

C---- Close the file
      CLOSE(2)

      GO TO 999

C---- Errors
 900  CONTINUE
      PRINT*, '*** Unable to open Unpublished References list'
      GO TO 999

 902  CONTINUE
      PRINT*, '*** ERROR. File error in Unpub Refs list at line:',
     -    LINE + 1
      GO TO 999

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE OLD_SWISS  -  Check whether this PDB file has any links to
C                       entries in Swiss Prot (routine using sp_list file)
C
C----------------------------------------------------------------------+---

      SUBROUTINE OLD_SWISS(FNAME,SWADDR,BRCODE)

      CHARACTER*1   COMMA
      CHARACTER*4   BRCODE, PDBCOD
      CHARACTER*(*) FNAME, SWADDR
      CHARACTER*20  ENTRY
      CHARACTER*256 ENTADD, IREC
      INTEGER       ALEN, ELEN, IEND, IENTRY, IPOS, ISTART, LINE, NENTRY
      LOGICAL       DONE, HAVENT

C---- Initialise variables
      DONE = .FALSE.
      ENTADD = ' '
      ENTRY = ' '
      LINE = 0
      HAVENT = .FALSE.
      NENTRY = 0

C---- Convert the PDB number into upper-case
      PDBCOD = BRCODE
      CALL UPPCAS(4,PDBCOD)

C---- Open input file
      OPEN(UNIT=2,FILE=FNAME,STATUS='OLD',
CVAX     -    CARRIAGECONTROL='LIST',READONLY,
     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=500)

C---- Loop to the file to search for current PDB code
100   CONTINUE

C----     Read in the next record from the input file
          READ(2,110,ERR=500,END=500) IREC
110       FORMAT(A)
          LINE = LINE + 1
          IF (IREC(1:4).EQ.PDBCOD) HAVENT = .TRUE.

C---- If haven't yet found the entry, loop back for the next record
      IF (.NOT.HAVENT) GO TO 100

C---- End of file reached
500   CONTINUE

C---- If have a Swiss Prot link, then write out
      IF (HAVENT) THEN

C----     Initialise number of entries
          NENTRY = 1
          DONE = .FALSE.

C----     Loop while searching for commas separating entries
 600      CONTINUE

C----         Look for comma in line
              IPOS = INDEX(IREC,',')

C----         If have a comma, then there's another entry to come
              IF (IPOS.GT.1) THEN
                  NENTRY = NENTRY + 1

C----             Blank out this comma
                  IREC(IPOS:IPOS) = ' '

C----         Otherwise, there are no more commas
              ELSE
                  DONE = .TRUE.
              ENDIF

C----     Loop back for next entry
          IF (.NOT.DONE) GO TO 600

C----     Write out heading
          WRITE(7,610) '<p>'
 610      FORMAT(10A)
          IF (NENTRY.GT.1) THEN
              WRITE(7,610) '<b>SWISS-PROT entries:</b>'
          ELSE
              WRITE(7,610) '<b>SWISS-PROT entry:</b>'
          ENDIF
          DONE = .FALSE.
          IENTRY = 0

C----     Loop through the entries until no more left
 700      CONTINUE

C----         Find the start-position of the next entry
              ISTART = INDEX(IREC,'<A HREF =') + 10
              IEND = INDEX(IREC,'">') - 1

C----         Check whether a tag has been found
              IF (IEND.GT.ISTART) THEN

C----             Form the URL for this link
                  ENTADD = SWADDR // IREC(ISTART:IEND)
                  ALEN = INDEX(ENTADD,' ') - 1

C----             Blank out this entry
                  IREC(ISTART - 10:IEND + 2) = ' '

C----             Get entry name
                  ISTART = IEND + 3
                  IEND = INDEX(IREC,'</A>') - 1
                  ENTRY = IREC(ISTART:IEND)
                  ELEN = INDEX(ENTRY,' ') - 1

C----             Blank out the entry name
                  IREC(ISTART:IEND + 4) = ' '

C----             Write the link out to the html file
                  IENTRY = IENTRY + 1
                  IF (IENTRY.LT.NENTRY) THEN
                      COMMA = ','
                  ELSE
                      COMMA = '.'
                  ENDIF
                  WRITE(7,610) '<a href="', ENTADD(1:ALEN), '">',
     -                ENTRY(1:ELEN), '</a>', COMMA
              ELSE
                  DONE = .TRUE.
              ENDIF

C----     Loop back for next entry
          IF (.NOT.DONE) GO TO 700
      ENDIF

C---- Close the file
      CLOSE(2)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE SWISS  -  Check the SWIFIL file for any links to entries in
C                       Swiss Prot
C
C----------------------------------------------------------------------+---

      SUBROUTINE SWISS

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   INCHN
      CHARACTER*4   PDBCOD
      CHARACTER*12  SWCODE
      CHARACTER*20  SCODE
      CHARACTER*256 IREC
      INTEGER       I, IPOS, LENSTR, LINE
      LOGICAL       DONE
      REAL          PERCEN

C---- Initialise variables
      DONE = .FALSE.
      LINE = 0

C---- Convert the PDB number into upper-case
      PDBCOD = BRCODE
      CALL UPPCAS(4,PDBCOD)

C---- Open input file
      OPEN(UNIT=2,FILE=SWIFIL,STATUS='OLD',
CVAX     -    CARRIAGECONTROL='LIST',READONLY,
     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=900)

C---- Loop to the file to search for current PDB code and count
C     number of unique occurrences
 100  CONTINUE

C----     Read in the next record from the input file
          READ(2,110,ERR=500,END=500) IREC
 110      FORMAT(A)
          LINE = LINE + 1
          IF (IREC(1:4).EQ.PDBCOD) THEN

C----         Get the appropriate chain-id
              INCHN = IREC(5:5)

C----         Extract the Swiss-Prot code
              SCODE = IREC(6:21)
              IPOS = 0
              DO 200, I = 1, 12
                  IF (SCODE(I:I).NE.' ' .AND. IPOS.EQ.0) THEN
                     IPOS = I
                  ENDIF
 200          CONTINUE
              IF (IPOS.EQ.0) IPOS = 1
              SWCODE = SCODE(IPOS:)

C----         Get the %-tage homology score
              READ(IREC,220,ERR=902) PERCEN
 220          FORMAT(22X,F5.1)

C----         Store the SWISS-PROT code, if seq sufficiently similar to
C             that in SWISS-PROT
              IF (PERCEN.GE.90.0) THEN
                  CALL STOSWS(SWCODE,INCHN)
              ENDIF
          ENDIF

C---- Loop back for next record
      GO TO 100

C---- End of file reached
 500  CONTINUE

C---- Close the file
      CLOSE(2)

      GO TO 999

C---- Errors
 900  CONTINUE
      PRINT*, '*** Warning. Unable to open SWISS-PROT codes file [',
     -    SWIFIL(1:LENSTR(SWIFIL)), ']'
      GO TO 999

 902  CONTINUE
      PRINT*, '*** Warning. Data error reading [',
     -    SWIFIL(1:LENSTR(SWIFIL)), '] at line', LINE
      GO TO 999

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE INITS  -  Initialise program variables
C
C----------------------------------------------------------------------+---

      SUBROUTINE INITS(ECTMPL,NUMLEN,CLENTH)

      CHARACTER*12  ECTMPL
      INTEGER       CLENTH(3), ILEN(4), IPART, IPOS, ITRAN, NUMLEN(4)

      DATA ILEN   / 1, 2, 2, 4 /

C---- Store the lengths of each element of the 4-digit E.C. code and form
C     a standard template
      IPOS = 0
      ITRAN = -1
      ECTMPL = ' '
      DO 100, IPART = 1, 4
          NUMLEN(IPART) = ILEN(IPART)
          ITRAN = ITRAN + NUMLEN(IPART) + 1
          ECTMPL(ITRAN:ITRAN) = '-'
          IF (IPART.LT.4) THEN
              ECTMPL(ITRAN + 1:ITRAN + 1) = '.'
              CLENTH(IPART) = ITRAN
          ENDIF
100   CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE OPENTR  -  Open the PDB entries file, pdbent.dat, (created by
C                        Andrew's program)
C
C----------------------------------------------------------------------+---

      SUBROUTINE OPENTR(PDBENT,IFAIL)

      CHARACTER*120 PDBENT
      INTEGER       LENSTR
      LOGICAL       IFAIL

C---- Open the PDB entries file
      OPEN(UNIT=3, FILE=PDBENT, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

C---- Open output file of E.C. number mismatches
      OPEN(UNIT=12, FILE='enzyme.out', STATUS='UNKNOWN',
     -    FORM='FORMATTED', ACCESS='SEQUENTIAL',
CVAX     -    CARRIAGECONTROL='LIST',
     -    ERR=902)

      GO TO 999

C---- Fatal errors
 900  CONTINUE
      PRINT*, '*** ERROR. Unable to open data file ',
     -    PDBENT(1:LENSTR(PDBENT))
      GO TO 990

 902  CONTINUE
      PRINT*, '*** ERROR. Unable to open enzyme.out output file '
      GO TO 990

 990  CONTINUE
      IFAIL = .TRUE.

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE OPNNEW  -  Open the new CATH data file
C
C----------------------------------------------------------------------+---

      SUBROUTINE OPNNEW(CATFIL,CATPDB,CATNUM,DOMPDB,DOMNUM,MXCATH,
     -     NUMLEV,IFAIL)

      INTEGER       MXCATH, NUMLEV

      CHARACTER*5   DOMPDB(MXCATH)
      CHARACTER*7   CATPDB(MXCATH)
      CHARACTER*120 CATFIL
      INTEGER       CATNUM(NUMLEV,MXCATH), DOMNUM(MXCATH), ILEVEL, ICATH
      LOGICAL       IFAIL

C---- Initialise the CATH values
      DO 200, ICATH = 1, MXCATH
          CATPDB(ICATH) = ' '
          DO 100, ILEVEL = 1, NUMLEV
              CATNUM(ILEVEL,ICATH) = 0
 100      CONTINUE
 200  CONTINUE

C---- Initialise the domain numbers
      DO 300, ICATH = 1, MXCATH
          DOMPDB(ICATH) = ' '
          DOMNUM(ICATH) = 0
 300  CONTINUE

C---- Open the CATH numbers file
      OPEN(UNIT=4, FILE=CATFIL, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

      GO TO 999

C---- Fatal errors
900   CONTINUE
      PRINT*, '*** ERROR. Unable to open CATH numbers data file '
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

