C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETEC   -  Get the E.C. number for this PDB code from the   
C                        pdb_EC file
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETEC(BRCODE,ECCODE,EENTRY,NAMLEN,NLEN,MXENTR,NENTRY,
     -    ECTMPL,NUMLEN,IFAIL)

      INTEGER       MXENTR

      CHARACTER*1   CHAIN
      CHARACTER*4   BCODE, BRCODE, PDBCOD
      CHARACTER*12  ECCODE(MXENTR), ECSTAN, ECTMPL, EENTRY(MXENTR)
      CHARACTER*120 IREC
      INTEGER       ICODE, LINE, NAMLEN(MXENTR), NLEN(MXENTR), NCODES,
     -              NENTRY, NUMLEN(4)
      LOGICAL       FOUND, IERROR, IFAIL

C---- Initialise variables
      FOUND = .FALSE.
      LINE = 0
      NENTRY = 0

C---- Convert the PDB number into upper-case
      PDBCOD = BRCODE
      CALL UPPCAS(4,PDBCOD)

C---- Loop while reading in records from the file
100   CONTINUE

C----     Read in the next record
          READ(3,120,ERR=900,END=500) IREC
120       FORMAT(A)
          LINE = LINE + 1

C----     If this is the required code, then extract the E.C. number
          IF (BRCODE.EQ.IREC(1:4)) THEN
              FOUND = .TRUE.

C----         Extract the E.C. number
C              ECSTAN = IREC(10:)
C              ECSTAN = IREC(7:)
C              NAMLEN = INDEX(ECSTAN,' ') - 1
C              ECCODE = ECSTAN(1:NAMLEN)

C----         Read in the EC number(s) associated with this PDB file
C             from Andrew Martin's pdb_EC list
              CALL GETNUM(IREC,BCODE,CHAIN,ECCODE,NLEN,MXENTR,
     -            NCODES)

C----         Process each of the E.C. numbers just read in
              DO 300, ICODE = 1, NCODES

C----             Retrieve the code
                  ECSTAN = ECCODE(ICODE)

C----             Process if code not marked as "none"
                  IF (ECSTAN(1:4).NE.'none') THEN

C----                 Increment count of E.C. codes for this PDB entry
                      NENTRY = NENTRY + 1
                      IF (NENTRY.GT.MXENTR) THEN
                          NENTRY = MXENTR
                          PRINT*, '*** Warning. Maximum no. of E.C. en',
     -                        'tries per PDB code exceeded, MXENTR',
     -                        MXENTR
                      ELSE

C----                     Convert the E.C. number into its standard form
                          CALL ECCONV(ECCODE(ICODE),ECSTAN,NUMLEN,
     -                        ECTMPL,IERROR)
                          EENTRY(NENTRY) = ECSTAN
                          NAMLEN(NENTRY) = NLEN(ICODE)
                      ENDIF
                  ENDIF
 300          CONTINUE
          ENDIF

C---- Loop back for next record
      IF (.NOT.FOUND) GO TO 100

C---- End of file reached
500   CONTINUE
      CLOSE(3)

      GO TO 999

C---- Errors
900   CONTINUE
      PRINT*, '*** Read-error in file PDB-EC numbers file at line',
     -    LINE + 1
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETNUM  -  Read in the EC number(s) associated with this
C                        PDB file from Andrew Martin's pdb_EC list
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETNUM(IREC,BCODE,CHAIN,ECCODE,NAMLEN,MAXCOD,NCODES)

      INTEGER       MAXCOD

      CHARACTER*1   CH, CHAIN
      CHARACTER*4   BCODE
      CHARACTER*12  ECCODE(MAXCOD)
      CHARACTER*(*) IREC
      INTEGER       DOTPOS, IPOS, LEN, NAMLEN(MAXCOD), NCODES
      LOGICAL       ATEND, INCODE, VALID

C---- Initialise variables
      ATEND = .FALSE.
      INCODE = .FALSE.
      IPOS = 6
      LEN = 0
      NCODES = 0

C---- Get the PDB code
      BCODE = IREC(1:4)
      CALL UPPCAS(4,BCODE)
      CHAIN = IREC(5:5)

C---- Search through the line storing any E.C. numbers encountered
 100  CONTINUE

C----     Retrieve current character
          CH = IREC(IPOS:IPOS)

C----     If it is a space and we have been storing an E.C. number, then
C         have reached its end
          IF (CH.EQ.' ' .AND. INCODE) THEN

C----         Re-initialise flag and store length
              INCODE = .FALSE.
              NAMLEN(NCODES) = LEN

C----         Check whether what's been read in is an E.C. number
              VALID = .TRUE.

C----         Number should contain at least one dot
              DOTPOS = INDEX(ECCODE(NCODES),'.')
              IF (DOTPOS.EQ.0) VALID = .FALSE.

C----         If number not valid, then remove
              IF (.NOT.VALID) THEN
                  NCODES = NCODES - 1
              ENDIF

C----     If this is not a space, then have a possible E.C. number
          ELSE IF (CH.NE.' ') THEN

C----         If first character of a number, then initialise
              IF (.NOT.INCODE) THEN

C----             Check for obvious non-EC code
                  IF (LLT(CH,'1') .OR. LGT(CH,'6')) THEN
                      ATEND = .TRUE.

C----             Otherwise, if first character is between 1 and 6, then
C                 OK to go ahead
                  ELSE
C----                 Prepare for storing this code
                      INCODE = .TRUE.
                      LEN = 0
                      NCODES = NCODES + 1
                      IF (NCODES.GT.MAXCOD) THEN
                          PRINT*, '*** ERROR. Maximum number of E.C. c',
     -                        'odes for single PDB entry exceeded'
                          PRINT*, '***        For PDB code: [', BCODE,
     -                        CHAIN, ']'
                          NCODES = MAXCOD
                      ENDIF

C----                 Initialise code
                      ECCODE(NCODES) = ' '
                      NAMLEN(NCODES) = 0
                  ENDIF
              ENDIF

C----         Store the current character
              IF (LEN.LT.12 .AND. .NOT.ATEND) THEN
                  LEN = LEN + 1
                  ECCODE(NCODES)(LEN:LEN) = CH
              ENDIF
          ENDIF

C----     Increment character position
          IPOS = IPOS + 1

C---- Loop back if there may be more E.C. numbers on this line
      IF (IPOS.LT.80 .AND. .NOT.ATEND) GO TO 100

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE OPENDB  -  Open the NDB entries file, pdb_NDB (obtained by
C                        querying the NDB database)
C
C----------------------------------------------------------------------+---

      SUBROUTINE OPENDB(PDBNDB,IFAIL)

      CHARACTER*120 PDBNDB
      INTEGER       LENSTR
      LOGICAL       IFAIL

C---- Open the NDB entries file
      OPEN(UNIT=3, FILE=PDBNDB, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

      GO TO 999

C---- Fatal errors
900   CONTINUE
      PRINT*, '*** ERROR. Unable to open data file ',
     -    PDBNDB(1:LENSTR(PDBNDB))
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETNDB  -  Get the NDB reference number for this PDB code
C                        (if relevant) from the pdb_NDB file
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETNDB(PDBCOD,NDBREF,IFAIL)

      CHARACTER*4   PDBCOD
      CHARACTER*8   NDBREF
      CHARACTER*120 IREC
      INTEGER       LINE
      LOGICAL       FOUND, IFAIL

C---- Initialise variables
      FOUND = .FALSE.
      LINE = 0

C---- Loop while reading in records from the file
100   CONTINUE

C----     Read in the next record
          READ(3,120,ERR=900,END=500) IREC
120       FORMAT(A)
          LINE = LINE + 1

C----     If this is the required code, then extract the NDB number
          IF (PDBCOD.EQ.IREC(43:46)) THEN
              FOUND = .TRUE.

C----         Extract the NDB reference number
              NDBREF = IREC(29:36)

C----         Convert into lower case
              CALL LOWCAS(8,NDBREF)
          ENDIF

C---- Loop back for next record
      IF (.NOT.FOUND) GO TO 100

C---- End of file reached
500   CONTINUE
      CLOSE(3)

      GO TO 999

C---- Errors
900   CONTINUE
      PRINT*, '*** Read-error in file pdb_NDB file at line',
     -    LINE + 1
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE REANEW  -  Read in the CATH data from the new-format file
C
C----------------------------------------------------------------------+---

      SUBROUTINE REANEW(CATPDB,CATNUM,NCATH,DOMPDB,DOMNUM,NDOMS,MXCATH,
     -     NUMLEV,IFAIL)

      INTEGER       MXCATH, NUMLEV

      CHARACTER*5   DOMPDB(MXCATH), LSTPDB, PDB
      CHARACTER*7   CATPDB(MXCATH)
      CHARACTER*20  CATNO
      CHARACTER*120 IREC
      INTEGER       CATNUM(NUMLEV,MXCATH), DOMNUM(MXCATH), I, ILEV,
     -     IPOS, LEN, LINE, NCATH, ND, NDOMS, NDOTS
      LOGICAL       COPY, IFAIL

C---- Initialise variables
      LINE = 0
      LSTPDB = ' '
      NCATH = 0
      NDOMS = 0
      ND = 0

C---- Loop while reading in records from the file
100   CONTINUE

C----     Read in the next record
          READ(4,120,ERR=900,END=500) IREC
120       FORMAT(A)
          LINE = LINE + 1

C----     If this is not a blank line, store CATH number
          IF (IREC.NE.' ' .AND. IREC(1:1).NE.'#') THEN
              NCATH = NCATH + 1
              IF (NCATH.GT.MXCATH) GO TO 902
              CATPDB(NCATH) = IREC(1:7)

C----         Get the length of the line
              LEN = LENSTR(IREC)

C----         Get the PDB number
              PDB = IREC(1:5)

C----         Extract the CATH number from the line
              CATNO = ' '
              COPY = .FALSE.
              IPOS = 0
              ND = 1
              DO 200, I = 9, LEN

C----             If a space, see if start of CATH code
                  IF (IREC(I:I).EQ.' ') THEN

C----                 If don't yet have CATH number, set flag
                      IF (CATNO.EQ.' ') THEN
                         COPY = .TRUE.
                      ELSE
                         COPY = .FALSE.
                      ENDIF

C----             If this a comma, increment domain count
                  ELSE IF (IREC(I:I).EQ.',') THEN

                     ND = ND + 1

C----             Otherwise, if copying, copy across
                  ELSE IF (COPY) THEN
                     IPOS = IPOS + 1
                     CATNO(IPOS:IPOS) = IREC(I:I)
                  ENDIF
 200          CONTINUE

C----         Convert the dots in the CATH number to spaces
              NDOTS = 0
              LEN = LENSTR(CATNO)
              DO 300, I = 1, LEN

C----             If this is a dot, then convert
                  IF (CATNO(I:I).EQ.'.') THEN
                     CATNO(I:I) = ' '
                     NDOTS = NDOTS + 1
                  ENDIF
 300          CONTINUE


C----         If have 3 dots, can save the CATH number
              IF (NDOTS.EQ.3) THEN

C----            Pull out the four CATH numbers
                 READ(CATNO,*,ERR=400) (CATNUM(ILEV,NCATH),
     -                ILEV = 1, 4)



C----            If this is a new PDB code, create a new domain record
                 IF (PDB.NE.LSTPDB) THEN

C----               Increment PDB count and save PDB code
                    NDOMS = NDOMS + 1
                    DOMPDB(NDOMS) = PDB

C----               Save the PDB code
                    LSTPDB = PDB
                 ENDIF

C----            Update the domain count
                 DOMNUM(NDOMS) = DOMNUM(NDOMS) + ND
              ENDIF
 400          CONTINUE
          ENDIF

C---- Loop back for next record
      GO TO 100

C---- End of file reached
500   CONTINUE

C---- Print statistics on numbers read in
      PRINT*, NCATH, ' CATH-number entries read in'

C---- Close the file
      CLOSE(4)

      GO TO 999

C---- Errors
900   CONTINUE
      PRINT*, '*** Read-error in CATH-numbers file at line', LINE + 1
      GO TO 990

 902  CONTINUE
      PRINT*, '*** Warning. Maximum number of CATH entries, MXCATH, ex',
     -    'ceeded ', MXCATH
      NCATH = MXCATH
      GO TO 999

 904  CONTINUE
      PRINT*, '*** Data error in CATH-numbers file at line', LINE + 1
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE REACAT  -  Read in the CATH numbers
C
C----------------------------------------------------------------------+---

      SUBROUTINE REACAT(CATPDB,CATNUM,NCATH,MXCATH,NUMLEV,IFAIL)

      INTEGER       MXCATH, NUMLEV

      CHARACTER*7   CATPDB(MXCATH)
      CHARACTER*120 IREC, TEMP
      INTEGER       CATNUM(NUMLEV,MXCATH), ILEV, LINE, NCATH
      LOGICAL       IFAIL

C---- Initialise variables
      LINE = 0
      NCATH = 0

C---- Loop while reading in records from the file
100   CONTINUE

C----     Read in the next record
          READ(4,120,ERR=900,END=500) IREC
120       FORMAT(A)
          LINE = LINE + 1

C----     If this is not a blank line, store CATH number
          IF (IREC.NE.' ' .AND. IREC(1:1).NE.'#') THEN
              NCATH = NCATH + 1
              IF (NCATH.GT.MXCATH) GO TO 902
              CATPDB(NCATH) = IREC(1:7)
              TEMP = IREC(8:)
              READ(TEMP,*,ERR=904) (CATNUM(ILEV,NCATH),
     -            ILEV = 1, NUMLEV)
C              READ(IREC,140,ERR=904) (CATNUM(ILEV,NCATH),
C     -            ILEV = 1, NUMLEV)
C 140          FORMAT(6X,8I5)
C 140          FORMAT(6X,8I4)
C 140          FORMAT(7X,8I4)
          ENDIF

C---- Loop back for next record
      GO TO 100

C---- End of file reached
500   CONTINUE

C---- Print statistics on numbers read in
      PRINT*, NCATH, ' CATH-number entries read in'

C---- Close the file
      CLOSE(4)

      GO TO 999

C---- Errors
900   CONTINUE
      PRINT*, '*** Read-error in CATH-numbers file at line', LINE + 1
      GO TO 990

 902  CONTINUE
      PRINT*, '*** Warning. Maximum number of CATH entries, MXCATH, ex',
     -    'ceeded ', MXCATH
      NCATH = MXCATH
      GO TO 999

 904  CONTINUE
      PRINT*, '*** Data error in CATH-numbers file at line', LINE + 1
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE READOM  -  Read in the CATH domains
C
C----------------------------------------------------------------------+---

      SUBROUTINE READOM(DOMPDB,DOMNUM,NDOMS,MXCATH,IFAIL)

      INTEGER       MXCATH

      CHARACTER*5   DOMPDB(MXCATH)
      CHARACTER*120 IREC
      INTEGER       DOMNUM(MXCATH), LINE, NDOMS
      LOGICAL       IFAIL

C---- Initialise variables
      LINE = 0
      NDOMS = 0

C---- Loop while reading in records from the file
100   CONTINUE

C----     Read in the next record
          READ(4,120,ERR=900,END=500) IREC
120       FORMAT(A)
          LINE = LINE + 1

C----     If this is not a blank line, store number of CATH domains
          IF (IREC.NE.' ' .AND. IREC(1:1).NE.'#') THEN
              NDOMS = NDOMS + 1
              IF (NDOMS.GT.MXCATH) GO TO 902
              DOMPDB(NDOMS) = IREC(1:5)
              IF (IREC(7:7).EQ.'D') THEN
                  READ(IREC(8:9),*,ERR=904) DOMNUM(NDOMS)
              ENDIF
          ENDIF

C---- Loop back for next record
      GO TO 100

C---- End of file reached
500   CONTINUE

C---- Print statistics on numbers read in
      PRINT*, NDOMS, ' CATH-number entries read in'

C---- Close the file
      CLOSE(4)

      GO TO 999

C---- Errors
900   CONTINUE
      PRINT*, '*** Read-error in CATH-numbers file at line', LINE + 1
      GO TO 990

 902  CONTINUE
      PRINT*, '*** Warning. Maximum number of CATH entries, MXCATH, ex',
     -    'ceeded ', MXCATH
      NDOMS = MXCATH
      GO TO 999

 904  CONTINUE
      PRINT*, '*** Data error in CATH-numbers file at line', LINE + 1
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE OPNTIT  -  Open the CATH titles file, cath.titles (created by
C                        Alex's program)
C
C----------------------------------------------------------------------+---

      SUBROUTINE OPNTIT(TITFIL,CATLEV,CATDSC,MXTITL,NLEVEL,IFAIL)

      INTEGER       MXTITL, NLEVEL

      CHARACTER*50  CATDSC(MXTITL)
      CHARACTER*120 TITFIL
      INTEGER       CATLEV(NLEVEL,MXTITL), ILEVEL, ITITLE
      LOGICAL       IFAIL

C---- Initialise the CATH titles
      DO 200, ITITLE = 1, MXTITL
          DO 100, ILEVEL = 1, NLEVEL
              CATLEV(ILEVEL,ITITLE) = 0
              CATDSC(ITITLE) = ' '
 100      CONTINUE
 200  CONTINUE

C---- Open the CATH numbers file
      OPEN(UNIT=4, FILE=TITFIL, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

      GO TO 999

C---- Fatal errors
900   CONTINUE
      PRINT*, '*** ERROR. Unable to open CATH titles data file '
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE REATIT  -  Read in the CATH titles
C
C----------------------------------------------------------------------+---

      SUBROUTINE REATIT(CATLEV,CATDSC,NTITLE,MXTITL,NLEVEL,IFAIL)

      INTEGER       MXTITL, NLEVEL

      CHARACTER     CH
      CHARACTER*20  NUMBER
      CHARACTER*50  CATDSC(MXTITL), LEVNAM, TOPNAM
      CHARACTER*256 IREC
      INTEGER       CATLEV(NLEVEL,MXTITL), ILEVEL, IPOS, LAST1, LAST2,
     -              LEN, LENSTR, LEVEL, LEVVAL(4), LINE, NLEV, NTITLE,
     -              NUMPOS, VALUE
      LOGICAL       DONE, IFAIL

C---- Initialise variables
      LAST1 = 0
      LAST2 = 0
      LINE = 0
      NTITLE = 0
      TOPNAM = ' '
      DO 50, ILEVEL = 1, 4
          LEVVAL(ILEVEL) = 0
 50   CONTINUE

C---- Loop while reading in records from the file
100   CONTINUE

C----     Read in the next record
          READ(4,120,ERR=900,END=500) IREC
120       FORMAT(A)
          LINE = LINE + 1

C----     Get the length of this line
          LEN = LENSTR(IREC)

C----     If this is not a comment or a blank line, get the CATH number (or
C         part-number) and its description
C         records, then store CATH title
          IF (IREC(1:1).NE.'#' .AND. IREC.NE.' ') THEN

C----         Find the start of the name
C              IPOS = INDEX(IREC,':')
              IPOS = INDEX(IREC,' ')

C----         Store the name
              IF (IPOS.GT.0 .AND. IPOS.LT.LEN) THEN
                  LEVNAM = IREC(IPOS+1:)

C----             Initialise level number
                  DONE = .FALSE.
                  IPOS = 0
                  LEVEL = 0
                  NUMPOS = 0
                  DO 150, ILEVEL = 1, 4
                     LEVVAL(ILEVEL) = 0
 150              CONTINUE

C----             Loop through the digits to extract the CATH number
 200              CONTINUE

C----             Increment position along line
                  IPOS = IPOS + 1

C----             If off end, then set flag
                  IF (IPOS.GT.LEN) THEN
                     DONE = .TRUE.

C----             Otherwise get this character
                  ELSE

C----                Get character
                     CH = IREC(IPOS:IPOS)

C----                If dot or space, process previous number
                     IF ((CH.EQ.' ' .OR. CH.EQ.'.') .AND.
     -                    NUMPOS.GT.0) THEN

C----                   Increment current level
                        LEVEL = LEVEL + 1

C----                   Interpret the current number
                        NUMBER(NUMPOS+1:) = ' '
                        READ(NUMBER,*) VALUE

C----                   Store the level value
                        IF (VALUE.EQ.0) THEN
                           LEVEL = LEVEL - 1
                        ELSE IF (LEVEL.LE.4) THEN
                           LEVVAL(LEVEL) = VALUE
                        ENDIF

C----                   Reinitialise parameters
                        NUMPOS = 0

C----                Otherwise, add to current number
                     ELSE

C----                   If not off end of number, increment number
C                       position
                        IF (NUMPOS.LT.10) THEN
                           NUMPOS = NUMPOS + 1
                           NUMBER(NUMPOS:NUMPOS) = CH
                        ENDIF
                     ENDIF

C----                If have reached a space or the colon, we are done
                     IF (CH.EQ.' ' .OR. CH.EQ.':') DONE = .TRUE.
                  ENDIF

C----             If not yet done, loop back
                  IF (.NOT.DONE) GO TO 200

C----             If level not to deep, store the description
                  IF (LEVEL.LE.NLEVEL) THEN

C----                Increment count of stored titles
                     NTITLE = NTITLE + 1
                     IF (NTITLE.GT.MXTITL) GO TO 902

C----                Store the title
                     CATDSC(NTITLE) = LEVNAM

C----                Store the partial CATH number
                     DO 400, ILEVEL = 1, NLEVEL
                        CATLEV(ILEVEL,NTITLE) = LEVVAL(ILEVEL)
 400                 CONTINUE
                  ENDIF
               ENDIF
            ENDIF

C---- Loop back for next record
      GO TO 100

C---- End of file reached
500   CONTINUE

C---- Print statistics on numbers read in
      PRINT*, NTITLE, ' CATH titles read in'

C---- Close the file
      CLOSE(4)

      GO TO 999

C---- Errors
 900  CONTINUE
      PRINT*, '*** Read-error in CATH-titles file at line', LINE + 1
      GO TO 990

 902  CONTINUE
      PRINT*, '*** Maximum number of CATH titles, MXTITL, exceeded ',
     -    MXTITL
      GO TO 990

 904  CONTINUE
      PRINT*, '*** Data-error 1 in CATH-titles file at line', LINE
      GO TO 990

 906  CONTINUE
      PRINT*, '*** Data-error 2 in CATH-titles file at line', LINE
      GO TO 990

 990  CONTINUE
      IFAIL = .TRUE.

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE OLDTIT  -  Read in the CATH titles - Old version of REATIT
C                        for old file format
C
C----------------------------------------------------------------------+---

      SUBROUTINE OLDTIT(CATLEV,CATDSC,NTITLE,MXTITL,NLEVEL,IFAIL)

      INTEGER       MXTITL, NLEVEL

      CHARACTER*50  CATDSC(NLEVEL,MXTITL), LEVNAM, TOPNAM
      CHARACTER*256 IREC
      INTEGER       CATLEV(NLEVEL,MXTITL), IPOS, LAST1, LAST2, LEVEL1,
     -              LEVEL2, LINE, NTITLE
      LOGICAL       IFAIL

C---- Initialise variables
      LAST1 = 0
      LAST2 = 0
      LINE = 0
      NTITLE = 0
      TOPNAM = ' '

C---- Loop while reading in records from the file
100   CONTINUE

C----     Read in the next record
          READ(4,120,ERR=900,END=500) IREC
120       FORMAT(A)
          LINE = LINE + 1

C----     If this is not a blank line, and is not one of the lower-level
C         records, then store CATH title
          IF (IREC(1:1).NE.'#' .AND. IREC.NE.' ' .AND.
     -         IREC(2:2).NE.'.' .AND.(IREC(5:5).EQ.'.' .OR.
     -         IREC(5:5).EQ.' ')) THEN

C----         Find the start of the name
              IPOS = INDEX(IREC,':')

C----         Store the name
              IF (IPOS.GT.0) THEN
                  LEVNAM = IREC(IPOS+1:)
              ENDIF

C----         If this is the top level name, then store
              IF (IREC(5:9).EQ.' ') THEN

C----             Pick up the first number only
                  READ(IREC,140,ERR=904) LEVEL1
 140              FORMAT(I4)

C----             Store the name
                  TOPNAM = LEVNAM

C----             Save the level number
                  LAST1 = LEVEL1

C----         Otherwise, pick up the first two numbers only
              ELSE
                  READ(IREC,160,ERR=906) LEVEL1, LEVEL2
 160              FORMAT(I4,1X,I4)

C----             If first number is wrong, then show warning
                  IF (LEVEL1.NE.LAST1) THEN
                      PRINT*, '*** Warning. CATH titles file has missi',
     -                    'ng top heading at line: ', LINE
                  ENDIF

C----             Get the name and store
                  NTITLE = NTITLE + 1
                  IF (NTITLE.GT.MXTITL) GO TO 902
                  CATLEV(1,NTITLE) = LEVEL1
                  CATLEV(2,NTITLE) = LEVEL2
                  CATDSC(1,NTITLE) = TOPNAM
                  CATDSC(2,NTITLE) = LEVNAM
              ENDIF

C----         Store the current level
              LAST2 = LEVEL2
          ENDIF

C---- Loop back for next record
      GO TO 100

C---- End of file reached
500   CONTINUE

C---- Print statistics on numbers read in
      PRINT*, NTITLE, ' CATH-number titles read in'

C---- Close the file
      CLOSE(4)

      GO TO 999

C---- Errors
 900  CONTINUE
      PRINT*, '*** Read-error in CATH-titles file at line', LINE + 1
      GO TO 990

 902  CONTINUE
      PRINT*, '*** Maximum number of CATH titles, MXTITL, exceeded ',
     -    MXTITL
      GO TO 990

 904  CONTINUE
      PRINT*, '*** Data-error 1 in CATH-titles file at line', LINE
      GO TO 990

 906  CONTINUE
      PRINT*, '*** Data-error 2 in CATH-titles file at line', LINE
      GO TO 990

 990  CONTINUE
      IFAIL = .TRUE.

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE OLDREA  -  Read in the CATH titles - Even older version of
C                        REATIT for old file format
C
C----------------------------------------------------------------------+---

      SUBROUTINE OLDREA(CATLEV,CATDSC,NTITLE,MXTITL,NLEVEL,IFAIL)

      INTEGER       MXTITL, NLEVEL

      CHARACTER*50  CATDSC(NLEVEL,MXTITL)
      CHARACTER*256 IREC, NAMES
      INTEGER       CATLEV(NLEVEL,MXTITL), IPOS, JPOS, LAST1, LAST2,
     -              LEVEL1, LEVEL2, LINE, NTITLE
      LOGICAL       IFAIL

C---- Initialise variables
      LAST1 = 0
      LAST2 = 0
      LINE = 0
      NTITLE = 0

C---- Loop while reading in records from the file
100   CONTINUE

C----     Read in the next record
          READ(4,120,ERR=900,END=500) IREC
120       FORMAT(A)
          LINE = LINE + 1

C----     If this is not a blank line, store CATH title
          IF (IREC.NE.' ') THEN

C----         Pick up the first two numbers only
              READ(IREC,140,ERR=904) LEVEL1, LEVEL2
 140          FORMAT(I4,1X,I4)

C----         If the details have changed then pick up the titles and
C             store
              IF ((LEVEL1.NE.LAST1 .OR. LEVEL2.NE.LAST2) .AND.
     -            LEVEL2.NE.0) THEN

C----             Store the level numbers
                  NTITLE = NTITLE + 1
                  IF (NTITLE.GT.MXTITL) GO TO 902
                  CATLEV(1,NTITLE) = LEVEL1
                  CATLEV(2,NTITLE) = LEVEL2

C----             Pick up the first of the two descriptions
                  IPOS = 1
                  NAMES = IREC(45:)
                  JPOS = INDEX(NAMES,'_:_') - 1
                  IF (JPOS.GE.IPOS) THEN
                      CATDSC(1,NTITLE) = NAMES(IPOS:JPOS)

C----                 Pick up the second description
                      IPOS = JPOS + 4
                      CATDSC(2,NTITLE) = NAMES(IPOS:)
                  ELSE
                      CATDSC(1,NTITLE) = ' '
                      CATDSC(2,NTITLE) = ' '
                  ENDIF
              ENDIF

C----         Store the current level
              LAST1 = LEVEL1
              LAST2 = LEVEL2
          ENDIF

C---- Loop back for next record
      GO TO 100

C---- End of file reached
500   CONTINUE

C---- Print statistics on numbers read in
      PRINT*, NTITLE, ' CATH-number titles read in'

C---- Close the file
      CLOSE(4)

      GO TO 999

C---- Errors
900   CONTINUE
      PRINT*, '*** Read-error in CATH-titles file at line', LINE + 1
      GO TO 990

 902  CONTINUE
      PRINT*, '*** Maximum number of CATH titles, MXTITL, exceeded ',
     -    MXTITL
      GO TO 990

 904  CONTINUE
      PRINT*, '*** Data-error in CATH-titles file at line', LINE
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE OPNPRN  -  Open the PRINTS codes file (created by
C                        Alex's program)
C
C----------------------------------------------------------------------+---

      SUBROUTINE OPNPRN(PRNFIL,IFAIL)

      CHARACTER*120 PRNFIL
      INTEGER       LENSTR
      LOGICAL       IFAIL

C---- Open the PRINTS codes file
      OPEN(UNIT=4, FILE=PRNFIL, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

      GO TO 999

C---- Fatal errors
900   CONTINUE
      PRINT*, '*** ERROR. Unable to open PRINTS codes data file '
      PRINT*, '***       ', PRNFIL(1:LENSTR(PRNFIL))
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE REAPRN  -  Read in the PRINTS codes
C
C----------------------------------------------------------------------+---

      SUBROUTINE REAPRN(BRCODE,PRCODE,PRNPDB,PRNUM,MXPCOD,MXPRIN,NPCODE,
     -    NPRLNK,IFAIL)

      INTEGER       MXPCOD, MXPRIN

      CHARACTER*4   BRCODE, INCODE, PRNPDB(MXPCOD)
      CHARACTER*20  PRCODE(MXPRIN)
      CHARACTER*256 IREC
      INTEGER       ICODE, IPOS, LINE, NPCODE, NPRINT, NPRLNK,
     -              PRNUM(MXPCOD)
      LOGICAL       DONE, IFAIL

C---- Initialise variables
      LINE = 0
      NPCODE = 0
      NPRINT = 0
      NPRLNK = 0

C---- Loop while reading in records from the file
 100  CONTINUE

C----     Read in the next record
          READ(4,120,ERR=900,END=500) IREC
 120      FORMAT(A)
          LINE = LINE + 1

C----     If this is not a blank line, extract the PRINTS code and
C         associated PDB codes
          IF (IREC.NE.' ') THEN

C----         Increment count of PRINTS codes
              NPRINT = NPRINT + 1
              IF (NPRINT.GT.MXPRIN) THEN
                  PRINT*, '*** Warning. Maximum number of PRINTS codes',
     -                'exceeded, MXPRIN', MXPRIN
                  PRINT*, '***          Some data lost'
                  NPRINT = MXPRIN

C----         If can store this code, then do so
              ELSE
                  PRCODE(NPRINT) = IREC(1:20)

C----             Pick up all the associated PDB codes
                  DONE = .FALSE.
                  IPOS = 22

C----             Loop while still more codes to pick up
 200              CONTINUE

C----                 Get the next code and check it isn't blank
                      INCODE = IREC(IPOS:IPOS+3)
                      IF (INCODE.NE.' ') THEN

C----                     Increment count of stored PDB codes
                          NPCODE = NPCODE + 1
                          IF (NPCODE.GT.MXPCOD) THEN
                              PRINT*, '*** Warning. Maximum number of ',
     -                            'PDB entries for PRINT codes exceede',
     -                            'd, MXPCOD', MXPCOD
                              PRINT*, '***          Some data lost'
                              NPCODE = MXPCOD
                          ELSE
                              CALL LOWCAS(4,INCODE)
                              PRNPDB(NPCODE) = INCODE
                              PRNUM(NPCODE) = NPRINT
                          ENDIF

C----                     Move position along the record
                          IPOS = IPOS + 5
                      ELSE
                          DONE = .TRUE.
                      ENDIF

C----             Loop back for the next PDB code
                  IF (.NOT.DONE .AND. IPOS.LT.250) GO TO 200
              ENDIF
          ENDIF

C---- Loop back for next record
      GO TO 100

C---- End of file reached
500   CONTINUE

C---- Print statistics on numbers read in
      PRINT*, NPRINT, ' PRINTS codes read in'
      PRINT*, NPCODE, ' PRINTS PDB entries read in'

C---- Close the file
      CLOSE(4)

C---- Loop through all the PDB entries with PRINTS codes to see how many
C     match the current one
      DO 600, ICODE = 1, NPCODE

C----     If this code matches the PDB code, increment count
          IF (PRNPDB(ICODE).EQ.BRCODE) NPRLNK = NPRLNK + 1
 600  CONTINUE

      GO TO 999

C---- Errors
900   CONTINUE
      PRINT*, '*** Read-error in PRINTSvsPDB file at line', LINE + 1
      GO TO 990

990   CONTINUE
      IFAIL = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE TYPSET  -  Remove typographical characters and convert into
C                        upper and lower case.
C
C----------------------------------------------------------------------+---

      SUBROUTINE TYPSET(LINLEN,NLINES,STRING,AUTH)

      INTEGER       LINLEN, NLINES

      CHARACTER*1   CH, LASTCH, STRING(LINLEN*NLINES)
      INTEGER       IFREE, IPOS, NCHARS
      LOGICAL       AUTH, CAPITL, DOLLAR, SKIP, SLASH, UPCASE, UPONE

C---- Initialise variables
      CAPITL = .TRUE.
      LASTCH = ' '
      UPCASE = .FALSE.
      UPONE = .FALSE.
      IFREE = 0
      NCHARS = LINLEN * NLINES

C---- Check whether the string contains a dollar after a slash
      DOLLAR = .FALSE.
      SLASH = .FALSE.
      DO 100, IPOS = 1, NCHARS
          CH = STRING(IPOS)
          IF (CH.EQ.'/') SLASH = .TRUE.
          IF (CH.EQ.'$' .AND. SLASH) DOLLAR = .TRUE.
 100  CONTINUE

C---- Loop over all the characters
      DO 600, IPOS = 1, NCHARS

C----     Retrieve this character
          CH = STRING(IPOS)
          SKIP = .FALSE.

C----     Check if this is a letter
          IF (LGE(CH,'A') .AND. LLE(CH,'Z')) THEN

C----         If first character then leave it in upper-case
              IF (CAPITL .OR. UPONE) THEN
                  CAPITL = .FALSE.
                  UPONE = .FALSE.

C----         Otherwise, check whether upper-casing it
              ELSE IF (.NOT.UPCASE .AND. .NOT.UPONE) THEN
                  CH = CHAR(ICHAR('a') + ICHAR(CH) - ICHAR('A'))
              ENDIF

C----     Check if this is a number
          ELSE IF (LGE(CH,'0') .AND. LLE(CH,'9')) THEN

C----         If first character then set whole word in lower-case (as
C             possibly a PDB code)
              IF (CAPITL) THEN
                  CAPITL = .FALSE.
                  UPONE = .FALSE.
              ENDIF

C----     Check if this is one of the typesetting characters

C----     Upper-case the next letter only
          ELSE IF (CH.EQ.'*') THEN
              IF (IFREE.GE.0) IFREE = IFREE - 1
              UPONE = .TRUE.
              SKIP = .TRUE.

C----     Upper-case until dollar
          ELSE IF (CH.EQ.'/' .AND. DOLLAR) THEN
              IF (IFREE.GE.0) IFREE = IFREE - 1
              UPCASE = .TRUE.
              SKIP = .TRUE.

C----     End upper-case
          ELSE IF (CH.EQ.'$') THEN
              IF (IFREE.GE.0) IFREE = IFREE - 1
              UPCASE = .FALSE.
              SKIP = .TRUE.

C----     After a full-stop, need to capitalise next character
          ELSE IF (CH.EQ.'.') THEN
              CAPITL = .TRUE.

C----     If in author-list, capitalise next letter after a comma, too
          ELSE IF (AUTH .AND. (CH.EQ.',' .OR. CH.EQ.'-' .OR.
     -        CH.EQ.'''' .OR. CH.EQ.' ')) THEN
              CAPITL = .TRUE.
          ENDIF

C----     (Undo: don't close up on typographical characters)
          IF (SKIP) THEN
              SKIP = .FALSE.
              IFREE = IFREE + 1
              CH = ' '
          ENDIF

C----     Save the current character
          IFREE = IFREE + 1
          IF (.NOT.SKIP) THEN
              STRING(IFREE) = CH
              LASTCH = CH
          ENDIF

 600  CONTINUE

C---- Blank out end characters
      DO 800, IPOS = IFREE + 1, NCHARS
          STRING(IPOS) = ' '
 800  CONTINUE

C---- If not author names, then check for certain strings which should
C     be in upper-case
      IF (.NOT.AUTH) THEN
          CALL UPSET(NCHARS,STRING)
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE UPSET  -  Search for certain strings that must be set in
C                       upper-case
C
C----------------------------------------------------------------------+---

      SUBROUTINE UPSET(NCHARS,STRING)

      SAVE

      INTEGER       MXLEN, MAXCAP
      PARAMETER    (MXLEN = 20, MAXCAP=15)

      INTEGER       NCHARS

      CHARACTER*1   CH, STRING(NCHARS)
      CHARACTER*10  CAPWRD(MAXCAP), UPPWRD(MAXCAP)
      CHARACTER*(MXLEN) WORD
      INTEGER       CAPLEN(MAXCAP), I, IMATCH, IPOS, ISTART, IWORD, LEN,
     -              LENSTR
      LOGICAL       FIRST

      DATA CAPWRD / 'PDB       ', 'DNA       ', 'RNA       ',
     -              'HIV       ', 'NAG       ', 'NAD       ',
     -              'NADP      ', 'NADPH     ', 'tRNA      ',
     -              'mRNA      ', '          ', '          ',
     -              '          ', '          ', '          ' / 
      DATA FIRST  / .TRUE. /

C---- Initialise variables
      LEN = 0
      ISTART = 0

C---- If this is the very first time through, pre-calculate the length
C     of all the capitalised words
      IF (FIRST) THEN

C----     Loop over all the capital words
          DO 100, IWORD = 1, MAXCAP

C----         Get the length of the word
              IF (CAPWRD(IWORD).EQ.' ') THEN
                  CAPLEN(IWORD) = 0
              ELSE

C----             Store the word's length
                  CAPLEN(IWORD) = LENSTR(CAPWRD(IWORD))

C----             Form the upper-case version of the word
                  UPPWRD(IWORD) = ' '

C----             Loop over all the word's character positions
                  DO 50, IPOS = 1, CAPLEN(IWORD)

C----                 Get this letter
                      CH = CAPWRD(IWORD)(IPOS:IPOS)

C----                 Convert character into upper-case if is lower
                      IF (LGE(CH,'a') .AND. LLE(CH,'z')) THEN
                          CH = CHAR(ICHAR('A') + ICHAR(CH) - ICHAR('a'))
                      ENDIF

C----                 Store upper-case version of the character
                      UPPWRD(IWORD)(IPOS:IPOS) = CH
 50               CONTINUE
              ENDIF
 100      CONTINUE

C----     Set flag for next loop
          FIRST = .FALSE.
      ENDIF

C---- Loop over all the characters
      DO 600, IPOS = 1, NCHARS

C----     Get the current character
          CH = STRING(IPOS)

C----     Check if this is a word-end
          IF (CH.EQ.' ' .OR. CH.EQ.'.' .OR. CH.EQ.',' .OR.
     -        CH.EQ.'-' .OR. CH.EQ.'/' .OR. CH.EQ.'+' .OR.
     -        CH.EQ.')' .OR. CH.EQ.'(') THEN

C----         If last word exists, then check if needs to be put into
C             upper case
              IF (LEN.GT.1) THEN

C----             Initialise flag
                  IMATCH = 0

C----             Loop through all the possible capital words
                  DO 200, IWORD = 1, MAXCAP

C----                 If word is of the right length
                      IF (LEN.EQ.CAPLEN(IWORD)) THEN

C----                     Check whether it matches
                          IF (WORD.EQ.UPPWRD(IWORD)) THEN
                              IMATCH = IWORD
                          ENDIF
                      ENDIF
 200              CONTINUE

C----             If have found a match, then insert the upper-case
C                 version into the string
                  IF (IMATCH.NE.0) THEN

C----                 Insert back into the string
                      DO 300, I = 1, LEN
                          STRING(ISTART + I - 1) = CAPWRD(IMATCH)(I:I)
 300                  CONTINUE
                  ENDIF

C----         Check for special case of E.C. number
              ELSE IF (WORD.EQ.'C' .OR. WORD.EQ.'c') THEN

C----             Check if previous string was an E
                  IF (ISTART - 2.GT.0) THEN
                      CH = STRING(ISTART - 2)
                      IF (CH.EQ.'E' .OR. CH.EQ.'e') THEN

C----                     Convert both letters to upper case
                          STRING(ISTART - 2) = 'E'
                          STRING(ISTART) = 'C'
                      ENDIF
                  ENDIF
              ENDIF

C----         Reset word counters
              LEN = 0
              ISTART = 0

C----     Otherwise, add character to current word
          ELSE IF (LEN.LT.MXLEN) THEN

C----         Increment character position
              LEN = LEN + 1

C----         Convert character into upper-case if is lower
              IF (LGE(CH,'a') .AND. LLE(CH,'z')) THEN
                  CH = CHAR(ICHAR('A') + ICHAR(CH) - ICHAR('a'))
              ENDIF

C----         Add character
              WORD(LEN:) = CH

C----         If this is the first character, store string-position where
C             it came from
              IF (LEN.EQ.1) THEN
                  ISTART = IPOS
              ENDIF
          ENDIF
 600  CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE COMPRS  -  Compress the E.C. number by removing blank spaces
C
C----------------------------------------------------------------------+---

      SUBROUTINE COMPRS(ECCODE,ECOMPR)

      CHARACTER*12  ECCODE, ECOMPR
      INTEGER       IPOS, ITRAN

C---- Initialise variables
      ECOMPR = ' '
      ITRAN = 0

C---- Transfer the characters across, one by one, skipping any blanks
      DO 200, IPOS = 1, 12
          IF (ECCODE(IPOS:IPOS).NE.' ') THEN
              ITRAN = ITRAN + 1
              ECOMPR(ITRAN:ITRAN) = ECCODE(IPOS:IPOS)
          ENDIF
200   CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE SUPNEW  -  Write superseded PDB code out to superseded.new
C                        file so that its PDBsum page can be subsequently
C                        updated
C
C----------------------------------------------------------------------+---

      SUBROUTINE SUPNEW(SFOPEN,CODE,IFAIL)

      CHARACTER*4   CODE

      LOGICAL       IFAIL, SFOPEN

C---- Initialise variables
      IFAIL = .FALSE.

C---- If file hasn't been opened, then do so now
      IF (.NOT.SFOPEN) THEN

C----     Open the superseded.new file
          OPEN(UNIT=16,FILE='superseded.new',STATUS='UNKNOWN',
     -        ACCESS='SEQUENTIAL',
CVAX     -        CARRIAGECONTROL='LIST',
     -        FORM='FORMATTED',ERR=900)
          SFOPEN = .TRUE.
      ENDIF

C---- Write out the current PDB code
      WRITE(16,110) CODE
 110  FORMAT(A)
      GO TO 999

C---- Fatal errors
 900  CONTINUE
      PRINT*, '*** ERROR. Unable to open superseded.new file'
      GO TO 990

 990  CONTINUE
      IFAIL = .TRUE.

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETDES  -  Get the appropriate information about the
C                        non-standard residue types found in the current
C                        chain/ligand
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETDES(SEQUEN,MXLNAM,MXLINE,MXNTRY,IENTRY,ITEM,
     -    NONAME,NODESC,NOFORM,NONUMB,MXNONS,NOTYPE)

      INTEGER       MXLINE, MXLNAM, MXNONS, MXNTRY

      CHARACTER*1   CH, NCH, SEQUEN(MXLNAM,MXLINE,MXNTRY,3)
      CHARACTER*3   NONAME(MXNONS), RESDUE
      CHARACTER*40  NODESC(MXNONS)
      CHARACTER*51  NOFORM(MXNONS)
      CHARACTER*120 INREC
      INTEGER       IENTRY, ILINE, IMATCH, IPOS, ITEM, ITYPE, JPOS,
     -              LINE, NONUMB(MXNONS), NOTYPE, NPOS, RERROR

C---- Initialise variables
      IPOS = 1
      NOTYPE = 0
      DO 100, ITYPE = 1, MXNONS
          NODESC(ITYPE) = ' '
          NOFORM(ITYPE) = ' '
          NONAME(ITYPE) = ' '
          NONUMB(ITYPE) = 0
 100  CONTINUE
      NPOS = MXLNAM * MXLINE

C---- Loop through all the sequence lines, character by character
      DO 800, ILINE = 1, MXLINE

C----     Initilaise for this line
          IPOS = 0

C----     Loop through the characters in this line
 200      CONTINUE
              IPOS = IPOS + 1

C----         Get the current character
              CH = SEQUEN(IPOS,ILINE,IENTRY,ITEM)

C----         If this is a blank character or hyphen, then ignore
              IF (CH.NE.' ' .AND. CH.NE.'-') THEN

C----             If very next character is hyphen or space, then have
C                 a standard a.a.
                  JPOS = IPOS + 1
                  IF (JPOS.LE.MXLNAM) THEN
                      NCH = SEQUEN(JPOS,ILINE,IENTRY,ITEM)

C----                 If next character shows this to be a one-letter
C                     code, then can skip onto next residue position
                      IF (NCH.EQ.' ' .OR. NCH.EQ.'-') THEN
                          IPOS = IPOS + 2

C----                 Otherwise, this must be a non-standard residue
                      ELSE IF (IPOS + 2.LE.MXLNAM) THEN

C----                     Extract the residue name
                          RESDUE = SEQUEN(IPOS,ILINE,IENTRY,ITEM)
     -                        // SEQUEN(IPOS + 1,ILINE,IENTRY,ITEM)
     -                        // SEQUEN(IPOS + 2,ILINE,IENTRY,ITEM)

C----                     Check whether already have this one
                          IMATCH = 0
                          DO 300, ITYPE = 1, NOTYPE
                              IF (RESDUE.EQ.NONAME(ITYPE)) THEN
                                  IMATCH = ITYPE
                              ENDIF
 300                      CONTINUE

C----                     If have not found a match, put onto end
                          IF (IMATCH.EQ.0) THEN
                              NOTYPE = NOTYPE + 1
                              IF (NOTYPE.GT.MXNONS) THEN
                                  PRINT*, '* WARNING. Maximum number ',
     -                                'non-standard types, MXNONS, ',
     -                                'exceeded', MXNONS
                              ELSE
                                 IMATCH = NOTYPE

C----                            Rewind the input file so that can
C                                pick up a description and formula for
C                                this residue
                                 REWIND(1)
                                 LINE = 0

C----                            Loop while reading through the file
 400                             CONTINUE

C----                                Read in the next record
                                     READ(1,410,IOSTAT=RERROR,
     -                                   END=500) INREC
 410                                 FORMAT(A)
                                     LINE = LINE + 1

C----                                Check for HET atom description
                                     IF (INREC(1:6).EQ.'HET   ') THEN
                                         IF (RESDUE.EQ.INREC(8:10))
     -                                       NODESC(IMATCH)
     -                                           = INREC(31:70)
                                     ENDIF
                                     IF (INREC(1:6).EQ.'FORMUL') THEN
                                         IF (RESDUE.EQ.INREC(13:15))
     -                                       NOFORM(IMATCH)
     -                                           = INREC(20:70)
                                     ENDIF

                                 GO TO 400

C----                            End of file reached
 500                             CONTINUE
                              ENDIF
                          ENDIF

C----                     Store residue type and increment count
                          IF (IMATCH.GT.0) THEN
                              NONAME(IMATCH) = RESDUE
                              NONUMB(IMATCH) = NONUMB(IMATCH) + 1
                          ENDIF

C----                    Move onto next residue
                         IPOS = IPOS + 3
                      ENDIF
                  ENDIF
              ENDIF

C----     Loop back for next character
          IF (IPOS.LT.MXLNAM) GO TO 200
 800  CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETCAT  -  Pick up the CATH number for the given PDB file
C                        from Alex Michie's total_list file
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETCAT(BRCODE,CHAIN,CDESC,NLEVEL,NCATH,CATPDB,CATNUM,
     -    CATLEV,CATDSC,MXCATH,MXTITL,NTITLE,GOTCAT,CATH,NUMLEV,CATNEW,
     -    MAXDOM,NDOM)

      INTEGER       MAXDOM, MXCATH, MXTITL, NLEVEL, NUMLEV

      CHARACTER*1   CHAIN
      CHARACTER*4   BRCODE, PDBCOD
      CHARACTER*7   CATPDB(MXCATH)
      CHARACTER*20  CATFIL, CATNEW(MAXDOM)
      CHARACTER*50  CATDSC(MXTITL), CDESC(NLEVEL,MAXDOM)
      INTEGER       CATH(NUMLEV,MAXDOM), CATLEV(NLEVEL,MXTITL),
     -              CATNUM(NUMLEV,MXCATH), ICATH, IDOM, ILEV, ITITLE,
     -              NCATH, NDOM, NENTRY, NTITLE
      LOGICAL       GOTCAT

C---- Initialise variables
      GOTCAT = .FALSE.
      NDOM = 0
      NENTRY = 0
      DO 100, IDOM = 1, MAXDOM
          CATNEW(IDOM) = ' '
          DO 50, ILEV = 1, NLEVEL
              CDESC(ILEV,IDOM) = ' '
 50       CONTINUE
 100  CONTINUE

C---- Convert the PDB code to lower-case
      PDBCOD = BRCODE
      CALL LOWCAS(4,PDBCOD)

C---- Loop through all the PDB CATH entries, looking for matches
      DO 800, ICATH = 1, NCATH

C----     If this entry matches, store the details
          IF (CATPDB(ICATH)(1:4).EQ.PDBCOD .AND.
     -        ((CHAIN.EQ.' ' .OR. CHAIN.EQ.CATPDB(ICATH)(5:5)) .OR.
     -         (CHAIN.EQ.'A' .AND. CATPDB(ICATH)(5:5).EQ.'0'))) THEN

C----         Get the domain
              IDOM = 0
              READ(CATPDB(ICATH),220,ERR=300) IDOM
 220          FORMAT(5X,I2)
              IF (IDOM.EQ.0) THEN
                  IF (NDOM.NE.0) THEN
                      PRINT*, '*** Warning. Domain zero PLUS other dom',
     -                    'ains in CATH numbers file!'
                  ENDIF
                  IDOM = NDOM + 1
              ENDIF

C----         Check that maximum number of domains not exceeded
 300          CONTINUE
              IF (IDOM.GT.MAXDOM) THEN
                  PRINT*, '*** Warning. Maximum number of domains exce',
     -                'eded ', MAXDOM
                  GO TO 999

C----         If OK, then store this domain's CATH details
              ELSE IF (IDOM.NE.0) THEN

C----             Store the CATH number 
                  DO 350, ILEV = 1, NUMLEV
                      CATH(ILEV,IDOM) = CATNUM(ILEV,ICATH)
 350              CONTINUE

C----             Store the highest domain number so far
                  NDOM = MAX(IDOM,NDOM)

C----             Compress it into a string for display
                  CALL COMCAT(CATH(1,IDOM),CATNEW(IDOM),CATFIL,NUMLEV)

C----             Retrieve the description
                  DO 400, ITITLE = 1, NTITLE
                      IF (CATH(1,IDOM).EQ.CATLEV(1,ITITLE) .AND.
     -                    CATLEV(2,ITITLE).EQ.0) THEN
                          CDESC(1,IDOM) = CATDSC(ITITLE)
                          GOTCAT = .TRUE.
                      ELSE IF (CATH(1,IDOM).EQ.CATLEV(1,ITITLE) .AND.
     -                         CATH(2,IDOM).EQ.CATLEV(2,ITITLE) .AND.
     -                         CATLEV(3,ITITLE).EQ.0) THEN
                          CDESC(2,IDOM) = CATDSC(ITITLE)
                          GOTCAT = .TRUE.
                      ELSE IF (CATH(1,IDOM).EQ.CATLEV(1,ITITLE) .AND.
     -                         CATH(2,IDOM).EQ.CATLEV(2,ITITLE) .AND.
     -                         CATH(3,IDOM).EQ.CATLEV(3,ITITLE) .AND.
     -                         CATLEV(4,ITITLE).EQ.0) THEN
                          CDESC(3,IDOM) = CATDSC(ITITLE)
                          GOTCAT = .TRUE.
                      ELSE IF (CATH(1,IDOM).EQ.CATLEV(1,ITITLE) .AND.
     -                         CATH(2,IDOM).EQ.CATLEV(2,ITITLE) .AND.
     -                         CATH(3,IDOM).EQ.CATLEV(3,ITITLE) .AND.
     -                         CATH(4,IDOM).EQ.CATLEV(4,ITITLE)) THEN
                          CDESC(4,IDOM) = CATDSC(ITITLE)
                          GOTCAT = .TRUE.
                      ENDIF
 400              CONTINUE
              ENDIF
          ENDIF
 800  CONTINUE

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETDOM  -  See if current PDB chain has an CATH domain 
C                        annotations (minus domain numbers)
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETDOM(BRCODE,CHAIN,CDESC,NLEVEL,NDOMS,DOMPDB,DOMNUM,
     -    CATLEV,CATDSC,MXCATH,MXTITL,NTITLE,GOTCAT,CATH,NUMLEV,CATNEW,
     -    MAXDOM,NDOM)

      INTEGER       MAXDOM, MXCATH, MXTITL, NLEVEL, NUMLEV

      CHARACTER*1   CHAIN
      CHARACTER*4   BRCODE, PDBCOD
      CHARACTER*5   DOMPDB(MXCATH)
      CHARACTER*20  CATFIL, CATNEW(MAXDOM)
      CHARACTER*50  CATDSC(MXTITL), CDESC(NLEVEL,MAXDOM)
      INTEGER       CATH(NUMLEV,MAXDOM), CATLEV(NLEVEL,MXTITL),
     -              DOMNUM(MXCATH), ICATH, IDOM, ILEV, ITITLE,
     -              NDOMS, NDOM, NENTRY, NTITLE
      LOGICAL       GOTCAT

C---- Initialise variables
      GOTCAT = .FALSE.
      NDOM = 0
      NENTRY = 0
      DO 100, IDOM = 1, MAXDOM
          CATNEW(IDOM) = ' '
          DO 50, ILEV = 1, NLEVEL
              CDESC(ILEV,IDOM) = ' '
 50       CONTINUE
 100  CONTINUE

C---- Convert the PDB code to lower-case
      PDBCOD = BRCODE
      CALL LOWCAS(4,PDBCOD)

C---- Loop through all the PDB CATH entries, looking for matches
      DO 800, ICATH = 1, NDOMS

C----     If this entry matches, store the details
          IF (DOMPDB(ICATH)(1:4).EQ.PDBCOD .AND.
     -        ((CHAIN.EQ.' ' .OR. CHAIN.EQ.DOMPDB(ICATH)(5:5)) .OR.
     -         (CHAIN.EQ.'A' .AND. DOMPDB(ICATH)(5:5).EQ.'0'))) THEN

C----         Get the number of domains
              NDOM = DOMNUM(ICATH)

C----         Check that maximum number of domains not exceeded
 300          CONTINUE
              IF (NDOM.GT.MAXDOM) THEN
                  PRINT*, '*** Warning. Maximum number of domains exce',
     -                'eded ', MAXDOM
                  GO TO 999

C----         If OK, then store fake CATH details for each domain
              ELSE IF (NDOM.GT.0) THEN

C----             Loop over all the domains
                  DO 500, IDOM = 1, NDOM

C----                 Store the CATH number as zero
                      DO 350, ILEV = 1, NUMLEV
                          CATH(ILEV,IDOM) = 0
 350                  CONTINUE

C----                 Compress it into a string for display
                      CALL COMCAT(CATH(1,IDOM),CATNEW(IDOM),CATFIL,
     -                    NUMLEV)
 500              CONTINUE
              ENDIF
          ENDIF
 800  CONTINUE

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETPAT  -  Pick up any PROSITE patterns present in the
C                        given chain. Found by looking up Kasuya's 
C                        database of pattern-matches
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETPAT(PATFIL,TOFFIL,BRCODE,CHAIN,PROSIT,PDESC,PATRES,
     -    PATRNO,PATSEQ,PATCOL,PATOCC,MAXPAT,NPATTN,NDIFF,UPLOAD)

      INTEGER       MAXPAT, NAMINO

      PARAMETER    (NAMINO = 20)

      CHARACTER*1   CH, CHAIN, RCHAR(2)
      CHARACTER*3   CODE(NAMINO), PATRES(2,MAXPAT)
      CHARACTER*4   BRCODE, PDBCOD
      CHARACTER*5   PATRNO(2,MAXPAT), RESNO1, RESNO2
      CHARACTER*10  LSTPAT, PROPAT, PROSIT(MAXPAT)
      CHARACTER*30  PDESC(MAXPAT)
      CHARACTER*110 PATCOL(MAXPAT), PATSEQ(MAXPAT)
      CHARACTER*120 PATFIL, TOFFIL
      CHARACTER*520 IREC
      CHARACTER*1000 TEMP
      CHARACTER*(NAMINO)  AMINOS
      INTEGER       IPAT, IPOS, IRANGE, LEN, NDIFF, NOCCUR, NPATTN,
     -              NXTPOS, PATOCC(MAXPAT)
      LOGICAL       GOTPAT, UPLOAD, WANTED

      DATA  AMINOS / 'ACDEFGHIKLMNPQRSTVWY'/
      DATA  CODE   / 'Ala','Cys','Asp','Glu','Phe','Gly','His',
     -               'Ile','Lys','Leu','Met','Asn','Pro','Gln','Arg',
     -               'Ser','Thr','Val','Trp','Tyr' /

C---- Initialise variables
      GOTPAT = .FALSE.
      LSTPAT = ' '
      NDIFF = 0
      NOCCUR = 0
      NPATTN = 0
      DO 100, IPAT = 1, MAXPAT
          PATCOL(IPAT) = ' '
          PATOCC(IPAT) = 0
          PATRES(1,IPAT) = ' '
          PATRES(2,IPAT) = ' '
          PATRNO(1,IPAT) = ' '
          PATRNO(2,IPAT) = ' '
          PATSEQ(IPAT) = ' '
          PROSIT(IPAT) = ' '
          PDESC(IPAT) = ' '
 100  CONTINUE

C---- Convert the PDB code to lower-case
      PRINT*, 'Searching for PROSITE patterns for chain [', CHAIN,
     -    '] ...'
      PDBCOD = BRCODE
      CALL LOWCAS(4,PDBCOD)

C---- Open local copy of PROSITE pattern-matches database
      OPEN(UNIT=4, FILE='3dp.matches.list', STATUS='OLD',
     -    FORM='FORMATTED', ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=120)
      GO TO 150

C---- Open the PROSITE pattern-matches database
 120  CONTINUE
      OPEN(UNIT=4, FILE=PATFIL, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

C---- Open local copy of the PROSITE true/false database
 150  CONTINUE
      OPEN(UNIT=3, FILE='3dp.tof.list', STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=170)
      GO TO 200

C---- Open the PROSITE true/false database
 170  CONTINUE
      OPEN(UNIT=3, FILE=TOFFIL, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=902)

C---- Loop through the PROSITE pattern-matches database
 200  CONTINUE

C----     Read in the next record
          READ(4,320,ERR=800,END=800) IREC
 320      FORMAT(A)

C----     If this is the right record, then store pattern
          IF (IREC(1:4).EQ.PDBCOD .AND. (CHAIN.EQ.' ' .OR.
     -        IREC(7:7).EQ.CHAIN)) THEN

C----         Get the key details
              PROPAT = IREC(11:17)
              RESNO1 = IREC(52:56)
              RESNO2 = IREC(58:62)

C----         Check whether we already have this pattern stored
              CALL CHKDUP(PROPAT,PROSIT,PATRNO,RESNO1,RESNO2,NPATTN,
     -            MAXPAT,WANTED)

C----         Determine whether this is a "TRUE" hit
              IF (WANTED) THEN
                  CALL CHKPAT(PDBCOD,CHAIN,PROPAT,WANTED,UPLOAD)
              ENDIF

C----         Increment pattern count
              IF (WANTED .AND. NPATTN.LT.MAXPAT) THEN

C----             Increment number
                  NPATTN = NPATTN + 1

C----             Store the PROSITE id and pattern description
                  PROSIT(NPATTN) = PROPAT
                  PDESC(NPATTN) = IREC(20:42)

C----             If this is a new pattern, then reinitialise
C                 occurrence count
                  IF (PROSIT(NPATTN).NE.LSTPAT) THEN
                      NOCCUR = 0
                      NDIFF = NDIFF + 1
                  ENDIF
                  LSTPAT = PROSIT(NPATTN)
                  NOCCUR = NOCCUR + 1

C----             Store the pattern occurrence
                  PATOCC(NPATTN) = NOCCUR

C----             Get the start- and end residues of the pattern
                  PATRNO(1,NPATTN) = RESNO1
                  PATRNO(2,NPATTN) = RESNO2
                  TEMP = IREC(64:)

C----             Remove all extraneous characters
                  NXTPOS = 1
                  DO 400, IPOS = 1, 520
                      CH = TEMP(IPOS:IPOS)
                      IF (ICHAR(CH).EQ.9) THEN
                          TEMP(IPOS:IPOS) = ' '
                          CH = ' '
                      ENDIF

C----                 Ignore various extraneous characters
                      IF (CH.NE.'?' .AND. CH.NE.'>' .AND.
     -                    CH.NE.'<' .AND. CH.NE.'!' .AND.
     -                    CH.NE.'|') THEN
                          TEMP(NXTPOS:NXTPOS) = CH
                          NXTPOS = NXTPOS + 1
                      ENDIF

C----                 If have an exclamation mark, need to remove
C                     previous character as well
                      IF (CH.EQ.'!' .AND. NXTPOS.GT.0) THEN
                          NXTPOS = NXTPOS - 1
                      ENDIF
 400              CONTINUE
                  TEMP(NXTPOS:) = ' '

C----             Find where the pattern ends
                  LEN = INDEX(TEMP,' ') - 1

C----             Chop pattern off at end of sequence
                  IF (LEN.GT.0) THEN
                      PATSEQ(NPATTN) = TEMP(1:LEN)
                      PATCOL(NPATTN) = TEMP(LEN + 2:)
                  ELSE
                      PATSEQ(NPATTN) = TEMP
                      LEN = 110
                  ENDIF

C----             Get single-letter codes of first and last residues
                  RCHAR(1) = PATSEQ(NPATTN)(1:1)
                  RCHAR(2) = PATSEQ(NPATTN)(LEN:LEN)

C----             Convert single-letter codes to 3-letter residue names
                  DO 700, IRANGE = 1, 2

C----                 Get identifier for this single-letter code
                      IPOS = INDEX(AMINOS,RCHAR(IRANGE))

C----                 If valid code, then store corresponding name
                      IF (IPOS.GT.0 .AND. IPOS.LE.NAMINO) THEN
                          PATRES(IRANGE,NPATTN) = CODE(IPOS)

C----                 Otherwise, show as unknown
                      ELSE
                          PATRES(IRANGE,NPATTN) = 'UNK'
                      ENDIF
 700              CONTINUE

C----         Otherwise, if over the limit, display warning message
              ELSE IF (WANTED) THEN
                  PRINT*, '*** Warning. Maximum number of PROSITE matc',
     -                'hes exceeded for chain [', CHAIN, '] ', MAXPAT
              ENDIF

C----     If have hit a higher PDB code, then can end here as the
C         file is sorted by PDB code
          ELSE IF (LGT(IREC(1:4),PDBCOD)) THEN
              GO TO 800
          ENDIF

C---- Loop back for next record
      GO TO 200

C---- End of file reached
 800  CONTINUE

C---- Close the files
      CLOSE(3)
      CLOSE(4)
      PRINT*, '... done'

      GO TO 999

C---- Fatal errors
 900  CONTINUE
      PRINT*, '*** ERROR. Unable to open PROSITE data file '
      GO TO 990

 902  CONTINUE
      PRINT*, '*** ERROR. Unable to open PROSITE true/false file '
      GO TO 990

 990  CONTINUE

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETSWS  -  Identify any SWISS-PROT codes associated with this
C                        chain
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETSWS(ICHAIN,ITEM1)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   CH
      CHARACTER*6   NUMBER
      CHARACTER*20  ITEM1, ITEM2

      INTEGER       ICHAIN, ICHN, ISWISS, LENSTR, NSWS

C---- Initialise variables
      NSWS = 0

C---- Loop over the stored SWISS-PROT codes
      DO 300, ISWISS = 1, NSWISS

C----     Loop through all the chains associated with this code
          DO 250, ICHN = 1, NSWCHN(ISWISS)

C----         Get the chain identifier
              CH = SWICHN(ICHN,ISWISS)

C----         If this is our chain, write out the SWISS-PROT code to
C             the databases.dat file
              IF (CH.EQ.CHAIN(ICHAIN,CHN)) THEN

C----             Increment count of codes written out
                  NSWS = NSWS + 1

C----             Form subscript for current code
                  CALL SUBSCR(NSWS,ITEM2)

C----             Write out the code to the databases.dat file
C                  WRITE(DBASE,510) 'SPROT_CODE',
C     -                ITEM1(1:LENSTR(ITEM1)),
C     -                ITEM2(1:LENSTR(ITEM2)), ' ',
C     -                SWNAME(ISWISS)(1:LENSTR(SWNAME(ISWISS)))
              ENDIF
 250      CONTINUE
 300  CONTINUE

C---- Write out the number of SWISS-PROT codes associated with this
C     chain
C      IF (NSWS.GT.0) THEN
C          CALL FORNUM(NUMBER,NSWS)
C          WRITE(DBASE,510) 'NSWISS', ITEM1(1:LENSTR(ITEM1)), ' ',
C     -         NUMBER
C      ENDIF
      
 510  FORMAT(10A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE CHKDUP  -  Check whether we already have this PROSITE pattern
C                        stored
C
C----------------------------------------------------------------------+---

      SUBROUTINE CHKDUP(PROPAT,PROSIT,PATRNO,RESNO1,RESNO2,NPATTN,
     -    MAXPAT,WANTED)

      INTEGER       MAXPAT

      CHARACTER*5   PATRNO(2,MAXPAT), RESNO1, RESNO2
      CHARACTER*10  PROPAT, PROSIT(MAXPAT)
      LOGICAL       WANTED
      INTEGER       IPATTN, NPATTN

C---- Initialise variables
      WANTED = .TRUE.

C---- Loop through all the currently-stored patterns for this PDB entry
      DO 800, IPATTN = 1, NPATTN

C----     Check all the details'
          IF (PROPAT.EQ.PROSIT(IPATTN) .AND.
     -        PATRNO(1,IPATTN).EQ.RESNO1 .AND.
     -        PATRNO(2,IPATTN).EQ.RESNO2) THEN
              WANTED = .FALSE.
          ENDIF

 800  CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE CHKPAT  -  Check whether the entry is marked as TRUE in the
C                        PROSITE patterns true/false file
C
C----------------------------------------------------------------------+---

      SUBROUTINE CHKPAT(PDBCOD,CHAIN,PROSIT,WANTED,UPLOAD)

      CHARACTER*1   CHAIN
      CHARACTER*4   PDBCOD
      CHARACTER*10  PROSIT
      CHARACTER*120 IREC
      LOGICAL       UPLOAD, WANTED

C---- Initialise variables
      WANTED = .FALSE.

C---- Rewind the true/false file
      REWIND(3)

C---- Loop through the PROSITE true/false file
 200  CONTINUE

C----     Read in the next record
          READ(3,320,ERR=800,END=800) IREC
 320      FORMAT(A)

C----     If this is the right record, then store pattern
          IF (IREC(1:4).EQ.PDBCOD .AND. (CHAIN.EQ.' ' .OR.
     -        IREC(7:7).EQ.CHAIN) .AND. IREC(12:18).EQ.PROSIT) THEN

C----         Check whether it is a true match
              IF (IREC(44:44).EQ.'T' .OR. IREC(44:44).EQ.'t') THEN
                  WANTED = .TRUE.
              ENDIF

C----         If this is an uploaded PDB file, take it to be a true match
              IF (UPLOAD) WANTED = .TRUE.

C----     If have hit a higher PDB code, then can end here as the
C         file is sorted by PDB code
          ELSE IF (LGT(IREC(1:4),PDBCOD)) THEN
              GO TO 800
          ENDIF

C---- Loop back for next record
      GO TO 200

C---- End of file reached
 800  CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE COMCAT  -  Compress the CATH number and form the CATH
C                        filename
C
C----------------------------------------------------------------------+---

      SUBROUTINE COMCAT(CATH,CATCMP,CATFIL,NUMLEV)

      INTEGER       NUMLEV

      CHARACTER*20  CATNEW, CATCMP, CATFIL
      INTEGER       CATH(NUMLEV), ILEV, IPOS, ITRAN

C---- Initialise variables
      CATCMP = ' '
      CATFIL = ' '
      ITRAN = 0

C---- Write the component numbers
      WRITE(CATNEW,100) (CATH(ILEV), ILEV = 1, NUMLEV)
 100  FORMAT(I1,3('.',I5))

C---- Transfer the characters across, one by one, skipping any blanks
      DO 200, IPOS = 1, 20
          CATFIL(IPOS:IPOS) = CATNEW(IPOS:IPOS)
          IF (CATNEW(IPOS:IPOS).EQ.'.') THEN
              CATFIL(IPOS:IPOS) = '_'
              ITRAN = ITRAN + 1
              CATCMP(ITRAN:ITRAN) = CATNEW(IPOS:IPOS)
          ELSE IF (CATNEW(IPOS:IPOS).NE.' ') THEN
              ITRAN = ITRAN + 1
              CATCMP(ITRAN:ITRAN) = CATNEW(IPOS:IPOS)
          ELSE
              CATFIL(IPOS:IPOS) = '0'
          ENDIF
200   CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRITIT  -  Write title to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRITIT(IFILE,BRCODE)

      CHARACTER*4   BRCODE
      INTEGER       IFILE

C---- Write out HTML header details
      WRITE(IFILE,510) '<html>'
      WRITE(IFILE,510) '<head>'
      WRITE(IFILE,140) BRCODE
 140  FORMAT('<title>PDB ',A4,'</title>')
      WRITE(IFILE,510) '</head>'
      WRITE(IFILE,510) '<body>'
      WRITE(IFILE,*)

 510  FORMAT(10A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIGIF  -  Write GIF image(s) of structure to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIGIF(IFILE,PDBSUM,BRCODE)

      CHARACTER*4   BRCODE
      CHARACTER*(*) PDBSUM
      INTEGER       IFILE
      LOGICAL       HAVGIF, HAVTRA, NOREAD

C---- Small GIF image of protein
      WRITE(IFILE,510) '<h1><a href="tracel.html">',
     -    '<IMG ALIGN=MIDDLE SRC="traces.gif" ALT="View 1"></a>'

C---- Check whether there is a GIF image to be place to the right
      NOREAD = .FALSE.
      CALL CHKLNK(PDBSUM,'tracel_r.html',HAVTRA,NOREAD)
      NOREAD = .TRUE.
      CALL CHKLNK(PDBSUM,'traces_r.gif',HAVGIF,NOREAD)

C---- If have a GIF file, then include
      IF (HAVTRA .AND. HAVGIF) THEN
          WRITE(IFILE,510) '&nbsp;'
          WRITE(IFILE,510) '<a href="tracel_r.html" ALT="View 2">',
     -        '<IMG ALIGN=MIDDLE SRC="traces_r.gif"></a>'
      ENDIF

C---- PDB heading
      WRITE(IFILE,510) '&nbsp;'
      WRITE(IFILE,510) 'PDB code: ', BRCODE, '</h1>'
      WRITE(IFILE,*)

C---- Check whether there is a GIF image to be place below first image
      NOREAD = .FALSE.
      CALL CHKLNK(PDBSUM,'tracel_b.html',HAVTRA,NOREAD)
      NOREAD = .TRUE.
      CALL CHKLNK(PDBSUM,'traces_b.gif',HAVGIF,NOREAD)

C---- If have a GIF file, then include
      IF (HAVTRA .AND. HAVGIF) THEN
          WRITE(IFILE,510) '<a href="tracel_b.html">',
     -        '<IMG ALIGN=TOP SRC="traces_b.gif" ALT="View 3"></a>'
          WRITE(IFILE,510) '&nbsp;&nbsp;&nbsp;'
          WRITE(IFILE,510) '<EM>3 orthogonal views</EM>'
      ENDIF
      WRITE(IFILE,*)
      WRITE(IFILE,510) '<p>'

 510  FORMAT(10A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIOBS  -  Write links to entries superseding current PDB
C                        code to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIOBS(IFILE,PSTMPL,WWWPDB,NSUPER,SPRSDE,MXITEM,DBASE)

      INCLUDE 'fcommon.inc'

      INTEGER       MXITEM

      INTEGER       MAXLEN
      PARAMETER    (MAXLEN =   1000)

      CHARACTER*1   COMMA
      CHARACTER*4   OTHCOD, SPRSDE(MXITEM)
      CHARACTER*6   NUMBER
      CHARACTER*20  ITEM1, ITEM2
      CHARACTER*(FNAMLN) PSTMPL, PSUMDR
      CHARACTER*(MAXLEN) OUTLIN
      CHARACTER*(*) WWWPDB
      INTEGER       DBASE, IENTRY, IFILE, LENSTR, NSUPER, PLEN
      LOGICAL       HAVPDB, NOREAD

C---- Start heading
      WRITE(IFILE,510) '<H1><FONT color="#FF0000">Superseded'

C---- Write number of superseding entries to database.dat file
      WRITE(DBASE,510) 'OBSOLETE TRUE'
      IF (NSUPER.GT.0) THEN
          CALL FORNUM(NUMBER,NSUPER)
          WRITE(DBASE,510) 'NSUPER ', NUMBER
      ENDIF

C---- Next bit depends on number of superseding entries
      IF (NSUPER.EQ.0) THEN
          WRITE(IFILE,510) '</FONT></H1>'

C---- If have at least one entry, then list them
      ELSE

C----     Heading depends whether one or more entries
          IF (NSUPER.EQ.1) THEN
              WRITE(IFILE,510) 'by entry</FONT>'
          ELSE
              WRITE(IFILE,510) 'by entries</FONT>'
          ENDIF

C----     List through all the superseding entries
          DO 200, IENTRY = 1, NSUPER

C----         Form subscript for current line
              CALL SUBSCR(IENTRY,ITEM1)

C----         Initialise
              COMMA = ','
              IF (IENTRY.EQ.NSUPER) COMMA = '.'
              NOREAD = .TRUE.
              HAVPDB = .FALSE.

C----         Check whether this PDB file exists
              OTHCOD = SPRSDE(IENTRY)
              CALL LOWCAS(4,OTHCOD)

C----         Form the name of this PDBsum directory
              CALL FRMFNM(OTHCOD,PSTMPL,PSUMDR,FNAMLN)

C----         Check whether the database.dat file exists
              CALL CHKLNK(PSUMDR,'database.dat',HAVPDB,NOREAD)

C----         If file exists then add link to it
              IF (HAVPDB) THEN
                 PLEN = INDEX(WWWPDB,' ') - 1
                 OUTLIN = '<a href="' // WWWPDB(1:PLEN) // OTHCOD //
     -               '/main.html' // '">' // OTHCOD // '</a>'

C----         Otherwise just show the PDB code
              ELSE
                  OUTLIN = OTHCOD
              ENDIF

C----         Write out
              WRITE(DBASE,510) 'SUPERSEDED_BY',
     -                ITEM1(1:LENSTR(ITEM1)), ' ', OTHCOD

C----         Write the line
              WRITE(IFILE,510) OUTLIN(1:LENSTR(OUTLIN)), COMMA
 200      CONTINUE

C----     Finish off heading
          WRITE(IFILE,510) '</H1>'
      ENDIF

 510  FORMAT(10A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIVIE  -  Write links to PDB viewers to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIVIE(IFILE,BRCODE,PDBSUM,WWWRSC,NATOMS,MXSCRP)

      CHARACTER*1   QUOTE
      CHARACTER*4   BRCODE
      CHARACTER*60  MESSAG
      CHARACTER*(*) PDBSUM, WWWRSC
      INTEGER       IFILE, LENSTR, NATOMS, MXSCRP
      LOGICAL       HAVRSC, HAVWRL, NOREAD, TOOBIG

      DATA QUOTE  / '''' /

C---- Check whether have a Rasmol script file for this protein
      NOREAD = .TRUE.
      CALL CHKLNK(PDBSUM,'rasmol.dfn',HAVRSC,NOREAD)

C---- Check whether structure is too large to add link to Rasmol script
      TOOBIG = .FALSE.
      IF (NATOMS.GT.MXSCRP) TOOBIG = .TRUE.
      IF (TOOBIG) PRINT*, '*** Very large structure:- ', NATOMS,
     -    ' atoms'

C---- Add link to Perl script for displaying coords in RASMOL using the
C     Rasmol script
      WRITE(IFILE,510) '<P>'
      IF (HAVRSC .AND. .NOT.TOOBIG) THEN
          WRITE(IFILE,510) '<a href="', WWWRSC(1:LENSTR(WWWRSC)),
     -        BRCODE, '"'
          MESSAG = 'View schematic of structure (RasMol script)'
          WRITE(IFILE,510) 'onMouseOver="window.status=', QUOTE,
     -        MESSAG(1:LENSTR(MESSAG)), QUOTE, '; return true">'
          WRITE(IFILE,510) '<IMG WIDTH=50 BORDER=0 ALIGN=BOTTOM',
     -        ' SRC="../rasmol_scr.gif" ALT="RasMol script"></A>'
          WRITE(IFILE,*)
          WRITE(IFILE,510) '&nbsp;'
      ENDIF

C---- Add link to Perl script for displaying coords in Rasmol
      WRITE(IFILE,510) '<a href="', WWWRSC(1:LENSTR(WWWRSC)), BRCODE,
     -    '&script=NO"'
      MESSAG = 'Standard RasMol view of structure'
      WRITE(IFILE,510) 'onMouseOver="window.status=', QUOTE,
     -    MESSAG(1:LENSTR(MESSAG)), QUOTE, '; return true">'
      WRITE(IFILE,510) '<IMG ALIGN=BOTTOM SRC="../rasmol.gif" ALT="Ras',
     -    'Mol"></A>'
      WRITE(IFILE,*)
      WRITE(IFILE,510) '&nbsp;'

C---- Check whether have a VRML file for this protein
      NOREAD = .FALSE.
      CALL CHKLNK(PDBSUM,'secsurf.wrl',HAVWRL,NOREAD)

C---- If have a VRML file for this protein (secsurf.wrl), then add link
C     to it
      IF (HAVWRL) THEN
          WRITE(IFILE,510) '<A HREF="secsurf.wrl"'
          MESSAG = 'View schematic of structure using VRML browser'
          WRITE(IFILE,510) 'onMouseOver="window.status=', QUOTE,
     -        MESSAG(1:LENSTR(MESSAG)), QUOTE, '; return true">'
          WRITE(IFILE,510) '<IMG ALIGN=BOTTOM WIDTH=50 ',
     -        'SRC="../VRML.gif" ALT="VRML"></A>'
          WRITE(IFILE,510) 'v.1.0'
          WRITE(IFILE,*)
          WRITE(IFILE,510) '&nbsp;'

C---- Otherwise, check whether the gzipped version exists
      ELSE
          NOREAD = .TRUE.
          CALL CHKLNK(PDBSUM,'secsurf.wrl.gz',HAVWRL,NOREAD)

C----     If it does, add a link to it via the VRML.pl script
          IF (HAVWRL) THEN
              WRITE(IFILE,510) '<A HREF="/cgi-bin/cath/VRML.pl?pdb=',
     -            BRCODE, '"'
              MESSAG = 'View schematic of structure using VRML browser'
              WRITE(IFILE,510) 'onMouseOver="window.status=', QUOTE,
     -            MESSAG(1:LENSTR(MESSAG)), QUOTE, '; return true">'
              WRITE(IFILE,510) '<IMG ALIGN=BOTTOM WIDTH', '=50 SRC="..',
     -            '/VRML.gif" ALT="VRML"></A>'
              WRITE(IFILE,510) 'v.1.0'
              WRITE(IFILE,*)
              WRITE(IFILE,510) '&nbsp;'
          ENDIF
      ENDIF

C---- Add link to help page describing viewing in RasMol and VRML
      WRITE(IFILE,510) '<a href="../viewers.html">Help!</A>'

 510  FORMAT(10A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIPRO  -  Write protein header details to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIPRO(IFILE,HEADER,LAYER1,TITLE,NTLINE,COMPND,NCLINE,
     -    SOURCE,NSLINE,AUTHOR,NALINE,NMR,NMODEL,RESOL,RFACT,RFREE,DATE)

      INTEGER       NALINE, NCLINE, NSLINE, NTLINE, PDILEN
      PARAMETER    (PDILEN = 60)

      CHARACTER*11  DATE
      CHARACTER*(PDILEN) AUTHOR(NALINE), COMPND(NCLINE), OUTREC,
     -              SOURCE(NSLINE), TITLE(NTLINE)
      CHARACTER*(*) HEADER
      INTEGER       IEND, IFILE, ILINE, IPOS, LENSTR, NMODEL
      LOGICAL       LAYER1, NMR
      REAL          RESOL, RFACT, RFREE

C---- Protein name
      WRITE(IFILE,*)
      WRITE(IFILE,510) '<h2>'
      WRITE(IFILE,510) HEADER
      WRITE(IFILE,510) '</h2>'
      WRITE(IFILE,*)
      WRITE(IFILE,510) '<p>'

C---- If this is a "Layer 1" release, show warning
      IF (LAYER1) THEN
          WRITE(IFILE,510) '<H3><FONT color="#FF0000">WARNING:</FONT>'
          WRITE(IFILE,510) '<FONT color="#0000FF">This entry comes from'
          WRITE(IFILE,510) 'a PDB "Layer 1" release file and, as such,'
          WRITE(IFILE,510) 'may contain severe irregularities.</FONT>'
          WRITE(IFILE,510) '</H3>'
      ENDIF

C---- Title
      IF (NTLINE.GT.0) THEN
          WRITE(IFILE,510) '<b>Title:</b><em>'
          WRITE(IFILE,520) (TITLE(ILINE)(1:LENSTR(TITLE(ILINE))),
     -        ILINE = 1, NTLINE)
          WRITE(IFILE,510) '</em><br>'
      ENDIF

C---- Structure
      WRITE(IFILE,510) '<b>Structure:</b><em>'
      WRITE(IFILE,520) (COMPND(ILINE), ILINE = 1, NCLINE)
      WRITE(IFILE,510) '</em><br>'

C---- Source
      WRITE(IFILE,510) '<b>Source:</b><em>'
      WRITE(IFILE,520) (SOURCE(ILINE), ILINE = 1, NSLINE)
      WRITE(IFILE,510) '</em>'
      WRITE(IFILE,*)

C---- NMR structure - number of models
      IF (NMR) THEN
          WRITE(IFILE,510) '<p>'
          WRITE(IFILE,510) '<FONT COLOR=BLUE><b>NMR</b> structure:</FO',
     -        'NT>'
          IF (NMODEL.EQ.1) THEN
              WRITE(IFILE,320) NMODEL
 320          FORMAT('<b>',I6,'</b> model.')
          ELSE
              WRITE(IFILE,340) NMODEL
 340          FORMAT('<b>',I6,'</b> models.')
          ENDIF

C---- Resolution and R-factor
      ELSE

C----     If have an ensemble of crystal structures, write out the number
C         of models
          IF (NMODEL.GT.0) THEN
              WRITE(IFILE,510) '<p>'
              WRITE(IFILE,510) 'Ensemble of '
              IF (NMODEL.EQ.1) THEN
                  WRITE(IFILE,420) NMODEL
 420              FORMAT('<b>',I6,'</b> model.')
              ELSE
                  WRITE(IFILE,440) NMODEL
 440              FORMAT('<b>',I6,'</b> models.')
              ENDIF
          ENDIF

C----     Write out the resolution and R-factor(s)
          WRITE(IFILE,510) '<p>'
          IF (RESOL.GT.0.0) THEN
              WRITE(IFILE,560) '<b>Resolution:</b>', RESOL
 560          FORMAT(A,1X,F5.2,'&Aring;. ')
          ELSE
              WRITE(IFILE,510) 'No resolution given.'
          ENDIF
          IF (RFACT.GT.0.0) THEN
              WRITE(IFILE,580) '<b>R-factor:</b>', RFACT
 580          FORMAT(A,1X,F8.3,'. ')
          ELSE
              WRITE(IFILE,510) 'No <i>R</i>-factor given.'
          ENDIF
          IF (RFREE.GT.0.0) THEN
              WRITE(IFILE,580) '<b>R-free:</b>', RFREE
          ENDIF
          WRITE(IFILE,*)
      ENDIF

C---- Authors
      WRITE(IFILE,510) '<p>'
      WRITE(IFILE,510) '<b>Authors:</b> '

C---- Loop over the author lines
      DO 1200, ILINE = 1, NALINE

C----     Initialise variables for current author line
          IPOS = 1

C----     Loop through the authors, writing out one by one
 1100     CONTINUE
              OUTREC = AUTHOR(ILINE)(IPOS:PDILEN)
              IF (OUTREC.NE.' ') THEN
                  IEND = INDEX(OUTREC,',')
                  IF (IEND.LT.1) IEND = PDILEN
                  WRITE(IFILE,520) OUTREC(1:IEND)
                  IPOS = IPOS + IEND
                  IF (IPOS.LE.PDILEN) GO TO 1100
              ENDIF
 1200 CONTINUE
      WRITE(IFILE,*)

C---- Date
      WRITE(IFILE,510) '<P><b>Date:</b> ', DATE
      WRITE(IFILE,*)

 510  FORMAT(10A)
 520  FORMAT(A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRITAB  -  Write table of links to other Web sites to the
C                        HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRITAB(IFILE,DOHEAD,BRCODE,PDBCOD,HAVUNP,UNPUBL,PDB3DB,
     -    IMBJEN,WWWCAT,WWWFSP,WWWMAC,WWWMMD,WWWNDB,WWWREP,WWWSCP,
     -    WWWYEA,NCHAIN,NNUCL,NDBREF,YEAST,HAVCHK,HAVPRO)


      CHARACTER*1   FSTLET
      CHARACTER*4   BRCODE, PDBCOD
      CHARACTER*8   NDBREF, UPPREF
      CHARACTER*200 FILNAM
      CHARACTER*(*) DOHEAD, PDB3DB, UNPUBL
      CHARACTER*(*) IMBJEN, WWWCAT, WWWFSP, WWWMAC, WWWMMD, WWWNDB,
     -              WWWREP, WWWSCP, WWWYEA
      INTEGER       IFILE, ILINK, IPOS, LENSTR, NCHAIN, NLINK, NNUCL
      LOGICAL       HAVCHK, HAVPRO, HAVUNP, YEAST

C---- Start of "Further information" block

C---- Create the table that will hold the links
      WRITE(IFILE,510) '<p>'
      WRITE(IFILE,510) '<b>Further information:</b>'
      WRITE(IFILE,510) '<CENTER>'
      WRITE(IFILE,510) '<TABLE WIDTH=90%>'

C---- Row 1: PDB header, PDB entry, MMDB entry
      WRITE(IFILE,510) '<TR>'

C---- ... 1a. PDB header information

C---- ..... Link
      FILNAM = DOHEAD(1:LENSTR(DOHEAD)) // BRCODE
      WRITE(IFILE,510) '<TD ALIGN=CENTER>'
      WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)), '">'
      WRITE(IFILE,510) '<IMG SRC="../button1.gif" ALT="."></A>'
      WRITE(IFILE,510) '<TD><B>PDB header</B>'

C---- ..... Description
      IF (HAVUNP) THEN
          WRITE(IFILE,510) '(including references, see also <a href="',
     -        UNPUBL(1:LENSTR(UNPUBL)), BRCODE, '">',
     -        'Updated refs.</a>)'
      ELSE
          WRITE(IFILE,510) '(including references)'
      ENDIF
      WRITE(IFILE,*)

C---- ... 1b. Link to PDB entry (new site)
      
C---- ..... Link
      FILNAM = PDB3DB(1:LENSTR(PDB3DB)) // PDBCOD // '&new=TRUE'
      WRITE(IFILE,510) '<TD ALIGN=CENTER>'
      WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)), '">'
      WRITE(IFILE,510) '<IMG SRC="../button1.gif" ALT="."></A>'

C---- ..... Description
      WRITE(IFILE,510) '<TD><B>PDB entry</B>'
      WRITE(IFILE,*)

CC---- ... 1c. Link to PDB entry (old site)
C      
CC---- ..... Link
C      FILNAM = PDB3DB(1:LENSTR(PDB3DB)) // PDBCOD
C      WRITE(IFILE,510) '<TD ALIGN=CENTER>'
C      WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)), '">'
C      WRITE(IFILE,510) '<IMG SRC="../button1.gif" ALT="."></A>'
C
CC---- ..... Description
C      WRITE(IFILE,510) '<TD><B>PDB entry</B><BR>(old)'
C      WRITE(IFILE,*)

C---- ... 1c. Link to  IMB Jena
      
C---- ..... Link
      FILNAM = IMBJEN(1:LENSTR(IMBJEN)) // BRCODE
      WRITE(IFILE,510) '<TD ALIGN=CENTER>'
      WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)), '">'
      WRITE(IFILE,510) '<IMG SRC="../button1.gif" ALT="."></A>'

C---- ..... Description
      WRITE(IFILE,510) '<TD><B>IMB Jena</B><BR>image library'
      WRITE(IFILE,*)


C---- Row 2: MMDB link at NCBI, NDB entry, Macromolecule, Yeast

C---- Start the new row
      WRITE(IFILE,510) '<TR>'

C---- ... 2a. MMDB link (NCBI)
      
C---- ..... Link
      FILNAM = WWWMMD(1:LENSTR(WWWMMD)) // BRCODE
      WRITE(IFILE,510) '<TD ALIGN=CENTER>'
      WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)), '">'
      WRITE(IFILE,510) '<IMG SRC="../button1.gif" ALT="."></A>'

C---- ..... Description
      WRITE(IFILE,510) '<TD><B>MMDB entry</B> at the NCBI'
      WRITE(IFILE,*)

C---- Check whether there are any entries on this row
      IF (NDBREF.NE.' ' .OR. NCHAIN.GT.0 .OR. NNUCL.GT.0
     -    .OR. YEAST) THEN

C----     Initialise count of links written out
          NLINK = 1

C----     ... 2a. NDB entry, if present
          IF (NDBREF.NE.' ') THEN

C----         ..... Link
              FSTLET = NDBREF(1:1)
              CALL UPPCAS(1,FSTLET)
              FILNAM = WWWNDB(1:LENSTR(WWWNDB)) // FSTLET // '/' //
     -             NDBREF(1:LENSTR(NDBREF)) // '/' // NDBREF
              WRITE(IFILE,510) '<TD ALIGN=CENTER>'
              WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)),
     -            '">'
              WRITE(IFILE,510) '<IMG SRC="../button2.gif" ALT="."></A>'

C----         ..... Description
              UPPREF = NDBREF
              CALL UPPCAS(8,UPPREF)
              WRITE(IFILE,510) '<TD><B>NDB entry</B> (ref: ',
     -            UPPREF(1:LENSTR(UPPREF)), ')'
              WRITE(IFILE,*)
              NLINK = NLINK + 1
          ENDIF

C---- ... 2b. Complete Macromolecule
          IF (NCHAIN.GT.0 .OR. NNUCL.GT.0) THEN

C----         ..... Link
              FILNAM = WWWMAC(1:LENSTR(WWWMAC)) // BRCODE
              WRITE(IFILE,510) '<TD ALIGN=CENTER>'
              WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)),
     -            '">'
              WRITE(IFILE,510) '<IMG SRC="../button2.gif" ALT="."></A>'

C----         ..... Description
              WRITE(IFILE,510) '<TD>The complete <B>macromolecule</B>'
              WRITE(IFILE,*)
              NLINK = NLINK + 1
          ENDIF

C----     ... 2c. Yeast
          IF (YEAST) THEN
              
C----         ..... Link
              FILNAM = WWWYEA
              WRITE(IFILE,510) '<TD ALIGN=CENTER>'
              WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)),
     -            '">'
              WRITE(IFILE,510) '<IMG SRC="../button2.gif" ALT="."></A>'

C----         ..... Description
              WRITE(IFILE,510) '<TD><B>Yeast Structures</B> database'
              WRITE(IFILE,*)
              NLINK = NLINK + 1
          ENDIF

C----     Pad out missing links
          DO 1250, ILINK = NLINK + 1, 3
              WRITE(IFILE,510) '<TD>&nbsp;'
              WRITE(IFILE,*)
1250      CONTINUE
      ENDIF

C---- Row 3: CATH, SCOP and FSSP links

C---- Check whether there are any entries on this row
      IF (NCHAIN.NE.0) THEN

C----     Start the new row
          WRITE(IFILE,510) '<TR>'

C----     ... 3a. CATH

C----     ..... Link
          IPOS = INDEX(WWWCAT,'****') - 1
          FILNAM = WWWCAT(1:IPOS) // BRCODE // WWWCAT(IPOS + 5:)
          WRITE(IFILE,510) '<TD ALIGN=CENTER>'
          WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)), '">'
          WRITE(IFILE,510) '<IMG SRC="../button3.gif" ALT="."></A>'

C----     ..... Description
          WRITE(IFILE,510) '<TD><B>CATH</B> structural classification'
          WRITE(IFILE,*)

C----     ... 3b. SCOP

C----     ..... Link
          FILNAM = WWWSCP(1:LENSTR(WWWSCP)) // BRCODE
          WRITE(IFILE,510) '<TD ALIGN=CENTER>'
          WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)), '">'
          WRITE(IFILE,510) '<IMG SRC="../button3.gif" ALT="."></A>'

C----     ..... Description
          WRITE(IFILE,510) '<TD><B>SCOP</B> structural classification'
          WRITE(IFILE,*)

C----     ... 3c. FSSP

C----     ..... Link
          FILNAM = WWWFSP(1:LENSTR(WWWFSP)) // BRCODE
          WRITE(IFILE,510) '<TD ALIGN=CENTER>'
          WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)), '">'
          WRITE(IFILE,510) '<IMG SRC="../button3.gif" ALT="."></A>'

C----     ..... Description
          WRITE(IFILE,510) '<TD><B>FSSP</B> structural alignments'
          WRITE(IFILE,*)
      ENDIF

C---- Row 4: PROCHECK, WHATCHECK and PROMOTIF

C---- Check whether there are any entries on this row
      IF (HAVCHK .OR. HAVPRO) THEN
          NLINK = 0

C----     Start the new row
          WRITE(IFILE,510) '<TR>'

C----     If have PROCHECK info, write out PROCHECK and WHATCHECK links
          IF (HAVCHK) THEN

C----         ... 4a. PROCHECK

C----         ..... Link
              FILNAM = 'procheck.html'
              WRITE(IFILE,510) '<TD ALIGN=CENTER>'
              WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)),
     -            '">'
              WRITE(IFILE,510) '<IMG SRC="../button4.gif" ALT="."></A>'

C----         ..... Description
              WRITE(IFILE,510) '<TD><B>PROCHECK</B> summary'
              WRITE(IFILE,*)
              NLINK = NLINK + 1

C----         ... 4b. WHATCHECK

C----         ..... Link
              FILNAM = WWWREP(1:LENSTR(WWWREP)) // BRCODE
              WRITE(IFILE,510) '<TD ALIGN=CENTER>'
              WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)),
     -            '">'
              WRITE(IFILE,510) '<IMG SRC="../button4.gif" ALT="."></A>'

C----         ..... Description
              WRITE(IFILE,510) '<TD><B>WHATIF</B> check report'
              WRITE(IFILE,*)
              NLINK = NLINK + 1
          ENDIF

C----     ... 4c. PROMOTIF
          IF (HAVPRO) THEN

C----         ..... Link
              FILNAM = 'promotif.html'
              WRITE(IFILE,510) '<TD ALIGN=CENTER>'
              WRITE(IFILE,510) '<A HREF="', FILNAM(1:LENSTR(FILNAM)),
     -            '">'
              WRITE(IFILE,510) '<IMG SRC="../button4.gif" ALT="."></A>'

C----         ..... Description
              WRITE(IFILE,510) '<TD><B>PROMOTIF</B> analyses'
              WRITE(IFILE,*)
              NLINK = NLINK + 1
          ENDIF

C----     Pad out missing links
          DO 1300, ILINK = NLINK + 1, 3
              WRITE(IFILE,510) '&nbsp;'
              WRITE(IFILE,*)
 1300     CONTINUE
      ENDIF

C---- Close off the "Further information" table
      WRITE(IFILE,510) '</TABLE>'
      WRITE(IFILE,510) '</CENTER>'
      WRITE(IFILE,*)

 510  FORMAT(10A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIECN  -  Write E.C. number to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIECN(IFILE,BRCODE,ECNUMB,NEC,EENTRY,MXENTR,WWWENZ,
     -    ENZPTH,NAMLEN,EXPENZ,KYOENZ,WITENZ,NUMLEN,ECTMPL,DBASE)

      INTEGER       MXENTR

      CHARACTER*1   QUOTE
      CHARACTER*4   BRCODE
      CHARACTER*6   NUMBER
      CHARACTER*12  EENTRY(MXENTR), ECOMPR, ECSTAN, ECTMPL
      CHARACTER*20  ITEM1
      CHARACTER*25  ECLINE
      CHARACTER*30  ECNUMB, SAVNUM, STONUM
      CHARACTER*120 FNAME
      CHARACTER*(*) ENZPTH, EXPENZ, KYOENZ, WITENZ, WWWENZ
      INTEGER       DBASE, IENTRY, IFILE, IPOS, LENSTR, NAMLEN(MXENTR),
     -              NEC, NUMLEN(4)
      LOGICAL       DIFFER, IERROR, NEWSTY

      DATA QUOTE / '''' /

C---- Initialise flag
      DIFFER = .TRUE.
      STONUM = ECNUMB

C---- Write out heading
      IF (IFILE.EQ.7) THEN
          IF (NEC.GT.1) THEN
              WRITE(IFILE,510) '<b>Enzyme Classification numbers:</b>'
          ELSE
              WRITE(IFILE,510) '<b>Enzyme Classification number:</b>'
          ENDIF

C----     Set flag
          NEWSTY = .FALSE.
          ECLINE = ' '

      ELSE
          ECLINE = 'Enzyme Classification:'

C----     Set flag
          NEWSTY = .TRUE.
      ENDIF

C---- If there is more than one number, start list
      IF (.NOT.NEWSTY .AND. NEC.GT.1) THEN
          WRITE(IFILE,510) '<UL>'
      ENDIF

C---- Write number of entries to the database.dat file
      IF (NEC.GT.0) THEN
C          WRITE(DBASE,510) 'ENZYME TRUE'
C          CALL FORNUM(NUMBER,NEC)
C          WRITE(DBASE,510) 'NEC ', NUMBER
      ENDIF

C---- Get the URL of the appropriate Enzymes Database entry/entries
      DO 1400, IENTRY = 1, NEC

C----     Form subscript for current E.C. number
          CALL SUBSCR(IENTRY,ITEM1)

C----     For new-style layout, start table-row
          IF (NEWSTY) THEN
              WRITE(IFILE,510) '<TR><TH>', ECLINE(1:LENSTR(ECLINE)),
     -            '</TH>'
              ECLINE = '&nbsp;'
          ENDIF

C----     Get the WWW directory
          CALL GETDIR(EENTRY(IENTRY),WWWENZ,ENZPTH,NAMLEN(IENTRY))
          FNAME = ENZPTH(1:NAMLEN(IENTRY)) // 'index.html#' //
     -        BRCODE
          NAMLEN(IENTRY) = NAMLEN(IENTRY) + 15

C----     Compress the E.C. number
          CALL COMPRS(EENTRY(IENTRY),ECOMPR)

C----     Write number of entries to the database.dat file
C          WRITE(DBASE,510) 'EC_NUMBER', ITEM1(1:LENSTR(ITEM1)),
C     -        ' ', ECOMPR(1:LENSTR(ECOMPR))

C----     Old-style
          IF (.NOT.NEWSTY) THEN

C----         Write out the URL for the E.C. number
              WRITE(IFILE,510) '<a href="', FNAME(1:NAMLEN(IENTRY)),
     -            '"><b>E.C.', ECOMPR, '</b></a>, '

C----         Add link to ExPaSy ENZYME database
              WRITE(IFILE,510) '[<a href="',
     -            EXPENZ(1:LENSTR(EXPENZ)), ECOMPR(1:LENSTR(ECOMPR)),
     -            '">ExPaSy</a>], '

C----         Add link to Kyoto Univ database
              WRITE(IFILE,510) '[<a href="',
     -            KYOENZ(1:LENSTR(KYOENZ)), ECOMPR(1:LENSTR(ECOMPR)),
     -            '">Kyoto Univ.</a>], '

C----         Add link to WIT database
              WRITE(IFILE,510) '[<a href="',
     -            WITENZ(1:LENSTR(WITENZ)), ECOMPR(1:LENSTR(ECOMPR)),
     -            '">WIT</a>]'

C----     New-style
          ELSE

C----         Write out the EC number
              WRITE(IFILE,510) '<TH><FONT COLOR=BLUE>',
     -            ECOMPR, '</FONT></TH>'

C----         Add link to Enzyme structures database
              WRITE(IFILE,510) '<TH><a href="', FNAME(1:NAMLEN(IENTRY)),
     -            '" onMouseOver="window.status=', QUOTE, 'E.C.->PDB: ',
     -            'Enzyme Structures Database at UCL', QUOTE, '; retur',
     -            'n true;"><IMG BORDER=0 SRC="../gif/ecpdb_off.gif"><',
     -            '/a></TH>'

C----         Add link to ExPaSy ENZYME database
              WRITE(IFILE,510) '<TH><a href="',
     -            EXPENZ(1:LENSTR(EXPENZ)), ECOMPR(1:LENSTR(ECOMPR)),
     -            '" onMouseOver="window.status=', QUOTE, 'ExPaSy Enzy',
     -            'me Database', QUOTE, '; return true;"><IMG BORDER=0',
     -            ' SRC="../gif/expasy_off.gif"></a></TH>'

C----         Add link to KEGG database
              WRITE(IFILE,510) '<TH><a href="',
     -            KYOENZ(1:LENSTR(KYOENZ)), ECOMPR(1:LENSTR(ECOMPR)),
     -            '" onMouseOver="window.status=', QUOTE, 'KEGG: Kyoto',
     -            ' Encyclopedia of Genes and Genomes', QUOTE, '; retu',
     -            'rn true;"><IMG BORDER=0 SRC="../gif/kegg_off.gif"><',
     -            '/a></TH>'

C----         Add link to WIT database
              WRITE(IFILE,510) '<TH><a href="',
     -            WITENZ(1:LENSTR(WITENZ)), ECOMPR(1:LENSTR(ECOMPR)),
     -            '" onMouseOver="window.status=', QUOTE, 'WIT (What I',
     -            's There) database of functional assignments and met',
     -            'abolic pathways', QUOTE, '; return true;"><IMG BORD',
     -            'ER=0 SRC="../gif/wit_off.gif"></a></TH>'
          ENDIF

C----     For new-style, close off table-row
          IF (NEWSTY) THEN
              WRITE(IFILE,510) '</TR>'

C----     Old-style
          ELSE

C----         Line-throw
              WRITE(IFILE,*)

C----         If more than one, throw new line
              IF (NEC.GT.1) THEN
                  WRITE(IFILE,510) '<BR>'
              ENDIF
          ENDIF

C----     Check whether this matched the E.C. number given in the 
C         PDB file
          IF (ECOMPR.EQ.ECNUMB) DIFFER = .FALSE.
 1400 CONTINUE

C---- If there is more than one number, end list
      IF (.NOT.NEWSTY .AND. NEC.GT.1) THEN
          WRITE(IFILE,510) '</UL>'
      ENDIF

C---- Number from PDB file, if different
      IF (ECNUMB.NE.' ' .AND. DIFFER) THEN
          IF (NEWSTY) THEN
              IF (NEC.EQ.0) THEN
                  WRITE(IFILE,510) '<TR><TH><em>Enzyme class from PDB ',
     -                'file:</em></TH>'
              ELSE
                  WRITE(IFILE,510) '<TR><TH><em>from PDB file:</em></T',
     -                'H>'
              ENDIF
          ELSE
              WRITE(IFILE,510) '(<em>from PDB file:</em> '
          ENDIF

C----     Write out to database.dat file
C          IF (NEC.EQ.0) THEN
C              WRITE(DBASE,510) 'ENZYME TRUE'
C          ENDIF
C          WRITE(DBASE,510) 'EC_PDB ', ECNUMB(1:LENSTR(ECNUMB))

C----     If the E.C. number from the PDB file is the only E.C.
C         number reference we have (ie no reference in pdb_EC), then
C         add the appropriate link to it
          IF (NEC.EQ.0) THEN

C----         Check if there is more than one
              SAVNUM = ' '
              IPOS = INDEX(ECNUMB,',')
              IF (IPOS.GT.1) THEN
                  SAVNUM = ECNUMB(IPOS + 1:)
                  ECNUMB = ECNUMB(1:IPOS - 1)
              ENDIF

C----         Convert the number into the standard form
              CALL ECCONV(ECNUMB,ECSTAN,NUMLEN,ECTMPL,IERROR)

C----         Get the WWW directory
              CALL GETDIR(ECSTAN,WWWENZ,ENZPTH,NAMLEN(IENTRY))
              FNAME = ENZPTH(1:NAMLEN(IENTRY)) // 'index.html#' //
     -             BRCODE
              NAMLEN(IENTRY) = NAMLEN(IENTRY) + 15

C----         Write out the URL for the E.C. number
              IF (.NOT.NEWSTY) THEN
                  IF (SAVNUM.EQ.' ') THEN
                      WRITE(IFILE,510) '<a href="',
     -                    FNAME(1:NAMLEN(IENTRY)),
     -                    '"><b>E.C.', ECNUMB, '</b></a>)'
                  ELSE
                      WRITE(IFILE,510) '<a href="',
     -                    FNAME(1:NAMLEN(IENTRY)),
     -                    '"><b>E.C.', ECNUMB, '</a>, ',
     -                    SAVNUM(1:LENSTR(SAVNUM)), '</b>)'
                  ENDIF
                  WRITE(IFILE,*)

C----         New-style
              ELSE

C----             Write out EC number from PDB file
                  WRITE(IFILE,510) '<TH><FONT COLOR=BLUE>E.C.', ECNUMB,
     -                '</FONT></TH>'

C----             Write out link to Enzyme Structures Database
                  WRITE(IFILE,510) '<TH><a href="',
     -                FNAME(1:NAMLEN(IENTRY)),
     -                '" onMouseOver="window.status=', QUOTE,
     -                'E.C.->PDB: Enzyme Structures Database at UCL',
     -                QUOTE, '; return true;"><IMG BORDER=0 SRC="../gi',
     -                'f/ecpdb_off.gif"></a></TH>'
 
                  IF (SAVNUM.NE.' ') THEN
                      WRITE(IFILE,510) '<TH><FONT COLOR=BLUE>',
     -                    SAVNUM(1:LENSTR(SAVNUM)), '</FONT></TH>'
                  ENDIF
              ENDIF

C----         Write the details out to the enzyme.out info file
              WRITE(12,1620) BRCODE, ECNUMB, SAVNUM
 1620         FORMAT(A4,' -p- from PDB file only:',A12,A)

C----     Otherwise, just write out the E.C. number
          ELSE
              IF (NEWSTY) THEN
                  WRITE(IFILE,520) '<TH><FONT COLOR=BLUE>', ECNUMB,
     -                '</TH>'
              ELSE
                  WRITE(IFILE,520) ECNUMB
              ENDIF

C----         Write the details out to the enzyme.out info file
              WRITE(12,1640) BRCODE, EENTRY(1), ECNUMB
 1640         FORMAT(A4,' *** Mismatch. pdb_EC :',A12,'  PDB: ',A12)
              WRITE(IFILE,510) ' )'
          ENDIF

C----     New-style close off table-row
          IF (NEWSTY) THEN
              WRITE(IFILE,510) '</TR>'
          ELSE
              WRITE(IFILE,*)
          ENDIF
      ENDIF

C---- Restore the saved E.C. number
      ECNUMB = STONUM

 510  FORMAT(20A)
 520  FORMAT(A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE ECCONV  -  Convert the read-in E.C. number into a standard
C                        format
C
C----------------------------------------------------------------------+---

      SUBROUTINE ECCONV(ECCODE,ECSTAN,NUMLEN,ECTMPL,IERROR)

      CHARACTER*12  ECCODE, ECSTAN, ECTEMP, ECTMPL
      INTEGER       DPOS, IPART, IPOS, ITRAN, NUMLEN(4)
      LOGICAL       IERROR

C---- Initialise variables
      ECSTAN = ECTMPL
      IPOS = 1
      ITRAN = -1

C---- Remove any unwanted commas
      DPOS = INDEX(ECCODE,',')
      IF (DPOS.GT.1) THEN
          ECTEMP = ECCODE(1:DPOS - 1)
          ECCODE = ECTEMP
      ENDIF

C---- Locate all 4 numbers
      DO 200, IPART = 1, 4

C----     Get (end) position where this number will go
          ITRAN = ITRAN + NUMLEN(IPART) + 1

C----     Retrieve the next part of the number
          ECTEMP = ECCODE(IPOS:)
          IF (IPART.LT.4) THEN
              DPOS = INDEX(ECTEMP,'.')
          ELSE
              DPOS = INDEX(ECTEMP,' ')
          ENDIF
          IF (DPOS.LE.1) GO TO 900

C----     Check whether number of digits is not too long
          IF (DPOS - 1.GT.NUMLEN(IPART)) GO TO 902

C----     Transfer this part across into the standard format
          ECSTAN(ITRAN - DPOS + 2:ITRAN) = ECTEMP(1:DPOS - 1)

C----     Set pointers for next loop
          IPOS = IPOS + DPOS
200   CONTINUE

      GO TO 999

C---- Errors
900   CONTINUE
      PRINT*, '*** Error in E.C. number  [', ECCODE, '] at position',
     -    IPOS
      PRINT*, '*** Missing dot or space'
      GO TO 990

902   CONTINUE
      PRINT*, '*** Error in E.C. number  [', ECCODE, '] at position',
     -    IPOS
      PRINT*, '*** Too many digits at this position'
      GO TO 990

990   CONTINUE
      IERROR = .TRUE.

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETDIR  -  Return the name of the given directory from the
C                        supplied E.C. number
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETDIR(ECCODE,ENZDIR,ENZPTH,NAMLEN)

      CHARACTER*1   CH
      CHARACTER*12  ECCODE
      CHARACTER*120 ENZDIR, ENZPTH, STUB
      INTEGER       IEND, IPOS, LPOS, NAMLEN, SPOS
      LOGICAL       FINISH

C---- Initialise variables
      FINISH = .FALSE.
      IEND = 0
      NAMLEN = INDEX(ENZDIR,' ') - 1
      STUB = 'ec'
      LPOS = 1
      SPOS = 3

C---- Loop through the characters of the E.C. number to form the path
      DO 300, IPOS = 1, 12

C----     Process if not already finished
          IF (.NOT.FINISH) THEN

C----         Retrieve the character at this position
              CH = ECCODE(IPOS:IPOS)

C----         If this is a space, then replace by a zero
              IF (CH.EQ.' ') THEN
                  STUB(SPOS:SPOS) = '0'
                  SPOS = SPOS + 1

C----         If this is a dot, then prepare for next directory
              ELSE IF (CH.EQ.'.') THEN
                  STUB(SPOS:SPOS + 2) = '/ec'
                  LPOS = SPOS
                  SPOS = SPOS + 3

C----         If this is a hyphen, then stop at this class
              ELSE IF (CH.EQ.'-') THEN
                  SPOS = LPOS
                  FINISH = .TRUE.

C----         Otherwise, transfer this digit across
              ELSE
                  STUB(SPOS:SPOS) = CH
                  SPOS = SPOS + 1
              ENDIF
          ENDIF
300   CONTINUE

C---- Finish the directory stub and form the full path
      STUB(SPOS:SPOS) = '/'
      ENZPTH = ENZDIR(1:NAMLEN) // STUB(1:SPOS)
      NAMLEN = NAMLEN + SPOS

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRISWS  -  Write out any SWISS-PROT links
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRISWS(IFILE)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   COMMA, QUOTE
      CHARACTER*4   BREAK
      CHARACTER*12  SWCODE
      CHARACTER*20  SWLINE
      CHARACTER*256 ENTADD
      CHARACTER*(MAXLEN) IREC
      INTEGER       ICHN, IFILE, ISWISS, LEN, LENSTR
      LOGICAL       LIST, NEWSTY

      DATA QUOTE / '''' /

C---- Old style
      IF (IFILE.EQ.7) THEN

C----     Write out the text to the HTML file
          IF (NSWISS.GT.1) THEN
              WRITE(IFILE,120) '<b>SWISS-PROT codes:</b>'
 120          FORMAT(20A)
              WRITE(IFILE,120) '<UL>'
              LIST = .TRUE.
          ELSE
              WRITE(IFILE,120) '<b>SWISS-PROT code:</b>'
              LIST = .FALSE.
          ENDIF

C----     Set flag
          NEWSTY = .FALSE.

C---- New style
      ELSE
          IF (NSWISS.GT.1) THEN
              SWLINE = 'SWISS-PROT codes:'
          ELSE
              SWLINE = 'SWISS-PROT code:'
          ENDIF

C----     Set flag
          NEWSTY = .TRUE.
      ENDIF

C---- Loop through the stored entries and write out
      DO 400, ISWISS = 1, NSWISS

C----     For new-style layout, start table-row
          IF (NEWSTY) THEN
              WRITE(IFILE,120) '<TR><TH>', SWLINE(1:LENSTR(SWLINE)),
     -            '</TH>'
              SWLINE = '&nbsp;'
          ENDIF

C----     Get the Swiss-prot code and form the link
          ENTADD = SWADDR(1:LENSTR(SWADDR)) // SWNAME(ISWISS)
          SWCODE = SWNAME(ISWISS)
                  
C----     Initialise list of chain-ids
          IREC = ' '
          LEN = 0

C----     If more than one SWISS-PROT code, or more than one chain-id 
C         for current code, then write out list of chain ids
          IF (NSWISS.GT.1 .OR. NSWCHN(ISWISS).GT.1) THEN

C----         Prepare output string
              IF (NSWCHN(ISWISS).EQ.1) THEN
                  IREC = ' (Chain <B>' // SWICHN(1,ISWISS) // '</B>)'
                  LEN = LENSTR(IREC)

C----         Where more than one chain, have to loop through them all
              ELSE
                  IREC = ' (Chains:'
                  LEN = LENSTR(IREC) + 2

C----             Loop through the chains
                  DO 200, ICHN = 1, NSWCHN(ISWISS)

C----                 If not off the end of the record, add this chain
                      IF (LEN + 10.LT.MAXLEN) THEN
                          IREC(LEN:) = '<B>' // SWICHN(ICHN,ISWISS) //
     -                       '</B>'
                          LEN = LEN + 8

C----                     If not last chain, add a comma
                          IF (ICHN.LT.NSWCHN(ISWISS)) THEN
                              IREC(LEN:) = ', '
                              LEN = LEN + 2
                          ENDIF
                      ELSE
                          PRINT*, '*** Warning. Output record length t',
     -                        'oo long for SWISS-PROT info', MAXLEN
                      ENDIF
 200              CONTINUE

C----             Close of the list of chains
                  IREC(LEN:) = ')'
              ENDIF
          ENDIF

C----     Throw line if writing out as a list
          IF (LIST) THEN
              BREAK = '<BR>'
          ELSE
              BREAK = ' '
          ENDIF

C----     Determine whether to put a comma or a full-stop at the end
          IF (NEWSTY) THEN
              COMMA = ' '
              BREAK = ' '
          ELSE
              IF (ISWISS.LT.NSWISS) THEN
                  COMMA = ','
              ELSE
                  COMMA = '.'
              ENDIF
          ENDIF

C----     Add to list of chain-ids
          IF (LEN.EQ.0) THEN
              IREC = COMMA // BREAK
          ELSE
              IREC(LEN+1:) = COMMA // BREAK
          ENDIF

C----     Old-style links
          IF (.NOT.NEWSTY) THEN

C----         Write the link out to the html file
              WRITE(IFILE,120) '<a href="', ENTADD(1:LENSTR(ENTADD)),
     -            '">', SWCODE(1:LENSTR(SWCODE)), '</a>'
              WRITE(IFILE,120) '<a href="', WWWPFA(1:LENSTR(WWWPFA)),
     -            SWCODE(1:LENSTR(SWCODE)), '">[Pfam]</a>'
              WRITE(IFILE,120) IREC(1:LENSTR(IREC))

C----     New-style links
          ELSE

C----         Write out the SWISS-PROT code
              WRITE(IFILE,120) '<TH><FONT COLOR=BLUE>',
     -            SWCODE(1:LENSTR(SWCODE)), '</FONT></TH>'

C----         Write SWISS-PROT and Pfam links
              WRITE(IFILE,120) '<TH><a href="',
     -            ENTADD(1:LENSTR(ENTADD)),
     -            '" onMouseOver="window.status=', QUOTE, 'SWISS-PROT ',
     -            'annotated sequence entry at ExPaSy', QUOTE, '; retu',
     -            'rn true;"><IMG BORDER=0 SRC="../gif/swissprot_off.g',
     -            'if"></a></TH>'
              WRITE(IFILE,120) '<TH><a href="',
     -            WWWPFA(1:LENSTR(WWWPFA)),
     -            SWCODE(1:LENSTR(SWCODE)),
     -            '" onMouseOver="window.status=', QUOTE, 'Pfam databa',
     -            'se of protein family alignments and HMMs', QUOTE,
     -            '; return true;"><IMG BORDER=0 SRC="../gif/pfam_off.',
     -            'gif"></a></TH>'
              IF(LENSTR(IREC).GT.0)THEN
              WRITE(IFILE,120) '<TH>', IREC(1:LENSTR(IREC)),
     -            '</TH></TR>'
              ENDIF
          ENDIF
 400  CONTINUE

C---- Close off list if required
      IF (LIST) THEN
          WRITE(IFILE,120) '</UL>'
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIPRN  -  Write out links to PRINTS entries
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIPRN(IFILE,WWWPRN,BRCODE,PRCODE,PRNPDB,PRNUM,MXPCOD,
     -    MXPRIN,NPCODE)

      INTEGER       MXPCOD, MXPRIN

      CHARACTER*1   COMMA
      CHARACTER*4   BRCODE, PRNPDB(MXPCOD)
      CHARACTER*20  PCODE, PRCODE(MXPRIN)
      CHARACTER*200 FNAME
      CHARACTER*(*) WWWPRN
      INTEGER       ICODE, IENTRY, IFILE, LENSTR, NENTRY, NPCODE,
     -              PRNUM(MXPCOD)

C---- Initialise variables
      IENTRY = 0
      NENTRY = 0

C---- Loop through all the PDB entries with PRINTS codes to see how many
C     match the current one
      DO 100, ICODE = 1, NPCODE

C----     If this code matches the PDB code, increment count
          IF (PRNPDB(ICODE).EQ.BRCODE) NENTRY = NENTRY + 1
 100  CONTINUE

C---- If have any entries, then write out
      IF (NENTRY.GT.0) THEN

C----     Write out the header text to the HTML file
          IF (NENTRY.GT.1) THEN
              WRITE(IFILE,110) '<p><b>Fingerprints:</b>'
 110          FORMAT(10A)
          ELSE
              WRITE(IFILE,110) '<p><b>PRINTS sequence template entry:',
     -            '</b>'
          ENDIF

C----     Loop through all the PDB entries again to list
          DO 500, ICODE = 1, NPCODE

C----         If this code matches the PDB code, then write the PRINTS
C             entry out
              IF (PRNPDB(ICODE).EQ.BRCODE) THEN

C----             Get the PRINTS code and form the link
                  PCODE = PRCODE(PRNUM(ICODE))
                  FNAME = WWWPRN(1:LENSTR(WWWPRN)) // PCODE
                  
C----             Write the link out to the html file
                  IENTRY = IENTRY + 1
                  IF (IENTRY.LT.NENTRY) THEN
                      COMMA = ','
                  ELSE
                      COMMA = '.'
                  ENDIF
                  WRITE(IFILE,110) '<a href="', FNAME(1:LENSTR(FNAME)),
     -                '">', PCODE(1:LENSTR(PCODE)), '</a>', COMMA
              ENDIF
 500      CONTINUE
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIRES  -  Write out resolution and R-factor(s)
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIRES(IFILE)

      INCLUDE 'pdbhtml.inc'

      INTEGER       IFILE

C---- Write out the resolution and R-factor(s)
      WRITE(IFILE,120) '<p>'
 120  FORMAT(A)
      IF (RESOL.GT.0.0) THEN
          WRITE(IFILE,140) '<FONT COLOR=BLUE><b>Resolution:</b></FONT>',
     -        RESOL
 140      FORMAT(A,1X,F5.2,'&Aring;. ')
      ELSE
          WRITE(IFILE,120) 'No resolution given.'
      ENDIF
      IF (RFACT.GT.0.0) THEN
          WRITE(IFILE,180) '<FONT COLOR=BLUE><b>R-factor:</b></FONT>',
     -        RFACT
 180      FORMAT(A,1X,F8.3,'. ')
      ELSE
          WRITE(IFILE,120) 'No <i>R</i>-factor given.'
      ENDIF
      IF (RFREE.GT.0.0) THEN
          WRITE(IFILE,180) '<FONT COLOR=BLUE><b>R-free:</b></FONT>',
     -        RFREE
      ENDIF
      WRITE(IFILE,*)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIAUT  -  Write out the author details
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIAUT(IFILE)

      INCLUDE 'pdbhtml.inc'

      INTEGER       IEND, IFILE, ILINE, IPOS

C---- Loop over the author lines
      DO 200, ILINE = 1, NALINE

C----     Initialise variables for current author line
          IPOS = 1

C----     Loop through the authors, writing out one by one
 100      CONTINUE
              OUTREC = AUTHOR(ILINE)(IPOS:)
              IF (OUTREC.NE.' ') THEN
                  IEND = INDEX(OUTREC,',')
                  IF (IEND.LT.1) IEND = PDILEN
                  WRITE(IFILE,120) OUTREC(1:IEND)
 120              FORMAT(A)
                  IPOS = IPOS + IEND
                  IF (IPOS.LE.PDILEN) GO TO 100
              ENDIF
 200  CONTINUE
      WRITE(IFILE,*)


      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIREL  -  Write links to related entries to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIREL(IFILE,RELATE,NELINE,ENSLNK,NMRLNK,RELINK,
     -    LNKCOD,NLINKS,PDBDIR,PDBPRE,PDBSUF,WWWPDB,DIRSEP)

      INTEGER       MAXLEN, NELINE, NLINKS, PDILEN
      PARAMETER    (MAXLEN = 1000,PDILEN = 60)

      CHARACTER*1   COMMA, DIRSEP
      CHARACTER*4   LNKCOD(NLINKS)
      CHARACTER*200 FILNAM
      CHARACTER*(MAXLEN) OUTLIN
      CHARACTER*(PDILEN) RELATE(NELINE)
      CHARACTER*(*) PDBDIR, PDBPRE, PDBSUF, WWWPDB
      INTEGER       ILINE, ILINK, IFILE, LEN, LENSTR, PLEN
      LOGICAL       ENSLNK, NMRLNK, RELINK

C---- Related entries
      IF (NELINE.GT.0 .OR. NMRLNK) THEN
          WRITE(IFILE,510) '<p>'
          WRITE(IFILE,510) '<b>Related entries:</b> '
          WRITE(IFILE,510) '<EM>'

C----     Loop over the related entry lines
          DO 1800, ILINE = 1, NELINE

C----         Check that not blank
              IF (RELATE(ILINE).NE.' ') THEN

C----             Get length of text
                  LEN = LENSTR(RELATE(ILINE))

C----             Add links to anything that looks like a PDB code
                  CALL ADDLNK(RELATE(ILINE),LEN,PDILEN,OUTLIN,MAXLEN,
     -                PDBDIR,PDBPRE,PDBSUF,WWWPDB,DIRSEP)

C----             Write the line
                  WRITE(IFILE,520) OUTLIN(1:LENSTR(OUTLIN))
              ENDIF
 1800     CONTINUE

C----     If have links picked up from nmr_links.data file, add these here
          IF (NMRLNK .AND. NELINE.EQ.0) THEN

C----        Determine what the linked entry is
             IF (.NOT.RELINK) THEN
                 IF (ENSLNK) THEN
                     WRITE(IFILE,510) 'Ensemble of structures given in'
                 ELSE
                     WRITE(IFILE,510) 'Minimized structure given in'
                 ENDIF
             ENDIF

C----        Loop over all the links
             DO 1900, ILINK = 1, NLINKS

C----            Add comma or close-brackets at end
                 COMMA = ','
                 IF (ILINK.EQ.NLINKS) COMMA = '.'

C----            Form the filename for the link
                 PLEN = INDEX(WWWPDB,' ') - 1
                 FILNAM = WWWPDB(1:PLEN) // LNKCOD(ILINK) //
     -               '/main.html'
                 WRITE(IFILE,510) '</EM><B><a href="',
     -               FILNAM(1:LENSTR(FILNAM)), '">', LNKCOD(ILINK),
     -               '</a></B><EM>', COMMA
 1900        CONTINUE
          ENDIF
          WRITE(IFILE,510) '</EM>'
          WRITE(IFILE,*)
      ENDIF

 510  FORMAT(10A)
 520  FORMAT(A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE ADDLNK  -  Add links to anything that looks like a PDB code
C
C----------------------------------------------------------------------+---

      SUBROUTINE ADDLNK(INLINE,NCHARS,MAXIN,OUTLIN,MAXOUT,PDBDIR,PDBPRE,
     -    PDBSUF,WWWPDB,DIRSEP)

      CHARACTER*1   CH, DIRSEP
      CHARACTER*4   CODE, PDBSUF
      CHARACTER*156 FILNAM
      CHARACTER*(*) INLINE, OUTLIN, PDBDIR, PDBPRE, WWWPDB
      INTEGER       I, IPOS, ISTART, LEN, LENOUT, LENSTR, LSTPOS, MAXIN,
     -              MAXOUT, NCHARS, PLEN
      LOGICAL       MATCH

C---- Initialise variables
      LEN = 0
      ISTART = 0
      OUTLIN = ' '
      LENOUT = 0
      LSTPOS = 0

C---- Loop over all the characters
      DO 600, IPOS = 1, NCHARS

C----     Get the current character
          CH = INLINE(IPOS:IPOS)

C----     Check if this is a word-end
          IF (CH.EQ.' ' .OR. CH.EQ.'.' .OR. CH.EQ.',' .OR.
     -        CH.EQ.'-' .OR. CH.EQ.'/' .OR. CH.EQ.'+' .OR.
     -        CH.EQ.')' .OR. CH.EQ.'(' .OR. IPOS.EQ.NCHARS) THEN

C----         If this is the very last character, increment length
              IF (IPOS.EQ.NCHARS.AND.LEN.LT.4) THEN
                  LEN = LEN + 1
                  CODE(LEN:) = CH
              ENDIF

C----         If last word exists, then check if it might be a PDB code
              IF (LEN.EQ.4) THEN

C----             Initialise flag
                  MATCH = .TRUE.

C----             Check that first character is numeric and all others
C                 are alphanumeric
                  CH = CODE(1:1)
                  IF (LLT(CH,'0') .OR. LGT(CH,'9')) THEN
                      MATCH = .FALSE.

C-----            First character OK, check others
                  ELSE
                      DO 200, I = 2, 4

C----                     Get character and check it is a number or letter
                          CH = CODE(I:I)
                          IF ((LGE(CH,'a') .AND. LLE(CH,'z')) .OR.
     -                        (LGE(CH,'0') .AND. LLE(CH,'9'))) THEN
                          ELSE
                              MATCH = .FALSE.
                          ENDIF
 200                  CONTINUE
                  ENDIF

C----             If have a possible PDB code, then continue
                  IF (MATCH) THEN

C----                 Form name of appropriate PDB file
                      FILNAM = PDBDIR(1:LENSTR(PDBDIR)) // DIRSEP //
     -                    PDBPRE(1:LENSTR(PDBPRE)) // CODE // PDBSUF

C----                 Check whether the PDB file exists
                      INQUIRE(FILE=FILNAM,EXIST=MATCH)
                  ENDIF

C----             If have a likely PDB code, then insert link to its
C                 PDBsum page
                  IF (MATCH) THEN

C----                Transfer string to output from input line up to PDB
C                    code
                     IF (ISTART.GT.1) THEN
                         OUTLIN(LENOUT+1:) = INLINE(LSTPOS+1:ISTART-1)
                         LENOUT = LENOUT + (ISTART - LSTPOS - 1)
                     ENDIF
                     IF (IPOS.LT.NCHARS) THEN
                         LSTPOS = IPOS - 1
                     ELSE
                         LSTPOS = IPOS
                     ENDIF

C----                Form the link to the PDB file's PDBsum page
                     PLEN = INDEX(WWWPDB,' ') - 1
                     FILNAM = '</EM><B><a href="' // WWWPDB(1:PLEN) //
     -                   CODE // '/main.html' // '">' // CODE //
     -                   '</a></B><EM>'
                     PLEN = LENSTR(FILNAM)

C----                Add in the link and adjust length of output line
                     IF (LENOUT + PLEN.LT.MAXOUT) THEN
                         OUTLIN(LENOUT+1:) = FILNAM
                         LENOUT = LENOUT + PLEN
                     ENDIF
                  ENDIF
              ENDIF

C----         Reset word counters
              LEN = 0
              ISTART = 0

C----     Otherwise, add character to current word
          ELSE IF (LEN.LT.4) THEN

C----         Increment character position
              LEN = LEN + 1

C----         Add character
              CODE(LEN:) = CH

C----         If this is the first character, store string-position where
C             it came from
              IF (LEN.EQ.1) THEN
                  ISTART = IPOS
              ENDIF
          ENDIF
 600  CONTINUE

C---- If anything left of input line to transfer, then do so
      IF (LSTPOS.LT.NCHARS) THEN
          OUTLIN(LENOUT+1:) = INLINE(LSTPOS+1:NCHARS)
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRISUP  -  Write entries superseded by this one to the
C                        HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRISUP(IFILE,SPRSDE,NSUPER,PSTMPL,WWWPDB,SFOPEN)

      INCLUDE 'fcommon.inc'

      INTEGER       MAXLEN, NSUPER
      PARAMETER    (MAXLEN = 1000)

      CHARACTER*1   COMMA
      CHARACTER*4   SPRSDE(NSUPER), OTHCOD
      CHARACTER*(*) WWWPDB
      CHARACTER*(FNAMLN) PSTMPL, PSUMDR
      CHARACTER*(MAXLEN) OUTLIN
      INTEGER       IENTRY, IFILE, LENSTR, PLEN
      LOGICAL       HAVPDB, IFAIL, NOREAD, SFOPEN

C---- Entries superseded by this one
      WRITE(IFILE,510) '<p>'
      IF (NSUPER.EQ.1) THEN
          WRITE(IFILE,510) '<b>Supersedes entry:</b> '
      ELSE
          WRITE(IFILE,510) '<b>Supersedes entries:</b> '
      ENDIF

C---- Loop over the superseded entries
      DO 1950, IENTRY = 1, NSUPER

C----     Initialise for current entry
          COMMA = ','
          IF (IENTRY.EQ.NSUPER) COMMA = '.'
          NOREAD = .TRUE.
          HAVPDB = .FALSE.

C----     Check whether this PDB file exists
          OTHCOD = SPRSDE(IENTRY)
          CALL LOWCAS(4,OTHCOD)

C----     Form the name of this PDBsum directory
          CALL FRMFNM(OTHCOD,PSTMPL,PSUMDR,FNAMLN)


C----     Check whether the database.dat file exists
          CALL CHKLNK(PSUMDR,'database.dat',HAVPDB,NOREAD)

C----     If file exists then add link to it
          IF (HAVPDB) THEN
             PLEN = INDEX(WWWPDB,' ') - 1
             OUTLIN = '<a href="' // WWWPDB(1:PLEN) // OTHCOD //
     -           '/main.html' // '">' // OTHCOD // '</a>'

C----        Write superseded code out for later processing
             CALL SUPNEW(SFOPEN,OTHCOD,IFAIL)

C----     Otherwise just show the PDB code
          ELSE
              OUTLIN = OTHCOD
          ENDIF

C----     Write the line
          WRITE(IFILE,510) OUTLIN(1:LENSTR(OUTLIN)), COMMA
 1950 CONTINUE

      WRITE(IFILE,*)

 510  FORMAT(10A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIHED  -  Write molecule heading to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIHED(IFILE,BRCODE)

      CHARACTER*4   BRCODE
      INTEGER       IFILE

C---- Heading for molecules in the PDB file
      WRITE(IFILE,*)
      WRITE(IFILE,510) '<p>'
      WRITE(IFILE,510) '<hr>'
      WRITE(IFILE,*)
      WRITE(IFILE,510) '<h2>Molecule(s) in PDB file ', BRCODE, ':</h2>'
      WRITE(IFILE,*)

 510  FORMAT(10A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIBIN  -  Write out the binding site analysis page
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIBIN(IFILE,BFILE,HAVBIN,BINPAG)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   QUOTE
      CHARACTER*256 FILNAM
      INTEGER       BFILE, ICHAIN, IFILE, LENSTR, NHAVE
      LOGICAL       BINPAG, HAVBIN, HAVONE, NOREAD

      DATA QUOTE  /''''/

C---- Initialise variables
      HAVBIN = .FALSE.
      BINPAG = .FALSE.
      NHAVE = 0

C---- Loop through all the protein chains to check if we have and
C     binding site analyses
      DO 100, ICHAIN = 1, NCHAIN

C----     Form name of appropriate binding-site file
          FILNAM = 'bindsite_.html'
          IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
              FILNAM = 'bindsite_' // CHAIN(ICHAIN,CHN) // '.html'
          ENDIF

C----     Check whether the file exists
          HAVONE = .FALSE.
          NOREAD = .FALSE.
          CALL CHKLNK(PDBSUM,FILNAM(1:LENSTR(FILNAM)),HAVONE,
     -        NOREAD)

C----     If this file exists, then set flag that we have binding-site
C         data
          IF (HAVONE) THEN
              HAVBIN = .TRUE.
              NHAVE = NHAVE + 1
          ENDIF
 100  CONTINUE

C---- Create binding-site page if have binding site data and at least
C     two chains
      IF (HAVBIN .AND. NCHAIN + NNUCL.GE.2) BINPAG = .TRUE.

C---- If have binding-site data, then create the page bindsite.html
      IF (BINPAG) THEN

C----     Form name of the bindsite.html file
          FILNAM = PDBSUM(1:LENSTR(PDBSUM)) //
     -        '/bindsite.html'

C----     Open the file
          OPEN(UNIT=BFILE, FILE=FILNAM, STATUS='UNKNOWN',
     -        FORM='FORMATTED', ACCESS='SEQUENTIAL',
CVAX     -        CARRIAGECONTROL='LIST',
     -        ERR=900)

C----     If this is an MCSG structure, add link to this page from
C         the main page
          IF (MCSG) THEN
              WRITE(IFILE,110) '<A HREF="bindsite.html"'
              WRITE(IFILE,110) 'onMouseOver="window.status=', QUOTE,
     -            'Binding site analysis', QUOTE, '; return true">'
              WRITE(IFILE,110) '<IMG ALIGN=MIDDLE BORDER=0 WIDTH=150',
     -            ' ALT="Site" SRC="/ebi/research/thornton/www/database
     ~s/html/pdbsum/gif/bsite.gif"></A>',' &nbsp; <A HREF="bindsite.htm
     ~l">Binding site analysis</A>'
          ENDIF

C----     Write header records
          WRITE(BFILE,110) '<HTML>'
 110      FORMAT(10A)
          WRITE(BFILE,110) '<HEADER>'
          WRITE(BFILE,110) '<TITLE>Binding site analysis</TITLE>'
          WRITE(BFILE,110) '</HEADER>'
          WRITE(BFILE,110) '<BODY BGCOLOR="#F0FFFF">'
          WRITE(BFILE,110) '<H1>Binding site analysis</H1>'

C----     Description and instructions
          IF (NHAVE.EQ.2) THEN
              WRITE(BFILE,110) 'This page allows you to generate an'
              WRITE(BFILE,110) 'analysis of the potential binding sites'
              WRITE(BFILE,110) 'for the whole protein structure.'
          ELSE
              WRITE(BFILE,110) 'This page allows you to generate an'
              WRITE(BFILE,110) 'analysis of potential binding sites'
              WRITE(BFILE,110) 'for selected groupings of chains in'
              WRITE(BFILE,110) 'the protein structure.'
          ENDIF
          WRITE(BFILE,110) 'Analyses have already been generated for'
          WRITE(BFILE,110) 'each of the protein chains, individually,'
          WRITE(BFILE,110) 'and the links below take you to those'
          WRITE(BFILE,110) 'analyses.'
          WRITE(BFILE,110)
          WRITE(BFILE,110) '<P>'
          WRITE(BFILE,110) 'Here you can select which chains are to be'
          WRITE(BFILE,110) 'used jointly to arrive at potential binding'
          WRITE(BFILE,110) 'sites. Select which chains are to be'
          WRITE(BFILE,110) 'included from the list below, and then'
          WRITE(BFILE,110) 'click on the <FONT COLOR=RED>GO</FONT>'
          WRITE(BFILE,110) 'button. For very large structures the'
          WRITE(BFILE,110) 'analysis can take several minutes. The'
          WRITE(BFILE,110) 'program may fail altogether if you select'
          WRITE(BFILE,110) 'more than 3-4 chains.'
          WRITE(BFILE,110)
          WRITE(BFILE,110) '<P>'

C----     Create the form
c!!          WRITE(BFILE,110) '<FORM METHOD="POST" ACTION="',
c!!     -        DOSPEE(1:LENSTR(DOSPEE)), '">'
          WRITE(BFILE,110) '<FORM METHOD="POST" ACTION="http://www.ebi.a
     ~c.uk/thornton-srv/databases/cgi-bin/cath/GetPDBSUMCODE.pl">'


          WRITE(BFILE,110) '<INPUT TYPE="HIDDEN" NAME="source" VALUE=',
     -         '"genhtml">'
          WRITE(BFILE,110) '<INPUT TYPE="HIDDEN" NAME="pdb" VALUE="',
     -         BRCODE, '">'

C----     Create the table for the check boxes
          WRITE(BFILE,110) '<P>'
          WRITE(BFILE,110) '<TABLE>'

C----     Loop over the protein chains to write out the checkboxes
          IF (NCHAIN.GT.0) THEN
              WRITE(BFILE,110) '<TR>'
              WRITE(BFILE,110) '<TH ALIGN=LEFT>Protein chains:</TH>'
              WRITE(BFILE,110) '<TD><B>'
              DO 200, ICHAIN = 1, NCHAIN

C----             Write out checkbox and chain-id
                  WRITE(BFILE,110) '<INPUT TYPE="checkbox" NAME="chain',
     -                '" VALUE="-chain ', CHAIN(ICHAIN,CHN), '"',
     -                ' CHECKED>&nbsp;',
     -                CHAIN(ICHAIN,CHN)
 200          CONTINUE
              WRITE(BFILE,110) '</B></TD>'
              WRITE(BFILE,110) '</TR>'
          ENDIF

C----     Repeat for DNA chains, if any
          IF (NNUCL.GT.0) THEN
              WRITE(BFILE,110) '<TR>'
              WRITE(BFILE,110) '<TH ALIGN=LEFT>DNA/RNA chains:</TH>'
              WRITE(BFILE,110) '<TD><B>'
              DO 300, ICHAIN = 1, NNUCL

C----             Write out checkbox and chain-id
                  WRITE(BFILE,110) '<INPUT TYPE="checkbox" NAME="chain',
     -                '" VALUE="-chain ', CHAIN(ICHAIN,NUC), '">&nbsp;',
     -                CHAIN(ICHAIN,NUC)
 300          CONTINUE
              WRITE(BFILE,110) '</B></TD>'
              WRITE(BFILE,110) '</TR>'
          ENDIF

C----     Close the table
          WRITE(BFILE,110) '</TABLE>'

C----     Add the GO button
          WRITE(BFILE,110) '<P>'
          WRITE(BFILE,110) '<FONT COLOR=RED><INPUT TYPE="submit" ',
     -        'VALUE="GO"></FONT>'

C----     Close the form
          WRITE(BFILE,110) '</FORM>'

C----     Start list of individual chains
          WRITE(BFILE,110) '<H1>Binding sites for individual ',
     -        'chains</H1>'
      ENDIF

      GO TO 999

C---- File-read errors
900   CONTINUE
      PRINT*, '*** ERROR - Unable to open output file: ',
     -    FILNAM(1:LENSTR(FILNAM))
      GO TO 999

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIFIG  -  Write link to auto-generated figures page
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIFIG(IFILE)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   QUOTE
      CHARACTER*256 FILNAM
      INTEGER       IFILE, LENSTR
      LOGICAL       HAVFIG, NOREAD

      DATA QUOTE  /''''/

C---- Initialise variables
      HAVFIG = .FALSE.

C---- Form name of figure file
      FILNAM = 'figures.html'

C---- Check whether the file exists
      NOREAD = .FALSE.
      CALL CHKLNK(PDBSUM,FILNAM(1:LENSTR(FILNAM)),HAVFIG,
     -     NOREAD)

C---- If this file exists, then write link to it in current HTML page
      IF (MCSG .AND. HAVFIG) THEN

C----     Add link
          WRITE(IFILE,110) '&nbsp;&nbsp;&nbsp;&nbsp;'
 110      FORMAT(10A)
          WRITE(IFILE,110) '<A HREF="figures.html"'
          WRITE(IFILE,110) 'onMouseOver="window.status=', QUOTE,
     -         'Auto-generated figures', QUOTE, '; return true">'
          WRITE(IFILE,110) '<IMG ALIGN=MIDDLE BORDER=0',
     -         ' ALT="Figs" SRC="/ebi/research/thornton/www/databases/h
     ~tml/pdbsum/gif/doc_purple.gif"></A> &nbsp; <A HREF="figures.html"
     ~> Auto-generated figures</A>'
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIFUN  -  Write link to functional analysis report, if
C                        there is one
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIFUN(IFILE)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   QUOTE
      CHARACTER*256 FILNAM
      INTEGER       IFILE, LENSTR
      LOGICAL       HAVREP, NOREAD

      DATA QUOTE  /''''/

C---- Initialise variables
      HAVREP = .FALSE.

C---- Form name of index file
      FILNAM = 'report/index.html'

C---- Check whether the file exists
      NOREAD = .FALSE.
      CALL CHKLNK(PDBSUM,FILNAM(1:LENSTR(FILNAM)),HAVREP,
     -     NOREAD)

C---- If this file exists, then write link to it in current HTML page
      IF (MCSG .AND. HAVREP) THEN

C----     Add link
          WRITE(IFILE,110) '&nbsp;&nbsp;&nbsp;&nbsp;'
 110      FORMAT(10A)
          WRITE(IFILE,110) '<A HREF="', FILNAM(1:LENSTR(FILNAM)), '"'
          WRITE(IFILE,110) 'onMouseOver="window.status=', QUOTE,
     -         'Functional analysis report', QUOTE, '; return true">'
          WRITE(IFILE,110) '<IMG ALIGN=MIDDLE BORDER=0',
     -         ' ALT="Function"',
     -         ' SRC="/ebi/research/thornton/www/databases/html/pdbsum/g
     ~if/doc_blue.gif"></A> &nbsp; <A HREF="', FILNAM(1:LENSTR(FILNAM)),
     ~'"> Functional analysis</A>'
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRICHN  -  Write out all the chain entries and associated
C                        .html files
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRICHN(IFILE,BFILE,HAVBIN,BINPAG)

      SAVE

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   COMMA, INCHN, DOMNO
      CHARACTER*1   DQUOTE, QUOTE, PCHAIN
      CHARACTER*2   CHNUMB, EXTNUM, ND, NUMSTR
      CHARACTER*5   CODE, RESNUM
      CHARACTER*6   FILID, WOLF, NUMBER
      CHARACTER*7   BAKCOL
      CHARACTER*9   DCOL
      CHARACTER*10  CNAME, LSTPAT, PROSIT(MAXPAT)
      CHARACTER*12  LEVNAM(NLEVEL), RESFRM, RESTO
      CHARACTER*20  CATHNO(MAXDOM), LASTNO, PROPAT
      CHARACTER*19  FONTP2, LONGCT
      CHARACTER*20  ITEM1, ITEM2
      CHARACTER*30  FONTP1, PDESC(MAXPAT)
      CHARACTER*50  CATSTR, CD, CDESC(NLEVEL,MAXDOM)
      CHARACTER*60  MESSAG
      CHARACTER*120 FILNAM
      CHARACTER*120 OUTFLD, TEMP
      INTEGER       BFILE, CATH(NUMLEV,MAXDOM), CHAINO, CHCOLR,
     -              ICHAIN, ICOUNT, IDOM, IFILE, IFROM, ILEVEL, IPATTN,
     -              IPOS, ITO, IUNIQ, JCHAIN, LENSTR, LENNAM, NCOPY,
     -              NDOM, NGIFS, NPATTN, NXTLNK
      LOGICAL       BINPAG,DITTOS, EXTRAG, FIRST, GOTCAT, HAVBIN,
     -              HAVCAT, HAVGIF, HAVLNK, HAVSEQ, LIGRES, WIROUT

      DATA LEVNAM / 'Class', 'Architecture', 'Protein', 'Function' /
      DATA QUOTE  /''''/
      DATA DQUOTE /'"'/


C---- Initialise variables
      LSTPAT = ' '

C---- Write out number of unique chains to the database.dat file
      IF (NUNIQ.GT.0) THEN
          CALL FORNUM(NUMBER,NUNIQ)
          WRITE(DBASE,510) 'NUNIQ ', NUMBER
      ENDIF

C---- Loop until all unique chains have been processed
      DO 1000, IUNIQ = 1, NUNIQ

C----     Get the chain representing this unique sequence
          HAVCAT = .FALSE.
          ICHAIN = 0
          ICOUNT = 0
          DO 100, JCHAIN = 1, NCHAIN

C----         If this is a representative chain, increment count
              IF (DUPLIC(JCHAIN).GT.0) THEN

C----             Increment count
                  ICOUNT = ICOUNT + 1

C----             If this is our unique chain, then store location
                  IF (ICOUNT.EQ.IUNIQ) ICHAIN = JCHAIN
              ENDIF
 100      CONTINUE

C----     Write out chain identifier to the database.dat file
          IF (ICHAIN.GT.0) THEN

C----         Form subscript for current line
              CALL SUBSCR(IUNIQ,ITEM1)

C----         Write out
              IF (CHAIN(ICHAIN,CHN).EQ.' ') THEN
                  WRITE(DBASE,510) 'CHAIN',
     -                ITEM1(1:LENSTR(ITEM1))
              ELSE
                  WRITE(DBASE,510) 'CHAIN',
     -                ITEM1(1:LENSTR(ITEM1)), ' ', CHAIN(ICHAIN,CHN)
              ENDIF

C----         Write out number of this chain's residues
              CALL FORNUM(NUMBER,NRESID(ICHAIN,CHN))
              WRITE(DBASE,510) 'NRESID',
     -             ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER
              NCOPY = 0

C----         If C-alpha only entry, write out flag
              IF (CALPHA(ICHAIN).NE.' ') THEN
                  WRITE(DBASE,510) 'CALPHA_ONLY',
     -                ITEM1(1:LENSTR(ITEM1)), ' TRUE'
              ENDIF

C----         If have chains identical to this one, then list them
              IF (NXTCHN(ICHAIN).NE.0) THEN

C----             Initialise count of copy chains
                  ICOUNT = 0

C----             Get first link
                  NXTLNK = NXTCHN(ICHAIN)

C----             Chase down the duplicates of the current chain to
C                 list them to the database.dat file
 200              CONTINUE

C----                 If the next link is not zero, then get the
C                     next link and loop back
                      IF (NXTLNK.NE.0) THEN

C----                     Increment count of copies
                          ICOUNT = ICOUNT + 1

C----                     Form subscript for current line
                          CALL SUBSCR(ICOUNT,ITEM2)

C----                     Write out
                          IF (CHAIN(NXTLNK,CHN).EQ.' ') THEN
                              WRITE(DBASE,510) 'COPY',
     -                            ITEM1(1:LENSTR(ITEM1)),
     -                            ITEM2(1:LENSTR(ITEM2)), ' blank'
                          ELSE
                              WRITE(DBASE,510) 'COPY',
     -                            ITEM1(1:LENSTR(ITEM1)),
     -                            ITEM2(1:LENSTR(ITEM2)),
     -                            ' ', CHAIN(NXTLNK,CHN)
                          ENDIF

C----                     Get this chain's colour and write out
                          CALL OBJCOL(CHAINO,CHAIN(NXTLNK,CHN),CHCOLR,
     -                        CNAME)
                          WRITE(DBASE,510) 'COPY_COL',
     -                         ITEM1(1:LENSTR(ITEM1)),
     -                         ITEM2(1:LENSTR(ITEM2)), ' ',
     -                         CNAME(1:LENSTR(CNAME))

C----                     Get the next link and store current chain
C                         position
                          NXTLNK = NXTCHN(NXTLNK)
                          NCOPY = NCOP Y+ 1

C----                     Loop back
                          GO TO 200
                      ENDIF

C----             Write out the number of copy chains we have
                  CALL FORNUM(NUMBER,ICOUNT)
                  WRITE(DBASE,510) 'NCOPIES',
     -                ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER
              ENDIF

C----         Write out the number of chains we have
              CALL FORNUM(NUMBER,NCOPY + 1)
              WRITE(DBASE,510) 'NCHAINS',
     -            ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER

C----     If have serious error, then abort
          ELSE
              PRINT*, '*** PROGRAM ERROR. ICHAIN = 0'
              STOP
          ENDIF

C----     Get CATH data and PROSITE patterns
          IF (.NOT.PDBSM1) THEN
   
C----        Get the CATH number and URL for this chain
             CALL GETCAT(BRCODE,CHAIN(ICHAIN,CHN),CDESC,NLEVEL,NCATH,
     -            CATPDB,CATNUM,CATLEV,CATDSC,MXCATH,MXTITL,NTITLE,
     -            GOTCAT,CATH,NUMLEV,CATHNO,MAXDOM,NDOM)

C----        If no CATH numbers found, check whether there are any CATH
C            domain annotations for this PDB entry
             IF (NDOM.EQ.0) THEN
                CALL GETDOM(BRCODE,CHAIN(ICHAIN,CHN),CDESC,NLEVEL,NDOMS,
     -               DOMPDB,DOMNUM,CATLEV,CATDSC,MXCATH,MXTITL,
     -               NTITLE,GOTCAT,CATH,NUMLEV,CATHNO,MAXDOM,NDOM)
             ENDIF

C----        Get any PROSITE pattern(s) found in this chain, as given
C            by Kasuya's database
             CALL GETPAT(PATFIL,TOFFIL,BRCODE,CHAIN(ICHAIN,CHN),PROSIT,
     -            PDESC,PATRES,PATRNO,PATSEQ,PATCOL,PATOCC,MAXPAT,
     -            NPATTN,NDIFF,UPLOAD)
          ENDIF

C----     Get any SWISS-PROT codes associated with this chain
          CALL GETSWS(ICHAIN,ITEM1)

C----     Work out the full path name to the corresponding .html file

C----     Form the filename
C          LENNAM = INDEX(WWWCAT,' ') - 1
C          FNAME = WWWCAT(1:LENNAM) // 'CATHdbtop_00' //
C     -        CATFIL // '.html#' // BRCODE // CHAIN(ICHAIN,CHN)
          IPOS = INDEX(WWWCAT,'****') - 1
          TEMP = WWWCAT(1:IPOS) // BRCODE
          LENNAM = IPOS + 4
          IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
              FNAME = TEMP(1:LENNAM) // CHAIN(ICHAIN,CHN) //
     -            WWWCAT(LENNAM + 1:)
          ELSE
              FNAME = TEMP(1:LENNAM) // WWWCAT(LENNAM + 1:)
          ENDIF

C----     Get the chain's colour
          CALL OBJCOL(CHAINO,CHAIN(ICHAIN,CHN),CHCOLR,CNAME)
          WRITE(DBASE,510) 'CHAIN_COL',
     -         ITEM1(1:LENSTR(ITEM1)), ' ', CNAME(1:LENSTR(CNAME))
        
C----     Start this chain's entry
          WRITE(IFILE,510) '<p>'
          WRITE(IFILE,510) '<IMG ALIGN=BOTTOM SRC="../',
     -        CNAME(1:LENSTR(CNAME)), 'dot.gif" ALT=".">'
 510      FORMAT(10A)

C----     Chain heading
          IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
              WRITE(IFILE,510) '<b>Chain ', CHAIN(ICHAIN,CHN), '</b>'
          ELSE
              WRITE(IFILE,510) '<em>Protein:</em>'
          ENDIF

C----     Number of residues in chain
          WRITE(CNUMB,540) NRESID(ICHAIN,CHN)
 540      FORMAT(I8)
          IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
              WRITE(IFILE,510) '(<b>', CNUMB, '</b> residues )'
          ELSE
              WRITE(IFILE,510) '<b>', CNUMB, '</b> residues'
          ENDIF

C----     For a C-alpha entry, just state this
          IF (CALPHA(ICHAIN).NE.' ') THEN
              WRITE(IFILE,510) '- <b>C-alpha</b> coordinates only'
          ENDIF
          WRITE(IFILE,*)
          WRITE(IFILE,510) '<ul>'

C----     Write out the CATH number, if there is one
C          IF (CATH.NE.' ') THEN
C              LENNAM = INDEX(FNAME,' ') - 1
C              WRITE(IFILE,510) ' - <b>CATH <a href="', FNAME(1:LENNAM),
C     -            '">'
C              WRITE(IFILE,510) CATH, '.</a></b>'
C              WRITE(IFILE,510) '<b> -> </b><em>'
C              DO 600, ILEVEL = 1, NLEVEL
C                  WRITE(IFILE,510) '<b>', LEVNAM(ILEVEL)(1:LEVLEN(ILEVEL)),
C     -                ': </b>', CDESC(ILEVEL), '. '
C 600          CONTINUE
C              WRITE(IFILE,510) '</em>'
C          ENDIF

C----     Write out any nonstandard residue types and attached HET groups
          CALL WRNONS(IFILE,IUNIQ,ICHAIN,CHN,NRESID(ICHAIN,CHN),ITEM1)
        
C----     If no CATH domains, then just write out the heading
C          IF (NDOM.EQ.0 .OR. .NOT.GOTCAT) THEN
          IF (NDOM.EQ.0) THEN
              WRITE(IFILE,510) '<li>Secondary structure:<BR>'

C----         Write that no CATH information to database.dat file
              WRITE(DBASE,510) 'NOCATH',
     -             ITEM1(1:LENSTR(ITEM1)), ' TRUE'
          ELSE

C----         Write out link to CATH
              LENNAM = INDEX(FNAME,' ') - 1
              WRITE(IFILE,510) '<li><a href="', FNAME(1:LENNAM), '"'
              IF (CHAIN(ICHAIN,CHN).EQ.' ') THEN
                  WRITE(IFILE,510) 'onMouseOver="window.status=', QUOTE,
     -                'CATH summary for ', BRCODE, QUOTE, ';'
              ELSE
                  WRITE(IFILE,510) 'onMouseOver="window.status=', QUOTE,
     -                'CATH summary for ', BRCODE, ', chain ',
     -                CHAIN(ICHAIN,CHN), QUOTE, ';'
              ENDIF
              WRITE(IFILE,510) 'return true;">'
              WRITE(IFILE,510) '<IMG BORDER=0 WIDTH=80 SRC="../gif/cat',
     -            'h_off.gif"></A>'
              IF (NDOM.LT.10) THEN
                  WRITE(ND,610) NDOM
 610              FORMAT(I1,1X)
              ELSE
                  WRITE(ND,620) NDOM
 620              FORMAT(I2)
              ENDIF
              WRITE(IFILE,510) 'structural classification ('

C----         Write number of domains to database.dat file
              CALL FORNUM(NUMBER,NDOM)
              WRITE(DBASE,510) 'CATH',
     -             ITEM1(1:LENSTR(ITEM1)), ' TRUE'
              WRITE(DBASE,510) 'NDOMAINS',
     -             ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER

C----         Check whether have any CATH classes of 6 or higher
              HAVCAT = .TRUE.
              IF (CATH(1,1).GE.6) THEN
                  HAVCAT = .FALSE.
                  CATSTR = ', as yet unassigned) :'
              ELSE
                  CATSTR = ') :'
                  WRITE(DBASE,510) 'CATH_ASSIGNED',
     -                 ITEM1(1:LENSTR(ITEM1)), ' TRUE'
              ENDIF

C----         Write out number of domains
              IF (NDOM.EQ.1) THEN
                  WRITE(IFILE,510) '1 domain', CATSTR(1:LENSTR(CATSTR))
              ELSE
                  WRITE(IFILE,510) ND(1:LENSTR(ND)), ' domains',
     -                CATSTR(1:LENSTR(CATSTR))
              ENDIF

C----         Old-style, write out as list
              IF (IFILE.EQ.7 .AND. NDOM.GT.1 .AND. HAVCAT) THEN
                  WRITE(IFILE,510) '<ul>'

C----         New-style, write out as a table with indiv links to CATH
C             and DHS
              ELSE IF (IFILE.NE.7 .AND. HAVCAT) THEN

C----             Start the table
                  WRITE(IFILE,510) '<P>'
                  WRITE(IFILE,510) '<TABLE>'

C----             Write out the table headings
                  WRITE(IFILE,510) '<TR>'
                  IF (NDOM.GT.1) THEN
                      WRITE(IFILE,510) '<TH>'
                      WRITE(IFILE,510) '<U>Domain</U>'
                      WRITE(IFILE,510) '</TH>'
                  ENDIF
                  WRITE(IFILE,510) '<TH>'
                  WRITE(IFILE,510) '<U>Links</U>'
                  WRITE(IFILE,510) '</TH>'
                  WRITE(IFILE,510) '<TH>'
                  WRITE(IFILE,510) '<U>CATH no.</U>'
                  WRITE(IFILE,510) '</TH>'
                  WRITE(IFILE,510) '<TH>'
                  WRITE(IFILE,510) '&nbsp;'
                  WRITE(IFILE,510) '</TH>'
                  WRITE(IFILE,510) '<TH ALIGN=LEFT>'
                  WRITE(IFILE,510) '<U>Class</U>'
                  WRITE(IFILE,510) '</TH>'
                  WRITE(IFILE,510) '<TH ALIGN=LEFT>'
                  WRITE(IFILE,510) '<U>Architecture</U>'
                  WRITE(IFILE,510) '</TH>'
                  WRITE(IFILE,510) '</TR>'
              ENDIF

C----         Old-style list
              IF (IFILE.EQ.7 .AND. HAVCAT) THEN

C----             Loop through domains
  
                  DO 650, IDOM = 1, NDOM

C----                 If there is more than one domain, then write out
C                     item-start
                      IF (NDOM.GT.1) THEN

C----                     Get the domain colour
                          CALL DOMCOL(IDOM,DCOL)

C----                     Write out the domain colour in the
C                         appropriate colour
                          WRITE(CNUMB,550) IDOM
 550                      FORMAT(I2)
                          WRITE(IFILE,560) DCOL, CNUMB
 560                      FORMAT('<FONT COLOR=',A,'>Domain ',A,':')
                      ENDIF

C----                 Write out the CATH data on this domain
                      WRITE(IFILE,510) '<b>', CATHNO(IDOM), '</b><em>'
                      FIRST = .TRUE.
                      DO 600, ILEVEL = 1, NLEVEL
                          IF (CDESC(ILEVEL,IDOM).NE.' ') THEN
                              IF (FIRST) THEN
                                  WRITE(IFILE,510) ' -> '
                                  FIRST = .FALSE.
                              ENDIF
                              CD = CDESC(ILEVEL,IDOM)
                              WRITE(IFILE,510) '<b>',
     -                         LEVNAM(ILEVEL)(1:LENSTR(LEVNAM(ILEVEL))),
     -                            ': </b>', CD(1:LENSTR(CD)), '. '
                          ENDIF
 600                  CONTINUE
                      WRITE(IFILE,510) '</em>'
                      IF (NDOM.GT.1) THEN
                          WRITE(IFILE,510) '</FONT>'
                      ENDIF

C----                 If there is more than one domain, have a newline
                      IF (NDOM.GT.1) THEN
                          WRITE(IFILE,510) '<br>'
                      ENDIF
 650              CONTINUE

C----         New-style table
              ELSE IF (HAVCAT) THEN

C----             Initialise last CATH number
                  LASTNO = ' '

C----             Loop through domains
                  DO 700, IDOM = 1, NDOM

C----                 Form subscript for current domain
                      CALL SUBSCR(IDOM,ITEM2)

C----                 Start current row
                      WRITE(IFILE,510) '<TR>'

C----                 If CATH number is the same as for the last domain,
C                     then set flag to show dittos
                      IF (CATHNO(IDOM).EQ.LASTNO) THEN
                          DITTOS = .TRUE.
                      ELSE
                          DITTOS = .FALSE.
                      ENDIF

C----                 Form the long version of the CATH number
                      WRITE(LONGCT,660) (CATH(ILEVEL,IDOM),
     -                    ILEVEL = 1, 4)
 660                  FORMAT(I4.4,'.',I4.4,'.',I4.4,'.',I4.4)

C----                 Get the domain number
                      WRITE(CNUMB,670) IDOM
 670                  FORMAT(I2.2)

C----                 Form the Wolf code for this domain
                      INCHN = CHAIN(ICHAIN,CHN)
                      IF (INCHN.EQ.' ') INCHN = '0'
                      IF (NDOM.GT.1) THEN
                          WRITE(DOMNO,675) IDOM
 675                      FORMAT(I1)
                      ELSE
                          DOMNO = '0'
                      ENDIF
                      WOLF = BRCODE // INCHN // DOMNO

C----                 Form the CATH link
C                      IPOS = INDEX(WWWCDM,'****') - 1
C                      FILNAM = WWWCDM(1:IPOS) // LONGCT //
C     -                    WWWCDM(IPOS + 5:)
C                      FILNAM = FILNAM(1:LENSTR(FILNAM)) // BRCODE //
C     -                    CNUMB(1:2)
C                      FILNAM = WWWCDM(1:IPOS) // LONGCT
C                      FILNAM = WWWCDM(1:LENSTR(WWWCDM)) // CATHNO(IDOM)
                      FILNAM = WWWCDM(1:LENSTR(WWWCDM)) // WOLF

C----                 If there is more than one domain, then get its
C                     colour
                      IF (NDOM.GT.1) THEN

C----                     Get the domain colour
                          CALL DOMCOL(IDOM,DCOL)
                          WRITE(CNUMB,550) IDOM

C----                     Form the two font strings
                          WRITE(FONTP1,680) DCOL
 680                      FORMAT('<FONT COLOR=',A,'>')
                          FONTP2 = '</FONT>'

C----                     Write out the domain number
                          WRITE(IFILE,510) '<TH VALIGN=TOP>'
                          WRITE(IFILE,510) FONTP1(1:LENSTR(FONTP1)),
     -                        CNUMB(1:2), FONTP2(1:LENSTR(FONTP2))
                          WRITE(IFILE,510) '</TH>'

C----                 Otherwise, no colour
                      ELSE
                          DCOL = 'black'
                          FONTP1 = ' '
                          FONTP2 = ' '
                      ENDIF

C----                 Write out domain number and colour to database.dat
                      WRITE(DBASE,510) 'WOLF_CODE',
     -                     ITEM1(1:LENSTR(ITEM1)),
     -                     ITEM2(1:LENSTR(ITEM2)), ' ', WOLF
                      WRITE(DBASE,510) 'DOMAIN_COL',
     -                     ITEM1(1:LENSTR(ITEM1)),
     -                     ITEM2(1:LENSTR(ITEM2)), ' ',
     -                     DCOL(1:LENSTR(DCOL))

C----                 Write out the CATH link
                      WRITE(IFILE,510) '<TH VALIGN=TOP>'
                      IF (DITTOS) THEN
                          WRITE(IFILE,510) '"'
                      ELSE IF (CATHNO(IDOM).NE.' ') THEN
                          WRITE(IFILE,510) '<A HREF="',
     -                        FILNAM(1:LENSTR(FILNAM)), '"'
                          WRITE(IFILE,510) 'onMouseOver="window.status',
     -                        '=', QUOTE,
     -                        'Jump to list of domains with CATH code ',
     -                        CATHNO(IDOM)(1:LENSTR(CATHNO(IDOM))),
     -                        QUOTE, '; return true;">'
                          WRITE(IFILE,510) '<IMG BORDER=0 SRC="../gif/',
     -                        'cath_sm.gif"></A>'

C----                     Form the DHS link
                          FILNAM = WWWDHS(1:LENSTR(WWWDHS)) // WOLF

C----                     Write out the DHS link
                          WRITE(IFILE,510) '<A HREF="',
     -                        FILNAM(1:LENSTR(FILNAM)), '"'
                          WRITE(IFILE,510) 'onMouseOver="window.status',
     -                        '=', QUOTE,
     -                        'Dictionary of Homologous Superfamilies ',
     -                        'entry', QUOTE, '; return true;">'
                          WRITE(IFILE,510) '<IMG BORDER=0 SRC="../gif/',
     -                        'dhs_sm.gif"></A>'
                      ENDIF
                      WRITE(IFILE,510) '</TH>'

C----                 Write out the CATH code
                      WRITE(IFILE,510) '<TH VALIGN=TOP>'
                      IF (DITTOS) THEN
                          OUTFLD = '"'
                      ELSE IF (CATHNO(IDOM).NE.' ') THEN
                          OUTFLD = CATHNO(IDOM)
                      ELSE
                          OUTFLD = 'Unassigned'
                      ENDIF
                      IF(LENSTR(FONTP1).NE.0) THEN
                      WRITE(IFILE,510) FONTP1(1:LENSTR(FONTP1)),
     -                    OUTFLD(1:LENSTR(OUTFLD)),
     -                    FONTP2(1:LENSTR(FONTP2))
                      ELSE
                      WRITE(IFILE,510) OUTFLD(1:LENSTR(OUTFLD))
                      ENDIF
                      WRITE(IFILE,510) '</TD>'

C----                 Write out CATH number to database.dat
                      IF (CATHNO(IDOM).EQ.' ') THEN
                          CATHNO(IDOM) = 'Unassigned'
                      ENDIF
                      WRITE(DBASE,510) 'CATH_CODE',
     -                     ITEM1(1:LENSTR(ITEM1)),
     -                     ITEM2(1:LENSTR(ITEM2)), ' ',
     -                     CATHNO(IDOM)(1:LENSTR(CATHNO(IDOM)))

C----                 Form the filename of the topology diagram gif file
C                     (if there is one)
                      IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
                          PCHAIN = CHAIN(ICHAIN,CHN)
                      ELSE
                          PCHAIN = '0'
                      ENDIF
                      WRITE(FILNAM,695) PCHAIN, IDOM
 695                  FORMAT('dom',A1,I2.2,'.gif')

C----                 For PDBsum1, look in the hera directory
                      IF (PDBSM1) THEN
                         TEMP = 'hera/' // FILNAM
                         FILNAM = TEMP(1:LENSTR(TEMP))
                      ENDIF

C----                 Check whether this domain has an associated
C                     topology diagram
                      CALL CHKFIL(PDBSUM,FILNAM,HAVGIF)

C----                 If have topology file, then write flag out to
C                     database.dat
                      IF (HAVGIF) THEN
                          WRITE(DBASE,510) 'TOPOLDOM',
     -                         ITEM1(1:LENSTR(ITEM1)),
     -                         ITEM2(1:LENSTR(ITEM2)), ' TRUE'
                      ENDIF

C----                 Write out arrow
                      WRITE(IFILE,510) '<TD VALIGN=TOP>'
                      IF(LENSTR(FONTP1).NE.0) THEN
                      WRITE(IFILE,510) FONTP1(1:LENSTR(FONTP1)),
     -                     '->',
     -                     FONTP2(1:LENSTR(FONTP2))
                      ELSE
                      WRITE(IFILE,510) '->'
                      ENDIF
                      WRITE(IFILE,510) '</TD>'

C----                 Write out the descriptions
                      DO 690, ILEVEL = 1, NLEVEL

C----                     Write out the CATH classification description
                          IF (DITTOS) THEN
                              OUTFLD = '&nbsp;&nbsp;&nbsp;' //
     -                            '&nbsp;&nbsp;"&nbsp;&nbsp;&nbsp;' //
     -                            '&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"'
                          ELSE
                              OUTFLD = CDESC(ILEVEL,IDOM)
                          ENDIF
                          WRITE(IFILE,510) '<TD VALIGN=TOP>'
                          IF(LENSTR(FONTP1).NE.0) THEN                         
                          WRITE(IFILE,510) FONTP1(1:LENSTR(FONTP1)),
     -                        '<EM>'
                          ELSE
                          WRITE(IFILE,510) '<EM>'
                          ENDIF
                          IF (OUTFLD.NE.' ') THEN
                              WRITE(IFILE,510) OUTFLD(1:LENSTR(OUTFLD))
                          ENDIF

C----                     Close off the descriptive items
                          IF(LENSTR(FONTP2).NE.0) THEN 
                          WRITE(IFILE,510) '</EM>',
     -                        FONTP2(1:LENSTR(FONTP2))
                          ELSE
                          WRITE(IFILE,510) '</EM>'
                          ENDIF
                          WRITE(IFILE,510) '</TD>'
 690                  CONTINUE

C----                 Write out CATH descriptions to database.dat
                      IF (CDESC(1,IDOM).EQ.' ') CDESC(1,IDOM) = '-'
                      IF (CDESC(2,IDOM).EQ.' ') CDESC(2,IDOM) = '-'
                      IF (CDESC(3,IDOM).EQ.' ') CDESC(3,IDOM) = '-'
                      IF (CDESC(4,IDOM).EQ.' ') CDESC(4,IDOM) = '-'
                      WRITE(DBASE,510) 'CATH_CLASS',
     -                     ITEM1(1:LENSTR(ITEM1)),
     -                     ITEM2(1:LENSTR(ITEM2)), ' ',
     -                     CDESC(1,IDOM)(1:LENSTR(CDESC(1,IDOM)))
                      WRITE(DBASE,510) 'CATH_ARCH',
     -                     ITEM1(1:LENSTR(ITEM1)),
     -                     ITEM2(1:LENSTR(ITEM2)), ' ',
     -                     CDESC(2,IDOM)(1:LENSTR(CDESC(2,IDOM)))
                      WRITE(DBASE,510) 'CATH_PROT',
     -                     ITEM1(1:LENSTR(ITEM1)),
     -                     ITEM2(1:LENSTR(ITEM2)), ' ',
     -                     CDESC(3,IDOM)(1:LENSTR(CDESC(3,IDOM)))
                      WRITE(DBASE,510) 'CATH_FUNC',
     -                     ITEM1(1:LENSTR(ITEM1)),
     -                     ITEM2(1:LENSTR(ITEM2)), ' ',
     -                     CDESC(4,IDOM)(1:LENSTR(CDESC(4,IDOM)))

C----                 Close off the current row
                      WRITE(IFILE,510) '</TR>'

C----                 Store last CATH number encountered
                      LASTNO = CATHNO(IDOM)
 700              CONTINUE
              ENDIF

C----         If new-style, close off the table
              IF (HAVCAT) THEN
                  IF (IFILE.NE.7) THEN
                      WRITE(IFILE,510) '</TR>'
                      WRITE(IFILE,510) '</TABLE>'
                  ELSE
                      WRITE(IFILE,510) '<br>'
                  ENDIF
              ELSE
                  WRITE(IFILE,510) '<br>'
              ENDIF
          ENDIF

C----     Form the filename of the gif file holding the secondary
C         structure diagram (if there is one)
          WRITE(CHNUMB,720) IUNIQ
720       FORMAT(I2)
          IF (CHNUMB(1:1).EQ.' ') CHNUMB(1:1) = '0'
          FILNAM = 'wirplot_' // CHNUMB // '_01.gif'

C----     If the gif file is present, then set flag to include it
          CALL CHKFIL(PDBSUM,FILNAM,HAVGIF)

C----     Get chain ID for sec. structure page
          IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
              PCHAIN = CHAIN(ICHAIN,CHN)
          ELSE
              PCHAIN = ' '
          ENDIF

C----     Check how many wireplots there are for the current chain
          EXTRAG = .TRUE.
          HAVSEQ = .TRUE.
          NGIFS = 0
 750      CONTINUE

C----         Form file name to be checked
              WRITE(EXTNUM,720) NGIFS + 1
              IF (EXTNUM(1:1).EQ.' ') EXTNUM(1:1) = '0'
              FILNAM = 'wirplot_' // CHNUMB // '_' // EXTNUM //
     -            '.gif'

C----         Check whether the file exists
              CALL CHKFIL(PDBSUM,FILNAM,HAVSEQ)
          IF (HAVSEQ) THEN
              NGIFS = NGIFS + 1
              GO TO 750
          ENDIF

C----     Set flag checking whether and wirplot gifs have been written
C         out
          WIROUT = .FALSE.
CNew-->
          WIROUT = .TRUE.
          HAVGIF = .FALSE.
CNew<--

C----     If have the main-page gif files then include them
          IF (HAVGIF) THEN

C----         Loop through all the possible main-page wireplots
              HAVSEQ = .TRUE.
              NGIFS = 0
 800          CONTINUE

C----             Form file name to be checked
                  WRITE(EXTNUM,720) NGIFS + 1
                  IF (EXTNUM(1:1).EQ.' ') EXTNUM(1:1) = '0'
                  FILNAM = 'wirplot_' // CHNUMB // '_' // EXTNUM //
     -                '.gif'
                  FILID = CHNUMB // '_' // EXTNUM

C----             Check whether the file exists
                  CALL CHKFIL(PDBSUM,FILNAM,HAVSEQ)
                  NGIFS = NGIFS + 1

C----             If the file exists, include it in the main-page .html
C                 file
                  IF (HAVSEQ) THEN
                      WRITE(IFILE,510) '<IMG ALIGN=BOTTOM SRC="',
     -                    FILNAM(1:LENSTR(FILNAM)), '" ALT="Secondary ',
     -                    'structure plot">'
                      WIROUT = .TRUE.

C----                 Form subscript for current GIF
                      CALL SUBSCR(NGIFS,ITEM2)

C----                 Write out file name to database.dat file
                      WRITE(DBASE,510) 'WIRPLOT_NAME',
     -                     ITEM1(1:LENSTR(ITEM1)),
     -                     ITEM2(1:LENSTR(ITEM2)), ' ',
     -                     FILID(1:LENSTR(FILID))
                  ELSE
                      NGIFS = NGIFS - 1
                  ENDIF
              IF (HAVSEQ) GO TO 800

C----         Write out the number of wirplot GIFs to the database.dat file
              IF (NGIFS.GT.0) THEN
                  CALL FORNUM(NUMBER,NGIFS)
                  WRITE(DBASE,510) 'NWIRPLOT',
     -                ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER
              ENDIF
          ENDIF

C----     If any wiring-diagram GIFs were written out, add the link to
C         generation of PostScript version
          IF (WIROUT) THEN

C----         Write otu database.dat file that we have wiring diagram
              WRITE(DBASE,510) 'WIRPLOT',
     -            ITEM1(1:LENSTR(ITEM1)), ' TRUE'

C----         Form the link
              FILNAM = RUNWIR(1:LENSTR(RUNWIR)) // BRCODE // '&chain='
     -            // CHAIN(ICHAIN,CHN)
              WRITE(IFILE,510)
     -            '<A HREF="', FILNAM(1:LENSTR(FILNAM)), '"'
              WRITE(IFILE,510)
     -            'onmouseover="'
              WRITE(IFILE,510)
     -            'window.status=', QUOTE, ' Download PostScript versi',
     -            'on of secondary structure plot', QUOTE, ';'
              WRITE(IFILE,510)
     -            'return true;">'
              WRITE(IFILE,510)
     -            '<IMG BORDER=0 ALIGN=BOTTOM SRC="../gif/psvers.gif">',
     -            '</A>'
          ENDIF

C----     If there is more than one domain, show RasMol button for
C         displaying the chain coloured by domain
          IF (NDOM.GT.1) THEN

C----         Write link
              WRITE(IFILE,510) '<BR>'
              WRITE(IFILE,510) '<a href="',
     -            WWWDOM(1:LENSTR(WWWDOM)), BRCODE, '&chain=',
     -            CHAIN(ICHAIN,CHN), '"'
              MESSAG = 'View domains (RasMol script)'
              WRITE(IFILE,510) 'onMouseOver="window.status=', QUOTE,
     -            MESSAG(1:LENSTR(MESSAG)), QUOTE, '; return true">'
              WRITE(IFILE,510) '<IMG WIDTH=50 BORDER=0 ALIGN=MIDDL',
     -             'E SRC="../rasmol_scr.gif" ALT="RasMol domains"',
     -             '></A>'

C----         Write out description
              IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
                  WRITE(IFILE,510) 'View chain <b>',
     -                CHAIN(ICHAIN,CHN),  '</b> coloured by domain.'
              ELSE
                  WRITE(IFILE,510) 'View protein coloured by domai',
     -                'n.'
              ENDIF
              WRITE(IFILE,510) '<br>'
              WRITE(IFILE,510) ' '

C----         End the list
              IF (IFILE.EQ.7) THEN
                  WRITE(IFILE,510) '</ul>'
              ENDIF
              WRITE(IFILE,510) ' '

C----     Otherwise, provide button to view single chain in RasMol
          ELSE IF (CHAIN(ICHAIN,CHN).NE.' ') THEN

C----         Write link
              WRITE(IFILE,510) '<BR>'
              WRITE(IFILE,510) '<a href="',
     -            WWWRSC(1:LENSTR(WWWRSC)), BRCODE, '&chain=',
     -            CHAIN(ICHAIN,CHN), '"'
              MESSAG = 'View this chain only (RasMol script)'
              WRITE(IFILE,510) 'onMouseOver="window.status=', QUOTE,
     -            MESSAG(1:LENSTR(MESSAG)), QUOTE, '; return true">'
              WRITE(IFILE,510) '<IMG WIDTH=50 BORDER=0 ALIGN=MIDDL',
     -             'E SRC="../rasmol_scr.gif" ALT="Chain in RasMol"',
     -             '></A>'

C----         Write out description
              WRITE(IFILE,510) 'View chain <b>',
     -            CHAIN(ICHAIN,CHN), '</b> alone.'
              WRITE(IFILE,510) '<br>'
              WRITE(IFILE,510) ' '

              IF (IFILE.EQ.7) THEN
                  WRITE(IFILE,510) '<br>'
              ENDIF
          ENDIF
 
C----     Add entries for PROMOTIF data
          CALL PROMTF(IFILE,PCHAIN,HAVLNK,ITEM1)

C----     Add entries for active site details
          CALL SITES(IFILE,PCHAIN,ITEM1)

C----     Add link to intron details file, if there is one
COUT          CALL INTRNS(IFILE,PCHAIN)

C----     Place the wire-plots in sequence and sec. str. page
          IF (HAVGIF) THEN

C----         Create the gif-holding .html file for the secondary
C             structure
              WRITE(IFILE,510) '<p>'
              BAKCOL = ' '
              LIGRES = .FALSE.

              CALL GIFILE(IFILE,'wirplot_',IUNIQ,
     -           '<b>Sequence</b> and <b>secondary structure</b>',
     -           '<b>Sequence</b> and <b>secondary structure</b>',
     -            PDBSUM,BRCODE,PLAIN,PCHAIN,EXTRAG,LIGRES,DOLRES,
     -            NGIFS,BAKCOL,RUNLIG)

C----         Show number of strands and helices
              IF (NHELIX(ICHAIN) + NSTRND(ICHAIN).GT.0) THEN
                  WRITE(IFILE,510) '['
                  COMMA = ' '
                  IF (NSTRND(ICHAIN).GT.0 .AND. NHELIX(ICHAIN).GT.0)
     -                COMMA = ','

C----             Write out the number of beta-strands
                  IF (NSTRND(ICHAIN).EQ.1) THEN
                      WRITE(IFILE,820) '<b>', NSTRND(ICHAIN),
     -                    '</b> strand', COMMA
                  ELSE IF (NSTRND(ICHAIN).GT.0) THEN
                      WRITE(IFILE,820) '<b>', NSTRND(ICHAIN),
     -                    '</b> strands', COMMA
                  ENDIF

C----             Write out the number of alpha-helices
                  IF (NHELIX(ICHAIN).EQ.1) THEN
                      WRITE(IFILE,820) '<b>', NHELIX(ICHAIN),
     -                    '</b> helix'
 820                  FORMAT(A,I6,2A)
                  ELSE IF (NHELIX(ICHAIN).GT.0) THEN
                      WRITE(IFILE,820) '<b>', NHELIX(ICHAIN),
     -                    '</b> helices'
                  ENDIF
                  IF (HAVGIF) THEN
                      WRITE(IFILE,510) ']:-'
                  ELSE
                      WRITE(IFILE,510) ']'
                  ENDIF
              ENDIF
C          ELSE IF (.NOT.HAVGIF) THEN
C              WRITE(IFILE,510) '<p>'
C              BAKCOL = ' '
C              CALL GIFILE(IFILE,'ssplot',ICHAIN,
C     -            '<b>Sequence</b> and <b>estimated accessibility</b>',
C     -            '<b>Sequence</b> and <b>estimated accessibility</b>',
C     -            BRCODE,PLAIN,PCHAIN,EXTRAG,NGIFS,BAKCOL,RUNLIG)
          ENDIF

C----     Add link to TOPs diagram
          IF (.NOT.NOLINK) THEN
              IPOS = INDEX(WWWTOP,'****') - 1
              TEMP = WWWTOP(1:IPOS) // BRCODE
              LENNAM = IPOS + 4
              FNAME = TEMP(1:LENNAM) // WWWTOP(LENNAM + 1:)
              IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
                  LENNAM = LENSTR(FNAME)
                  FNAME(LENNAM+1:) = CHAIN(ICHAIN,CHN)
              ENDIF
              WRITE(IFILE,510) '<p><li><a href='
              WRITE(IFILE,510) DQUOTE // FNAME(1:LENSTR(FNAME)) //
     -           DQUOTE // '>'
              WRITE(IFILE,510) '<b>TOPS</b></a> protein topology carto',
     -            'on'
          ENDIF

C----     Add link to SAS Perl scripts for annotation of sequence by
C         structural info and for FASTA searches
          IF (INCSAS) THEN

C----         Single-sequence SAS
C              WRITE(IFILE,510) '<p><li><a href='
C              LENNAM = INDEX(DOSAS,' ') - 1
C              WRITE(IFILE,510) DQUOTE // DOSAS(1:LENNAM) // BRCODE //
C     -            '&chainid=' // CHAIN(ICHAIN,CHN) // DQUOTE // '>'
C              WRITE(IFILE,510) '<B>SAS</B></A> - <EM>Sequence annotated by',
C     -            ' structure</EM>'
C              WRITE(IFILE,510) '</a>'

C----         FASTA/SAS search and annotation
              IPOS = INDEX(DOSAS,'****') - 1
              TEMP = DOSAS(1:IPOS) // BRCODE
              LENNAM = IPOS + 4
              FNAME = TEMP(1:LENNAM) // DOSAS(LENNAM + 1:)
              IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
                  LENNAM = LENSTR(FNAME)
                  FNAME(LENNAM+1:) = CHAIN(ICHAIN,CHN)
              ENDIF
              WRITE(IFILE,510) '<p><li><a href='
              WRITE(IFILE,510) DQUOTE // FNAME(1:LENSTR(FNAME))
     -              // DQUOTE // '>'
              WRITE(IFILE,510) '<IMG ALT="SAS" border=0 WIDTH=65 SRC="',
     -             '../sas.gif"></A>'
              WRITE(IFILE,510) '- annotated FASTA alignment of related',
     -             ' sequences in the <B>PDB</B>'
              WRITE(IFILE,510) '</a>'
          ENDIF

C----     Add binding site analysis links, where relevant
          IF (HAVBIN) THEN
              CALL BINLNK(IFILE,BFILE,BINPAG,CHAIN(ICHAIN,CHN))
          ENDIF

C----     If have any PROSITE pattern matches, then add
          IF (NPATTN.GT.0) THEN

C----         Write out heading
              WRITE(IFILE,510) '<p><li><FONT COLOR="#0000FF"><B>PROSIT',
     -                'E</B></FONT>'
              IF (NDIFF.EQ.1) THEN
                  WRITE(IFILE,510) 'pattern present in this chain:-'
              ELSE
                  WRITE(IFILE,510) 'patterns present in this chain:-'
              ENDIF

C----         For new-style file, write out the help image
              IF (IFILE.EQ.19) THEN
                  WRITE(IFILE,510) '<A HREF="../procols.html"><IMG ALI',
     -                'GN=BOTTOM BORDER=0 SRC="../gif/bubble_help.gif"',
     -                ' ALT="Help!"></A>'
              ENDIF

C----         Start the form giving PROSITE pattern options for display
C             of the patterns on the 3D structure in RasMol
              IF (NPATTN.GT.1) THEN
                  WRITE(IFILE,510) '<FORM METHOD="POST" ACTION="',
     -                DOPROS(1:LENSTR(DOPROS)), '">'
                  WRITE(IFILE,510) '<INPUT TYPE="hidden" NAME="origin"',
     -                ' VALUE="prosite">'
                  WRITE(IFILE,510) '<INPUT TYPE="hidden" NAME="script"',
     -                ' VALUE="YES">'
                  CODE = BRCODE
                  IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
                      CODE(5:5) = CHAIN(ICHAIN,CHN)
                  ENDIF
                  WRITE(IFILE,510) '<INPUT TYPE="hidden" NAME="pdb" VA',
     -                'LUE="', CODE(1:LENSTR(CODE)), '">'

C----             If more than one pattern type, start a numbered list
                  WRITE(IFILE,510) '<OL>'

C----         If only a single pattern entry, then use standard RasMol
C             script icon
              ELSE

C----             Form link to script for showing PROSITE pattern in 3D
C                 using RasMol script
                  IPATTN = 1
                  FNAME = DOPROS(1:LENSTR(DOPROS)) // '?pdb=' // BRCODE
                  IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
                      FNAME = FNAME(1:LENSTR(FNAME)) //
     -                    CHAIN(ICHAIN,CHN)
                  ENDIF
                  FNAME = FNAME(1:LENSTR(FNAME)) //
     -                '&origin=prosite&script=YES&prosite_id=' //
     -                PROSIT(IPATTN)

C----             Show icon
                  WRITE(IFILE,510) '<P>'
                  WRITE(IFILE,510) '<A HREF="', FNAME(1:LENSTR(FNAME)),
     -                '"'
                  WRITE(IFILE,510) 'onMouseOver="window.status=', QUOTE,
     -                'View pattern residues (RasMol script)', QUOTE,
     -                '; return true">'
                  WRITE(IFILE,510) '<IMG WIDTH=50 BORDER=0 ALIGN=MIDDL',
     -                'E SRC="../rasmol_scr.gif" ALT="PROSITE pattern ',
     -                PROSIT(IPATTN)(1:LENSTR(PROSIT(IPATTN))), '"></A>'
              ENDIF

C----         Initialise previous pattern
              LSTPAT = ' '

C----         Write out the number of PROSITE patterns for this chain
C             to database.dat
              IF (NPATTN.GT.0) THEN
                  CALL FORNUM(NUMBER,NPATTN)
                  WRITE(DBASE,510) 'NPROSITE',
     -                ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER
                  WRITE(DBASE,510) 'PROSITE',
     -                ITEM1(1:LENSTR(ITEM1)), ' TRUE'
              ENDIF

C----         Loop over all the PROSITE patterns, writing out links and
C             RasMol buttons for each
              DO 850, IPATTN = 1, NPATTN

C----             Form subscript for current pattern
                  CALL SUBSCR(IPATTN,ITEM2)

C----             Write pattern id and name to database.dat file
                  WRITE(DBASE,510) 'PROSITE_ID',
     -                 ITEM1(1:LENSTR(ITEM1)),
     -                 ITEM2(1:LENSTR(ITEM2)), ' ',
     -                 PROSIT(IPATTN)(1:LENSTR(PROSIT(IPATTN)))
                  WRITE(DBASE,510) 'PROSITE_NAME',
     -                 ITEM1(1:LENSTR(ITEM1)),
     -                 ITEM2(1:LENSTR(ITEM2)), ' ',
     -                 PDESC(IPATTN)(1:LENSTR(PDESC(IPATTN)))

C----             If this is a new pattern, determine how to proceed with it
                  IF (LSTPAT.NE.PROSIT(IPATTN)) THEN

C----                 Form link to this pattern's entry in the PROSITE database
                      FNAME = WWWPRO(1:LENSTR(WWWPRO)) //
     -                    PROSIT(IPATTN)(1:LENSTR(PROSIT(IPATTN))) //
     -                    '.html'

C----                 Write out the pattern-id and link to the PROSITE database
                      IF (NDIFF.GT.1) THEN
                          WRITE(IFILE,510) '<LI>'
                      ENDIF
                      WRITE(IFILE,510) '<A HREF="',
     -                    FNAME(1:LENSTR(FNAME)), '"><B>',
     -                    PROSIT(IPATTN)(1:LENSTR(PROSIT(IPATTN))),
     -                    '</B></A>'

C----                 Write out the pattern name
                      WRITE(IFILE,510) '- <B>',
     -                    PDESC(IPATTN)(1:LENSTR(PDESC(IPATTN))),
     -                    '.</B>'
                  ENDIF

C----             Save the current pattern
                  LSTPAT = PROSIT(IPATTN)

C----             Format first residue details of pattern's residue-range
                  RESNUM = PATRNO(1,IPATTN)
                  IFROM = 1
                  ITO = 5
                  IF (RESNUM(1:1).EQ.' ') IFROM = 2
                  IF (RESNUM(2:2).EQ.' ') IFROM = 3
                  IF (RESNUM(3:3).EQ.' ') IFROM = 4
                  IF (RESNUM(5:5).EQ.' ') ITO = 4
                  RESFRM = PATRES(1,IPATTN) // RESNUM(IFROM:ITO)

C----             Repeat for last residue of range
                  RESNUM = PATRNO(2,IPATTN)
                  IFROM = 1
                  ITO = 5
                  IF (RESNUM(1:1).EQ.' ') IFROM = 2
                  IF (RESNUM(2:2).EQ.' ') IFROM = 3
                  IF (RESNUM(3:3).EQ.' ') IFROM = 4
                  IF (RESNUM(5:5).EQ.' ') ITO = 4
                  RESTO = PATRES(2,IPATTN) // RESNUM(IFROM:ITO)

C----             Add chain-identifier, if required
C                  IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
C                      RESFRM = RESFRM(1:LENSTR(RESFRM)) // '(' //
C     -                    CHAIN(ICHAIN,CHN) // ')'
C                      RESTO = RESTO(1:LENSTR(RESTO)) // '(' //
C     -                    CHAIN(ICHAIN,CHN) // ')'
C                  ENDIF

C----             Form the pattern identifier
                  PROPAT = PROSIT(IPATTN)
                  WRITE(NUMSTR,840) PATOCC(IPATTN)
 840              FORMAT(I2)
                  IF (NUMSTR(1:1).EQ.' ') THEN
                      NUMSTR(1:1) = NUMSTR(2:2)
                      NUMSTR(2:2) = ' '
                  ENDIF
                  IF (NUMSTR.NE.' ') THEN
                      PROPAT = PROPAT(1:LENSTR(PROPAT)) // '/' //
     -                    NUMSTR
                  ENDIF

C----             Write the check-box for this pattern
                  WRITE(IFILE,510)
                  WRITE(IFILE,510) '<BR>'
                  IF (NPATTN.GT.1) THEN
                      WRITE(IFILE,510) '&nbsp;&nbsp;'
C                      WRITE(IFILE,510) '<IMG WIDTH=10 HEIGHT=1 ALIGN=MIDDL',
C     -                    'E SRC="../12p.gif" ALT=" ">'
                      WRITE(IFILE,510) '<INPUT TYPE="checkbox" NAME="p',
     -                    'rosite_id" VALUE="',
     -                    PROPAT(1:LENSTR(PROPAT)), '">'
                  ELSE
                      WRITE(IFILE,510) '&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;'
                      WRITE(IFILE,510) '&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;'
                      WRITE(IFILE,510) '&nbsp;&nbsp;'
C                      WRITE(IFILE,510) '<IMG WIDTH=60 HEIGHT=1 ALIGN=MIDDL',
C     -                    'E SRC="../12p.gif" ALT=" ">'
                  ENDIF

C----             Write out the residue-range
                  WRITE(IFILE,510) '&nbsp;'
C                  WRITE(IFILE,510) '<IMG WIDTH=5 HEIGHT=1 ALIGN=MIDDLE SR',
C     -                'C="../12p.gif" ALT=" ">'
                  WRITE(IFILE,510) RESFRM(1:LENSTR(RESFRM)), '->',
     -                RESTO(1:LENSTR(RESTO)), ':'
                  WRITE(IFILE,510) '&nbsp;'
C                  WRITE(IFILE,510) '<IMG WIDTH=5 HEIGHT=1 ALIGN=MIDDLE SRC',
C     -                '="../12p.gif" ALT=" ">'

C----             Write residue range to database.dat file
                  WRITE(DBASE,510) 'PROSITE_START',
     -                ITEM1(1:LENSTR(ITEM1)),
     -                ITEM2(1:LENSTR(ITEM2)), ' ',
     -                RESFRM(1:LENSTR(RESFRM))
                  WRITE(DBASE,510) 'PROSITE_END',
     -                ITEM1(1:LENSTR(ITEM1)),
     -                ITEM2(1:LENSTR(ITEM2)), ' ',
     -                RESTO(1:LENSTR(RESTO))

C----             Write out the sequence coloured according to residue
C                 importance
                  CALL COLSEQ(IFILE,DBASE,PATSEQ(IPATTN),PATCOL(IPATTN),
     -                ITEM1,ITEM2)
 850          CONTINUE

C----         Close off list
              IF (NPATTN.GT.1) WRITE(IFILE,510) '</OL>'

C----         Close off the form
              WRITE(IFILE,510)
              WRITE(IFILE,510) '<P>'
              IF (NPATTN.GT.1) THEN
                  WRITE(IFILE,510) 'Use the check-boxes to select patt',
     -                'ern(s) to view on the 3D structure in'
                  WRITE(IFILE,510) '<B>RasMol</B>, and press:<BR>'
                  WRITE(IFILE,510) '&nbsp;&nbsp;&nbsp;&nbsp;'
                  WRITE(IFILE,510) '&nbsp;&nbsp;&nbsp;&nbsp;'
C                  WRITE(IFILE,510) '<IMG WIDTH=40 HEIGHT=1 ALIGN=MIDDLE SR',
C     -                'C="../12p.gif" ALT=" ">'
                  WRITE(IFILE,510) '<FONT COLOR="#FF0000">'
                  WRITE(IFILE,510) '<INPUT TYPE="submit" VALUE="DISPLA',
     -                'Y">'
                  IF (IFILE.NE.19) THEN
                      WRITE(IFILE,510) '<A HREF="../procols.html">Help',
     -                    '!</A>'
                  ENDIF
                  WRITE(IFILE,510) '</FONT>'
                  WRITE(IFILE,510) '</FORM>'
              ELSE
                  IF (IFILE.NE.19) THEN
                      WRITE(IFILE,510) '<A HREF="../procols.html">Help',
     -                    '!</A>'
                  ENDIF
              ENDIF
              WRITE(IFILE,510)
          ENDIF

C----     Add entry for generating Molscript diagram
          IF (.NOT.NOLINK) THEN
              WRITE(IFILE,510) '<p><li><a href = http://www.ebi.ac.uk/th
     ~ornton-srv/databases/cgi-bin/genfigs/GenMolscript.pl?pdbcode='//BR
     ~CODE//'&chain='//CHAIN(ICHAIN,CHN)
              LENNAM = INDEX(DOMOLS,' ') - 1
c!              WRITE(IFILE,510) DQUOTE // DOMOLS(1:LENNAM) // BRCODE //
c!     -            CHAIN(ICHAIN,CHN) // DQUOTE
c!              WRITE(IFILE,'(A)') BRCODE//'&chain='//CHAIN(ICHAIN,CHN)
              WRITE(IFILE,510) '>'
              WRITE(IFILE,510) '<b>MolScript</b> picture</a> (PostScri',
     -            'pt file)'
          ENDIF

C----     Identify any non-standard residues
CC          CALL GETDES(SEQUEN,MXLNAM,MXLINE,MXNTRY,ICHAIN,CHN,
CC     -        NONAME,NODESC,NOFORM,NONUMB,MXNONS,NOTYPE)

C----     Write out chain end
          WRITE(IFILE,510) '</ul>'

C----     If no CATH classification, see if chain has a topology diagram
          IF (.NOT.HAVCAT) THEN

C----         Form the filename of the topology diagram gif file
C             (if there is one)
              IF (CHAIN(ICHAIN,CHN).NE.' ') THEN
                  PCHAIN = CHAIN(ICHAIN,CHN)
              ELSE
                  PCHAIN = '0'
              ENDIF
              WRITE(FILNAM,695) PCHAIN, 1

C----         For PDBsum1, look in the hera directory
              IF (PDBSM1) THEN
                 TEMP = 'hera/' // FILNAM
                 FILNAM = TEMP(1:LENSTR(TEMP))
              ENDIF

C----         Check whether this domain has an associated
C             topology diagram
              CALL CHKFIL(PDBSUM,FILNAM,HAVGIF)

C----         If have topology file, then write flag out to
C             database.dat
              IF (HAVGIF) THEN
                  WRITE(DBASE,510) 'TOPOLCHN',
     -                ITEM1(1:LENSTR(ITEM1)), ' TRUE'
              ENDIF
          ENDIF

 1000 CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE OBJCOL  -  Routine to locate the chain ID in the chain list
C                        and return its position
C
C----------------------------------------------------------------------+---

      SUBROUTINE OBJCOL(ICHAIN,INCHN,CHCOLR,CNAME)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   INCHN
      CHARACTER*10  CNAME, COLTXT(MXCOBJ)
      CHARACTER*37  CHAINS
      INTEGER       CHCOLR, COLMAP(MXCOBJ), ICHAIN, ICOLR

      DATA COLMAP /  9, 3, 17, 11, 5, 4, 10, 6 /
      DATA COLTXT /'purple    ', 'red       ', 'brown     ',
     -             'pink      ', 'blue      ', 'green     ',
     -             'cyan      ', 'yellow    ' /

      DATA CHAINS / 'ABCDEFGHIJKLMNOPQRSTUVWXYZ123456 7890' /


C---- Get the corresponding chain-ID
      ICOLR = INDEX(CHAINS,INCHN)
      IF (ICOLR.LT.1) ICOLR = 1

C---- Get the colour for this chain
100   CONTINUE
          IF (ICOLR.GT.MXCOBJ) THEN
              ICOLR = ICOLR - MXCOBJ
              GO TO 100
          ENDIF
      CHCOLR = COLMAP(ICOLR)
      CNAME = COLTXT(ICOLR)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE DOMCOL  -  Routine to return domain's colour
C
C----------------------------------------------------------------------+---

      SUBROUTINE DOMCOL(DOMAIN,COLOUR)

      SAVE

      INTEGER       MXDCOL
      PARAMETER    (MXDCOL = 7)

      CHARACTER*9   COLOUR, DCOL(MXDCOL)
      INTEGER       DOMAIN, IDOM

      DATA  DCOL   / '"#FF0000"',
     -               '"#0000CC"',
     -               '"#00FF00"',
     -               '"#B233FF"',
     -               '"#CC8000"',
     -               '"#00FFFF"',
     -               '"#FF00FF"'  /

C---- Get this domain's colour
      IDOM = DOMAIN
      IF (IDOM.GT.MXDCOL) IDOM = MOD(IDOM,MXDCOL)
      IF (IDOM.EQ.0) IDOM = MXDCOL
      COLOUR = DCOL(IDOM)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRNONS  -  Write out any nonstandard residues and/or
C                        attached HET groups
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRNONS(IFILE,IUNIQ,ICHAIN,ITEM,NR,ITEM1)

      INCLUDE 'pdbhtml.inc'

      INTEGER       LLEN
      PARAMETER    (LLEN = 70)

      CHARACTER*1   CH, DQUOTE, S
      CHARACTER*2   ACHAIN
      CHARACTER*3   RESDUE
      CHARACTER*6   NUMBER
      CHARACTER*(LLEN) DESC(MXITEM), FORMUL, SYNON(MXITEM)
      CHARACTER*15  HTYPES(3)
      CHARACTER*20  ITEM1, ITEM2, ITEM3
      CHARACTER*30  HETDSC(2,3), HTYPE
      CHARACTER*120 FILNAM, HETFIL
      CHARACTER*240 OUTLIN
      INTEGER       HLEN, I, IAPPEN, ICHAIN, ICOUNT, IFILE, ILINE, IPOS,
     -              ITEM, IUNIQ, LENSTR, LSTPOS, NDLINE, NENT,
     -              NITEM(NAPPEN), NR, NSATIS, NYLINE, NTIME, TPOS
      LOGICAL       DOLIST, FILOUT, FIRST, HAVLST, WROTE

      DATA HETDSC / 'Non-standard residue:', 'non-standard residues:',
     -              'Het Group:           ', 'Het Groups:           ',
     -              'Residue attachment:  ', 'residue attachments:  ' /
      DATA DQUOTE / '"' /
      DATA HTYPES / 'NON_STAND_RES', 'HET_GROUP', 'RESID_ATTACH' /

C---- Initialise flags
      DOLIST = .TRUE.
      FILOUT = .FALSE.
      FIRST = .TRUE.
      HAVLST = .FALSE.
      WROTE = .FALSE.

C---- Initialise variables
      HLEN = INDEX(WWWHET,' ') - 1
      NDLINE = 0
      NENT = 0
      NSATIS = 0

C---- Loop over all entries of this type to check how many
C     non-standard residues there are
      DO 200, IAPPEN = 1, NAPPEN

C----     Initialise count of entries of this type
          NITEM(IAPPEN) = 0

C----     Loop over all the lines read in for this entry type
          DO 100, ILINE = 1, MXNONS

C----         If any copies of this entry, increment counts
              IF (ACOUNT(ILINE,ICHAIN,IAPPEN,ITEM).GT.0) THEN
                  NENT = NENT + 1
                  NSATIS = NSATIS
     -                + ACOUNT(ILINE,ICHAIN,IAPPEN,ITEM)
                  NITEM(IAPPEN) = NITEM(IAPPEN)
     -                + ACOUNT(ILINE,ICHAIN,IAPPEN,ITEM)
              ENDIF
 100      CONTINUE
 200  CONTINUE

C---- If this is anything other than a ligand, and there are residue
C     attachments, then write out the sequence
      IF (ITEM.NE.LIG .AND. ITEM.NE.NUC .AND. NITEM(3).GT.0) THEN

C----     Form output file name
          S = ' '
          IF (NITEM(3).GT.1) S = 's'
          WRITE(ACHAIN,220) IUNIQ
 220      FORMAT(I2)
          IF (ACHAIN(1:1).EQ.' ') ACHAIN(1:1) = '0'
          FILNAM = 'chain' // ACHAIN // '_seq.html'

C----     Open the output file
          OPEN(UNIT=11, FILE=FILNAM, STATUS='UNKNOWN', FORM='FORMATTED',
     -        ACCESS='SEQUENTIAL',
CVAX     -        CARRIAGECONTROL='LIST',
     -        ERR=350)

C----     Write out header records to file
          WRITE(11,240) '<HTML>'
 240      FORMAT(10A)
          WRITE(11,240) '<TITLE>Sequence with residue attachment', S,
     -        '</TITLE>'
          WRITE(11,240) '<BODY>'
          WRITE(11,240) '<H1>Sequence with residue attachment', S,
     -        '</H1>'
          WRITE(11,240) '<PRE>'

C----     Write out the sequence of this chain
          DO 300, ILINE = 1, MXLINE
              IF (SEQUEN(ILINE,ICHAIN,ITEM).NE.' ') THEN

C----             Initialise output line
                  OUTLIN = ' '
                  TPOS = 0

C----             Get the location of the last non-blank character
                  LSTPOS = 0
                  DO 250, IPOS = 1, MXLNAM

C----                 Get the next character
                      CH = SEQUEN(ILINE,ICHAIN,ITEM)(IPOS:IPOS)

C----                 If not a blank, then store position
                      IF (CH.NE.' ') THEN
                          LSTPOS = IPOS
                      ENDIF
 250              CONTINUE

C----             Transfer the sequence to the output line to highlight
C                 the residue attachments
                  DO 280, IPOS = 1, MXLNAM

C----                 Get the next character
                      CH = SEQUEN(ILINE,ICHAIN,ITEM)(IPOS:IPOS)

C----                 If this is an open-bracket, then transfer in bold
                      IF (CH.EQ.'(') THEN
                          TPOS = TPOS + 1
                          OUTLIN(TPOS:) = '<B>('
                          TPOS = TPOS + 3

C----                 For a close-bracket, end the emboldening
                      ELSE IF (CH.EQ.')') THEN
                          TPOS = TPOS + 1
                          OUTLIN(TPOS:) = ')</B>'
                          TPOS = TPOS + 4

C----                 If this is a blank, replace by underline if part of
C                     a residue name
C                      ELSE IF (CH.EQ.' ') THEN

C----                     If position lower than that of last character
C                         replace by underline
C                          IF (IPOS.LT.LSTPOS) THEN
C                              TPOS = TPOS + 1
C                              OUTLIN(TPOS:TPOS) = '_'
C                          ENDIF

C----                 Otherwise, transfer the character across
                      ELSE IF (CH.NE.' ') THEN
                          TPOS = TPOS + 1
                          OUTLIN(TPOS:TPOS) = CH
                      ENDIF
 280              CONTINUE

C----             Write out the output line to the file
                  WRITE(11,240) OUTLIN(1:TPOS)
              ENDIF
 300      CONTINUE

C----     Write out closing lines
          WRITE(11,240) '</PRE>'
          WRITE(11,240) '</BODY>'
          WRITE(11,240) '</HTML>'

C----     Close file
          CLOSE(11)
          FILOUT = .TRUE.

 350      CONTINUE
      ENDIF

C---- Loop over the different types of non-standard residues
      DO 800, IAPPEN = 1, NAPPEN

C----     If there is only one nonstandard entry and this matches
C         the ligand in its entirety, then don't need a list of entries
          ICOUNT = 0
          DOLIST = .TRUE.
          HAVLST = .FALSE.
          FIRST = .TRUE.
          IF (ITEM.EQ.LIG) THEN
              IF (NENT.EQ.1 .AND. NSATIS.EQ.NR) DOLIST = .FALSE.

C----     Otherwise, set up list for non-standard residues
          ELSE IF (NITEM(IAPPEN).GT.0) THEN
              IF (NITEM(IAPPEN).EQ.1) THEN
                  WRITE(IFILE,240) HETDSC(1,IAPPEN)
                  WROTE = .TRUE.
              ELSE
                  WRITE(IFILE,420) NITEM(IAPPEN), HETDSC(2,IAPPEN)
 420              FORMAT('<b>',I6,' </b>',A)
                  WROTE = .TRUE.
              ENDIF
          ENDIF

C----     If have just written out a residue-attachments file, then
C         add a link to it
          IF (FILOUT .AND. NITEM(IAPPEN).GT.0) THEN
              WRITE(IFILE,240) '(see <A HREF=', DQUOTE,
     -            FILNAM(1:LENSTR(FILNAM)), DQUOTE, '>sequence</A>)'
              WROTE = .TRUE.
          ENDIF

C----     Loop over all entries of this type
          DO 600, ILINE = 1, MXNONS

C----         If any copies of this entry, then write out
              IF (ACOUNT(ILINE,ICHAIN,IAPPEN,ITEM).GT.0) THEN

C----             If the first time round, start the list, if a list
C                 is required
                  IF (FIRST .AND. DOLIST) THEN
                      IF (.NOT.HAVLST) THEN
                          WRITE(IFILE,510) '<ul>'
 510                      FORMAT(10A)
                          WROTE = .TRUE.
                      ENDIF
                      HAVLST = .TRUE.
                      FIRST = .FALSE.
                  ENDIF

C----             Get a description from the PDB file for this residue,
C                 if there is one
                  RESDUE = ATTNAM(ILINE,ICHAIN,IAPPEN,ITEM)
                  CALL RESDES(RESDUE,DESC,SYNON,MXITEM,NDLINE,NYLINE,
     -                FORMUL)

C----             Get description and formula from the Het group dictionary
                  CALL HETDES(RESDUE,DESC,SYNON,MXITEM,NDLINE,NYLINE,
     -                FORMUL)

C----             Replace any leading blanks by underscores
                  IF (RESDUE(1:1).EQ.' ') RESDUE(1:1) = '_'
                  IF (RESDUE(2:2).EQ.' ') RESDUE(2:2) = '_'
                  IF (RESDUE(3:3).EQ.' ') RESDUE(3:3) = '_'

C----             Increment count of this entry type
                  ICOUNT = ICOUNT + 1

C----             Form subscript for current item
                  CALL SUBSCR(ICOUNT,ITEM2)

C----             Write out the code to the databases.dat file
                  HTYPE = HTYPES(IAPPEN)
                  WRITE(DBASE,510) HTYPE(1:LENSTR(HTYPE)),
     -                ITEM1(1:LENSTR(ITEM1)),
     -                ITEM2(1:LENSTR(ITEM2)), ' ', RESDUE

C----             Get the link to the HET groups database
                  HETFIL = WWWHET(1:HLEN) // 'ind' // RESDUE // '.html'

C----             Write out the residue name and count
                  NTIME = ACOUNT(ILINE,ICHAIN,IAPPEN,ITEM)
                  IF (DOLIST) THEN
                      WRITE(IFILE,510) '<b>'
                      IF (NTIME.GT.1) THEN
                          WRITE(IFILE,520) NTIME
 520                      FORMAT(I6,' x ')
                      ENDIF
                      WRITE(IFILE,510) '<a href="', HETFIL(1:HLEN + 11),
     -                    '">'
                      WRITE(IFILE,510) RESDUE, '</a></b>'
                      WROTE = .TRUE.

C----             If no list required for a ligand, and it consists of
C                 multiple entries of the same unit, write out the
C                 unit name again
                  ELSE IF (ITEM.EQ.LIG .AND. NSATIS.NE.1 .AND.
     -                (DESC(1).NE.' ' .OR. FORMUL.NE.' ')) THEN
                      WRITE(IFILE,510) '<a href="', HETFIL(1:HLEN + 11),
     -                    '">'
                      WRITE(IFILE,510) RESDUE, '</a> = '
                      WROTE = .TRUE.
                  ENDIF

C----             Write out count of how many times this item
C                 appears
                  CALL FORNUM(NUMBER,NTIME)
                  WRITE(DBASE,510) HTYPE(1:LENSTR(HTYPE)), '_TIMES',
     -                ITEM1(1:LENSTR(ITEM1)),
     -                ITEM2(1:LENSTR(ITEM2)), ' ', NUMBER

C----             Write description and/or formula out
                  IF (DESC(1).NE.' ' .OR. SYNON(1).NE.' ') THEN
                      WRITE(IFILE,510) ' - <em>'

C----                 If description references REMARK 5, write that out
C                     instead
                      IF (DESC(1)(1:12).EQ.'SEE REMARK 5') THEN

C----                     Write to database.dat file
                          CALL FORNUM(NUMBER,NRLINE)
                          WRITE(DBASE,510) HTYPE(1:LENSTR(HTYPE)),
     -                        '_NDESC',
     -                         ITEM1(1:LENSTR(ITEM1)),
     -                         ITEM2(1:LENSTR(ITEM2)), ' ', NUMBER

C----                    Write out the REMARK 5 item
                         DO 3443 I= 1 , NRLINE
                         IF(LENSTR(REM5(I)).GT.0)THEN
                          WRITE(IFILE,510)REM5(I)(1:LENSTR(REM5(I)))
c     -                        (REM5(I)(1:LENSTR(REM5(I))),
c     -                        I = 1, NRLINE)
                         ELSE
                          WRITE(IFILE,510)REM5(I)(1:1)
c                          WRITE(IFILE,510)(REM5(I)(1:1),I =1 , NRLINE)
                         ENDIF 

C----                    Form subscript for current line
                         CALL SUBSCR(I,ITEM3)

C----                    Write out to the databases.dat file
                         IF(LENSTR(REM5(I)).GT.0)THEN
                             WRITE(DBASE,510) HTYPE(1:LENSTR(HTYPE)),
     -                           '_DESC',ITEM1(1:LENSTR(ITEM1)),
     -                           ITEM2(1:LENSTR(ITEM2)),
     -                           ITEM3(1:LENSTR(ITEM3)),' ',
     -                           REM5(I)(1:LENSTR(REM5(I)))
                         ENDIF 

 3443                    CONTINUE

C----                 Otherwise convert description and write out
                      ELSE
C----                     Write to database.dat file
                          CALL FORNUM(NUMBER,NDLINE)
                          WRITE(DBASE,510) HTYPE(1:LENSTR(HTYPE)),
     -                        '_NDESC',
     -                         ITEM1(1:LENSTR(ITEM1)),
     -                         ITEM2(1:LENSTR(ITEM2)), ' ', NUMBER

C----                     Write out the lines of the description
                          CALL TYPSET(LLEN,NDLINE,DESC,.FALSE.)
                          DO 550, I = 1, NDLINE
                            IF(LENSTR(DESC(I)).GT.0)THEN
                              WRITE(IFILE,510)
     -                            DESC(I)(1:LENSTR(DESC(I)))
                            ELSE
                              WRITE(IFILE,510) DESC(I)(1:1)
                            ENDIF

C----                       Form subscript for current line
                            CALL SUBSCR(I,ITEM3)

C----                       Write out to the databases.dat file
                             WRITE(DBASE,510) HTYPE(1:LENSTR(HTYPE)),
     -                           '_DESC',ITEM1(1:LENSTR(ITEM1)),
     -                           ITEM2(1:LENSTR(ITEM2)),
     -                           ITEM3(1:LENSTR(ITEM3)),' ',
     -                           DESC(I)(1:LENSTR(DESC(I)))

 550                      CONTINUE

C----                     If have a synonym for this Het group, then write
C                         this out in square brackets
                          IF (NYLINE.GT.0) THEN

C----                         Write out the opening bracket
                              WRITE(IFILE,510) '['

C----                         Convert into lower and upper case
                              CALL TYPSET(LLEN,NYLINE,SYNON,.FALSE.)

C----                         Write to database.dat file
                              CALL FORNUM(NUMBER,NYLINE)
                              WRITE(DBASE,510) HTYPE(1:LENSTR(HTYPE)),
     -                             '_NSYNONYM',
     -                             ITEM1(1:LENSTR(ITEM1)),
     -                             ITEM2(1:LENSTR(ITEM2)), ' ', NUMBER

C----                         Write out all lines of the synonym
                              DO 580, I = 1, NYLINE
                                  WRITE(IFILE,510)
     -                                SYNON(I)(1:LENSTR(SYNON(I)))

C----                             Form subscript for current line
                                  CALL SUBSCR(I,ITEM3)

C----                             Write out to the databases.dat file
                                  WRITE(DBASE,510)
     -                                 HTYPE(1:LENSTR(HTYPE)),
     -                                 '_SYNONYM',
     -                                 ITEM1(1:LENSTR(ITEM1)),
     -                                 ITEM2(1:LENSTR(ITEM2)),
     -                                 ITEM3(1:LENSTR(ITEM3)),' ',
     -                                 SYNON(I)(1:LENSTR(SYNON(I)))
 580                          CONTINUE

C----                         Write out the closing bracket
                              WRITE(IFILE,510) ']'
                          ENDIF
                      ENDIF
                      WRITE(IFILE,510) '</em> '
                      WROTE = .TRUE.
                  ENDIF

C----             If have a formula, write it out
                  IF (FORMUL.NE.' ') THEN
                      WRITE(IFILE,510) 'Formula:<b>'
                      WRITE(IFILE,510) FORMUL(1:LENSTR(FORMUL))
                      WRITE(IFILE,510) '</b> '
                      WROTE = .TRUE.

C----                 Write out to the databases.dat file
                      WRITE(DBASE,510)
     -                     HTYPE(1:LENSTR(HTYPE)), '_FORMULA',
     -                     ITEM1(1:LENSTR(ITEM1)),
     -                     ITEM2(1:LENSTR(ITEM2)),
     -                     FORMUL(1:LENSTR(FORMUL))
                  ENDIF
                  IF (DOLIST) THEN
                      WRITE(IFILE,510) '<br>'
                  ENDIF
              ENDIF
 600      CONTINUE

C----     End the list if one was created
          IF (HAVLST) THEN
              WRITE(IFILE,510) '</ul>'
          ENDIF
 800  CONTINUE

C---- Throw a line if anything written out
      IF (WROTE) WRITE(IFILE,510) '<P>'

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE RESDES  -  Get the appropriate information about the
C                        non-standard residue types found in the current
C                        chain/ligand
C
C----------------------------------------------------------------------+---

      SUBROUTINE RESDES(RESDUE,DESC,SYNON,MXITEM,NDLINE,NYLINE,FORMUL)

      INTEGER       LLEN, MXITEM
      PARAMETER    (LLEN = 70)

      CHARACTER*3   RESDUE
      CHARACTER*6   LNUM
      CHARACTER*(LLEN) ADD, DESC(MXITEM), FORMUL, SYNON(MXITEM)
      CHARACTER*120 INREC
      INTEGER       LINE, IPOS, LEN, LENSTR, LPOS, NDLINE, NYLINE,
     -              RERROR

C---- Initialise variables
      DO 50, LINE = 1, MXITEM
          DESC(LINE) = ' '
          SYNON(LINE) = ' '
 50   CONTINUE
      FORMUL = ' '
      LNUM = ' '
      NDLINE = 0
      NYLINE = 0

C---- Rewind the PDB file
      REWIND(1)
      LINE = 0

C---- Loop while reading through the file
 100  CONTINUE

C----     Read in the next record
          READ(1,110,IOSTAT=RERROR,END=500) INREC
 110      FORMAT(A)
          LINE = LINE + 1

C----     Check for HET atom description
          IF (INREC(1:6).EQ.'HET   ' .OR. INREC(1:6).EQ.'HETNAM') THEN

C----         Record format differs according to record type
              ADD = ' '
              IF (INREC(1:6).EQ.'HET   ') THEN

C----             If residue name agrees, get the description
                  IF (RESDUE.EQ.INREC(8:10)) THEN

C----                 Get the text to be added
                      ADD = INREC(31:70)

C----                 If this is the first part of the description, then start
                      IF (NDLINE.EQ.0) THEN
                          LNUM = INREC(13:18)

C----                 If residue details don't match, then don't want this
C                     record
                      ELSE IF (LNUM.NE.INREC(13:18)) THEN
                          ADD = ' '
                      ENDIF
                  ENDIF

C----         For HETNAM record, get the description
              ELSE IF (INREC(1:6).EQ.'HETNAM') THEN

C----             If residue name agrees, get the description
                  IF (RESDUE.EQ.INREC(12:14)) THEN

C----                 Get the text to be added
                      ADD = INREC(16:70)

C----                 If this is the very first HETNAM record for this
C                     residue type, then overwrite any description that
C                     may have come from the HET record
                      IF (INREC(10:10).EQ.' ') NDLINE = 0
                  ENDIF
              ENDIF

C----         If have a description, then store
              IF (ADD.NE.' ') THEN

C----             If the very first part of the description, then store
                  IF (NDLINE.EQ.0) THEN
                      NDLINE = 1
                      DESC(NDLINE) = ADD

C----             Otherwise, add to what we have so far
                  ELSE

C----                 Find the last-occupied position
                      LPOS = LENSTR(DESC(NDLINE))

C----                 Get the length of the text to be added
                      LEN = LENSTR(ADD)

C----                 Add the new information onto the end of what was there
C                     before
                      IF (LPOS + LEN.LT.LLEN - 1) THEN
                          DESC(NDLINE)(LPOS + 2:) = ADD(1:LEN)

C----                 If space on this line has run out, start a new one
                      ELSE IF (NDLINE.LT.MXITEM) THEN

C----                     Increment line count
                          NDLINE = NDLINE + 1

C----                     Put description into this line
                          DESC(NDLINE) = ADD
                      ENDIF
                  ENDIF
              ENDIF

C----     Check for HETSYN, Het group synonym
          ELSE IF (INREC(1:6).EQ.'HETSYN') THEN

C----         If residue name agrees, get the synonym
              IF (RESDUE.EQ.INREC(12:14)) THEN

C----             Get the text to be added
                  ADD = INREC(16:70)

C----             If the very first part of the description, then store
                  IF (NYLINE.EQ.0) THEN
                      NYLINE = 1
                      SYNON(NYLINE) = ADD

C----             Otherwise, add to what we have so far
                  ELSE

C----                 Find the last-occupied position
                      LPOS = LENSTR(SYNON(NYLINE))

C----                 Get the length of the text to be added
                      LEN = LENSTR(ADD)

C----                 Add the new information onto the end of what was there
C                     before
                      IF (LPOS + LEN.LT.LLEN - 1) THEN
                          SYNON(NYLINE)(LPOS + 2:) = ADD(1:LEN)

C----                 If space on this line has run out, start a new one
                      ELSE IF (NYLINE.LT.MXITEM) THEN

C----                     Increment line count
                          NYLINE = NYLINE + 1

C----                     Put description into this line
                          SYNON(NYLINE) = ADD
                      ENDIF
                  ENDIF
              ENDIF

C----     Check for formula
          ELSE IF (INREC(1:6).EQ.'FORMUL') THEN
              IF (RESDUE.EQ.INREC(13:15)) THEN

C----             If already have part of the formula, add this bit onto
C                 the end
                  IF (FORMUL.EQ.' ') THEN
                      FORMUL = INREC(20:70)
                      LNUM = INREC(9:10)
                  ELSE IF (LNUM(1:2).EQ.INREC(9:10)) THEN

C----                 Find the last-occupied position
                      LPOS = 0
                      DO 400, IPOS = 1, LLEN
                          IF (FORMUL(IPOS:IPOS).NE.' ') LPOS = IPOS
 400                  CONTINUE

C----                 Add the new information onto the end of what was there
C                     before
                      IF (LPOS.LT.LLEN - 1) THEN
                          FORMUL(LPOS + 2:) = INREC(20:70)
                      ENDIF
                  ENDIF
              ENDIF
          ENDIF

C---- Loop back for next record
      GO TO 100

C---- End of file reached
 500  CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE HETDES  -  Get the description and formula for the given
C                        residue from the Het Group Dictionary
C
C----------------------------------------------------------------------+---

      SUBROUTINE HETDES(RESDUE,DESC,SYNON,MXITEM,NDLINE,NYLINE,FORMUL)

      INTEGER       LLEN, MXITEM
      PARAMETER    (LLEN = 70)

      CHARACTER*3   RESDUE
      CHARACTER*6   LNUM
      CHARACTER*(LLEN) ADD, DESC(MXITEM), FORMUL, SYNON(MXITEM)
      CHARACTER*120 INREC
      INTEGER       LEN, LENSTR, LINE, LPOS, NDLINE, NYLINE, RERROR
      LOGICAL       DONE, GOTDES, GOTFOR, GOTRES, GOTSYN

C---- Initialise variables
      DONE = .FALSE.
      GOTRES = .FALSE.
      LNUM = ' '

C---- Check which details we already have for this residue and hence which
C     we don't need to pick up from the Het Group Dictionary
      IF (NDLINE.NE.0) THEN
          GOTDES = .TRUE.
      ELSE
          GOTDES = .FALSE.
      ENDIF
      IF (FORMUL.NE.' ') THEN
          GOTFOR = .TRUE.
      ELSE
          GOTFOR = .FALSE.
      ENDIF
      IF (NYLINE.NE.0) THEN
          GOTSYN = .TRUE.
      ELSE
          GOTSYN = .FALSE.
      ENDIF

C---- Rewind the Het Group Dictionary file
      REWIND(18)
      LINE = 0

C---- Loop while reading through the file
 100  CONTINUE

C----     Read in the next record
          READ(18,110,IOSTAT=RERROR,END=500) INREC
 110      FORMAT(A)
          LINE = LINE + 1

C----     Check for start of residue
          IF (INREC(1:7).EQ.'RESIDUE') THEN

C----         If this is the residue we're after, then set flag
              IF (INREC(11:13).EQ.RESDUE) THEN
                  GOTRES = .TRUE.

C----         Otherwise, if have been processing the relevant residue,
C             then this must be the next one, so can stop
              ELSE IF (GOTRES) THEN
                  GOTRES = .FALSE.
                  DONE = .TRUE.
              ENDIF

C----     Check for HET atom description
          ELSE IF (GOTRES .AND. INREC(1:6).EQ.'HETNAM' .AND.
     -        .NOT.GOTDES) THEN

C----         If no continuation record, then retrieve description
              IF (INREC(10:10).EQ.' ') THEN
                  NDLINE = 1
                  DESC(NDLINE) = INREC(16:)

C----         Otherwise, append onto existing description
              ELSE

C----             Get the text to be added and its length
                  ADD = INREC(16:)
                  LEN = LENSTR(ADD)

C----             Find the last-occupied position
                  LPOS = LENSTR(DESC(NDLINE))

C----             Add the new information onto the end of what was there
C                 before
                  IF (LPOS + LEN.LT.LLEN - 1) THEN
                      DESC(NDLINE)(LPOS + 2:) = ADD(1:LEN)

C----             If space on this line has run out, start a new one
                  ELSE IF (NDLINE.LT.MXITEM) THEN

C----                 Increment line count
                      NDLINE = NDLINE + 1

C----                 Put description into this line
                      DESC(NDLINE) = ADD
                  ENDIF
              ENDIF

C----     Check for HET group synonym
          ELSE IF (GOTRES .AND. INREC(1:6).EQ.'HETSYN' .AND.
     -        .NOT.GOTSYN) THEN

C----         If no continuation record, then retrieve description
              IF (INREC(10:10).EQ.' ') THEN
                  NYLINE = 1
                  SYNON(NYLINE) = INREC(16:)

C----         Otherwise, append onto existing description
              ELSE

C----             Get the text to be added and its length
                  ADD = INREC(16:)
                  LEN = LENSTR(ADD)

C----             Find the last-occupied position
                  LPOS = LENSTR(SYNON(NYLINE))

C----             Add the new information onto the end of what was there
C                 before
                  IF (LPOS + LEN.LT.LLEN - 1) THEN
                      SYNON(NYLINE)(LPOS + 2:) = ADD(1:LEN)

C----             If space on this line has run out, start a new one
                  ELSE IF (NYLINE.LT.MXITEM) THEN

C----                 Increment line count
                      NYLINE = NYLINE + 1

C----                 Put description into this line
                      SYNON(NYLINE) = ADD
                  ENDIF
              ENDIF

C----     Check for formula
          ELSE IF (GOTRES .AND. INREC(1:6).EQ.'FORMUL' .AND.
     -        .NOT.GOTFOR) THEN

C----         Get the formula
             FORMUL = INREC(20:)
          ENDIF

C---- Loop back for next record
      IF (.NOT.DONE) GO TO 100

C---- End of file reached
 500  CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE CHKFIL  -  Check whether given file exists
C
C----------------------------------------------------------------------+---

      SUBROUTINE CHKFIL(DIRNAM,FNAME,HAVGIF)

      CHARACTER*(*) FNAME, DIRNAM
      CHARACTER*120 FULNAM
      INTEGER       LENSTR
      LOGICAL       HAVGIF


C---- Initialise filename
      FULNAM = DIRNAM(1:LENSTR(DIRNAM)) // '/' // FNAME

C---- Test whether file is there
      INQUIRE(FILE=FULNAM,EXIST=HAVGIF)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE PROMTF  -  Write out all the summary PROMOTIF data
C
C----------------------------------------------------------------------+---

      SUBROUTINE PROMTF(IFILE,PCHAIN,HAVFIL,ITEM1)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   PCHAIN
      CHARACTER*6   NUMBER
      CHARACTER*7   CTEXT
      CHARACTER*20  ITEM1, ITEM2
      CHARACTER*120 FILNAM, IREC, OUTLIN, PREC
      INTEGER       HLEN, IFILE, IPOS, LENSTR, NBAR, NMOTIF, NSUM
      LOGICAL       HAVFIL
      CHARACTER NBARchar

C---- Initialise flags
      HAVFIL = .FALSE.
      NBAR = 0
      NMOTIF = 0
      NSUM = 0

C---- Initialise variables
      HLEN = INDEX(WWWPDB,' ') - 1

C---- Check whether the summary PROMOTIF file exists for this chain
      IF (PCHAIN.EQ.' ') THEN
          FILNAM = 'pdb' // BRCODE // '_sum.html'
      ELSE
          FILNAM = 'pdb' // BRCODE // PCHAIN // '_sum.html'
      ENDIF
      CALL CHKFIL(PDBSUM,FILNAM,HAVFIL)
      
C---- If have the summary file, then proceed with PROMOTIF info
      IF (HAVFIL) THEN

C----     Write out reference to PROMOTIF summary to database.dat file
C          NSUM = 1
C          CALL SUBSCR(NSUM,ITEM2)
C          WRITE(DBASE,110) 'MOTIF_NAME',
C     -            ITEM1(1:LENSTR(ITEM1)),
C     -            ITEM2(1:LENSTR(ITEM2)), ' Summary'

C----     Extract the name of the HTML file holding the summary details
C          IPOS = INDEX(FILNAM,'.html')
C          WRITE(DBASE,110) 'MOTIF_FILE',
C     -        ITEM1(1:LENSTR(ITEM1)),
C     -        ITEM2(1:LENSTR(ITEM2)), ' ',
C     -        FILNAM(1:IPOS - 1)

C----     Write out link to PROMOTIF analyses
C          WRITE(IFILE,110) '<p><li><a href="'
C     -        // FILNAM(1:LENSTR(FILNAM)) // '">'
 110      FORMAT(10A)
C          WRITE(IFILE,110) '<b>PROMOTIF</b> summary</a>'

C----     Check whether there are any TIM barrels in this structure
          IF (PCHAIN.EQ.' ') THEN
              FILNAM = PDBSUM(1:LENSTR(PDBSUM)) // '/nbar.dat'
          ELSE
              FILNAM = PDBSUM(1:LENSTR(PDBSUM)) // '/nbar' //
     -            PCHAIN // '.dat'
          ENDIF
          OPEN(UNIT=10, FILE=FILNAM, STATUS='OLD', FORM='FORMATTED',
     -        ACCESS='SEQUENTIAL',
CVAX     -        READONLY,
     -        ERR=200)
          NBARchar = " "

C----     Read in the number of barrels in this structure
          READ(10,*,ERR=200,END=200) NBARchar
          IF(NBARchar.EQ." ")THEN
             CLOSE(10)
             GOTO 200
          ENDIF
          NBAR = ICHAR(NBARchar)

C----     Close the file
          CLOSE(10)


C----     If have TIM barrel info, check that HTML file exists
          IF (NBAR.GT.0) THEN

C----         Form filename and check whether file exists
              IF (PCHAIN.EQ.' ') THEN
                  FILNAM = BRCODE // '_bar.html'
              ELSE
                  FILNAM = BRCODE // PCHAIN // '_bar.html'
              ENDIF
              CALL CHKFIL(PDBSUM,FILNAM,HAVFIL)

C----         If file not there, zero the barrel count
              IF (.NOT.HAVFIL) NBAR = 0
          ENDIF

C----     Open file listing all the motifs for this chain
 200      CONTINUE
          IF (PCHAIN.EQ.' ') THEN
              FILNAM = PDBSUM(1:LENSTR(PDBSUM)) // '/' // BRCODE // 
     -            '.motifs'
          ELSE
              FILNAM = PDBSUM(1:LENSTR(PDBSUM)) // '/' // BRCODE //
     -            PCHAIN // '.motifs'
          ENDIF
          OPEN(UNIT=9, FILE=FILNAM, STATUS='OLD', FORM='FORMATTED',
     -        ACCESS='SEQUENTIAL',
CVAX     -        READONLY,
     -        ERR=999)

C----     Prepare for writing out the motifs data
          PREC = ' '

C----     Read through the motifs file, writing each line out
 300      CONTINUE

C----         Read in the next record
              READ(9,320,ERR=500,END=500) IREC
 320          FORMAT(A)

C----         Form subscript for current pattern
              NMOTIF = NMOTIF + 1
              CALL SUBSCR(NMOTIF+NSUM,ITEM2)

C----         Extract the number of motifs
              IPOS = INDEX(IREC,'<')
              NUMBER = IREC(1:IPOS - 1)
              WRITE(DBASE,110) 'MOTIF_COUNT',
     -            ITEM1(1:LENSTR(ITEM1)),
     -            ITEM2(1:LENSTR(ITEM2)), ' ',
     -            NUMBER(1:LENSTR(NUMBER))

C----         Extract the name of the HTML file holding the details
              OUTLIN = IREC(IPOS+8:)
              IPOS = INDEX(OUTLIN,'.html>')
              WRITE(DBASE,110) 'MOTIF_FILE',
     -            ITEM1(1:LENSTR(ITEM1)),
     -            ITEM2(1:LENSTR(ITEM2)), ' ',
     -            OUTLIN(1:IPOS - 1)

C----         Extract motif name
              OUTLIN = OUTLIN(IPOS + 6:)
              IPOS = INDEX(OUTLIN,'<')
              WRITE(DBASE,110) 'MOTIF_NAME',
     -            ITEM1(1:LENSTR(ITEM1)),
     -            ITEM2(1:LENSTR(ITEM2)), ' ',
     -            OUTLIN(1:IPOS - 1)

C----         Write out to database.dat file
              WRITE(DBASE,110) 'MOTIF',
     -            ITEM1(1:LENSTR(ITEM1)),
     -            ITEM2(1:LENSTR(ITEM2)), ' ',
     -            IREC(1:LENSTR(IREC))

C----         Append comma to previous record and write out
              IF (PREC.NE.' ') THEN
                  PREC = PREC(1:LENSTR(PREC)) // ','
              ELSE
                  PREC = ':<ul>'
              ENDIF
              WRITE(IFILE,110) PREC(1:LENSTR(PREC))

C----         Store the current record
              PREC = IREC

C----     Loop back for next motif record
          GO TO 300

C----     End of motifs file reached
 500      CONTINUE
          CLOSE(9)

C----     Write out the last record, if there is one
          IF (PREC.NE.' ') THEN
              IF (NBAR.EQ.0) THEN
                  WRITE(IFILE,110) PREC(1:LENSTR(PREC)), '.</ul>'
              ELSE
                  WRITE(IFILE,110) PREC(1:LENSTR(PREC))
              ENDIF
          ENDIF

C----     If we have any barrels, write link to these
          IF (NBAR.GT.0) THEN

C----         Form the link
              IF (PCHAIN.EQ.' ') THEN
                  FILNAM = BRCODE // '_bar.html'
              ELSE
                  FILNAM = BRCODE // PCHAIN // '_bar.html'
              ENDIF

C----         Deal with plural
              IF (NBAR.EQ.1) THEN
                  CTEXT = 'barrel'
              ELSE
                  CTEXT = 'barrels'
              ENDIF

C----         Write out the link
              WRITE(IFILE,510) NBAR, FILNAM(1:LENSTR(FILNAM)),
     -            CTEXT(1:LENSTR(CTEXT))
 510          FORMAT(I3,' <A href="',A,'">',A,'</A>.</ul>')

C----         Form subscript for current motif
              NMOTIF = NMOTIF + 1
              CALL SUBSCR(NMOTIF,ITEM2)

C----         Extract the number of motifs
              WRITE(NUMBER,560) NBAR
              WRITE(DBASE,110) 'MOTIF_COUNT',
     -            ITEM1(1:LENSTR(ITEM1)),
     -            ITEM2(1:LENSTR(ITEM2)), ' ', NUMBER

C----         Extract the name of the HTML file holding the details
              IPOS = INDEX(FILNAM,'.html')
              WRITE(DBASE,110) 'MOTIF_FILE',
     -            ITEM1(1:LENSTR(ITEM1)),
     -            ITEM2(1:LENSTR(ITEM2)), ' ',
     -            FILNAM(1:IPOS - 1)

C----         Extract motif name
              WRITE(DBASE,110) 'MOTIF_NAME',
     -            ITEM1(1:LENSTR(ITEM1)),
     -            ITEM2(1:LENSTR(ITEM2)), ' ',
     -            CTEXT(1:LENSTR(CTEXT))
          ENDIF
      ENDIF

C---- Write out number of PROMOTIF motifs
      IF (NMOTIF.GT.0) THEN
          WRITE(NUMBER,560) NMOTIF + NSUM
 560      FORMAT(I6)
          WRITE(DBASE,110) 'NPROMOTIF',
     -         ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER
          WRITE(DBASE,110) 'PROMOTIF ',
     -         ITEM1(1:LENSTR(ITEM1)), ' TRUE'
      ENDIF

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************ifi
C
C  SUBROUTINE SITES  -  Write out all the active site data (if any)
C
C----------------------------------------------------------------------+---

      SUBROUTINE SITES(IFILE,PCHAIN,ITEM1)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   PCHAIN
      CHARACTER*6   NUMBER
      CHARACTER*20  ITEM1, ITEM2, SITGIF(MXSITE), SITNAM(MXSITE)
      CHARACTER*120 OUTLIN, SITDET(MXSITE)
      CHARACTER*120 FILNAM, SITFIL
      INTEGER       HLEN, IFILE, IPOS, ISITE, LENSTR, NSITE
      LOGICAL       HAVFIL

C---- Initialise flags
      HAVFIL = .FALSE.
      NSITE = 0

C---- Initialise variables
      HLEN = INDEX(WWWPDB,' ') - 1

C---- Check whether the active site details file exists for this chain
      IF (PCHAIN.EQ.' ') THEN
          FILNAM = 'sites.html'
      ELSE
          FILNAM = 'sites' // PCHAIN // '.html'
      ENDIF
      CALL CHKFIL(PDBSUM,FILNAM,HAVFIL)
      
C---- If have the file, then proceed with active site info
      IF (HAVFIL) THEN

C----     Pick up all the active site details from the sites.html file
          CALL GETSIT(PDBSUM,BRCODE,FILNAM,MXSITE,SITDET,SITNAM,SITGIF,
     -        NSITE)

C----     Write out link to active site details file
          WRITE(IFILE,110) '<p><li><a href="' //
     -        FILNAM(1:LENSTR(FILNAM)) // '">'
 110      FORMAT(10A)

C----     Write heading for active site details
          IF (NSITE.EQ.1) THEN
              WRITE(IFILE,110) '<b>Active site:</b></a>'
          ELSE
              WRITE(IFILE,110) '<b>Active sites:</b></a>'
          ENDIF

C----     Loop through all the active site details and write out
          DO 200, ISITE = 1, NSITE
              OUTLIN = SITDET(ISITE)
              WRITE(IFILE,110) OUTLIN(1:LENSTR(OUTLIN))

C----         Form subscript for current site
              CALL SUBSCR(ISITE,ITEM2)

C----         Form name of the site<chain>XX.html file
              IF (PCHAIN.EQ.' ') THEN
                  WRITE(SITFIL,220) 'site', ISITE, '.html'
 220              FORMAT(A,I2.2,A)
              ELSE
                  WRITE(SITFIL,240) 'site', PCHAIN, ISITE, '.html'
 240              FORMAT(2A,I2.2,A)
              ENDIF

C----         Check whether new-style file exists
              CALL CHKFIL(PDBSUM,SITFIL,HAVFIL)

C----         If not, use old name
              IF (.NOT.HAVFIL) SITFIL = FILNAM
      
C----         Write out name of site's HTML file to database.dat file
              IPOS = INDEX(SITFIL,".html")
              WRITE(DBASE,110) 'SITE_FILE',
     -            ITEM1(1:LENSTR(ITEM1)),
     -            ITEM2(1:LENSTR(ITEM2)), ' ',
     -            SITFIL(1:IPOS - 1)

C----         Write out the site name
              WRITE(DBASE,110) 'SITE_NAME',
     -            ITEM1(1:LENSTR(ITEM1)),
     -            ITEM2(1:LENSTR(ITEM2)), ' ',
     -            SITNAM(ISITE)(1:LENSTR(SITNAM(ISITE)))

C----         Write out the site gif
              WRITE(DBASE,110) 'SITE_GIF',
     -            ITEM1(1:LENSTR(ITEM1)),
     -            ITEM2(1:LENSTR(ITEM2)), ' ',
     -            SITGIF(ISITE)(1:LENSTR(SITGIF(ISITE)))
 200      CONTINUE
      ENDIF

C---- Write out number of active sites
      IF (NSITE.GT.0) THEN
          WRITE(NUMBER,560) NSITE
 560      FORMAT(I6)
          WRITE(DBASE,110) 'NSITE',
     -         ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER
          WRITE(DBASE,110) 'SITE',
     -         ITEM1(1:LENSTR(ITEM1)), ' TRUE'
      ENDIF

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETSIT  -  Pick up the site data (triangle icon and site
C                        name) from the sites.html file
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETSIT(PDBSUM,BRCODE,FNAME,MXSITE,SITDET,SITNAM,
     -    SITGIF,NSITE)

      INTEGER       MXSITE

      CHARACTER*3   NAME
      CHARACTER*20  SITGIF(MXSITE), SITNAM(MXSITE), TMPSTR
      CHARACTER*120 IREC, OUTLIN, SITDET(MXSITE)
      CHARACTER*120 FILNAM
      CHARACTER*(*) BRCODE, FNAME, PDBSUM
      INTEGER       IPOS, LENSTR, LINE, NSITE

C---- Initialise filename
      FiLNAM = PDBSUM(1:LENSTR(PDBSUM)) // '/' // FNAME

C---- Open the active sites file
      OPEN(UNIT=14, FILE=FILNAM, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=900)

C---- Initialise variables
      PRINT*
      PRINT*, 'Reading in active site details from ',
     -    FILNAM(1:LENSTR(FILNAM)), ' ...'
      LINE = 0
      NSITE = 0

C---- Read through the sites.html file
 100  CONTINUE

C----     Read in a record from the file
          READ(14,120,END=500,ERR=902) IREC
 120      FORMAT(A)
          LINE = LINE + 1

C----     Check whether this is the required line
          IF (IREC(1:13).EQ.'<H2><IMG src=' .OR.
     -        IREC(1:13).EQ.'<H2><IMG SRC=') THEN

C----         Strip out the required details from the line
              OUTLIN = '<IMG WIDTH=16 ' // IREC(10:)
              IPOS = INDEX(OUTLIN,'Site:')
              NAME = OUTLIN(IPOS+6:IPOS+8)
              OUTLIN(IPOS:) = NAME

C----         Increment count of active site details and store
              NSITE = NSITE + 1
              IF (NSITE.LE.MXSITE) THEN

C----             Store the full site details
                  SITDET(NSITE) = OUTLIN

C----             Store the site name
                  SITNAM(NSITE) = NAME

C----             Extract the GIF file associated with this site
                  TMPSTR = IREC(18:)
                  IPOS = INDEX(TMPSTR,".gif")
                  TMPSTR(IPOS:) = ' '
                  SITGIF(NSITE) = TMPSTR
              ENDIF
          ENDIF

C---- Loop back for next record in file
      GO TO 100

C---- End of file reached
 500  CONTINUE

C---- Close the file
      CLOSE(14)

C---- Check that too many site details not encountered
      IF (NSITE.GT.MXSITE) THEN
          PRINT*, '*** Warning. Maximum number of active site details ',
     -        'exceeded: ', NSITE
          NSITE = MXSITE
      ENDIF

      GO TO 999

C---- Errors
900   CONTINUE
      PRINT*, '*** ERROR. Unable to open active sites file [',
     -    FILNAM(1:LENSTR(FILNAM)), ']'
      GO TO 999

902   CONTINUE
      PRINT*, '*** ERROR. File error in active sites at line:',
     -    LINE + 1
      GO TO 999

 904  CONTINUE
      PRINT*, '*** ERROR. Read error in active sites at line:', LINE
      GO TO 999

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE INTRNS  -  Write link to introns file, if there is one
C
C----------------------------------------------------------------------+---

      SUBROUTINE INTRNS(IFILE,PCHAIN)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   PCHAIN
      CHARACTER*120 FILNAM
      INTEGER       IFILE, LENSTR
      LOGICAL       HAVFIL

C---- Initialise flags
      HAVFIL = .FALSE.

C---- Check whether the intron details file exists for this chain
      IF (PCHAIN.EQ.' ') THEN
          FILNAM = 'introns_.dat'
      ELSE
          FILNAM = 'introns_' // PCHAIN // '.dat'
      ENDIF
      CALL CHKFIL(PDBSUM,FILNAM,HAVFIL)
      
C---- If have the file, then proceed with active site info
      IF (HAVFIL) THEN

C----     Write out link to intron details file
          WRITE(IFILE,110) '<p><li><a href="',
     -        DOINTR(1:LENSTR(DOINTR)), BRCODE, PCHAIN, '">'
 110      FORMAT(10A)
          WRITE(IFILE,110) '<b>Intron splice sites</b></a>'
          WRITE(IFILE,110) '<IMG HEIGHT=25 ALIGN=BOTTOM SRC="../rsciss',
     -        '.gif">'
      ENDIF

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE BINLNK  -  Write out the binding site analysis page
C
C----------------------------------------------------------------------+---

      SUBROUTINE BINLNK(IFILE,BFILE,BINPAG,INCHN)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   INCHN, QUOTE
      CHARACTER*256 ALINAM, BINNAM, CNSNAM
      INTEGER       BFILE, I, IFILE, LENSTR, NOUT, OFILE
      LOGICAL       BINPAG, HAVALI, HAVBIN, HAVCNS, NOREAD, WRIPAG

      DATA QUOTE  /''''/

C---- Form name of appropriate binding-site file
      BINNAM = 'bindsite_.html'
      IF (INCHN.NE.' ') THEN
          BINNAM = 'bindsite_' // INCHN // '.html'
      ENDIF

C---- Check whether the file exists
      HAVBIN = .FALSE.
      NOREAD = .FALSE.
      CALL CHKLNK(PDBSUM,BINNAM(1:LENSTR(BINNAM)),HAVBIN,NOREAD)

C---- Repeat for the multiple alignment file
      ALINAM = 'align_.html'
      IF (INCHN.NE.' ') THEN
          ALINAM = 'align_' // INCHN // '.html'
      ENDIF

C---- Check whether the file exists
      HAVALI = .FALSE.
      NOREAD = .FALSE.
      CALL CHKLNK(PDBSUM,ALINAM(1:LENSTR(ALINAM)),HAVALI,NOREAD)

C---- Repeat for the residue conservation file
      CNSNAM = 'rescons_.html'
      IF (INCHN.NE.' ') THEN
          CNSNAM = 'rescons_' // INCHN // '.html'
      ENDIF

C---- Check whether the file exists
      HAVCNS = .FALSE.
      NOREAD = .FALSE.
      CALL CHKLNK(PDBSUM,CNSNAM(1:LENSTR(CNSNAM)),HAVCNS,NOREAD)

C---- If this file exists, then add all the relevant links
      IF (HAVALI .OR. HAVCNS .OR. HAVBIN) THEN

C----     Subheading on bindsite.html
          IF (BINPAG) THEN
              WRITE(BFILE,110) '<H2>Chain ', INCHN, '</H2>'
 110          FORMAT(10A)
          ENDIF

C----     If this is an MCSG structure, then add links to main.html
C         page as well as the bindsite.html file
          IF (MCSG) THEN
              NOUT = 2
          ELSE
              NOUT = 1
          ENDIF
          
C----     Link to this chain's files
          DO 200, I = 1, NOUT

C----         First time round, write to the bindsite.html file
              WRIPAG = .TRUE.
              IF (I.EQ.1) THEN
                  OFILE = BFILE

C----             If don't have a bindsite.html page, then don't want
C                 to write any of these links
                  IF (.NOT.BINPAG) WRIPAG = .FALSE.
              ELSE
                  OFILE = IFILE
              ENDIF

C----         If have the alignments file, add the link
              IF (WRIPAG .AND. HAVALI) THEN

C----             Write the link
                  WRITE(OFILE,110) '<P>'
                  IF (I.EQ.2) WRITE(OFILE,110) '<LI>'
                  WRITE(OFILE,110) '<A HREF="',
     -                ALINAM(1:LENSTR(ALINAM)), '"'
                  IF (INCHN.EQ.' ') THEN
                      WRITE(OFILE,110) 'onMouseOver="window.status=',
     -                    QUOTE, 'Seq alignment', QUOTE,
     -                    '; return true">'
                  ELSE
                      WRITE(OFILE,110) 'onMouseOver="window.status=',
     -                    QUOTE, 'Chain ', INCHN, ' seq alignment',
     -                    QUOTE, '; return true">'
                  ENDIF
                  WRITE(OFILE,110) '<IMG ALIGN=MIDDLE BORDER=0 ',
     -                'WIDTH=150 ALT="Align" ',
     -                'SRC="/ebi/research/thornton/www/databases/html/pd
     ~bsum/gif/align.gif"></A> &nbsp; <A HREF="', ALINAM(1:LENSTR(ALINAM
     ~)),'">', '     Multiple alignment </A>'
              ENDIF

C----         If have the residue conservation file, add the link
              IF (WRIPAG .AND. HAVCNS) THEN

C----             Write the link
                  WRITE(OFILE,110) '<P>'
                  IF (I.EQ.2) WRITE(OFILE,110) '<LI>'
                  WRITE(OFILE,110) '<A HREF="',
     -                CNSNAM(1:LENSTR(CNSNAM)), '"'
                  IF (INCHN.EQ.' ') THEN
                      WRITE(OFILE,110) 'onMouseOver="window.status=',
     -                    QUOTE, 'Residue conservation', QUOTE,
     -                    '; return true">'
                  ELSE
                      WRITE(OFILE,110) 'onMouseOver="window.status=',
     -                    QUOTE, 'Chain ', INCHN,
     -                    ' residue conservation', QUOTE,
     -                    '; return true">'
                  ENDIF
                  WRITE(OFILE,110) '<IMG ALIGN=MIDDLE BORDER=0 ',
     -                'WIDTH=150 ALT="Conserv" ',
     -                'SRC="/ebi/research/thornton/www/databases/html/pd
     ~bsum/gif/conserve.gif"></A> &nbsp; <A HREF="', CNSNAM(1:LENSTR(CNS
     ~NAM)),'">', '     Residue conservation</A>'
              ENDIF

C----         If have the binding-sites file, add the link
              IF (WRIPAG .AND. HAVBIN) THEN

C----             Write the link
                  WRITE(OFILE,110) '<P>'
                  IF (I.EQ.2) WRITE(OFILE,110) '<LI>'
                  WRITE(OFILE,110) '<A HREF="',
     -                BINNAM(1:LENSTR(BINNAM)), '"'
                  IF (INCHN.EQ.' ') THEN
                      WRITE(OFILE,110) 'onMouseOver="window.status=',
     -                    QUOTE, 'Binding sites', QUOTE,
     -                    '; return true">'
                  ELSE
                      WRITE(OFILE,110) 'onMouseOver="window.status=',
     -                    QUOTE, 'Chain ', INCHN, ' binding sites',
     -                    QUOTE, '; return true">'
                  ENDIF
                  WRITE(OFILE,110) '<IMG ALIGN=MIDDLE BORDER=0 ',
     -                'WIDTH=150 ALT="Site" ',
     -                'SRC="/ebi/research/thornton/www/databases/html/pd
     ~bsum/gif/bsite.gif"></A> &nbsp; <A HREF="', BINNAM(1:LENSTR(BINNAM
     ~))
                  IF (INCHN.EQ.' ') THEN
                      WRITE(OFILE,110) '">',
     -                    '     Binding site analysis for chain</A>'
                  ELSE
                      WRITE(OFILE,110) '">',
     -                    '     Binding site analysis for chain ',
     -                    INCHN, '</A>'
                  ENDIF
              ENDIF
 200      CONTINUE
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GIFILE  -  Generate a gif-holding .html file
C
C----------------------------------------------------------------------+---

      SUBROUTINE GIFILE(IFILE,FBODY,FNUMB,TITLE,DESC,DIRNAM,BRCODE,
     -    PLAIN,CHAIN,EXTRAG,LIGRES,DOLRES,NGIFS,BAKCOL,RUNLIG)

      CHARACTER*1   CHAIN, DQUOTE, QUOTE
      CHARACTER*2   CNUMB, CNUMB1
      CHARACTER*4   BRCODE
      CHARACTER*7   BAKCOL
      CHARACTER*10  CHNTXT, KEYOPT
      CHARACTER*60  MESSAG, OPTION
      CHARACTER*120 FILNAM, FNAME, HTML, LNKNAM, RANGE, RNAME, TSTNAM
      CHARACTER*100 DOLRES
      CHARACTER*120 RUNLIG
      CHARACTER*200 COMMND
      CHARACTER*(*) DESC, DIRNAM, FBODY, TITLE

      INTEGER       CLEN, DLEN, FNUMB, ICON, ILEN, IFILE, IGIF, LENSTR,
     -              NGIFS, RLEN
      LOGICAL       EXTRAG, HAVFIL, LIGRES, PLAIN

      DATA QUOTE  /''''/
      DATA DQUOTE /'"'/

C---- Initialise variables
      IF (CHAIN.NE.' ') THEN
          WRITE(CHNTXT,30) CHAIN
 30       FORMAT('Chain ',A1,' - ')
          CLEN = 10
      ELSE
          CHNTXT = ' '
          CLEN = 1
      ENDIF
      KEYOPT = ' '
      RNAME = BRCODE

C---- Generate filename for sequence and secondary structure
      IF (PLAIN) THEN
          FNAME = FBODY
      ELSE
          WRITE(CNUMB1,40) FNUMB
 40       FORMAT(I2)
          IF (CNUMB1(1:1).EQ.' ') CNUMB1(1:1) = '0'
          FNAME = FBODY // CNUMB1
      ENDIF
      ILEN = INDEX(FNAME,' ') - 1
      HTML = FNAME(1:ILEN) // '.html'

C---- Open the .html file
      OPEN(UNIT=10,FILE=HTML,STATUS='UNKNOWN',ACCESS='SEQUENTIAL',
CVAX     -    CARRIAGECONTROL='LIST',RECL=RECLEN,
     -    FORM='FORMATTED',ERR=900)

C---- Write out the header records
      WRITE(10,110) '<html>'
 110  FORMAT(10A)
      WRITE(10,110) '<head>'
      WRITE(10,140) BRCODE, CHNTXT(1:CLEN), TITLE
 140  FORMAT('<title>',A,': ',2A,'</title>')
      WRITE(10,110) '</head>'
      IF (BAKCOL.NE.' ') THEN
          WRITE(10,110) '<body bgcolor="', BAKCOL, '">'
      ELSE
          WRITE(10,110) '<body>'
      ENDIF
      WRITE(10,*)
      WRITE(10,110) '<CENTER>'
      WRITE(10,*)
      WRITE(10,110) '<p><h2>'
      WRITE(10,160) BRCODE, CHNTXT(1:CLEN), DESC
 160  FORMAT('<A HREF="main.html">',A,'</A>: ',2A)
      WRITE(10,110) '</h2>'
      WRITE(10,*)
      WRITE(10,110) '<p>'
      WRITE(10,*)
      WRITE(10,110) '<hr>'
      WRITE(10,*)

C---- Loop to include all the relevant gif files
      DO 400, IGIF = 1, NGIFS

C----     If there is the possibility of several gif files, add
C         sequential number for each one
          IF (EXTRAG) THEN
              WRITE(CNUMB,40) IGIF
              IF (CNUMB(1:1).EQ.' ') CNUMB(1:1) = '0'
              FILNAM = FNAME(1:ILEN) // '_' // CNUMB
          ELSE
              CNUMB = ' '
              FILNAM = FNAME
          ENDIF
          WRITE(10,110) '<img src='
          WRITE(10,110) DQUOTE // FILNAM(1:LENSTR(FILNAM)) // '.gif' //
     -        DQUOTE
          WRITE(10,110) '>'

C----     If dealing with LIGPLOTs, then check for additional files
          IF (LIGRES) THEN

C----         Start icons table
              WRITE(10,110) '<TABLE>'
              WRITE(10,110) '<TR>'

C----         Check for corresponding ligplot.drw file, such that PostScript
C             version of GIF image can be downloaded

C----         Form the filename of the gzipped ligplot.drw file
              TSTNAM = FILNAM(1:LENSTR(FILNAM)) // '.drw.gz'

C----         Check if the file exists
              CALL CHKFIL(DIRNAM,TSTNAM,HAVFIL)

C----         If the file is present, write link to Perl script that
C             re-runs LIGPLOT to generate the PostScript version of
C             the image
              IF (HAVFIL) THEN

C----             Determine whether LIGPLOT key will be required
                  IF (FILNAM(1:4).EQ.'ligp') THEN
                      KEYOPT = '&key=YES'
                  ELSE
                      KEYOPT = ' '
                  ENDIF

C----             Form the link
                  IF(LENSTR(KEYOPT).GT.0) THEN
                  LNKNAM = RUNLIG(1:LENSTR(RUNLIG)) // BRCODE //
     -                '&file=' // FILNAM(1:LENSTR(FILNAM)) //
     -                KEYOPT(1:LENSTR(KEYOPT))
                  ELSE
                  LNKNAM = RUNLIG(1:LENSTR(RUNLIG)) // BRCODE //
     -                '&file=' // FILNAM(1:LENSTR(FILNAM))
                  ENDIF
                  WRITE(10,110) '<TH>'
                  WRITE(10,110)
     -                '<A HREF="', LNKNAM(1:LENSTR(LNKNAM)), '"'
                  WRITE(10,110)
     -                'onmouseover="'
                  WRITE(10,110)
     -                'window.status=', QUOTE, ' Download PostScript v',
     -                'ersion of LIGPLOT diagram', QUOTE, ';'
                  WRITE(10,110)
     -                'return true;">'
                  WRITE(10,110)
     -                '<IMG BORDER=0 ALIGN=BOTTOM SRC="../gif/psvers.g',
     -                'if"></A>'
                  WRITE(10,110) '</TH>'
              ENDIF

C----         Form the filename of the ligplot.res file
              TSTNAM = FILNAM(1:LENSTR(FILNAM)) // '.res'

C----         Check if the file exists
              CALL CHKFIL(DIRNAM,TSTNAM,HAVFIL)

C----         If the file is present, then write out the link to the
C             Perl script that makes use of it to load Rasmol with the
C             ligand and its interacting residues
              IF (HAVFIL) THEN

C----             Read in the first line of the file to get the ligand
C                 range
                  CALL GETRNG(DIRNAM,BRCODE,TSTNAM,RANGE,RLEN)

C----             Loop twice for the two RasMol icons
                  DO 200, ICON = 1, 2

C----                 Determine the RomLas options, according to the icon
                      IF (ICON.EQ.1) THEN
                          IF (CNUMB.EQ.' ') THEN
                              OPTION = '&label_atoms=YES&script=YES'
                          ELSE
                              OPTION = '&label_ligand=YES' //
     -                            '&label_protein=YES&script=YES'
                          ENDIF
                      ELSE
                          OPTION = '&script=NO'
                      ENDIF

C----                 Form the command to call the Perl script
C                      IPOS = INDEX(DOLRES,'*') - 1
                      DLEN = INDEX(DOLRES,' ') - 1
                      IF (CNUMB.EQ.' ') THEN
                          RNAME = BRCODE // '_' // CNUMB1 // '_01'
C                          COMMND = DOLRES(1:IPOS) // BRCODE //
C     -                        DOLRES(IPOS+5:DLEN) //
C     -                        FBODY(1:LENSTR(FBODY)) // CNUMB1
C                          IADD = LENSTR(FBODY) + 2
                          COMMND = DOLRES(1:DLEN) //
     -                        RNAME(1:LENSTR(RNAME)) //
     -                        '&residues=-l' // OPTION
                      ELSE
C                          COMMND = DOLRES(1:IPOS) // BRCODE //
C     -                        DOLRES(IPOS+5:DLEN) //
C     -                        FBODY(1:LENSTR(FBODY)) // CNUMB1 // '_' //
C     -                        CNUMB
C                          IADD = LENSTR(FBODY) + 5
                          COMMND = DOLRES(1:DLEN) //
     -                        RNAME(1:LENSTR(RNAME)) // '_' // CNUMB1 //
     -                        '_' // CNUMB // '&residues=-lr' // OPTION
                      ENDIF

C----                 Write out the link
C                      WRITE(10,110) '<A HREF=', DQUOTE, COMMND(1:DLEN+IADD),
C     -                     DQUOTE, '>'
                      WRITE(10,110) '<TH>'
                      WRITE(10,110) '<A HREF=', DQUOTE,
     -                     COMMND(1:LENSTR(COMMND)), DQUOTE
                      IF (ICON.EQ.1) THEN
                          MESSAG = 'RasMol script'
                      ELSE
                          MESSAG = 'Standard RasMol view'
                      ENDIF
                      WRITE(10,110) 'onMouseOver="window.status=',
     -                    QUOTE, MESSAG(1:LENSTR(MESSAG)), QUOTE,
     -                    '; return true">'
                      IF (ICON.EQ.1) THEN
                          WRITE(10,110) '<img ALIGN="BOTTOM" BORDER=0 ',
     -                    'src="../rasmol_scr.gif" ALT="RASMOL script"',
     -                    '></A>'
                      ELSE
                          WRITE(10,110) '<img ALIGN="BOTTOM" src="../r',
     -                    'asmol.gif" ALT="RASMOL"></A>'
                      ENDIF
                      WRITE(10,110) '</TH>'
 200              CONTINUE

C----             Write out the residue-range for the ligand
                  WRITE(10,110) '<TD VALIGN=MIDDLE>'
                  WRITE(10,110) RANGE(1:RLEN)
                  WRITE(10,110) '</TD>'
              ENDIF

C----         Close off table
              WRITE(10,110) '</TR>'
              WRITE(10,110) '</TABLE>'
          ENDIF
 400  CONTINUE
      WRITE(10,*)
      WRITE(10,110) '<hr>'
      WRITE(10,*)
      WRITE(10,110) '</CENTER>'
      WRITE(10,*)
      WRITE(10,110) '</body>'
      WRITE(10,110) '</html>'

C---- Close the file
      CLOSE(10)

C---- Write url to home page
      IF (.NOT.PLAIN) THEN
          WRITE(IFILE,510) '<li><a href='
 510      FORMAT(10A)
          WRITE(IFILE,510) DQUOTE // FNAME(1:ILEN) // '.html' //
     -        DQUOTE
          WRITE(IFILE,510) '>'
          WRITE(IFILE,510) TITLE
          WRITE(IFILE,510) '</a>'
      ENDIF

      GO TO 999

C---- Fatal errors
 900  CONTINUE
      PRINT*, '*** ERROR. Unable to open .html file: ',
     -    FNAME(1:ILEN), '.html'

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETRNG  -  Get the ligand's residue range from the
C                        ligplot.res file
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETRNG(DIRNAM,BRCODE,FNAME,RANGE,ILEN)

      CHARACTER*(*) BRCODE, FNAME, DIRNAM, RANGE
      CHARACTER*1   CHAIN
      CHARACTER*3   RESID1, RESID2
      CHARACTER*5   RNUM1, RNUM2
      CHARACTER*120 LINE1, LINE2, RESNAM
      CHARACTER*120 FULNAM
      INTEGER       IEND, ILEN, LENSTR


C---- Initialise filename
      FULNAM = DIRNAM(1:LENSTR(DIRNAM)) // BRCODE // '/' // FNAME
      ILEN = 1
      RANGE = ' '

C---- Open the file and read in the first two lines
      OPEN(UNIT=4, FILE=FULNAM, STATUS='OLD', FORM='FORMATTED',
     -    ACCESS='SEQUENTIAL',
CVAX     -    READONLY,
     -    ERR=999)
      READ(4,20,ERR=999,END=999) LINE1
      READ(4,20,ERR=999,END=999) LINE2
 20   FORMAT(A)

C---- Retrieve the residue range
      IF (LINE1(1:15).EQ.'#Residue range:' .AND.
     -    LINE2(1:17).EQ.'#Ligand residues:') THEN
          READ(LINE1,40) RESID1, RNUM1, RESID2, RNUM2, CHAIN
 40       FORMAT(16X,A3,1X,A5,4X,A3,1X,A5,8X,A1)

C----     If only a single ligand, retrieve the residue name
          IF (RNUM1.EQ.RNUM2) THEN
              RANGE = '<EM>- Ligand residue: '
              ILEN = 22

C----     Otherwise, if more than one residue show the residue range
          ELSE
              RANGE = '<EM>- Ligand residues: '
              ILEN = 23
          ENDIF

C----     Get first residue
          RESNAM = RESID1 // ' ' // RNUM1
          IF (RNUM1(5:5).EQ.' ') THEN
              IEND = 8
          ELSE
              IEND = 9
          ENDIF

C----     Add first residue name/number
          RANGE = RANGE(1:ILEN) // RESNAM
          ILEN = ILEN + IEND

C----     Add second residue, if required
          IF (RNUM1.NE.RNUM2 .OR. RESID1.NE.RESID2) THEN
              IF (RNUM2(5:5).EQ.' ') THEN
                  IEND = 4
              ELSE
                  IEND = 5
              ENDIF
              RANGE = RANGE(1:ILEN) // ' -> ' // RESID2 // ' ' //
     -            RNUM2
              ILEN = ILEN + 8 + IEND
          ENDIF

C----     If chain not blank, then add that on
          IF (CHAIN.NE.' ') THEN
              RANGE = RANGE(1:ILEN) // ', chain ' // CHAIN
              ILEN = ILEN + 9
          ENDIF

C----     Close off the line
          RANGE = RANGE(1:ILEN) // '</EM>'
          ILEN = ILEN + 5
      ENDIF

C---- Close the file
      CLOSE(4)
 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE COLSEQ  -  Display the part of the sequence matching the
C                        current PROSITE pattern, colouring according to
C                        residue importance
C
C----------------------------------------------------------------------+---

      SUBROUTINE COLSEQ(IFILE,DBASE,PATSEQ,PATCOL,ITEM1,ITEM2)

      CHARACTER*1   CCOL, CH
      CHARACTER*6   NUMBER
      CHARACTER*7   COLSTR(9)
      CHARACTER*20  ITEM1, ITEM2, ITEM3
      CHARACTER*110 PATCOL, PATSEQ
      CHARACTER*5000 OUTLIN
      INTEGER       COLOUR, DBASE, IFILE, IPOS, LENCOL, LENSTR, LSTCOL,
     -              OUTPOS

      DATA COLSTR / '#FF0000', '#FF6600', '#FF9900', '#FFFF00',
     -              '#00FF00', '#339966', '#9900FF', '#6699FF',
     -              '#0000FF' /

C---- Initialise variables
      LENCOL = LENSTR(PATCOL)
      LSTCOL = 0
      OUTPOS = 3
      OUTLIN = '<B>'

C---- Write out this pattern's length to the database.dat file
      IF (LENSTR(PATSEQ).GT.0) THEN
          WRITE(NUMBER,60) LENSTR(PATSEQ)
 60       FORMAT(I6)
          WRITE(DBASE,110) 'PROSITE_LEN',
     -        ITEM1(1:LENSTR(ITEM1)),
     -        ITEM2(1:LENSTR(ITEM2)), ' ', NUMBER
 110      FORMAT(10A)
      ENDIF

C---- Loop through the character positions in the sequence
      DO 600, IPOS = 1, LENSTR(PATSEQ)

C----     Form subscript for current position
          CALL SUBSCR(IPOS,ITEM3)

C----     Get the next character and its colour
          CH = PATSEQ(IPOS:IPOS)

C----     Write to database.dat file
          WRITE(DBASE,110) 'R',
     -        ITEM1(1:LENSTR(ITEM1)),
     -        ITEM2(1:LENSTR(ITEM2)),
     -        ITEM3(1:LENSTR(ITEM3)), ' ', CH

C----     If have a colour for this residue, then extract it
          IF (IPOS.LE.LENCOL) THEN
              CCOL = PATCOL(IPOS:IPOS)
              READ(CCOL,120,ERR=200) COLOUR
 120          FORMAT(I1)

C----     Otherwise, blank out the colour
          ELSE
              COLOUR = 0
          ENDIF

C----     If colour has changed, then write out new colour
 200      CONTINUE
          IF (COLOUR.NE.LSTCOL) THEN

C----         Close off previous colour, if there was one
              IF (LSTCOL.NE.0) THEN
                  OUTLIN(OUTPOS + 1:) = '</FONT>'
                  OUTPOS = OUTPOS + 7
              ENDIF

C----         Start the new colour
              IF (COLOUR.NE.0) THEN

C----             Get the appropriate colour
                  OUTLIN(OUTPOS + 1:) = '<FONT COLOR="' //
     -                COLSTR(COLOUR) // '">'
                  OUTPOS = LENSTR(OUTLIN)
              ENDIF
          ENDIF

C----     Write colour to database.dat file
          IF (COLOUR.NE.0) THEN
              WRITE(DBASE,110) 'COL',
     -            ITEM1(1:LENSTR(ITEM1)),
     -            ITEM2(1:LENSTR(ITEM2)),
     -            ITEM3(1:LENSTR(ITEM3)), ' ', COLSTR(COLOUR)
          ENDIF

C----     Add the residue itself
          OUTLIN(OUTPOS + 1:) = CH
          OUTPOS = OUTPOS + 1

C----     Store the current colour
          LSTCOL = COLOUR
 600  CONTINUE

C---- Close off previous colour, if there was one
      IF (LSTCOL.NE.0) THEN
          OUTLIN(OUTPOS + 1:) = '</FONT>'
          OUTPOS = OUTPOS + 7
      ENDIF
      OUTLIN(OUTPOS + 1:) = '</B>'

C---- Write out the coloured sequence
      WRITE(IFILE,620) OUTLIN(1:LENSTR(OUTLIN))
 620  FORMAT(A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRINUC  -  Write out all the nucleic acid chain entries
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRINUC(IFILE)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*6   NUMBER
      CHARACTER*10  CNAME
      CHARACTER*20  ITEM1, ITEM2
      CHARACTER*(MXLNAM) OUTLIN, TEMP
      CHARACTER*560 OUTSEQ
      INTEGER       CHAINO, CHCOLR, ICHAIN, IFILE, ILEN, ILINE, IPOS,
     -              ITIME, LENSTR, NLINE

C---- Write out the number of DNA/RNA chains to database.dat
      IF (NNUCL.GT.0) THEN
          WRITE(NUMBER,60) NNUCL
 60       FORMAT(I6)
          WRITE(DBASE,110) 'NNUCL ', NUMBER
      ENDIF

C---- Write heading to chain-trace file
CXXX      IF (NNUCL.GT.0) THEN
CXXX          WRITE(8,110) '<li><b>Nucleotide chains (all bonds)</b>'
CXXX          WRITE(8,110) '<ul>'
CXXX      ENDIF

C---- Loop until all chains have been processed
      DO 800, ICHAIN = 1, NNUCL

C----     Form subscript for current chain
          CALL SUBSCR(ICHAIN,ITEM1)

C----     Write out the chain identifier
          IF (CHAIN(ICHAIN,NUC).EQ.' ') THEN
              WRITE(DBASE,110) 'NUCL_CHAIN',
     -            ITEM1(1:LENSTR(ITEM1))
          ELSE
              WRITE(DBASE,110) 'NUCL_CHAIN',
     -            ITEM1(1:LENSTR(ITEM1)), ' ', CHAIN(ICHAIN,NUC)
          ENDIF

C----     Write out the number of bases
          WRITE(NUMBER,60) NRESID(ICHAIN,NUC)
          WRITE(DBASE,110) 'NNUCL_BASES',
     -         ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER

C----     Get the chain's colour
          CALL OBJCOL(CHAINO,CHAIN(ICHAIN,NUC),CHCOLR,CNAME)
          WRITE(DBASE,110) 'NUCL_COL',
     -         ITEM1(1:LENSTR(ITEM1)), ' ', CNAME(1:LENSTR(CNAME))

C----     Start this chain's entry
          WRITE(IFILE,110) '<IMG ALIGN=BOTTOM SRC="../',
     -        CNAME(1:LENSTR(CNAME)), 'dot.gif" ALT=".">'
 110      FORMAT(10A)

C----     Chain heading and number of bases
          WRITE(CNUMB,220) NRESID(ICHAIN,NUC)
 220      FORMAT(I8)
          WRITE(IFILE,110) '<b>Chain ', CHAIN(ICHAIN,NUC),
     -        '</b>: Nucleic acid sequence (<b>', CNUMB, '</b> bases )'

C----     Write chain heading to chain-trace file
CXXX          WRITE(8,110) '<li><b>Chain'
CXXX          WRITE(8,120) CHAIN(ICHAIN,NUC)
CXXX          WRITE(8,110) '</b> (<b>'
CXXX          WRITE(8,120) CNUMB
CXXX          WRITE(8,110) '</b> bases )'

C----     Write out the chain colour
CXXX          WRITE(8,110) ' - <em>backbone '
CXXX          WRITE(8,110) NUCCOL(ICHAIN)
CXXX          WRITE(8,110) '</em>'

C----     Write out the sequence of bases
          NLINE = 0
          WRITE(IFILE,110) '  <ul>'
          WRITE(IFILE,110) '  <li><em>Sequence:</em> <b>'
          DO 400, ILINE = 1, MXLINE

C----         Form subscript for current line
              CALL SUBSCR(ILINE,ITEM2)

C----         Determine the length of the line and close up any blank
C             spaces
              ILEN = 0
              IPOS = 0
              ITIME = 0
              OUTLIN = SEQUEN(ILINE,ICHAIN,NUC)
              OUTSEQ = SEQUEN(ILINE,ICHAIN,NUC)

C----         Process line if not blank
              IF (OUTLIN.NE.' ') THEN
 300              CONTINUE

C----                 Go to next character position
                      IPOS = IPOS + 1
                      ITIME = ITIME + 1

C----                 If this is a non-space, then save position as
C                     current length of line
                      IF (OUTLIN(IPOS:IPOS).NE.' ') THEN
                          ILEN = IPOS

C----                 If have a blank character, then shift sequence
C                     along by one character
                      ELSE
                          TEMP = OUTLIN
                          TEMP(IPOS:) = OUTLIN(IPOS + 1:)
                          OUTLIN = TEMP
                          IPOS = IPOS - 1
                      ENDIF

C----             Go back for next character if not already reached end
                  IF (ITIME.LT.MXLNAM) GO TO 300

C----             Write the sequence out
                  IF (ILEN.GT.0) THEN
                      IF (ILINE.EQ.1) THEN
                          WRITE(IFILE,110) OUTLIN(1:ILEN)
                          WRITE(DBASE,110) 'NUCL_SEQ',
     -                         ITEM1(1:LENSTR(ITEM1)),
     -                         ITEM2(1:LENSTR(ITEM2)),
     -                         ' ', OUTLIN(1:ILEN)
                      ELSE
                          WRITE(IFILE,110) '-' // OUTLIN(1:ILEN)
                          WRITE(DBASE,110) 'NUCL_SEQ',
     -                         ITEM1(1:LENSTR(ITEM1)),
     -                         ITEM2(1:LENSTR(ITEM2)),
     -                         ' -', OUTLIN(1:ILEN)
                      ENDIF
                      NLINE = NLINE + 1
                  ENDIF
              ENDIF
 400      CONTINUE

C----     Write out number of lines of sequence
          WRITE(NUMBER,60) NLINE
          WRITE(DBASE,110) 'NSEQLINE',
     -         ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER

C----     Write out any nonstandard residue types and attached HET groups
          WRITE(IFILE,110) '  </b><BR>'
          CALL WRNONS(IFILE,ICHAIN,ICHAIN,NUC,NRESID(ICHAIN,NUC),ITEM1)

C----     Chain end
          WRITE(IFILE,110) '  </ul>'
 800  CONTINUE

C---- Write chain-end to chain-trace file
CXXX      IF (NNUCL.GT.0) THEN
CXXX          WRITE(8,110) '</ul>'
CXXX      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE NUCPLT  -  Write out link for NUCPLOT display script (if any)
C
C----------------------------------------------------------------------+---

      SUBROUTINE NUCPLT(IFILE)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   DQUOTE
      CHARACTER*120 COMMND, FILNAM
      INTEGER       DLEN, HLEN, IFILE, IPOS
      LOGICAL       HAVFIL

      DATA DQUOTE /'"'/

C---- Initialise flags
      HAVFIL = .FALSE.

C---- Initialise variables
      HLEN = INDEX(WWWPDB,' ') - 1

C---- Check whether the nucplot.ps.gz file exists
      FILNAM = 'nucplot.ps.gz'
      CALL CHKFIL(PDBSUM,FILNAM,HAVFIL)

C---- If PDBsum1, check for the nucplot.ps file
      IF (PDBSM1) THEN
         FILNAM = 'nucplot/nucplot.ps'
         CALL CHKFIL(PDBSUM,FILNAM,HAVFIL)
      ENDIF

C---- If have the file, then create the link
      IF (HAVFIL) THEN

C----     Write flag to database.dat file to indicate existence of
C         NUCPLOT
          WRITE(DBASE,110) 'NUCPLOT TRUE'

C----     Form the command to call the Perl script
          IPOS = INDEX(DONUCP,'*') - 1
          DLEN = INDEX(DONUCP,' ') - 1
          COMMND = DONUCP(1:IPOS) // BRCODE

C----     Write out the link
          WRITE(IFILE,110) '<P>'
 110      FORMAT(10A)
          WRITE(IFILE,110) '<A HREF=', DQUOTE, COMMND(1:DLEN),
     -         DQUOTE, '>'
          WRITE(IFILE,110) '<IMG ALIGN=MIDDLE SRC="../nucplot.gif">'
          WRITE(IFILE,110) '</A>'
          WRITE(IFILE,110) '<A HREF=', DQUOTE, COMMND(1:DLEN),
     -         DQUOTE, '>'
          WRITE(IFILE,110) '<B>NUCPLOT</B></A>'
          WRITE(IFILE,110) '- Plot of protein-DNA interactions'
          WRITE(IFILE,110) '(PostScript file)'
          WRITE(IFILE,110) '<P>'
      ENDIF

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRILIG  -  Write out all the ligand entries and associated
C                        .html files
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRILIG(IFILE)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   CH
      CHARACTER*2   EXTNUM, LNUMB
      CHARACTER*3   RESDUE
      CHARACTER*6   NUMBER
      CHARACTER*7   BAKCOL
      CHARACTER*20  ITEM1, ITEM2
      CHARACTER*120 EXTNAM, HETFIL
CXXX      CHARACTER*120 FILNAM
      INTEGER       HLEN, IENTRY, IFILE, ILEN, ILINE, IPOS, LENSTR,
     -              LSTLIN, NEXTRL
      LOGICAL       ALLDNA, GOTHET, HAVEXT, HAVFIL, HAVGIF, LIGRES

C---- Initialise variables
      HLEN = INDEX(WWWHET,' ') - 1

C---- Check whether this is an all-DNA structure
      IF (NCHAIN.EQ.0 .AND. NLIGAN.LT.2) THEN
          ALLDNA = .TRUE.
      ELSE
          ALLDNA = .FALSE.
      ENDIF

C---- Write out the number of ligands to database.dat
C      IF (NLIGAN.GT.0) THEN
C          WRITE(NUMBER,60) NLIGAN
 60       FORMAT(I6)
C          WRITE(DBASE,110) 'NLIGAN ', NUMBER
C      ENDIF

C---- Process any ligands
      DO 1000, IENTRY = 1, NLIGAN

C----     Form subscript for current ligand entry
          CALL SUBSCR(IENTRY,ITEM1)

C----     Process only if have ligand details
          IF (NTIMES(IENTRY,LIG).GT.0) THEN

C----         Write number of ligand residues to database.dat file
C              WRITE(NUMBER,60) NRESID(IENTRY,LIG)
C              WRITE(DBASE,110) 'NLIGAND_RES',
C     -             ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER

C----         Write number of copies of this ligand in the structure
C              IF (NTIMES(IENTRY,LIG).GT.1) THEN
C                  WRITE(NUMBER,60) NTIMES(IENTRY,LIG)
C                  WRITE(DBASE,110) 'NLIGAND_TIMES',
C     -                ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER
C              ENDIF

C----         Ligand
              WRITE(IFILE,110) '<BR><IMG ALIGN=BOTTOM ',
     -            'SRC="../blackdot.gif" ALT=".">'
 110          FORMAT(10A)
              IF (NTIMES(IENTRY,LIG).GT.1) THEN
                  WRITE(CNUMB,120) NTIMES(IENTRY,LIG)
 120              FORMAT(I8)
                  WRITE(IFILE,110) '<b>', CNUMB, ' x</b>'
              ENDIF
              WRITE(IFILE,110) '      <em>Ligand:</em> <b>'
              GOTHET = .FALSE.

C----         If there is only one residue in this ligand, and it is a
C             non-standard one, then set up link to HET groups database
              IF (NRESID(IENTRY,LIG).EQ.1) THEN
                  RESDUE = ' '
                  IF (ACOUNT(1,IENTRY,1,LIG).EQ.1) THEN
                      RESDUE = ATTNAM(1,IENTRY,1,LIG)
                  ELSE IF (ACOUNT(1,IENTRY,2,LIG).EQ.1) THEN
                      RESDUE = ATTNAM(1,IENTRY,2,LIG)
                  ELSE IF (ACOUNT(1,IENTRY,3,LIG).EQ.1) THEN
                      RESDUE = ATTNAM(1,IENTRY,3,LIG)
                  ENDIF

C----             If have a description for this entry, then want to
C                 write out the URL to the HET groups database
                  IF (RESDUE.NE.' ') THEN
                      GOTHET = .TRUE.
                      IF (RESDUE(1:1).EQ.' ') RESDUE(1:1) = '_'
                      IF (RESDUE(2:2).EQ.' ') RESDUE(2:2) = '_'
                      IF (RESDUE(3:3).EQ.' ') RESDUE(3:3) = '_'

C----                 Write out the URL
                      HETFIL = WWWHET(1:HLEN) // 'ind' // RESDUE //
     -                    '.html'
                      WRITE(IFILE,110) '<a href="', HETFIL(1:HLEN + 11),
     -                    '">'
                  ENDIF
              ENDIF

C----         Write out the ligand sequence
              DO 300, ILINE = 1, MXLINE

C----             Form subscript for current line
                  CALL SUBSCR(ILINE,ITEM2)

C----             Get the location of the last non-blank character
                  ILEN = 0
                  DO 200, IPOS = 1, MXLNAM

C----                 Get the next character
                      CH = SEQUEN(ILINE,IENTRY,LIG)(IPOS:IPOS)

C----                 If not a blank, then store position
                      IF (CH.NE.' ') THEN
                          ILEN = IPOS
                      ENDIF
 200              CONTINUE

C----             Write out the sequence
                  IF (ILEN.GT.1) THEN
                      IF (ILINE.EQ.1) THEN
                          WRITE(IFILE,220)
     -                        SEQUEN(ILINE,IENTRY,LIG)(1:ILEN)
 220                      FORMAT(4X,A)
C                          WRITE(DBASE,110) 'LIGAND_SEQ',
C     -                         ITEM1(1:LENSTR(ITEM1)),
C     -                         ITEM2(1:LENSTR(ITEM2)),
C     -                         ' ', SEQUEN(ILINE,IENTRY,LIG)(1:ILEN)
                      ELSE
                          WRITE(IFILE,220) '-' //
     -                        SEQUEN(ILINE,IENTRY,LIG)(1:ILEN)
C                          WRITE(DBASE,110) 'LIGAND_SEQ',
C     -                         ITEM1(1:LENSTR(ITEM1)),
C     -                         ITEM2(1:LENSTR(ITEM2)),
C     -                         ' -', SEQUEN(ILINE,IENTRY,LIG)(1:ILEN)
                      ENDIF
                      LSTLIN = ILINE
                  ENDIF
 300          CONTINUE

C----         Write out number of lines of ligand sequence
              WRITE(NUMBER,60) LSTLIN
C              WRITE(DBASE,110) 'NLIGLINE',
C     -            ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER

              IF (GOTHET) WRITE(IFILE,110) '</a>'
              WRITE(IFILE,110) '</b>'
              IF (NRESID(IENTRY,LIG).GT.1) THEN
                  WRITE(IFILE,110) ' (<b>'
                  WRITE(CNUMB,320) NRESID(IENTRY,LIG)
 320              FORMAT(I8)
                  WRITE(IFILE,220) CNUMB
                  WRITE(IFILE,110) '</b> residues )'
              ENDIF

C----         Identify any non-standard residues
CC              CALL GETDES(SEQUEN,MXLNAM,MXLINE,MXNTRY,IENTRY,LIG,
CC     -            NONAME,NODESC,NOFORM,NONUMB,MXNONS,NOTYPE)

C----         Write out any non-standard residues
C              IF (NOTYPE.GT.0) THEN

C----             Start new list if ligand contains both standard and non-
C                 standard residue types
C                  IF (NOTYPE.LT.NRESID(IENTRY,LIG)) THEN
C                      WRITE(IFILE,110) '  <ul>'
C                      WRITE(IFILE,110) '    <li> <b>'
C                      WRITE(CNUMB,320) NOTYPE
C                      WRITE(IFILE,220) CNUMB
C                      IF (NOTYPE.EQ.1) THEN
C                          WRITE(IFILE,110) 
C     -                        '</b>non-standard residue type:'
C                      ELSE
C                          WRITE(IFILE,110)
C     -                        '</b> non-standard residue types:'
C                      ENDIF
C                      WRITE(IFILE,110) '    </ul>'
C                  ENDIF

C----             Start a new list if necessary
C                  IF (NRESID(IENTRY,LIG).GT.1) THEN
C                      WRITE(IFILE,110) '      <ul>'
C                  ENDIF

C----             Loop over the non-standard residues
CC                  DO 500, ITYPE = 1, NOTYPE
CC                      IF (NRESID(IENTRY,LIG).GT.1) THEN
CC                          WRITE(IFILE,110) '      <ul>'
CC                          WRITE(IFILE,110) '      <li> <b>'
CC                          WRITE(CNUMB,320) NONUMB(ITYPE)
CC                          WRITE(IFILE,220) CNUMB
CC                          WRITE(IFILE,220) NONAME(ITYPE)
CC                          WRITE(IFILE,110) '</b>'
CC                      ENDIF

C----                 If have a description, write it out
C                      IF (NODESC(ITYPE).NE.' ') THEN
C                          WRITE(IFILE,110) ' - <em>'

C----                     If description references REMARK 5, write that out
C                         instead
C                          IF (NODESC(ITYPE)(1:12).EQ.'SEE REMARK 5')
C     -                        THEN
C                              WRITE(IFILE,220)
C     -                            (REM5(ILINE), ILINE = 1, NRLINE)

C----                     Otherwise convert description and write out
C                          ELSE
C                              CALL TYPSET(40,1,NODESC(ITYPE),.FALSE.)
C                              WRITE(IFILE,220) NODESC(ITYPE)
C                          ENDIF
C                          WRITE(IFILE,110) '</em> '
C                      ENDIF

C----                 If have a formula, write it out
C                      IF (NOFORM(ITYPE).NE.' ') THEN
C                          WRITE(IFILE,110) 'Formula:<b>'
C                          WRITE(IFILE,220) NOFORM(ITYPE)
C                          WRITE(IFILE,110) '</b> '
C                      ENDIF
C                      IF (NRESID(IENTRY,LIG).GT.1) THEN
C                          WRITE(IFILE,110) '      </ul>'
C                      ENDIF
C 500              CONTINUE

C----             End the list
C                  IF (NRESID(IENTRY,LIG).GT.1) THEN
C                      WRITE(IFILE,110) '      </ul>'
C                  ENDIF
C              ENDIF

C----         Write out any nonstandard residue types and attached HET groups
CC              WRITE(IFILE,110) '<p>'
              CALL WRNONS(IFILE,IENTRY,IENTRY,LIG,NRESID(IENTRY,LIG),
     -            ITEM1)

C----         Show a picture of the ligand, if it exists
              HAVGIF = .FALSE.
              LNUMB = ' '

C----         Form the filename of the gif file holding the simple
C             picture of the ligand
              WRITE(LNUMB,520) IENTRY
 520          FORMAT(I2)
              IF (LNUMB(1:1).EQ.' ') LNUMB(1:1) = '0'
CXXX              FILNAM = 'ligmain' // LNUMB // '.gif'

C----         If the gif file is present, then set flag to include it
CXXX              CALL CHKFIL(PRODIR,BRCODE,FILNAM,HAVGIF)

C----         If the gif file exists, then include it
CXXX              IF (HAVGIF) THEN
CXXX                  WRITE(IFILE,110) '<BR>', '<IMG SRC="', 
CXXX     -                FILNAM(1:LENSTR(FILNAM)), '"><BR>'
CXXX              ENDIF

C----         Write out the following entries only if the ligand
C             contains enough identifiable bonds for LIGPLOT to have
C             generated its plots
              IF (NBONDS(IENTRY).GE.2) THEN

C----             Start list of items for this ligand
                  WRITE(IFILE,110) '<ul>'

C----             Prepare ligand name
                  IF (NRESID(IENTRY,LIG).EQ.1) THEN
                      LNAME = SEQUEN(1,IENTRY,LIG)
                  ELSE
                      LNAME = 'Ligand'
                  ENDIF
                  ILEN = INDEX(LNAME,' ') - 1

C----             Generate the gif-holding .html file for the schematic
C                 diagram of the ligand
                  BAKCOL = '#ffffa0'
                  LIGRES = .TRUE.
                  IF(ILEN.NE.0)THEN
                  CALL GIFILE(IFILE,'lig',IENTRY,
     -                'Schematic diagram of molecule',
     -                LNAME(1:ILEN) // ' - Schematic diagram',
     -                PDBSUM,BRCODE,PLAIN,' ',.FALSE.,LIGRES,DOLRES,1,
     -                BAKCOL,RUNLIG)
                  ELSE
                  CALL GIFILE(IFILE,'lig',IENTRY,
     -                'Schematic diagram of molecule',
     -                ' - Schematic diagram',
     -                PDBSUM,BRCODE,PLAIN,' ',.FALSE.,LIGRES,DOLRES,1,
     -                BAKCOL,RUNLIG)
                  ENDIF

C----             Generate the gif-holding .html file for box-plot
COUT                  CALL GIFILE(IFILE,'box',IENTRY,'Boxplot of molecule',
COUT     -                LNAME(1:ILEN) // ' - Boxplot',BRCODE,PLAIN,' ',
COUT     -                .FALSE.,1,BAKCOL,RUNLIG)

C----             Generate the gif-holding .html file for Raster3D plot
                  BAKCOL = ' '
                  LIGRES = .FALSE.
                  IF(ILEN.NE.0)THEN
                  CALL GIFILE(IFILE,'raster',IENTRY,
     -                'Raster3D picture of molecule',
     -                LNAME(1:ILEN) // ' - Raster3D picture',PDBSUM,
     -                BRCODE,PLAIN,' ',.FALSE.,LIGRES,DOLRES,1,BAKCOL,
     -                RUNLIG)
                  ELSE
                  CALL GIFILE(IFILE,'raster',IENTRY,
     -                'Raster3D picture of molecule',
     -                ' - Raster3D picture',PDBSUM,
     -                BRCODE,PLAIN,' ',.FALSE.,LIGRES,DOLRES,1,BAKCOL,
     -                RUNLIG)
                  ENDIF

C----             Determine how many gif files for any extra ligands
C                 there may be
                  NEXTRL = 0
                  HAVEXT = .FALSE.
 800              CONTINUE

C----                 Form the filename and check whether file exists
                      WRITE(EXTNUM,520) NEXTRL + 1
                      IF (EXTNUM(1:1).EQ.' ') EXTNUM(1:1) = '0'
                      EXTNAM = 'ligplot' // LNUMB // '_' // EXTNUM
     -                    // '.gif'
                      CALL CHKFIL(PDBSUM,EXTNAM,HAVFIL)

C----             If file exists, increment count and check next one
                  IF (HAVFIL .AND. NEXTRL.LT.100) THEN
                      NEXTRL = NEXTRL + 1
                      HAVEXT = .TRUE.
                      GO TO 800
                  ENDIF

C----             Generate the gif-holding .html file for LIGPLOT
C                  IF (.NOT.ALLDNA) THEN
                      BAKCOL = '#ffffa0'
                      LIGRES = .TRUE.
                      IF(ILEN.NE.0)THEN
                      CALL GIFILE(IFILE,'ligplot',IENTRY,
     -                    'LIGPLOT of interactions',
     -                    LNAME(1:ILEN) //
     -                    ' - Interactions with protein',PDBSUM,
     -                    BRCODE,PLAIN,' ',.TRUE.,LIGRES,DOLRES,NEXTRL,
     -                    BAKCOL,RUNLIG)
                      ELSE
                      CALL GIFILE(IFILE,'ligplot',IENTRY,
     -                    'LIGPLOT of interactions',
     -                    ' - Interactions with protein',PDBSUM,
     -                    BRCODE,PLAIN,' ',.TRUE.,LIGRES,DOLRES,NEXTRL,
     -                    BAKCOL,RUNLIG)
                      ENDIF
C                  ENDIF

C----             Generate the gif-holding .html file for atomic
C                 accessibilities
C                  CALL GIFILE(IFILE,'access',IENTRY,'Atomic accessibilities',
C     -                LNAME(1:ILEN) // ' - Atomic accessibilities',BRCODE,
C     -                PLAIN,' ',.FALSE.,1,BAKCOL,RUNLIG)

C----             End of ligand
                  WRITE(IFILE,110) '  </ul>'
              ENDIF
          ENDIF
1000  CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIMET  -  Write any metals to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIMET(IFILE,DBASE,WWWHET,METYPE,NMETYP,NMETAL)

      INTEGER       NMETAL

      CHARACTER*3   RESDUE
      CHARACTER*4   METYPE(NMETAL)
      CHARACTER*6   NUMBER
      CHARACTER*8   CNUMB
      CHARACTER*10  COLNAM
      CHARACTER*20  ITEM1
      CHARACTER*200 HETFIL
      CHARACTER*(*) WWWHET
      INTEGER       DBASE, HLEN, ICOL, IFILE, IMETAL, LENSTR,
     -              NMETYP(NMETAL)
      REAL          RADIUS

C---- Initialise variables
      HLEN = INDEX(WWWHET,' ') - 1

C---- Write out the number of metals to database.dat
      IF (NMETAL.GT.0) THEN
          WRITE(NUMBER,60) NMETAL
 60       FORMAT(I6)
C          WRITE(DBASE,510) 'NMETAL ', NUMBER
      ENDIF

C---- Process any metals
      IF (NMETAL.GT.0) WRITE(IFILE,510) '<P>'
      DO 200, IMETAL = 1, NMETAL

C----     Form subscript for current chain
          CALL SUBSCR(IMETAL,ITEM1)

C----     Get the metal's colour and write out a coloured dot
          CALL ATMCOL(METYPE(IMETAL),ICOL,COLNAM,RADIUS)
          WRITE(IFILE,510) '<BR><IMG ALIGN=BOTTOM SRC="../',
     -        COLNAM(1:LENSTR(COLNAM)), 'dot.gif" ALT=".">'
C          WRITE(DBASE,510) 'METAL_COL',
C     -         ITEM1(1:LENSTR(ITEM1)), ' ', COLNAM(1:LENSTR(COLNAM))

C----     Metal atoms
          WRITE(CNUMB,120) NMETYP(IMETAL)
 120      FORMAT(I8)
          IF (NMETYP(IMETAL).EQ.1) THEN
              WRITE(IFILE,510) '<b>', CNUMB, '</b><em> Metal ion:</em>' 
          ELSE
              WRITE(IFILE,510) '<b>', CNUMB, '</b><em> Metal ions:</em>' 
          ENDIF

C----     Number of metal ions
          IF (NMETYP(IMETAL).GT.1) THEN
              WRITE(NUMBER,60) NMETYP(IMETAL)
C              WRITE(DBASE,510) 'NMETAL_IONS',
C     -            ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER
          ENDIF

C-----    Get the metal name
          RESDUE = ' ' // METYPE(IMETAL)
          IF (METYPE(IMETAL)(3:3).NE.' ') THEN
              RESDUE = METYPE(IMETAL)
          ENDIF
          IF (RESDUE(1:1).EQ.' ') RESDUE(1:1) = '_'
          IF (RESDUE(2:2).EQ.' ') RESDUE(2:2) = '_'
          IF (RESDUE(3:3).EQ.' ') RESDUE(3:3) = '_'

C----     Write out the metal name
C          WRITE(DBASE,510) 'METAL_ID',
C     -         ITEM1(1:LENSTR(ITEM1)), ' ', RESDUE

C----     Write out the URL
          HETFIL = WWWHET(1:HLEN) // 'ind' // RESDUE // '.html'
          WRITE(IFILE,510) '<a href="', HETFIL(1:HLEN + 11), '">'
          WRITE(IFILE,520) '<b>', RESDUE
          WRITE(IFILE,510) '</b></a>'
          IF (NMETYP(IMETAL).EQ.1) THEN
              WRITE(IFILE,510) ' ion<BR>'
          ELSE
              WRITE(IFILE,510) ' ions<BR>'
          ENDIF

 200  CONTINUE

 510  FORMAT(10A)
 520  FORMAT(A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE ATMCOL  -  Return the colour and van der Waals radius of
C                        the given atom type
C
C----------------------------------------------------------------------+---

      SUBROUTINE ATMCOL(ATNAME,ATCOL,COLNAM,RADIUS)

      INCLUDE 'pdbhtml.inc'

      SAVE

      INTEGER       ALLCOL, MCOLS, NRADII
      PARAMETER    (ALLCOL=11, MCOLS = 5, NRADII = 6)

      CHARACTER*2   AT(NRADII)
      CHARACTER*4   ATNAME
      CHARACTER*10  COLNAM, COLTXT(ALLCOL)
      INTEGER       ATCOL, ICOLR(ALLCOL), IMETYP, IPOS, JMETYP,
     -              MCOL(MCOLS)
      LOGICAL       FOUND, METAL
      REAL          RADIUS, VDWRAD(NRADII)

      DATA AT     / ' H', ' C', ' O', ' N', ' S', ' P' /
      DATA ICOLR  /   2,    1,    3,    5,    6,    9,   17,    7,
     -               10,    4,    4  /
      DATA VDWRAD /  1.2, 1.87,  1.4, 1.65, 1.85,  1.9 /

      DATA COLTXT /'white     ', 'black     ', 'red       ',
     -             'blue      ', 'yellow    ', 'purple    ',
     -             'brown     ', 'orange    ', 'cyan      ',
     -             'green     ', 'magenta   ' /

      DATA MCOL  /  10,  9,  8, 11,  7 /

C---- Get the atom's van der Waals radius and ATCOL
      RADIUS = VDWRAD(NRADII)
      IPOS = NRADII
      ATCOL = ICOLR(IPOS)
      FOUND = .FALSE.
      DO 500, IPOS = 1, NRADII - 1
          IF (ATNAME(1:2).EQ.AT(IPOS)) THEN
              RADIUS = VDWRAD(IPOS)
              ATCOL = ICOLR(IPOS)
              FOUND = .TRUE.
              GO TO 550
          ENDIF
500   CONTINUE

C---- If atom type not identified, check for various possibilties
 550  CONTINUE
      IF (.NOT.FOUND) THEN

C----     Check for various metals
          JMETYP = 0
          METAL = .FALSE.
          DO 600, IMETYP = 1, MXMETP
              IF (ATNAME(1:2).EQ.METYPE(IMETYP)(1:2)) THEN
                  METAL = .TRUE.
                  JMETYP = IMETYP
              ENDIF
 600      CONTINUE

C----     If the atom is a metal, set to standard radius and ATCOL
          IF (METAL) THEN
              IMETYP = JMETYP
              RADIUS = 1.2

C----         If this is a metal, then check if already have a
C             colour for it
              IF (IMETYP.GT.0) THEN

C----             If have a colour, then use it
                  IF (METCOL(IMETYP).GT.0) THEN
                      IPOS = METCOL(IMETYP)
                      ATCOL = ICOLR(IPOS)
                      GO TO 999

C----             Otherwise, assign the next available colour to this
C                 metal type
                  ELSE
                      NXTCOL = NXTCOL + 1
                      IF (NXTCOL.GT.MCOLS) NXTCOL = 1
                      IPOS = MCOL(NXTCOL)
                      METCOL(IMETYP) = IPOS
                      ATCOL = ICOLR(IPOS)
                      GO TO 999
                  ENDIF
              ENDIF

C----     Otherwise check second letter of atom name
          ELSE
              DO 700, IPOS = 1, NRADII - 1
                  IF (ATNAME(2:2).EQ.AT(IPOS)(2:2)) THEN
                      RADIUS = VDWRAD(IPOS)
                      ATCOL = ICOLR(IPOS)
                  ENDIF
700           CONTINUE
          ENDIF
      ENDIF

C---- Get the colour name
 999  CONTINUE
      COLNAM = COLTXT(IPOS)

      RETURN
      END

C----------------------------------------------------------------------+---
C**************************************************************************
C
C  SUBROUTINE WRIEXT  -  Write extra, unidentified entries, to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIEXT(IFILE,EXTRA,NUMEXT,NEXTRA)

      INTEGER       NEXTRA

      CHARACTER*4   EXTRA(NEXTRA)
      CHARACTER*6   ATSTR
      CHARACTER*8   CNUMB
      INTEGER       IEXTRA, IFILE, NUMEXT(NEXTRA)

C---- Process any extra, unidentified entries
      IF (NEXTRA.GT.0) WRITE(IFILE,510) '<P>'
      DO 200, IEXTRA = 1, NEXTRA

C----     Extras dot
          WRITE(IFILE,510) '<BR><IMG ALIGN=BOTTOM SRC="../otherdot.gif',
     -        '" ALT=".">'

C----     Extra item
          WRITE(CNUMB,120) NUMEXT(IEXTRA)
 120      FORMAT(I8)
          IF (NUMEXT(IEXTRA).EQ.1) THEN
              ATSTR = ' atom'
          ELSE
              ATSTR = ' atoms'
          ENDIF
          WRITE(IFILE,510) '<em>Extra atom(s):</em> <b>', CNUMB, '</b>',
     -        EXTRA(IEXTRA), ATSTR

 200  CONTINUE

 510  FORMAT(10A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIWAT  -  Write waters to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIWAT(IFILE,DBASE,NWATER)

      INTEGER       DBASE, IFILE, NWATER
      CHARACTER*6   NUMBER
      CHARACTER*8   CNUMB

C---- Write out the number of waters to database.dat
      IF (NWATER.GT.0) THEN
          WRITE(NUMBER,60) NWATER
 60       FORMAT(I6)
          WRITE(DBASE,510) 'WATER TRUE'
          WRITE(DBASE,510) 'NWATER ', NUMBER
      ENDIF

C---- Show the numbers of waters
      IF (NWATER.GT.0) THEN

C----     Waters
          WRITE(CNUMB,120) NWATER
 120      FORMAT(I8)
          WRITE(IFILE,510) '<p><IMG ALIGN=BOTTOM SRC="../waterdot.gif"',
     -        ' ALT=".">'
          WRITE(IFILE,510) '<b>', CNUMB, '</b> water molecules.'
      ELSE
          WRITE(IFILE,510) '<p><b>No</b> water molecules.'
      ENDIF

 510  FORMAT(10A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIEND  -  Write closing lines to the HTML file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIEND(IFILE,WWWPDB)

      CHARACTER*1   QUOTE
      CHARACTER*200 FNAME
      CHARACTER*(*) WWWPDB
      INTEGER       IFILE, LENSTR

      DATA QUOTE  /''''/

C---- Write link to PDB search page
      IF (IFILE.EQ.7) THEN
          WRITE(IFILE,510) '<p>'
          WRITE(IFILE,510) 'Enter new <a'
          FNAME = 'href="' // WWWPDB(1:LENSTR(WWWPDB)) // 'index.html">'
          WRITE(IFILE,510) FNAME(1:LENSTR(FNAME))
          WRITE(IFILE,510) '<b>PDB</b> code</a>'

C---- New-style gif
      ELSE
          WRITE(IFILE,510) '<p>'
          WRITE(IFILE,510) '<a'
          FNAME = 'href="' // WWWPDB(1:LENSTR(WWWPDB)) // 'index.html"'
          WRITE(IFILE,510) FNAME(1:LENSTR(FNAME))
          WRITE(IFILE,510) 'onMouseOver="window.status=', QUOTE, 'Go t',
     -        'o PDBsum home page', QUOTE, '; return true;">'
C          WRITE(IFILE,510) '<b>PDBsum</b> home</a>'
          WRITE(IFILE,510) '<IMG BORDER=0 SRC="../gif/pdbsum_sm.gif"><',
     -        '/a>'
      ENDIF

C---- End off
      WRITE(IFILE,510) '</body>'
      WRITE(IFILE,510) '</html>'


 510  FORMAT(10A)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRIBND  -  Write closing lines to the binding sites HTML
C                        file
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRIBND(IFILE)

      INTEGER       IFILE

C---- End off the HTML page
      WRITE(IFILE,110) '</BODY>'
 110  FORMAT(10A)
      WRITE(IFILE,110) '</HTML>'

C---- Close the file
      CLOSE(IFILE)

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE NEWHED  -  Write out the new-format main.html file from
C                        the template
C
C----------------------------------------------------------------------+---

      SUBROUTINE NEWHED(IFILE,SUMDAT)

      INCLUDE 'pdbhtml.inc'

      INTEGER       MXSTAT, LENREC
      PARAMETER    (MXSTAT = 50, LENREC=256)

      CHARACTER*12  KEYWRD
      CHARACTER*20  OFFKEY
      CHARACTER*256 FILNAM
      CHARACTER*(*) SUMDAT
      CHARACTER*(LENREC) INREC, OUTLIN
      INTEGER       IFILE, IPOS, ISTATE, LENOFF, LENSTR, LINE, SPOS
      LOGICAL       HAVDAT(MXSTAT), WANTED

C---- Open input template file, template_head.html
      FILNAM = SUMDAT(1:LENSTR(SUMDAT)) // '/template_head.html'
      OPEN(UNIT=3,FILE=FILNAM,STATUS='OLD',
CVAX     -    CARRIAGECONTROL='LIST',READONLY,
     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=900)

C---- Initialise variables
      ISTATE = 0
      LENOFF = 1
      LINE = 0
      OFFKEY = ' '
      WANTED = .TRUE.

C---- Switch off the states that we don't want because we are missing
C     the corresponding information
      CALL SWOFF(HAVDAT,MXSTAT)

C---- Write out the various flags indicating what info is present
C     for this entry
      CALL DBINFO

C---- Loop while reading through input file
 100  CONTINUE

C----     Read in the next record from the input file
          READ(3,110,ERR=904,END=500) INREC
 110      FORMAT(A)
          LINE = LINE + 1

C----     Find position of first non-blank character
          SPOS = 0
          IF (INREC.NE.' ') THEN
              DO 200, IPOS = 1, LENREC
                  IF (INREC(IPOS:IPOS).NE.' ') THEN
                      SPOS = IPOS
                      GO TO 300
                  ENDIF
 200          CONTINUE

C----         Shift non-blank part of line to start
 300          CONTINUE
              IF (SPOS.GT.0) THEN
                  OUTLIN = INREC(SPOS:)
                  INREC = OUTLIN
              ENDIF
          ENDIF

C----     If this is a key-word line, change state accordingly
          IF (INREC(1:4).EQ.'<!-#' .AND. WANTED) THEN

C----         Extract the keyword
              KEYWRD = INREC(5:)

C----         Chop off end of keyword
              IPOS = INDEX(KEYWRD,'#')
              IF (IPOS.GT.0) KEYWRD(IPOS:) = ' '

C----         Search for the keyword in the list to determine the
C             state
              CALL GETSTA(KEYWRD,ISTATE)

C----         Check that we have the data for this state
              IF (ISTATE.EQ.0) THEN
                  WANTED = .TRUE.
              ELSE IF (HAVDAT(ISTATE)) THEN
                  WANTED = .TRUE.
              ELSE
                  WANTED = .FALSE.
              ENDIF
    
C----         Determine what the off-key for the current state is
C             (used when skipping an entire state)
              IF (ISTATE.EQ.0) THEN
                  OFFKEY = '<!/-#'
              ELSE
                  OFFKEY = '<!/-#' // KEYWRD(1:LENSTR(KEYWRD)) // '#>'
              ENDIF
              LENOFF = LENSTR(OFFKEY)

C----     Otherwise, check for state-end marker
          ELSE IF (INREC(1:LENOFF).EQ.OFFKEY(1:LENOFF)) THEN
              ISTATE = 0
              WANTED = .TRUE.

C----     Otherwise, write the record out, if it is wanted
          ELSE IF (WANTED .AND. SPOS.GT.0) THEN

C----         Write only if not an end-token
              IF (INREC(1:5).NE.'<!/-#') THEN

C----             Splice in any necessary data
                  CALL SPLICE(INREC,OUTLIN,IFILE)

C----             Write the line out to file
                  IF(LENSTR(OUTLIN).GT.0) THEN
                   WRITE(IFILE,110) OUTLIN(1:LENSTR(OUTLIN))
                  ENDIF
              ENDIF
          ENDIF

C---- Loop back for next record
      GO TO 100

C---- End of template file reached
500   CONTINUE

C---- Close the input template file
      CLOSE(3)

      GO TO 999

C---- File-read errors
900   CONTINUE
      PRINT*, '*** ERROR - Unable to open input template file: ',
     -    FILNAM(1:LENSTR(FILNAM))
      GO TO 999

904   CONTINUE
      PRINT*, '*** Read error on input template file at line ', LINE + 1
      PRINT 110, INREC
      GO TO 999

999   CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE SWOFF  -  Switch off the states that we don't want because
C                       we are missing the corresponding information
C
C----------------------------------------------------------------------+---

      SUBROUTINE SWOFF(HAVDAT,MXSTAT)

      INCLUDE 'pdbhtml.inc'

      INTEGER       NSTATE
      PARAMETER    (NSTATE = 9)

      INTEGER       MXSTAT

      CHARACTER*12  KEYWRD, OFFLNK(NSTATE)
      INTEGER       ISTATE, JSTATE
      LOGICAL       HAVDAT(MXSTAT), SWETAL

      DATA OFFLNK / 'PRINTS      ', 'UNPUB REFS  ',
     -              'DNA         ', 'PQS         ', 'WHAT        ',
     -              'YEAST       ', 'PROT CLASSIF', 'RELIBASE    ',
     -              'PDBLNK      ' /

C---- Initialise variables
      DO 50, ISTATE = 1, MXSTAT
          HAVDAT(ISTATE) = .TRUE.
 50   CONTINUE
      SWETAL = .FALSE.

C---- Keyword indicating lines of template file that are to be skipped
C     as though commented out
      KEYWRD = 'OUT'
      CALL GETSTA(KEYWRD,ISTATE)
      HAVDAT(ISTATE) = .FALSE.

C---- Javascript code to be included
      KEYWRD = 'JAVASCRIPT'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.JAVASC) HAVDAT(ISTATE) = .FALSE.

C---- Single GIF image of structure
      KEYWRD = 'SINGLE VIEW'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (HAVIEW) HAVDAT(ISTATE) = .FALSE.

C---- Side-views
      KEYWRD = 'SIDE VIEWS'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.HAVIEW) HAVDAT(ISTATE) = .FALSE.

C---- RasMol script view
      KEYWRD = 'RASCRIPT'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (TOOBIG .OR. .NOT.HAVRSC) HAVDAT(ISTATE) = .FALSE.

C---- VRML view
      KEYWRD = 'VRML VIEW'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.HAVWRL) HAVDAT(ISTATE) = .FALSE.

C---- Layer 1 entry
      KEYWRD = 'LAYER 1'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.LAYER1) HAVDAT(ISTATE) = .FALSE.

C---- Obsolete entry
      KEYWRD = 'OBSOLETE'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.OBSOL) HAVDAT(ISTATE) = .FALSE.

C---- Title
      KEYWRD = 'TITLE'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (NTLINE.EQ.0) HAVDAT(ISTATE) = .FALSE.

C---- Species image(s)
      KEYWRD = 'SPECIES'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (NSPECI.EQ.0) HAVDAT(ISTATE) = .FALSE.

C---- NMR details
      KEYWRD = 'NMR'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.NMR) HAVDAT(ISTATE) = .FALSE.

C---- Ensemble of models
      KEYWRD = 'ENSEMBLE'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (NMR .OR. NMODEL.EQ.0) HAVDAT(ISTATE) = .FALSE.

C---- X-RAY details
      KEYWRD = 'X-RAY'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (NMR) HAVDAT(ISTATE) = .FALSE.

C---- SWISS-PROT code
      KEYWRD = 'SWISS-PROT'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (NSWISS.EQ.0 .AND. ISTATE.NE.0) THEN
          HAVDAT(ISTATE) = .FALSE.
      ELSE
          SWETAL = .TRUE.
      ENDIF

C---- E.C. number
      KEYWRD = 'EC NUMBER'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (NEC.EQ.0 .AND. ECNUMB.EQ.' ' .AND. ISTATE.NE.0) THEN
          HAVDAT(ISTATE) = .FALSE.
      ELSE
          SWETAL = .TRUE.
      ENDIF

C---- PRINTS links
      KEYWRD = 'PRINTS'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (NPRLNK.EQ.0 .AND. ISTATE.NE.0) THEN
          HAVDAT(ISTATE) = .FALSE.
      ELSE
          SWETAL = .TRUE.
      ENDIF

C---- Related PDB entries
      KEYWRD = 'RELENT'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.NMRLNK .AND. NELINE.EQ.0 .AND. ISTATE.NE.0) THEN
          HAVDAT(ISTATE) = .FALSE.
      ELSE
          SWETAL = .TRUE.
      ENDIF

C---- Entries superseded by this one
      KEYWRD = 'SUPERSEDES'
      CALL GETSTA(KEYWRD,ISTATE)
      IF ((NSUPER.EQ.0 .OR. OBSOL) .AND. ISTATE.NE.0) THEN
          HAVDAT(ISTATE) = .FALSE.
      ELSE
          SWETAL = .TRUE.
      ENDIF

C---- None of the above
      IF (.NOT.SWETAL) THEN
          KEYWRD = 'SWISS ET AL'
          CALL GETSTA(KEYWRD,ISTATE)
          IF (ISTATE.NE.0) HAVDAT(ISTATE) = .FALSE.
      ENDIF

C---- Unpublished refertences
      KEYWRD = 'UNPUB REFS'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.HAVUNP) HAVDAT(ISTATE) = .FALSE.

C---- DNA structure
      KEYWRD = 'DNA'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (NDBREF.EQ.' ') HAVDAT(ISTATE) = .FALSE.

C---- Complete Macromolecule link
      KEYWRD = 'PQS'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (NCHAIN.EQ.0 .AND. NNUCL.EQ.0) HAVDAT(ISTATE) = .FALSE.

C---- Yeast structure
      KEYWRD = 'YEAST'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.YEAST) HAVDAT(ISTATE) = .FALSE.

C---- Structure classification databases
      KEYWRD = 'PROT CLASSIF'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (NCHAIN.EQ.0) HAVDAT(ISTATE) = .FALSE.

C---- Protein structural quality checks
      KEYWRD = 'CHECKS'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.HAVCHK) HAVDAT(ISTATE) = .FALSE.

C---- Structure from the MCSG
      KEYWRD = 'MCSG'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.MCSG) HAVDAT(ISTATE) = .FALSE.

C---- PROMOTIF analyses
      KEYWRD = 'PROMOTIF'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.HAVPRO) HAVDAT(ISTATE) = .FALSE.

C---- RELIBASE analyses
      KEYWRD = 'RELIBASE'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.HAVLIG) HAVDAT(ISTATE) = .FALSE.

C---- No SURFPLOT image
      KEYWRD = 'NOSURF'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (HAVSRF) HAVDAT(ISTATE) = .FALSE.

C---- SURFPLOT image
      KEYWRD = 'SURFPLOT'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (.NOT.HAVSRF) HAVDAT(ISTATE) = .FALSE.

C---- RasMol script view of the protein surface
      KEYWRD = 'RASURF'
      CALL GETSTA(KEYWRD,ISTATE)
      IF (NCHAIN.EQ.0 .AND. NNUCL.EQ.0) HAVDAT(ISTATE) = .FALSE.

C---- If no links are to be made to external databases, then switch
C     all these off
      IF (NOLINK) THEN
          DO 500, JSTATE = 1, NSTATE
              KEYWRD = OFFLNK(JSTATE)
              CALL GETSTA(KEYWRD,ISTATE)
              HAVDAT(ISTATE) = .FALSE.
 500      CONTINUE
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE DBINFO  -  Write out the various flags indicating what info
C                        is present for this entry
C
C----------------------------------------------------------------------+---

      SUBROUTINE DBINFO

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   FSTLET
      CHARACTER*4   OTHCOD
      CHARACTER*6   CH, NUMBER
      CHARACTER*8   FLOAT, UPPREF
      CHARACTER*12  ECOMPR
      CHARACTER*20  ITEM1, ITEM2, NDBLNK
      CHARACTER*120 FILNAM
      CHARACTER*(MXTITL) OUTLIN
      INTEGER       ICHN, IENTRY, ILINE, ISPECI, ISWISS, LENSTR, NOUT
      LOGICAL       MATCH, NEWLIN, SWETAL

C---- Initialise variables
      SWETAL = .FALSE.

C---- Write out the PDB code
      WRITE(DBASE,510) 'PDB_CODE ', BRCODE
 510  FORMAT(10A)

C---- Title
      IF (NTLINE.GT.0) THEN
           WRITE(DBASE,510) 'TITLE ',
     -        (TITLE(ILINE)(1:LENSTR(TITLE(ILINE))), ILINE = 1, NTLINE)
      ENDIF

C---- Date
      IF (DATE.NE.' ') THEN
          WRITE(DBASE,510) 'DATE ', DATE(1:LENSTR(DATE))
      ELSE
          WRITE(DBASE,510) 'DATE not given'
      ENDIF

C---- Release date
      IF (RLDATE.NE.' ') THEN
          WRITE(DBASE,510) 'RELEASE_DATE ', RLDATE(1:LENSTR(DATE))
      ENDIF

C---- Header
      IF (HEADER.NE.' ') THEN
          WRITE(DBASE,510) 'HEADER ', HEADER(1:LENSTR(HEADER))
      ENDIF

C---- Structure name (in COMPND records)
      IF (NCLINE.GT.0) THEN
           WRITE(DBASE,510) 'STRUCTURE ',
     -         (COMPND(ILINE)(1:LENSTR(COMPND(ILINE))),
     -         ILINE = 1, NCLINE)
      ENDIF

C---- Source
      IF (NSLINE.GT.0) THEN
           WRITE(DBASE,510) 'SOURCE ',
     -        (SOURCE(ILINE)(1:LENSTR(SOURCE(ILINE))),
     -        ILINE = 1, NSLINE)
      ELSE
          WRITE(DBASE,510) 'SOURCE not given'
      ENDIF

C---- Authors
      IF (NALINE.GT.0) THEN
           WRITE(DBASE,510) 'AUTHORS ',
     -        (AUTHOR(ILINE)(1:LENSTR(AUTHOR(ILINE))),
     -        ILINE = 1, NALINE)
      ELSE
          WRITE(DBASE,510) 'AUTHORS not given'
      ENDIF

C---- Single GIF image of structure or with side views
      IF (HAVIEW .OR. HAVJPG) THEN
          WRITE(DBASE,510) 'SIDE_VIEWS TRUE'
      ELSE
          WRITE(DBASE,510) 'SINGLE_VIEW TRUE'
      ENDIF

C---- RasMol script view
      IF (.NOT.TOOBIG .AND. HAVRSC) THEN
          WRITE(DBASE,510) 'RASCRIPT TRUE'
      ENDIF

C---- VRML view
      IF (HAVWRL) THEN
          WRITE(DBASE,510) 'HAVE_VRML TRUE'
      ENDIF

C---- Layer 1 entry
      IF (LAYER1) THEN
          WRITE(DBASE,510) 'LAYER1 TRUE'
      ENDIF

C---- Obsolete entry
      IF (OBSOL) THEN
          WRITE(DBASE,510) 'OBSOLETE TRUE'
      ENDIF

C---- Species image(s)
      IF (NSPECI.GT.0) THEN
          WRITE(NUMBER,560) NSPECI
          WRITE(DBASE,510) 'NSPECIES_GIF ', NUMBER
          DO 100, ISPECI = 1, NSPECI

C----         Form subscript for current line
              CALL SUBSCR(ISPECI,ITEM1)

C----         Write out
              WRITE(DBASE,510) 'SPECIES_GIF',
     -            ITEM1(1:LENSTR(ITEM1)), ' ',
     -            SPEGIF(ISPECI)(1:LENSTR(SPEGIF(ISPECI)))
 100      CONTINUE
      ENDIF

C---- Write out the experimental method
      IF (XRAY) THEN
          WRITE(DBASE,510) 'XRAY TRUE'
      ELSE IF (NMR) THEN
          WRITE(DBASE,510) 'NMR TRUE'
      ELSE IF (EMEXPT) THEN
          WRITE(DBASE,510) 'EM_EXPT TRUE'
      ELSE IF (ECEXPT) THEN
          WRITE(DBASE,510) 'EC_EXPT TRUE'
      ENDIF

C---- Resolution
      IF (RESOL.GT.0.0) THEN
          WRITE(FLOAT,520) RESOL
 520      FORMAT(F5.2)
          WRITE(DBASE,510) 'RESOLUTION ', FLOAT
      ELSE
          WRITE(DBASE,510) 'RESOLUTION not given'
      ENDIF

C---- R-Factor
      IF (RFACT.GT.0.0) THEN
          WRITE(FLOAT,540) RFACT
 540      FORMAT(F8.3)
          WRITE(DBASE,510) 'R-FACTOR ', FLOAT
      ELSE
          WRITE(DBASE,510) 'R-FACTOR not given'
      ENDIF

C---- R-Free
      IF (RFREE.GT.0.0) THEN
          WRITE(FLOAT,540) RFREE
          WRITE(DBASE,510) 'R-FREE ', FLOAT
      ENDIF

C---- E.C. number
      IF (ECNUMB.NE.' ') THEN
          WRITE(DBASE,510) 'EC_NUMBER ', ECNUMB(1:LENSTR(ECNUMB))
      ENDIF

C---- NMR details
      IF (NMR) THEN
          IF (NMODEL.EQ.0) NMODEL = 1
          WRITE(NUMBER,560) NMODEL
 560      FORMAT(I6)
          WRITE(DBASE,510) 'NMODELS ', NUMBER

C----     Form name of nmr restraints PDB file
          FILNAM = NMRDIR(1:LENSTR(NMRDIR)) // BRCODE // '.mr.Z'

C----     Check whether the file exists
          INQUIRE(FILE=FILNAM,EXIST=MATCH)

C----     If NMR restraints file is on the system, write out flag
          IF (MATCH) THEN
              WRITE(DBASE,510) 'NMR_RESTRAINTS TRUE'
          ENDIF
      ENDIF

C---- Ensemble of models
      IF (.NOT.NMR .AND. NMODEL.GT.0) THEN
          WRITE(DBASE,510) 'ENSEMBLE TRUE'
          WRITE(NUMBER,560) NMODEL
          WRITE(DBASE,510) 'NMODELS ', NUMBER
      ENDIF

C<--New
C---- If this is a theoretical model, write out flag
      IF (TMODEL) THEN
          WRITE(DBASE,510) 'THEORETICAL_MODEL TRUE'
      ENDIF
C<--New

C---- SWISS-PROT code
      IF (NSWISS.GT.0) THEN
C          WRITE(NUMBER,560) NSWISS
C          WRITE(DBASE,510) 'NSPROT_CODE ', NUMBER
C          DO 300, ISWISS = 1, NSWISS

C----         Form subscript for current line
C              CALL SUBSCR(ISWISS,ITEM1)

C----         Write out
C              WRITE(DBASE,510) 'SPROT_CODE',
C     -            ITEM1(1:LENSTR(ITEM1)), ' ', SWNAME(ISWISS)
C              WRITE(NUMBER,560) NSWCHN(ISWISS)
C              WRITE(DBASE,510) 'NSPROT_CHAIN',
C     -            ITEM1(1:LENSTR(ITEM1)), ' ', NUMBER

C----         Loop through all the chains associated with this code
C              DO 250, ICHN = 1, NSWCHN(ISWISS)

C----             Form subscript for current chain
C                  CALL SUBSCR(ICHN,ITEM2)

C----             Write out
C                  CH = SWICHN(ICHN,ISWISS)
C                  IF (CH.EQ.' ') CH = 'blank'
C                  WRITE(DBASE,510) 'SPROT_CHAIN',
C     -                 ITEM1(1:LENSTR(ITEM1)),
C     -                 ITEM2(1:LENSTR(ITEM2)), ' ', CH
C 250          CONTINUE
C 300      CONTINUE
          SWETAL = .TRUE.
C      ELSE
C          WRITE(DBASE,510) 'SPROT_CODE none'
      ENDIF

C---- E.C. number
      IF (NEC.GT.0 .OR. ECNUMB.NE.' ') THEN
C          IF (NEC.GT.0) THEN
C              WRITE(NUMBER,560) NEC
C              WRITE(DBASE,510) 'NEC_NUMBERS ', NUMBER
C          ENDIF
C          DO 400, IENTRY = 1, NEC

C----         Compress the E.C. number
C              CALL COMPRS(EENTRY(IENTRY),ECOMPR)

C----         Form subscript for current line
C              CALL SUBSCR(IENTRY,ITEM1)

C----         Write out
C              WRITE(DBASE,510) 'EC_NUMBER', ITEM1(1:LENSTR(ITEM1)),
C     -            ' ', ECOMPR
C 400      CONTINUE
          SWETAL = .TRUE.
      ENDIF

C---- PRINTS links
      IF (NPRLNK.GT.0) THEN
          WRITE(DBASE,510) 'GOT_PRINTS TRUE'
          SWETAL = .TRUE.
      ENDIF

C---- Related PDB entries
      IF (NMRLNK .OR. NELINE.GT.0) THEN

C----     Initialise related entries output line
          NOUT = 0
          OUTLIN = ' '

C----     Loop over the related entries lines
          DO 450, ILINE = 1, NELINE

C----         If output line is blank, then copy entry line
              IF (OUTLIN.EQ.' ') THEN
                  OUTLIN = RELATE(ILINE)

C----         Otherwise, decide whether to append current line, or
C             to start a new one
              ELSE

C----             Initialise flag
                  NEWLIN = .FALSE.

C----             If first character is non-blank, then want to start
C                 a new line
                  IF (RELATE(ILINE)(1:1).NE.' ') THEN
                      NEWLIN = .TRUE.

C----             Otherwise, if line already too long, then have to
C                 start a new line
                  ELSE IF (LENSTR(OUTLIN) + LENSTR(RELATE(ILINE)).GT.
     -                MXTITL) THEN
                      NEWLIN = .TRUE.
                  ENDIF

C----             If starting new line, write out any current line
                  IF (NEWLIN .AND. OUTLIN.NE.' ') THEN

C----                 Increment output count
                      NOUT = NOUT + 1

C----                 Form subscript for current line
                      CALL SUBSCR(NOUT,ITEM1)

C----                 Write out
                      WRITE(DBASE,510) 'RELATED_PDB_ENTRY',
     -                    ITEM1(1:LENSTR(ITEM1)), ' ',
     -                    OUTLIN(1:LENSTR(OUTLIN))

C----                 Re-initialise new line
                      OUTLIN = ' '
                  ENDIF

C----             Append current line onto end of existing line
                  IF (OUTLIN.EQ.' ') THEN
                      OUTLIN = RELATE(ILINE)
                  ELSE IF (RELATE(ILINE).NE.' ') THEN
                      OUTLIN = OUTLIN(1:LENSTR(OUTLIN)) //
     -                    RELATE(ILINE)(1:LENSTR(RELATE(ILINE)))
                  ENDIF
              ENDIF
 450      CONTINUE

C----     If line remaining to be written out, then write out now
          IF (OUTLIN.NE.' ') THEN

C----         Increment output count
              NOUT = NOUT + 1

C----         Form subscript for current line
              CALL SUBSCR(NOUT,ITEM1)

C----         Write out
              WRITE(DBASE,510) 'RELATED_PDB_ENTRY',
     -            ITEM1(1:LENSTR(ITEM1)), ' ',
     -            OUTLIN(1:LENSTR(OUTLIN))
          ENDIF

C----     If any related entries lines were written out, show how many
          IF (NOUT.GT.0) THEN
              WRITE(NUMBER,560) NOUT
              WRITE(DBASE,510) 'NRELATED ', NUMBER
              SWETAL = .TRUE.
          ENDIF
      ENDIF

C---- Entries superseded by this one
      IF (NSUPER.GT.0 .AND. .NOT.OBSOL) THEN
          DO 500, IENTRY = 1, NSUPER
              OTHCOD = SPRSDE(IENTRY)
              CALL LOWCAS(4,OTHCOD)
              WRITE(DBASE,510) 'SUPERSEDES ', OTHCOD
 500      CONTINUE
          SWETAL = .TRUE.
      ENDIF

C---- None of the above
      IF (SWETAL) THEN
          WRITE(DBASE,510) 'SWISS_ET_AL TRUE'
      ENDIF

C---- Unpublished references
      IF (HAVUNP) THEN
          WRITE(DBASE,510) 'HAVE_UNPUB_REFS TRUE'
      ENDIF

C---- DNA structure ... NDB link
      IF (NDBREF.NE.' ') THEN

C----     Create the link reference
          FSTLET = NDBREF(1:1)
          CALL UPPCAS(1,FSTLET)
          NDBLNK = FSTLET // '/' //
     -        NDBREF(1:LENSTR(NDBREF)) // '/' // NDBREF

          WRITE(DBASE,510) 'NDB_LINK ', NDBLNK(1:LENSTR(NDBLNK))
      ENDIF

C---- DNA structure ... NDB reference
      IF (NDBREF.NE.' ') THEN
          UPPREF = NDBREF
          CALL UPPCAS(8,UPPREF)
          WRITE(DBASE,510) 'NDB_REF ', UPPREF
      ENDIF

C---- Complete Macromolecule link
      IF (NCHAIN.GT.0 .OR. NNUCL.GT.0) THEN
          WRITE(DBASE,510) 'HAVE_PQS TRUE'
      ENDIF

C---- Yeast structure
      IF (YEAST) THEN
          WRITE(DBASE,510) 'FROM_YEAST TRUE'
      ENDIF

C---- Structure classification databases
      IF (NCHAIN.GT.0) THEN
          WRITE(DBASE,510) 'PROTEIN TRUE'
      ENDIF

C---- Any RNA/DNA chains
      IF (NNUCL.GT.0) THEN
          WRITE(DBASE,510) 'DNA TRUE'
      ENDIF

C---- Any metals
C      IF (NMETAL.GT.0) THEN
C          WRITE(DBASE,510) 'METAL TRUE'
C      ENDIF

C---- Protein structural quality checks
      IF (HAVCHK) THEN
          WRITE(DBASE,510) 'QUALITY_CHECKS TRUE'
      ENDIF

C---- Structure from the MCSG
C      IF (MCSG) THEN
C          WRITE(DBASE,510) 'MCSG_STRUCTURE TRUE'
C      ENDIF

C---- RELIBASE analyses
      IF (HAVLIG) THEN
          WRITE(DBASE,510) 'LIGAND TRUE'
      ENDIF

C---- Have SURFPLOT image
      IF (HAVSRF) THEN
          WRITE(DBASE,510) 'HAVE_SURF TRUE'
      ENDIF

C---- Have clefts image
      IF (HAVCLF) THEN
          WRITE(DBASE,510) 'HAVE_CLEFTS TRUE'
      ENDIF

C---- RasMol script view of the protein surface
      IF (NCHAIN.GT.0 .OR. NNUCL.GT.0) THEN
          WRITE(DBASE,510) 'RASURF TRUE'
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE SUBSCR  -  Convert givn number into a subscript eg 1 -> "[1]"
C
C----------------------------------------------------------------------+---

      SUBROUTINE SUBSCR(NUMBER,STRING)

      CHARACTER*(*) STRING
      INTEGER       NUMBER


C---- Write subscript according to number's value
      IF (NUMBER.LT.10) THEN
          WRITE(STRING,10) NUMBER
 10       FORMAT('[',I1,']')
      ELSE IF (NUMBER.LT.100) THEN
          WRITE(STRING,20) NUMBER
 20       FORMAT('[',I2,']')
      ELSE
          WRITE(STRING,30) NUMBER
 30       FORMAT('[',I3,']')
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE SPLICE  -  Splice in the required info
C
C----------------------------------------------------------------------+---

      SUBROUTINE SPLICE(INREC,OUTLIN,IFILE)

      INCLUDE 'pdbhtml.inc'

      CHARACTER*1   FSTLET
      CHARACTER*8   UPPREF
      CHARACTER*20  INSKEY, NDBLNK
      CHARACTER*(*) INREC, OUTLIN
      INTEGER       IFILE, ILINE, IPOS, JPOS, LENKEY, LENSTR


C---- Default is to write line out as it stands
 20   FORMAT(A)
      OUTLIN = INREC

C---- Loop until all asterisk replacements have been made
 100  CONTINUE

C----     Check for asterisks
          IPOS = INDEX(INREC,'*')

C----     If have asterisks, then need to replace with appropriate
C         data
          IF (IPOS.GT.0) THEN

C----         Extract the asterisk-delimited keyword for data
C             insertion
              INSKEY = INREC(IPOS + 1:)
              JPOS = INDEX(INSKEY,'*')

C----         Blank out everything from asterisk onwards
              IF (JPOS.GT.0) THEN
                  INSKEY(JPOS:) = ' '
                  LENKEY = JPOS - 1

C----         If no second asterisk, then merely blank out the
C             one encountered so far
              ELSE
                  INSKEY = ' '
                  LENKEY = 1
                  INREC(IPOS:IPOS) = ' '
                  OUTLIN = INREC
              ENDIF

C----         Check for PDB code
              IF (INSKEY(1:LENKEY).EQ.'PDB code') THEN

C----             Splice in the PDB code
                  IF (IPOS.GT.1) THEN
                      OUTLIN = INREC(1:IPOS-1) // BRCODE //
     -                    INREC(IPOS + LENKEY + 2:)
                  ELSE
                      OUTLIN = BRCODE // INREC(LENKEY + 3:)
                  ENDIF

C----         Species GIF file(s), so add in image(s)
              ELSE IF (INSKEY(1:LENKEY).EQ.'Gif') THEN

C----             Write out the links to the GIF files
                  CALL WRISPE(IFILE,WWWSPE,NSPECI,SPEGIF,MXSPEC)
                  OUTLIN = ' '

C----         Obsolete entry, so give link to entry that supersedes it
              ELSE IF (INSKEY(1:LENKEY).EQ.'Obsolete') THEN

C----             Write out the superseding entries
                  CALL WRIOBS(IFILE,PDBSUM,WWWPDB,NSUPER,SPRSDE,MXITEM,
     -                DBASE)
                  OUTLIN = ' '

C----         Process name in HEADER record
              ELSE IF (INSKEY(1:LENKEY).EQ.'Header' .AND.
     -            HEADER.NE.' ') THEN

C----             Splice in the header description
                  IF (IPOS.GT.1) THEN
                      OUTLIN = INREC(1:IPOS-1) //
     -                    HEADER(1:LENSTR(HEADER)) //
     -                    INREC(IPOS + LENKEY + 2:)
                  ELSE
                      OUTLIN = HEADER(1:LENSTR(HEADER)) //
     -                    INREC(LENKEY + 3:)
                  ENDIF

C----         Process title
              ELSE IF (INSKEY(1:LENKEY).EQ.'Title') THEN

C----             Write out all the lines making up the title
                  WRITE(IFILE,20) (TITLE(ILINE)(1:LENSTR(TITLE(ILINE))),
     -                ILINE = 1, NTLINE)
                  OUTLIN = ' '

C----         Check for NDB link
              ELSE IF (INSKEY(1:LENKEY).EQ.'NDBlink') THEN

C----             Create the link reference
                  FSTLET = NDBREF(1:1)
                  CALL UPPCAS(1,FSTLET)
                  NDBLNK = FSTLET // '/' //
     -                NDBREF(1:LENSTR(NDBREF)) // '/' // NDBREF

C----             Splice it in
                  IF (IPOS.GT.1) THEN
                      OUTLIN = INREC(1:IPOS-1) //
     -                    NDBLNK(1:LENSTR(NDBLNK)) //
     -                    INREC(IPOS + LENKEY + 2:)
                  ELSE
                      OUTLIN = NDBLNK(1:LENSTR(NDBLNK)) //
     -                    INREC(LENKEY + 3:)
                  ENDIF

C----         Check for NDB reference
              ELSE IF (INSKEY(1:LENKEY).EQ.'NDBref') THEN

C----             Convert to upper case
                  UPPREF = NDBREF
                  CALL UPPCAS(8,UPPREF)

C----             Splice it in
                  IF (IPOS.GT.1) THEN
                      OUTLIN = INREC(1:IPOS-1) //
     -                    UPPREF(1:LENSTR(UPPREF)) //
     -                    INREC(IPOS + LENKEY + 2:)
                  ELSE
                      OUTLIN = UPPREF(1:LENSTR(UPPREF)) //
     -                    INREC(LENKEY + 3:)
                  ENDIF

C----         Process structure name (in COMPND records)
              ELSE IF (INSKEY(1:LENKEY).EQ.'Structure') THEN

C----             Write out all the lines
                  WRITE(IFILE,20)
     -                (COMPND(ILINE)(1:LENSTR(COMPND(ILINE))),
     -                ILINE = 1, NCLINE)
                  
                  OUTLIN = ' '

C----         Process source
              ELSE IF (INSKEY(1:LENKEY).EQ.'Source') THEN

C----             Write out all the lines
                  WRITE(IFILE,20)
     -                (SOURCE(ILINE)(1:LENSTR(SOURCE(ILINE))),
     -                ILINE = 1, NSLINE)
                  OUTLIN = ' '

C----         Process no. of NMR models
              ELSE IF (INSKEY(1:LENKEY).EQ.'n models') THEN
                  IF (NMODEL.EQ.1) THEN
                      WRITE(OUTLIN,320) NMODEL
 320                  FORMAT('<b>',I6,'</b> model.')
                  ELSE
                      WRITE(OUTLIN,340) NMODEL
 340                  FORMAT('<b>',I6,'</b> models.')
                  ENDIF

C----         Process resolution and R-factor(s)
              ELSE IF (INSKEY(1:LENKEY).EQ.'R-factor etc') THEN

C----             Write out the X-ray details
                  CALL WRIRES(IFILE)
                  OUTLIN = ' '

C----         Process authors
              ELSE IF (INSKEY(1:LENKEY).EQ.'Authors') THEN

C----             Write out all the lines
                  CALL WRIAUT(IFILE)
                  OUTLIN = ' '

C----         Check for date
              ELSE IF (INSKEY(1:LENKEY).EQ.'Date') THEN

C----             Splice in the date
                  IF (IPOS.GT.1) THEN
                      OUTLIN = INREC(1:IPOS-1) // DATE //
     -                    INREC(IPOS + LENKEY + 2:)
                  ELSE
                      OUTLIN = DATE // INREC(LENKEY + 3:)
                  ENDIF

C----         Process SWISS-PROT code
              ELSE IF (INSKEY(1:LENKEY).EQ.'Swiss-prot') THEN

C----             Write out all the data
                  CALL WRISWS(IFILE)
                  OUTLIN = ' '

C----         Process E.C. number and links
              ELSE IF (INSKEY(1:LENKEY).EQ.'EC number') THEN

C----             Write out all the data
                  CALL WRIECN(IFILE,BRCODE,ECNUMB,NEC,EENTRY,MXENTR,
     -                WWWENZ,ENZPTH,NAMLEN,EXPENZ,KYOENZ,WITENZ,NUMLEN,
     -                ECTMPL,DBASE)
                  OUTLIN = ' '

C----         Process links to PRINTS database
              ELSE IF (INSKEY(1:LENKEY).EQ.'Prints') THEN

C----             Write out all the data
                  CALL WRIPRN(IFILE,WWWPRN,BRCODE,PRCODE,PRNPDB,PRNUM,
     -                MXPCOD,MXPRIN,NPCODE)
                  OUTLIN = ' '

C----         Process related entries
              ELSE IF (INSKEY(1:LENKEY).EQ.'Related Entries') THEN

C----             Write out all the data
C                  CALL WRIREL(IFILE,RELATE,NELINE,ENSLNK,NMRLNK,RELINK,
C     -                LNKCOD,NLINKS,PDBDIR,PDBPRE,PDBSUF,WWWPDB,DIRSEP)
                  OUTLIN = ' '

C----         Process entries superseded by this one
              ELSE IF (INSKEY(1:LENKEY).EQ.'Supersedes') THEN

C----             Write out all the data
C                  CALL WRISUP(IFILE,SPRSDE,NSUPER,
C     -                PDBSUM_TEMPLATE(PDB_CURRENT),WWWPDB,SFOPEN)
                  OUTLIN = ' '

C----         If key not identified, then just blank out the
C             asterisk and continue
              ELSE
                  OUTLIN(IPOS:IPOS) = ' '
              ENDIF

C----         Copy new line back
              INREC = OUTLIN

C----     Otherwise, jump out of this loop
          ELSE
              GO TO 999
          ENDIF

C---- Return to see if there are any more asterisk replacements to
C     be made
      GO TO 100


 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETSTA  -  Get the state corresponding to the current
C                        keyword
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETSTA(KEYWRD,ISTATE)

      INTEGER       NSTATE
      PARAMETER    (NSTATE = 33)

      CHARACTER*12  KEYWRD, KEYS(NSTATE)
      INTEGER       ISTATE, JSTATE

      DATA KEYS  / 'JAVASCRIPT  ', 'OUT         ', 'SINGLE VIEW ',
     -             'SIDE VIEWS  ', 'LAYER 1     ', 'RASCRIPT    ',
     -             'VRML VIEW   ', 'OBSOLETE    ', 'TITLE       ',
     -             'NMR         ', 'ENSEMBLE    ', 'X-RAY       ',
     -             'SWISS ET AL ', 'SWISS-PROT  ', 'EC NUMBER   ',
     -             'PRINTS      ', 'RELENT      ', 'SUPERSEDES  ',
     -             'UNPUB REFS  ', 'DNA         ', 'PQS         ',
     -             'YEAST       ', 'PROT CLASSIF', 'CHECKS      ',
     -             'PROMOTIF    ', 'NOSURF      ', 'SURFPLOT    ',
     -             'RELIBASE    ', 'SPECIES     ', 'RASURF      ',
     -             'WHAT        ', 'PDBLNK      ', 'MCSG        ' /

C---- Initialise state
      ISTATE = 0

C---- Search for the keyword in the list to determine the
C     state
      DO 200, JSTATE = 1, NSTATE
          IF (KEYWRD.EQ.KEYS(JSTATE)) THEN
              ISTATE = JSTATE
              GO TO 999
          ENDIF
 200  CONTINUE

 999  CONTINUE
      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE WRSIPE  -  Write out the species GIF images
C
C----------------------------------------------------------------------+---

      SUBROUTINE WRISPE(IFILE,WWWSPE,NSPECI,SPEGIF,MXSPEC)

      INTEGER       MXSPEC

      INTEGER       MAXLEN
      PARAMETER    (MAXLEN =   1000)

      CHARACTER*10  SPEGIF(MXSPEC)
      CHARACTER*(MAXLEN) OUTLIN
      CHARACTER*(*) WWWSPE
      INTEGER       ISPECI, IFILE, LENSTR, NSPECI

C---- List through all the GIF entries
      DO 200, ISPECI = 1, NSPECI

C----     Add image
          OUTLIN = '<IMG SRC="' //
     -        WWWSPE(1:LENSTR(WWWSPE)) //
     -        SPEGIF(ISPECI)(1:LENSTR(SPEGIF(ISPECI))) // '.gif">'

C----     Write the line
          WRITE(IFILE,510) OUTLIN(1:LENSTR(OUTLIN))
 510      FORMAT(10A)
 200  CONTINUE

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE FORNUM  -  Format the given integer to left-justify
C
C----------------------------------------------------------------------+---

      SUBROUTINE FORNUM(NUMBER,IVALUE)

      CHARACTER*(*) NUMBER
      INTEGER       IVALUE

C---- Format number according to size
      IF (IVALUE.LT.10) THEN
          WRITE(NUMBER,10) IVALUE
 10       FORMAT(I1)
      ELSE IF (IVALUE.LT.100) THEN
          WRITE(NUMBER,20) IVALUE
 20       FORMAT(I2)
      ELSE IF (IVALUE.LT.1000) THEN
          WRITE(NUMBER,30) IVALUE
 30       FORMAT(I3)
      ELSE IF (IVALUE.LT.10000) THEN
          WRITE(NUMBER,40) IVALUE
 40       FORMAT(I4)
      ELSE IF (IVALUE.LT.100000) THEN
          WRITE(NUMBER,50) IVALUE
 50       FORMAT(I5)
      ELSE
          WRITE(NUMBER,60) IVALUE
 60       FORMAT(I6)
      ENDIF

      RETURN
      END

C--------------------------------------------------------------------------
C**************************************************************************
C
C  SUBROUTINE GETDAT  -  Check whether given file exists and is non-empty
C
C----------------------------------------------------------------------+---

      SUBROUTINE GETDAT(PDBSUM,DBASE)

      CHARACTER*(*) PDBSUM
      CHARACTER*120 FULNAM, IREC
      INTEGER       DBASE, LENSTR, LINE
      LOGICAL       HAVFIL, NOREAD


C---- Initialise variables
      FULNAM = PDBSUM(1:LENSTR(PDBSUM)) // '/database.dat'
      HAVFIL = .FALSE.
      LINE = 0

C---- Open input file
      OPEN(UNIT=2,FILE=FULNAM,STATUS='OLD',
CVAX     -    CARRIAGECONTROL='LIST',READONLY,
     -    ACCESS='SEQUENTIAL',FORM='FORMATTED',ERR=500)

C---- Loop until all file has been read
 100  CONTINUE

C----     Read in the next record from the input file
          READ(2,110,ERR=500,END=500) IREC
 110      FORMAT(A)

C----     If this is one of the required records, write out to new
C         database.dat file
          IF (IREC(1:3).EQ.'CSA' .OR. IREC(1:8).EQ.'HAVE_CSA') THEN
              WRITE(DBASE,110) IREC(1:LENSTR(IREC))
          ENDIF

C---- Loop back for next record
      GO TO 100

C---- End of file reached
500   CONTINUE

C---- Close the file
      CLOSE(2)

      RETURN
      END

C--------------------------------------------------------------------------
